tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set -euo pipefail

TEST_NAME="prim_arbiter_stall_keeps_first_request"
TB_DIR="/home/opentitan/.tb_prim_arbiter_stall"
COMPILE_LOG="$TB_DIR/compile.log"
RUN_LOG="$TB_DIR/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

mkdir -p "$TB_DIR"
rm -rf \
  "$TB_DIR/simv" \
  "$TB_DIR/simv.daidir" \
  "$TB_DIR/csrc" \
  "$TB_DIR/ucli.key" \
  "$TB_DIR/AN.DB" \
  "$TB_DIR/DVEfiles"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  localparam int N = 2;
  localparam int DW = 16;

  logic clk_i;
  logic rst_ni;
  logic [N-1:0] req;
  logic [DW-1:0] req_data [N];
  logic [N-1:0] gnt;
  logic arb_valid;
  logic [DW-1:0] arb_data;
  logic arb_ready;

  prim_arbiter #(
    .N(N),
    .DW(DW)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .req(req),
    .req_data(req_data),
    .gnt(gnt),
    .arb_valid(arb_valid),
    .arb_data(arb_data),
    .arb_ready(arb_ready)
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  initial begin
    rst_ni = 1'b0;
    req = '0;
    arb_ready = 1'b0;
    req_data[0] = 16'hA5A5;
    req_data[1] = 16'hBEEF;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    req = 2'b10;

    @(posedge clk_i);
    @(negedge clk_i);
    req = 2'b11;

    @(posedge clk_i);
    @(negedge clk_i);
    arb_ready = 1'b1;
    #1;

    if (arb_valid !== 1'b1 || gnt !== 2'b10 || arb_data !== 16'hBEEF) begin
      $display("TB_FAIL arb_valid=%b gnt=%b arb_data=%h", arb_valid, gnt, arb_data);
      $fatal(1, "prim_arbiter did not keep the original request during backpressure");
    end

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/files.f" <<'EOF'
/home/opentitan/hw/ip/prim/rtl/prim_arbiter.sv
/home/opentitan/.tb_prim_arbiter_stall/tb.sv
EOF

set +e
vcs -full64 -sverilog -timescale=1ns/1ps \
  -f "$TB_DIR/files.f" \
  -o "$TB_DIR/simv" \
  -l "$COMPILE_LOG"
compile_rc=$?
set -e

if [ "$compile_rc" -ne 0 ]; then
  emit_result "FAIL"
  exit "$compile_rc"
fi

set +e
"$TB_DIR/simv" | tee "$RUN_LOG"
run_rc=${PIPESTATUS[0]}
set -e

if grep -q "TB_PASS" "$RUN_LOG"; then
  emit_result "PASS"
  exit 0
fi

if grep -q "TB_FAIL" "$RUN_LOG"; then
  emit_result "FAIL"
  exit 1
fi

if [ "$run_rc" -eq 0 ]; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

