diff --git a/hw/ip/tlul/rtl/tlul_err.sv b/hw/ip/tlul/rtl/tlul_err.sv
new file mode 100644
index 0000000000000..feaa6045a33e0
--- /dev/null
+++ b/hw/ip/tlul/rtl/tlul_err.sv
@@ -0,0 +1,93 @@
+// Copyright lowRISC contributors.
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+
+module tlul_err import tlul_pkg::*; (
+  input clk_i,
+  input rst_ni,
+
+  input tl_h2d_t tl_i,
+
+  output logic err_o
+);
+
+  localparam int IW  = $bits(tl_i.a_source);
+  localparam int SZW = $bits(tl_i.a_size);
+  localparam int DW  = $bits(tl_i.a_data);
+  localparam int MW  = $bits(tl_i.a_mask);
+  localparam int SubAW = $clog2(DW/8);
+
+  logic opcode_allowed, a_config_allowed;
+
+  logic op_full, op_partial, op_get;
+  assign op_full    = (tl_i.a_opcode == PutFullData);
+  assign op_partial = (tl_i.a_opcode == PutPartialData);
+  assign op_get     = (tl_i.a_opcode == Get);
+
+  // Anything that doesn't fall into the permitted category, it raises an error
+  assign err_o = ~(opcode_allowed & a_config_allowed);
+
+  // opcode check
+  assign opcode_allowed = (tl_i.a_opcode == PutFullData)
+                        | (tl_i.a_opcode == PutPartialData)
+                        | (tl_i.a_opcode == Get);
+
+  // a channel configuration check
+  logic addr_sz_chk;    // address and size alignment check
+  logic mask_chk;       // inactive lane a_mask check
+  logic fulldata_chk;   // PutFullData should have size match to mask
+
+  logic [MW-1:0] mask;
+
+  assign mask = (1 << tl_i.a_address[SubAW-1:0]);
+
+  always_comb begin
+    addr_sz_chk  = 1'b0;
+    mask_chk     = 1'b0;
+    fulldata_chk = 1'b0; // Only valid when opcode is PutFullData
+
+    if (tl_i.a_valid) begin
+      unique case (tl_i.a_size)
+        'h0: begin // 1 Byte
+          addr_sz_chk  = 1'b1;
+          mask_chk     = ~|(tl_i.a_mask & ~mask);
+          fulldata_chk = mask_chk;
+        end
+
+        'h1: begin // 2 Byte
+          addr_sz_chk  = ~tl_i.a_address[0];
+          // check inactive lanes if lower 2B, check a_mask[3:2], if uppwer 2B, a_mask[1:0]
+          mask_chk     = (tl_i.a_address[1]) ? ~|(tl_i.a_mask & 4'b0011)
+                       : ~|(tl_i.a_mask & 4'b1100);
+          fulldata_chk = (tl_i.a_address[1]) ? &tl_i.a_mask[3:2] : &tl_i.a_mask[1:0] ;
+        end
+
+        'h2: begin // 4 Byte
+          addr_sz_chk  = ~|tl_i.a_address[SubAW-1:0];
+          mask_chk     = 1'b1;
+          fulldata_chk = &tl_i.a_mask[3:0];
+        end
+
+        default: begin // else
+          addr_sz_chk  = 1'b0;
+          mask_chk     = 1'b0;
+          fulldata_chk = 1'b0;
+        end
+      endcase
+    end else begin
+      addr_sz_chk  = 1'b0;
+      mask_chk     = 1'b0;
+      fulldata_chk = 1'b0;
+    end
+  end
+
+  assign a_config_allowed = addr_sz_chk
+                          & (op_get | mask_chk)
+                          & (op_get | op_partial | fulldata_chk) ;
+
+  // Only 32 bit data width for current tlul_err
+  `ASSERT_INIT(dataWidthOnly32_A, DW == 32)
+
+endmodule
+

tb_script:
#!/bin/bash
set -uo pipefail

cd /home/opentitan

TEST_NAME="tlul_adapter_reg_illegal_opcode_error"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
TB_FILE="$TB_DIR/tb.sv"
FILELIST="$TB_DIR/filelist.f"
COMPILE_LOG="$TB_DIR/compile.log"
RUN_LOG="$TB_DIR/run.log"
PASS_SIGNATURE="SIM_PASS illegal opcode error path exercised"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_FILE" <<'EOF'
`timescale 1ns/1ps

module tb;
  import top_pkg::*;
  import tlul_pkg::*;

  logic clk;
  logic rst_ni;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  logic re_o;
  logic we_o;
  logic [7:0] addr_o;
  logic [31:0] wdata_o;
  logic [3:0] be_o;
  logic [31:0] rdata_i;
  logic error_i;

  tlul_adapter_reg dut (
    .clk_i   (clk),
    .rst_ni  (rst_ni),
    .tl_i    (tl_i),
    .tl_o    (tl_o),
    .re_o    (re_o),
    .we_o    (we_o),
    .addr_o  (addr_o),
    .wdata_o (wdata_o),
    .be_o    (be_o),
    .rdata_i (rdata_i),
    .error_i (error_i)
  );

  always #5 clk = ~clk;

  task automatic check(input bit cond, input string msg);
    if (!cond) begin
      $display("SIM_FAIL %s", msg);
      $fatal(1, "%s", msg);
    end
  endtask

  initial begin
    int wait_cycles;
    bit saw_response;

    clk = 0;
    rst_ni = 0;
    tl_i = '0;
    rdata_i = 32'h1234_5678;
    error_i = 1'b0;

    repeat (3) @(posedge clk);
    rst_ni = 1;
    @(posedge clk);

    tl_i.a_valid = 1'b1;
    tl_i.d_ready = 1'b1;
    tl_i.a_opcode = tl_a_op_e'(3'h2);
    tl_i.a_size = 2;
    tl_i.a_source = 8'h5a;
    tl_i.a_address = 32'h0000_0010;
    tl_i.a_mask = 4'hf;
    tl_i.a_data = 32'hface_cafe;
    tl_i.a_user = '0;

    saw_response = 1'b0;
    for (wait_cycles = 0; wait_cycles < 4; wait_cycles++) begin
      @(posedge clk);
      #1;
      $display("TRACE cycle=%0d a_ready=%0b d_valid=%0b d_error=%0b",
               wait_cycles, tl_o.a_ready, tl_o.d_valid, tl_o.d_error);
      if (tl_o.d_valid === 1'b1) begin
        saw_response = 1'b1;
        break;
      end
    end

    check(saw_response, "Expected d_valid=1 after illegal opcode request");
    check(tl_o.d_opcode == AccessAck, "Expected AccessAck for illegal opcode request");
    check(tl_o.d_error === 1'b1, "Expected d_error=1 for illegal opcode request");
    check(tl_o.d_source == 8'h5a, "Expected source ID to be preserved");

    tl_i.a_valid = 1'b0;
    @(posedge clk);
    $display("SIM_PASS illegal opcode error path exercised");
    $finish;
  end
endmodule
EOF

cat > "$FILELIST" <<'EOF'
hw/ip/prim/rtl/prim_assert.sv
hw/top_earlgrey/rtl/top_pkg.sv
hw/ip/tlul/rtl/tlul_pkg.sv
hw/ip/tlul/rtl/tlul_adapter_reg.sv
EOF

if [[ -f hw/ip/tlul/rtl/tlul_err.sv ]]; then
  echo "hw/ip/tlul/rtl/tlul_err.sv" >> "$FILELIST"
fi

echo "$TB_FILE" >> "$FILELIST"

set +e
vcs -full64 -sverilog -timescale=1ns/1ps -top tb \
  -f "$FILELIST" \
  -o "$TB_DIR/simv" \
  -l "$COMPILE_LOG"
compile_rc=$?

sim_rc=1
if [[ $compile_rc -eq 0 ]]; then
  "$TB_DIR/simv" -l "$RUN_LOG"
  sim_rc=$?
fi
set -e

if [[ $compile_rc -eq 0 && -f "$RUN_LOG" && $(grep -F -c "$PASS_SIGNATURE" "$RUN_LOG") -gt 0 ]]; then
  cat "$RUN_LOG"
  emit_result "PASS"
  exit 0
fi

if [[ -f "$RUN_LOG" ]]; then
  cat "$RUN_LOG"
elif [[ -f "$COMPILE_LOG" ]]; then
  cat "$COMPILE_LOG"
else
  echo "Missing both compile and run logs under $TB_DIR"
fi

emit_result "FAIL"
exit 1

