    .addr_o,
    .wdata_o,
    .wmask_o,
    .rdata_i,
    .rvalid_i,
    .rerror_i
  );

  initial begin
    clk_i = 1'b0;
    forever #5 clk_i = ~clk_i;
  end

  task automatic apply_reset;
    begin
      saw_req_to_sram = 1'b0;
      saw_error_rsp = 1'b0;
      tl_i = '0;
      gnt_i = 1'b1;
      rdata_i = '0;
      rvalid_i = 1'b0;
      rerror_i = '0;
      rst_ni = 1'b0;
      repeat (5) @(posedge clk_i);
      rst_ni = 1'b1;
      repeat (2) @(posedge clk_i);
    end
  endtask

  task automatic send_illegal_opcode;
    begin
      tl_i.a_valid   = 1'b1;
      tl_i.a_opcode  = tl_a_op_e'(3'h7);
      tl_i.a_param   = '0;
      tl_i.a_size    = 2'h2;
      tl_i.a_source  = 8'h3c;
      tl_i.a_address = 32'h0000_0010;
      tl_i.a_mask    = 4'hf;
      tl_i.a_data    = 32'hfeed_c0de;
      tl_i.a_user    = '0;
      tl_i.d_ready   = 1'b1;

      do begin
        @(posedge clk_i);
        if (req_o) begin
          saw_req_to_sram = 1'b1;
        end
      end while (!tl_o.a_ready);

      tl_i.a_valid   = 1'b0;
      tl_i.a_opcode  = Get;
      tl_i.a_param   = '0;
      tl_i.a_size    = '0;
      tl_i.a_source  = '0;
      tl_i.a_address = '0;
      tl_i.a_mask    = '0;
      tl_i.a_data    = '0;
      tl_i.a_user    = '0;
    end
  endtask

  initial begin
    apply_reset();
    send_illegal_opcode();

    repeat (10) begin
      @(posedge clk_i);
      if (req_o) begin
        saw_req_to_sram = 1'b1;
      end
      if (tl_o.d_valid && tl_i.d_ready && tl_o.d_error &&
          (tl_o.d_opcode == AccessAck) &&
          (tl_o.d_source == 8'h3c)) begin
        saw_error_rsp = 1'b1;
      end
