    if (saw_req_to_sram) begin
      $fatal(1, "RUNTIME_ERROR: illegal opcode request was forwarded to SRAM");
    end

    if (!saw_error_rsp) begin
      $fatal(1, "RUNTIME_ERROR: missing AccessAck error response for illegal opcode");
    end

    $display("RUNTIME_PASS: illegal opcode was handled internally");
    $finish(0);
  end
endmodule
EOF

