#!/bin/bash

cd /home/opentitan || exit 1
set -u

TEST_NAME="rv_plic_claim_threshold_polling"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  localparam int N_SOURCE = 4;
  localparam int MAX_PRIO = 7;
  localparam int SRCW = $clog2(N_SOURCE + 1);
  localparam int PRIOW = $clog2(MAX_PRIO + 1);

  logic clk;
  logic rst_ni;
  logic [N_SOURCE-1:0] ip;
  logic [N_SOURCE-1:0] ie;
  logic [PRIOW-1:0] prio [N_SOURCE];
  logic [PRIOW-1:0] threshold;

  logic seq_irq;
  logic [SRCW-1:0] seq_irq_id;
  logic mat_irq;
  logic [SRCW-1:0] mat_irq_id;

  rv_plic_target #(
    .N_SOURCE(N_SOURCE),
    .MAX_PRIO(MAX_PRIO),
    .ALGORITHM("SEQUENTIAL")
  ) u_seq (
    .clk_i(clk),
    .rst_ni(rst_ni),
    .ip(ip),
    .ie(ie),
    .prio(prio),
    .threshold(threshold),
    .irq(seq_irq),
    .irq_id(seq_irq_id)
  );

  rv_plic_target #(
    .N_SOURCE(N_SOURCE),
    .MAX_PRIO(MAX_PRIO),
    .ALGORITHM("MATRIX")
  ) u_mat (
    .clk_i(clk),
    .rst_ni(rst_ni),
    .ip(ip),
    .ie(ie),
    .prio(prio),
    .threshold(threshold),
    .irq(mat_irq),
    .irq_id(mat_irq_id)
  );

  always #5 clk = ~clk;

  task automatic expect_eq;
    input string label;
    input int got;
    input int exp;
    begin
      if (got !== exp) begin
        $display("TB_FAIL %s got=%0d exp=%0d t=%0t", label, got, exp, $time);
        $fatal(1, "Mismatch on %s", label);
      end
    end
  endtask

  integer i;
  initial begin
    clk = 0;
    rst_ni = 0;
    ip = 0;
    ie = 0;
    threshold = 0;
    for (i = 0; i < N_SOURCE; i++) begin
      prio[i] = 0;
    end

    repeat (2) @(posedge clk);
    rst_ni = 1;

    ie[0] = 1;
    ip[0] = 1;
    prio[0] = MAX_PRIO;
    threshold = MAX_PRIO;

    repeat (2) @(posedge clk);

    expect_eq("seq_irq", seq_irq, 0);
    expect_eq("seq_irq_id", seq_irq_id, 1);
    expect_eq("mat_irq", mat_irq, 0);
    expect_eq("mat_irq_id", mat_irq_id, 1);

    threshold = MAX_PRIO - 1;
    repeat (2) @(posedge clk);

    expect_eq("seq_irq_after_lower_threshold", seq_irq, 1);
    expect_eq("seq_irq_id_after_lower_threshold", seq_irq_id, 1);
    expect_eq("mat_irq_after_lower_threshold", mat_irq, 1);
    expect_eq("mat_irq_id_after_lower_threshold", mat_irq_id, 1);

    $display("TB_PASS rv_plic_claim_threshold_polling");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/files.f" <<EOF
/home/opentitan/hw/ip/prim/rtl/prim_assert.sv
/home/opentitan/hw/ip/rv_plic/rtl/rv_plic_target.sv
