  if ! grep -q "^TB_PASS ${TEST_NAME}$" "$TB_DIR/sim.log" || \
     grep -q "^TB_FAIL " "$TB_DIR/sim.log" || \
     grep -q "^Fatal:" "$TB_DIR/sim.log"; then
    sim_rc=1
  fi
fi

rc=$compile_rc
if [ "$compile_rc" -eq 0 ]; then
  rc=$sim_rc
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

