#!/bin/bash
cd /home/opentitan || exit 1

export VCS_ARCH_OVERRIDE=linux
set +e
set -o pipefail

TEST_NAME="hmac_window_socket_no_internal_fifo"
TB_DIR="/home/opentitan/.tb_hmac_window_socket"

finish_test() {
  local status="$1"
  local rc="$2"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
  exit "$rc"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import top_pkg::*;
  import tlul_pkg::*;

  logic clk_i;
  logic rst_ni;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  tl_h2d_t tl_win_o [1];
  tl_d2h_t tl_win_i [1];
  hmac_reg_pkg::hmac_reg2hw_t reg2hw;
  hmac_reg_pkg::hmac_hw2reg_t hw2reg;
  int accepted_reqs;

  hmac_reg_top dut (
    .clk_i,
    .rst_ni,
    .tl_i,
    .tl_o,
    .tl_win_o,
    .tl_win_i,
    .reg2hw,
    .hw2reg,
    .devmode_i(1'b0)
  );

  always #5 clk_i = ~clk_i;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    tl_i = '0;
    tl_i.d_ready = 1'b1;
    tl_win_i[0] = '0;
    tl_win_i[0].a_ready = 1'b0;
    hw2reg = '0;
    accepted_reqs = 0;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    @(negedge clk_i);

    tl_i.a_valid = 1'b1;
    tl_i.a_opcode = PutFullData;
    tl_i.a_param = '0;
    tl_i.a_size = 2;
    tl_i.a_source = '0;
    tl_i.a_address = 32'h0000_0800;
    tl_i.a_mask = '1;
    tl_i.a_data = 32'h1234_5678;
    tl_i.a_user = '0;

    repeat (4) begin
      @(posedge clk_i);
      if (tl_i.a_valid && tl_o.a_ready) begin
        accepted_reqs++;
      end
      $display("TRACE cycle=%0t a_ready=%0b win_a_valid=%0b accepted=%0d outstanding_d_valid=%0b",
               $time, tl_o.a_ready, tl_win_o[0].a_valid, accepted_reqs, tl_o.d_valid);
    end

    tl_i.a_valid = 1'b0;
    repeat (2) @(posedge clk_i);

    if (accepted_reqs == 0) begin
      $display("SOCKET_CHECK_PASS accepted_reqs=%0d", accepted_reqs);
      $finish;
    end

    $error("SOCKET_CHECK_FAIL accepted_reqs=%0d", accepted_reqs);
    $fatal(1);
  end
endmodule
