tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set +e

TB_NAME="tlul_adapter_sram_outstanding"
TB_DIR="/home/opentitan/.tb_${TB_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
SIMV="${TB_DIR}/simv"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
`timescale 1ns/1ps

module tb;
  import tlul_pkg::*;

  logic clk_i;
  logic rst_ni;

  tl_h2d_t tl_i;
  tl_d2h_t tl_o;

  logic        req_o;
  logic        gnt_i;
  logic        we_o;
  logic [11:0] addr_o;
  logic [31:0] wdata_o;
  logic [31:0] wmask_o;
  logic [31:0] rdata_i;
  logic        rvalid_i;
  logic [1:0]  rerror_i;

  int accepted_reads;
  int completed_reads;
  int cycle_count;
  logic second_req_seen;
  logic second_req_ready_seen;

  tlul_adapter_sram #(
    .SramAw(12),
    .SramDw(32),
    .Outstanding(1)
  ) dut (
    .clk_i,
    .rst_ni,
    .tl_i,
    .tl_o,
    .req_o,
    .gnt_i,
    .we_o,
    .addr_o,
    .wdata_o,
    .wmask_o,
    .rdata_i,
    .rvalid_i,
    .rerror_i
  );

  always #5 clk_i = ~clk_i;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      rvalid_i <= 1'b0;
      rdata_i  <= '0;
    end else begin
      rvalid_i <= req_o & gnt_i & ~we_o;
      rdata_i  <= {20'hcafe0, addr_o};
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      accepted_reads <= 0;
      completed_reads <= 0;
      cycle_count <= 0;
      second_req_seen <= 1'b0;
      second_req_ready_seen <= 1'b0;
    end else begin
      cycle_count <= cycle_count + 1;

      if (tl_i.a_valid && tl_o.a_ready && (tl_i.a_opcode == Get)) begin
        accepted_reads <= accepted_reads + 1;
      end

      if (tl_o.d_valid && tl_i.d_ready && (tl_o.d_opcode == AccessAckData)) begin
        completed_reads <= completed_reads + 1;
      end

      if (tl_i.a_valid && (tl_i.a_opcode == Get) && (tl_i.a_address == 32'h0000_0004)) begin
        second_req_seen <= 1'b1;
        if (tl_o.a_ready) begin
          second_req_ready_seen <= 1'b1;
        end
      end

      if (cycle_count > 40) begin
        $display("TB_RESULT: FAIL timeout accepted_reads=%0d completed_reads=%0d second_req_ready_seen=%0b",
                 accepted_reads, completed_reads, second_req_ready_seen);
        $fatal(1, "timeout accepted_reads=%0d completed_reads=%0d second_req_ready_seen=%0b",
               accepted_reads, completed_reads, second_req_ready_seen);
      end
    end
  end

  task automatic drive_get(input logic [31:0] addr);
    tl_i.a_valid   <= 1'b1;
    tl_i.a_opcode  <= Get;
    tl_i.a_param   <= '0;
    tl_i.a_size    <= 2'h2;
    tl_i.a_source  <= 8'h1;
    tl_i.a_address <= addr;
    tl_i.a_mask    <= 4'hf;
    tl_i.a_data    <= '0;
    tl_i.a_user    <= '0;
  endtask

  task automatic drive_idle();
    tl_i.a_valid   <= 1'b0;
    tl_i.a_opcode  <= Get;
    tl_i.a_param   <= '0;
    tl_i.a_size    <= '0;
    tl_i.a_source  <= '0;
    tl_i.a_address <= '0;
    tl_i.a_mask    <= '0;
    tl_i.a_data    <= '0;
    tl_i.a_user    <= '0;
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    tl_i = '0;
    gnt_i = 1'b1;
    rerror_i = '0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    tl_i.d_ready = 1'b0;
    @(posedge clk_i);
    drive_get(32'h0000_0000);
    @(posedge clk_i);
    drive_get(32'h0000_0004);
    @(posedge clk_i);
    drive_idle();

    repeat (2) @(posedge clk_i);
    tl_i.d_ready = 1'b1;

    repeat (6) @(posedge clk_i);

    if (!second_req_seen) begin
      $display("TB_RESULT: FAIL second request was not observed on the TL interface");
      $fatal(1, "second request was not observed on the TL interface");
    end
    if (second_req_ready_seen) begin
      $display("TB_RESULT: FAIL second request observed a_ready=1 while Outstanding=1");
      $fatal(1, "second request observed a_ready=1 while Outstanding=1");
    end
    if (accepted_reads != 1) begin
      $display("TB_RESULT: FAIL accepted_reads=%0d", accepted_reads);
      $fatal(1, "accepted_reads=%0d", accepted_reads);
    end
    if (completed_reads != 1) begin
      $display("TB_RESULT: FAIL completed_reads=%0d", completed_reads);
      $fatal(1, "completed_reads=%0d", completed_reads);
    end

    $display("TB_RESULT: PASS accepted_reads=%0d completed_reads=%0d", accepted_reads, completed_reads);
    $finish;
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<EOF
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/hw/top_earlgrey/rtl/top_pkg.sv
/home/opentitan/hw/ip/tlul/rtl/tlul_pkg.sv
/home/opentitan/hw/ip/prim/rtl/prim_fifo_sync.sv
/home/opentitan/hw/ip/tlul/rtl/tlul_err.sv
/home/opentitan/hw/ip/tlul/rtl/tlul_adapter_sram.sv
${TB_DIR}/tb.sv
EOF

vcs -full64 -sverilog -timescale=1ns/1ps -assert svaext \
  -f "${TB_DIR}/files.f" \
  -o "${SIMV}" \
  -l "${COMPILE_LOG}"
compile_rc=$?

if [ "${compile_rc}" -ne 0 ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TB_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "${compile_rc}"
fi

"${SIMV}" -l "${RUN_LOG}"
sim_rc=$?
run_rc=${sim_rc}

if grep -q '^TB_RESULT: PASS' "${RUN_LOG}"; then
  run_rc=0
else
  run_rc=1
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${run_rc}" -eq 0 ]; then
  echo "TEST: ${TB_NAME} ... PASS"
else
  echo "TEST: ${TB_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"
exit "${run_rc}"

resolved_issues.body:
I simulated I2C IP with EEPROM model.
Usually, an I2C host holds SCL to low after a target asserts ACK.
![fnxAG](https://user-images.githubusercontent.com/56853860/75740193-6283f680-5d4a-11ea-9c52-4acecc1ff966.png)

At the simulation, after the target transmits ack signal, I2C changes its state from _PopFmtFifo_ to _Idle_.
You can see "SCL" pulse at this screenshot.
I guess FSM should be changed a little bit to handle the _PopFmtFifo case_ differently from the _stop_ case or the _idle case.

![i2c_glitches](https://user-images.githubusercontent.com/56853860/75739693-f6ed5980-5d48-11ea-8627-e1e0800c3ebb.png)
![I2C_Glithces_2](https://user-images.githubusercontent.com/56853860/75740031-f0131680-5d49-11ea-8752-8bbacf73984c.png)


Test Sequence

		tl_driver.write(i2c_reg_pkg::I2C_TIMING0_OFFSET, {tlow, thigh});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING1_OFFSET, {t_f, t_r});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING2_OFFSET, {thd_sta, tsu_sta});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING3_OFFSET, {thd_dat, tsu_dat});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING4_OFFSET, {t_buf, tsu_sto});
		tl_driver.write(i2c_reg_pkg::I2C_FIFO_CTRL_OFFSET, 32'h00000003);	// FIFO RESET
		tl_driver.write(i2c_reg_pkg::I2C_CTRL_OFFSET, 32'h00000001);		// Enable I2C Host

		@ (posedge clk_i);

		// EEPROM START (DEV : 0xA0, WR)
		start = 1'b1;
		fbyte = 8'ha0;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

		// EEPROM ADDR_MSB = 0x0
		start = 1'b0;
		fbyte = 8'h00;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

		// EEPROM ADDR_LSB = 0x0
		start = 1'b0;
		fbyte = 8'h00;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

                // EEPROM Write Data 0x0 ~ 0x9
		repeat(10) begin
			tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});
			fbyte = fbyte + 1;
		end

                // EEPROM Write Data 0xA and Stop
		stop = 1'b1;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

