tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set -uo pipefail

TB_DIR=/home/opentitan/.tb_i2c_popfmt_glitch
COMPILE_LOG="$TB_DIR/compile.log"
RUN_LOG="$TB_DIR/run.log"
TEST_NAME=i2c_popfmt_glitch

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

report_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

cat > "$TB_DIR/tb.sv" <<'EOF'
`timescale 1ns/1ps

module tb;
  logic clk_i;
  logic rst_ni;
  logic scl_i;
  logic scl_o;
  logic sda_i;
  logic sda_o;
  logic host_enable_i;
  logic fmt_fifo_rvalid_i;
  logic fmt_fifo_rready_o;
  logic [7:0] fmt_byte_i;
  logic fmt_flag_start_before_i;
  logic fmt_flag_stop_after_i;
  logic fmt_flag_read_bytes_i;
  logic fmt_flag_read_continue_i;
  logic fmt_flag_nak_ok_i;
  logic rx_fifo_wvalid_o;
  logic [7:0] rx_fifo_wdata_o;
  logic host_idle_o;
  logic [15:0] thigh_i;
  logic [15:0] tlow_i;
  logic [15:0] t_r_i;
  logic [15:0] t_f_i;
  logic [15:0] thd_sta_i;
  logic [15:0] tsu_sta_i;
  logic [15:0] tsu_sto_i;
  logic [15:0] tsu_dat_i;
  logic [15:0] thd_dat_i;
  logic [15:0] t_buf_i;
  logic [30:0] stretch_timeout_i;
  logic timeout_enable_i;
  logic event_nak_o;
  logic event_scl_interference_o;
  logic event_sda_interference_o;
  logic event_stretch_timeout_o;
  logic event_sda_unstable_o;

  int q_idx;
  int cycle_count;
  bit first_pop_checked;
  bit saw_second_byte_activity;

  always #5 clk_i = ~clk_i;

  always_comb begin
    int eff_idx;
    eff_idx = q_idx;
    if (fmt_fifo_rready_o && q_idx < 2) eff_idx = q_idx + 1;

    fmt_fifo_rvalid_i = (eff_idx < 2);
    fmt_byte_i = 8'h00;
    fmt_flag_start_before_i = 1'b0;
    fmt_flag_stop_after_i = 1'b0;
    fmt_flag_read_bytes_i = 1'b0;
    fmt_flag_read_continue_i = 1'b0;
    fmt_flag_nak_ok_i = 1'b0;

    unique case (eff_idx)
      0: begin
        fmt_byte_i = 8'hA0;
        fmt_flag_start_before_i = 1'b1;
      end
      1: begin
        fmt_byte_i = 8'h00;
        fmt_flag_stop_after_i = 1'b1;
      end
      default: begin
        fmt_fifo_rvalid_i = 1'b0;
      end
    endcase
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_idx <= 0;
      cycle_count <= 0;
      first_pop_checked <= 1'b0;
      saw_second_byte_activity <= 1'b0;
    end else begin
      cycle_count <= cycle_count + 1;

      if (fmt_fifo_rready_o && q_idx < 2) begin
        q_idx <= q_idx + 1;
      end

      if (!first_pop_checked && fmt_fifo_rready_o && q_idx == 0) begin
        first_pop_checked <= 1'b1;
        if (scl_o !== 1'b0) begin
          $display("TB_RESULT: FAIL");
          $display("Detected unexpected SCL high during FIFO pop continuation at cycle %0d", cycle_count);
          $fatal(1, "SCL glitch after first byte ack");
        end
      end

      if (first_pop_checked && !fmt_fifo_rready_o && !host_idle_o) begin
        saw_second_byte_activity <= 1'b1;
      end

      if (saw_second_byte_activity && host_idle_o && q_idx >= 2) begin
        $display("TB_RESULT: PASS");
        $display("Observed clean continuation into second byte without SCL glitch");
        $finish;
      end

      if (cycle_count > 300) begin
        $display("TB_RESULT: FAIL");
        $fatal(1, "Timed out waiting for the second byte transfer");
      end
    end
  end

  assign scl_i = scl_o;
  assign sda_i = sda_o;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    host_enable_i = 1'b0;
    thigh_i = 16'd0;
    tlow_i = 16'd0;
    t_r_i = 16'd0;
    t_f_i = 16'd0;
    thd_sta_i = 16'd0;
    tsu_sta_i = 16'd0;
    tsu_sto_i = 16'd0;
    tsu_dat_i = 16'd0;
    thd_dat_i = 16'd0;
    t_buf_i = 16'd0;
    stretch_timeout_i = 31'd0;
    timeout_enable_i = 1'b0;

    repeat (3) @(posedge clk_i);
    rst_ni = 1'b1;
    host_enable_i = 1'b1;
  end

  i2c_fsm dut (
    .clk_i,
    .rst_ni,
    .scl_i,
    .scl_o,
    .sda_i,
    .sda_o,
    .host_enable_i,
    .fmt_fifo_rvalid_i,
    .fmt_fifo_rready_o,
    .fmt_byte_i,
    .fmt_flag_start_before_i,
    .fmt_flag_stop_after_i,
    .fmt_flag_read_bytes_i,
    .fmt_flag_read_continue_i,
    .fmt_flag_nak_ok_i,
    .rx_fifo_wvalid_o,
    .rx_fifo_wdata_o,
    .host_idle_o,
    .thigh_i,
    .tlow_i,
    .t_r_i,
    .t_f_i,
    .thd_sta_i,
    .tsu_sta_i,
    .tsu_sto_i,
    .tsu_dat_i,
    .thd_dat_i,
    .t_buf_i,
    .stretch_timeout_i,
    .timeout_enable_i,
    .event_nak_o,
    .event_scl_interference_o,
    .event_sda_interference_o,
    .event_stretch_timeout_o,
    .event_sda_unstable_o
  );
endmodule
EOF

timeout 1800 vcs -full64 -sverilog \
  -o "$TB_DIR/simv" \
  -l "$COMPILE_LOG" \
  "$TB_DIR/tb.sv" \
  "/home/opentitan/hw/ip/i2c/rtl/i2c_fsm.sv"
compile_rc=$?
if [ $compile_rc -ne 0 ]; then
  report_result FAIL
  exit $compile_rc
fi

timeout 1800 "$TB_DIR/simv" | tee "$RUN_LOG"
run_rc=$?
if grep -q 'TB_RESULT: FAIL' "$RUN_LOG"; then
  report_result FAIL
  if [ $run_rc -eq 0 ]; then
    run_rc=1
  fi
elif grep -q 'TB_RESULT: PASS' "$RUN_LOG"; then
  report_result PASS
else
  report_result FAIL
  if [ $run_rc -eq 0 ]; then
    run_rc=1
  fi
fi
exit $run_rc

resolved_issues.body:
It is invalid to write to the HMAC FIFO when `hash_start = 0`, however with the current hardware doing so can cause the core to lock up. From my testing this happens when doing a two writes to `MSG_FIFO` after `fifo_depth = 16`.

This isn't ideal behavior since it forces the DIF implementation to track this bit of state in order to prevent a potential deadlock. It would be better for these writes to get treated as a no-op so an invalid state can't lock up the system.

## Steps to reproduce

If you would like to see this behavior for yourself you can checkout my HMAC DIF branch jon-flatley/opentitan@b3a31b01b47cbc7fa9d7eb5162c0fe2a33ba32d4 and apply this patch to set the test to run without setting `hash_start`:

<details>
  <summary>Test patch</summary>
  
  ```patch
