+#include "sw/device/lib/log.h"
 
 #define HMAC_HASH_SIZE_BITS 256u
 #define HMAC_KEY_REG_COUNT (HMAC_HASH_SIZE_BITS / 32)
@@ -115,7 +116,7 @@ dif_hmac_fifo_error_t dif_hmac_fifo_push(const dif_hmac_t *hmac,
     return kDifHmacFifoErrorInvalidArgument;
   }
 
-  if (!hmac->hmac_started) {
+  if (false && !hmac->hmac_started) {
     return kDifHmacFifoErrorInvalidState;
   }
 
@@ -127,6 +128,8 @@ dif_hmac_fifo_error_t dif_hmac_fifo_push(const dif_hmac_t *hmac,
 
   // Bring |data_sent| into alignment so we can use |read32()| in the next loop.
   while (unaligned_bytes > 0 && get_fifo_available_space(hmac) > 0) {
+    LOG_INFO("Unaligned bytes remaining = %d\r\n", unaligned_bytes);
+    LOG_INFO("FIFO depth = %d\r\n", get_fifo_entry_count(hmac));
     mmio_region_write8(hmac->base_addr, HMAC_MSG_FIFO_REG_OFFSET, *data_sent);
