#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="rv_plic_target_irq_id_matches_source_bit"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

print_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  localparam int N_SOURCE = 8;
  localparam int MAX_PRIO = 7;
  localparam int SRCW = $clog2(N_SOURCE + 1);
  localparam int PRIOW = $clog2(MAX_PRIO + 1);

  logic clk_i;
  logic rst_ni;
  logic [N_SOURCE-1:0] ip;
  logic [N_SOURCE-1:0] ie;
  logic [PRIOW-1:0] prio [N_SOURCE];
  logic [PRIOW-1:0] threshold;
  logic irq;
  logic [SRCW-1:0] irq_id;
  integer idx;

  rv_plic_target #(
    .N_SOURCE(N_SOURCE),
    .MAX_PRIO(MAX_PRIO)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .ip(ip),
    .ie(ie),
    .prio(prio),
    .threshold(threshold),
    .irq(irq),
    .irq_id(irq_id)
  );

  always #5 clk_i = ~clk_i;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    ip = '0;
    ie = '0;
    threshold = '0;
    for (idx = 0; idx < N_SOURCE; idx++) begin
      prio[idx] = '0;
    end

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    ie[3] = 1'b1;
    ip[3] = 1'b1;
    prio[3] = 3'd5;

    repeat (2) @(posedge clk_i);

    if (!irq) begin
      $error("Expected irq to assert");
      $fatal(1);
    end

    if (irq_id !== 4'd3) begin
      $error("Expected irq_id 3, got %0d", irq_id);
      $fatal(1);
    end

    $display("Observed irq_id=%0d as expected", irq_id);
    $finish;
  end
endmodule
EOF

vcs -full64 -sverilog -timescale=1ns/1ps \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
