module prim_fifo_sync_empty_tb;
  logic clk_i;
  logic rst_ni;
  logic clr_i;
  logic wvalid;
  logic wready;
  logic [7:0] wdata;
  logic rvalid;
  logic rready;
  logic [7:0] rdata;
  logic depth;

  prim_fifo_sync #(
    .Width(8),
    .Depth(1)
  ) dut (
    .clk_i,
    .rst_ni,
    .clr_i,
    .wvalid,
    .wready,
    .wdata,
    .rvalid,
    .rready,
    .rdata,
    .depth
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic fail(input string msg);
    begin
      $display("TB_FAIL: %s", msg);
      $fatal(1, "%s", msg);
    end
  endtask

  initial begin
    rst_ni = 1'b0;
    clr_i = 1'b0;
    wvalid = 1'b0;
    wdata = '0;
    rready = 1'b0;

    repeat (3) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    wdata = 8'hA5;
    wvalid = 1'b1;

    @(posedge clk_i);
    if (!(wvalid && wready)) fail("write handshake did not complete");

    @(negedge clk_i);
    wvalid = 1'b0;
    #1;
    if (rvalid !== 1'b1) fail($sformatf("expected rvalid after write, got %0b", rvalid));
    if (rdata !== 8'hA5) fail($sformatf("expected queued data 0xA5, got 0x%0h", rdata));

    @(negedge clk_i);
    rready = 1'b1;

    @(posedge clk_i);
    if (!(rvalid && rready)) fail("read handshake did not complete");

    @(negedge clk_i);
    rready = 1'b0;
    #1;
    $display("TB_INFO: after empty rvalid=%0b rdata=0x%0h", rvalid, rdata);
    if (rvalid !== 1'b0) fail($sformatf("expected empty FIFO rvalid=0, got %0b", rvalid));
