cat > "$TB_DIR/arbiter_fairness_tb.sv" <<'EOF'
module arbiter_fairness_tb;
  localparam int N = 4;
  localparam int DW = 1;

  logic clk_i;
  logic rst_ni;
  logic [N-1:0] req_i;
  logic [DW-1:0] data_i [N];
  logic [N-1:0] gnt_o;
  logic [$clog2(N)-1:0] idx_o;
  logic valid_o;
  logic [DW-1:0] data_o;
  logic ready_i;
  integer grant_count;
  integer i;
  integer expected [0:5];

  prim_arbiter_tree #(
    .N(N),
    .DW(DW)
  ) dut (
    .clk_i,
    .rst_ni,
    .req_i,
    .data_i,
    .gnt_o,
    .idx_o,
    .valid_o,
    .data_o,
    .ready_i
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  initial begin
    expected[0] = 0;
    expected[1] = 1;
    expected[2] = 2;
    expected[3] = 0;
    expected[4] = 1;
    expected[5] = 2;
    for (i = 0; i < N; i++) begin
      data_i[i] = '0;
    end

    rst_ni = 1'b0;
    req_i = '0;
    ready_i = 1'b1;
    grant_count = 0;

    repeat (2) @(posedge clk_i);
    @(negedge clk_i);
    rst_ni = 1'b1;
    req_i = 4'b0111;
  end

  always @(posedge clk_i) begin
    if (rst_ni && valid_o && ready_i) begin
      $display("TRACE grant[%0d]=%0d gnt=%b", grant_count, idx_o, gnt_o);
      if (grant_count < 6) begin
        if (idx_o !== expected[grant_count]) begin
          $fatal(1, "grant[%0d] expected %0d got %0d", grant_count, expected[grant_count], idx_o);
        end
      end
      grant_count <= grant_count + 1;
      if (grant_count == 5) begin
        $display("TB_PASS observed expected round-robin order");
        $finish;
      end
    end
  end

  initial begin
    repeat (20) @(posedge clk_i);
    $fatal(1, "timeout waiting for six grants");
  end
endmodule
EOF

