    #1;
    if (intr_o !== 1'b1) begin
      $fatal(1, "intr_o did not assert after one clock delay");
    end

    @(negedge clk_i);
    reg2hw_intr_state_q_i = 1'b0;

    #1;
    if (intr_o !== 1'b1) begin
      $fatal(1, "intr_o deasserted before the next clock edge");
    end

    @(posedge clk_i);
    #1;
    if (intr_o !== 1'b0) begin
      $fatal(1, "intr_o did not clear after one clock delay");
    end

    $finish;
  end
endmodule
EOF

