tb_script:
#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME=otp_ctrl_scrmbl_roundtrip
WORK_CORE_DIR=hw/ip/otp_ctrl/dv/roundtrip_msb
BUILD_ROOT=/home/opentitan/.tb_otp_scrmbl_build
CORE_FILE="${WORK_CORE_DIR}/otp_ctrl_scrmbl_roundtrip_sim.core"
TB_FILE="${WORK_CORE_DIR}/otp_ctrl_scrmbl_roundtrip_tb.sv"
SIM_LOG="${BUILD_ROOT}/sim-vcs/vcs.log"

report_and_exit() {
  local status="$1"
  local code="$2"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${code}"
}

rm -rf "${WORK_CORE_DIR}" "${BUILD_ROOT}"
mkdir -p "${WORK_CORE_DIR}"
export PATH="/opt/synopsys/vcs/T-2022.06-SP2-10/bin:${PATH}"

cat > "${CORE_FILE}" <<'EOF'
CAPI=2:
name: "lowrisc:dv:otp_ctrl_scrmbl_roundtrip_sim:0.1"
description: "OTP scrambler roundtrip sim"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:otp_ctrl_pkg:0.1
      - lowrisc:prim:all
    files:
      - otp_ctrl_scrmbl_roundtrip_tb.sv
      - ../../rtl/otp_ctrl_scrmbl.sv
    file_type: systemVerilogSource

targets:
  sim:
    toplevel: otp_ctrl_scrmbl_roundtrip_tb
    filesets:
      - files_dv
    default_tool: vcs
    tools:
      vcs:
        vcs_options:
          - "-timescale=1ns/1ps"
EOF

cat > "${TB_FILE}" <<'EOF'
module otp_ctrl_scrmbl_roundtrip_tb;
  import otp_ctrl_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i;
  logic rst_ni;
  otp_scrmbl_cmd_e cmd_i;
  logic [ConstSelWidth-1:0] sel_i;
  logic [ScrmblBlockWidth-1:0] data_i;
  logic valid_i;
  logic ready_o;
  logic [ScrmblBlockWidth-1:0] data_o;
  logic valid_o;
  lc_tx_t escalate_en_i;
  logic fsm_err_o;

  otp_ctrl_scrmbl dut (
    .clk_i,
    .rst_ni,
    .cmd_i,
    .sel_i,
    .data_i,
    .valid_i,
    .ready_o,
    .data_o,
    .valid_o,
    .escalate_en_i,
    .fsm_err_o
  );

  always #5 clk_i = ~clk_i;

  task automatic issue_cmd(
      input otp_scrmbl_cmd_e cmd,
      input logic [ConstSelWidth-1:0] sel,
      input logic [ScrmblBlockWidth-1:0] data
  );
    begin
      @(posedge clk_i);
      while (!ready_o) @(posedge clk_i);
      cmd_i <= cmd;
      sel_i <= sel;
      data_i <= data;
      valid_i <= 1'b1;
      @(posedge clk_i);
      valid_i <= 1'b0;
      data_i <= '0;
    end
  endtask

  task automatic wait_result(output logic [ScrmblBlockWidth-1:0] data);
    begin
      do @(posedge clk_i); while (!valid_o);
      data = data_o;
    end
  endtask

  task automatic check_roundtrip(
      input key_sel_e key_sel,
      input logic [ScrmblBlockWidth-1:0] plain
  );
    logic [ScrmblBlockWidth-1:0] cipher;
    logic [ScrmblBlockWidth-1:0] recovered;
    begin
      issue_cmd(Encrypt, key_sel, plain);
      wait_result(cipher);
      issue_cmd(Decrypt, key_sel, cipher);
      wait_result(recovered);
      if (fsm_err_o) begin
        $display("FSM error asserted");
        $fatal(1);
      end
      if (recovered !== plain) begin
        $display("ROUNDTRIP_MISMATCH key=%0d plain=%h cipher=%h recovered=%h",
                 key_sel, plain, cipher, recovered);
        $fatal(1);
      end
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    cmd_i = Encrypt;
    sel_i = '0;
    data_i = '0;
    valid_i = 1'b0;
    escalate_en_i = Off;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    check_roundtrip(Secret0Key, 64'h0123_4567_89ab_cdef);
    check_roundtrip(Secret1Key, 64'hfedc_ba98_7654_3210);
    check_roundtrip(Secret2Key, 64'h0f1e_2d3c_4b5a_6978);

    $display("ROUNDTRIP_PASS");
    $finish;
  end
endmodule
EOF

timeout 900 fusesoc \
  --cores-root . \
  --cores-root "${WORK_CORE_DIR}" \
  run \
  --no-export \
  --build-root "${BUILD_ROOT}" \
  --setup \
  --build \
  --run \
  --target=sim \
  --tool=vcs \
  lowrisc:dv:otp_ctrl_scrmbl_roundtrip_sim:0.1
rc=$?

if [[ ${rc} -eq 124 ]]; then
  echo "[ERROR] FuseSoC/VCS timed out after 900 seconds"
  report_and_exit FAIL 124
fi

if [[ -f "${SIM_LOG}" ]] && grep -Eq '^ROUNDTRIP_PASS$' "${SIM_LOG}"; then
  report_and_exit PASS 0
fi

if [[ -f "${SIM_LOG}" ]]; then
  echo "[ERROR] Simulation failed"
  tail -n 80 "${SIM_LOG}"
else
  echo "[ERROR] FuseSoC run failed before generating ${SIM_LOG}"
fi

report_and_exit FAIL 1

#!/bin/bash
cd /home/opentitan
set +e
set -o pipefail

TEST_NAME="csrng_lc_dft_en_bypass"
TB_DIR="/home/opentitan/.tb_csrng_lc"
BUILD_ROOT="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

mkdir -p "${TB_DIR}"
rm -rf "${BUILD_ROOT}" "${RUN_LOG}"

cat > "${TB_DIR}/csrng_lc_repro.core" <<'EOF'
CAPI=2:
name: "local:tb:csrng_lc_repro:0.1"
description: "csrng lifecycle AES bypass reproducer"
filesets:
  files_rtl:
    depend:
      - lowrisc:ip:csrng
      - lowrisc:ip:lc_ctrl_pkg
      - lowrisc:prim:multibit_sync
    files:
      - checker.sv
      - tb.sv
    file_type: systemVerilogSource
targets:
  default: &default_target
    filesets:
      - files_rtl
    toplevel: tb
  sim:
    <<: *default_target
    default_tool: vcs
    tools:
      vcs:
        vcs_options:
          - "-ntb_opts uvm-1.2"
          - "-debug_access+f"
EOF

cat > "${TB_DIR}/checker.sv" <<'EOF'
module csrng_block_encrypt_chk (
  input logic              clk_i,
  input logic              rst_ni,
  input logic              block_encrypt_bypass_i,
  input logic              block_encrypt_req_i,
  input logic              block_encrypt_rdy_o,
  input logic [127:0]      block_encrypt_v_i,
  input logic [2:0]        block_encrypt_cmd_i,
  input logic [3:0]        block_encrypt_id_i,
  input logic              block_encrypt_ack_o,
  input logic [2:0]        block_encrypt_cmd_o,
  input logic [3:0]        block_encrypt_id_o,
  input logic [127:0]      block_encrypt_v_o
);
  logic [127:0] req_v;
  logic [2:0] req_cmd;
  logic [3:0] req_id;
  logic req_seen;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      req_seen <= 1'b0;
    end else begin
      if (block_encrypt_req_i && block_encrypt_rdy_o) begin
        req_v <= block_encrypt_v_i;
        req_cmd <= block_encrypt_cmd_i;
        req_id <= block_encrypt_id_i;
        req_seen <= 1'b1;
      end

      if (block_encrypt_ack_o && req_seen) begin
        if (block_encrypt_v_o == req_v) begin
          $fatal(1, "block_encrypt bypass must be ignored when lc_dft is Off");
        end
        if (block_encrypt_cmd_o !== req_cmd) begin
          $fatal(1, "block_encrypt cmd mismatch");
        end
        if (block_encrypt_id_o !== req_id) begin
          $fatal(1, "block_encrypt id mismatch");
        end
        req_seen <= 1'b0;
        $finish;
      end
    end
  end
endmodule

bind csrng_block_encrypt csrng_block_encrypt_chk u_csrng_block_encrypt_chk (
  .clk_i,
  .rst_ni,
  .block_encrypt_bypass_i,
  .block_encrypt_req_i,
  .block_encrypt_rdy_o,
  .block_encrypt_v_i,
  .block_encrypt_cmd_i,
  .block_encrypt_id_i,
  .block_encrypt_ack_o,
  .block_encrypt_cmd_o,
  .block_encrypt_id_o,
  .block_encrypt_v_o
);
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import uvm_pkg::*;
  import csrng_pkg::*;
  import csrng_reg_pkg::*;
  import entropy_src_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;

  csrng_reg2hw_t reg2hw;
  csrng_hw2reg_t hw2reg;
  entropy_src_hw_if_req_t entropy_src_hw_if_o;
  entropy_src_hw_if_rsp_t entropy_src_hw_if_i;
  csrng_req_t [1:0] app_i;
  csrng_rsp_t [1:0] app_o;
  logic intr_cs_cmd_req_done_o;
  logic intr_cs_entropy_req_o;
  logic intr_cs_hw_inst_exc_o;
  logic intr_cs_fifo_err_o;
  logic [3:0] lc_dft_force;
  bit lc_dft_forced;

  always #5 clk_i = ~clk_i;

  csrng_core dut (
    .clk_i,
    .rst_ni,
    .reg2hw,
    .hw2reg,
    .efuse_sw_app_enable_i(1'b0),
    .entropy_src_hw_if_o,
    .entropy_src_hw_if_i,
    .csrng_cmd_i(app_i),
    .csrng_cmd_o(app_o),
    .intr_cs_cmd_req_done_o,
    .intr_cs_entropy_req_o,
    .intr_cs_hw_inst_exc_o,
    .intr_cs_fifo_err_o
  );

  task automatic send_cmd_word(input logic [31:0] word);
    reg2hw.cmd_req.q = word;
    reg2hw.cmd_req.qe = 1'b1;
    @(posedge clk_i);
    reg2hw.cmd_req.qe = 1'b0;
    @(posedge clk_i);
  endtask

  initial begin
    reg2hw = '0;
    entropy_src_hw_if_i = '0;
    app_i[0] = CSRNG_REQ_DEFAULT;
    app_i[1] = CSRNG_REQ_DEFAULT;

    lc_dft_force = lc_ctrl_pkg::Off;
    lc_dft_forced = uvm_hdl_force("tb.dut.lc_dft_en_i", lc_dft_force);

    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (4) @(posedge clk_i);

    reg2hw.ctrl.enable.q = 1'b1;
    reg2hw.ctrl.aes_cipher_disable.q = 1'b1;

    send_cmd_word(32'h0000_01c1);
    repeat (12) send_cmd_word(32'h0000_0000);

    repeat (1000) @(posedge clk_i);
    $fatal(1, "timeout waiting for block_encrypt ack");
  end
endmodule
EOF

fusesoc --cores-root /home/opentitan --cores-root "${TB_DIR}" \
  run --no-export \
  --build-root "${BUILD_ROOT}" \
  --target=sim \
  --tool=vcs \
  local:tb:csrng_lc_repro | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
if [ "${rc}" -eq 0 ] && grep -q 'block_encrypt bypass must be ignored when lc_dft is Off' "${RUN_LOG}"; then
  rc=1
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

