#!/bin/bash
cd /home/opentitan || exit 1

set -u
set -o pipefail

TEST_NAME="pwrmgr_escalation_reset_path"
TB_DIR="/home/opentitan/.tb_pwrmgr_escalation"
SETUP_DIR="${TB_DIR}/fusesoc"
BUILD_DIR="${SETUP_DIR}/build/lowrisc_ip_pwrmgr_0.1/default-vcs"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import pwrmgr_pkg::*;
  import pwrmgr_reg_pkg::*;
  import tlul_pkg::*;
  import prim_esc_pkg::*;

  logic clk_i = 1'b0;
  logic clk_slow_i = 1'b0;
  logic rst_ni = 1'b0;
  logic rst_slow_ni = 1'b0;

  tl_h2d_t tl_i = '0;
  tl_d2h_t tl_o;
  pwr_ast_rsp_t pwr_ast_i = PWR_AST_RSP_DEFAULT;
  pwr_ast_req_t pwr_ast_o;
  pwr_rst_rsp_t pwr_rst_i = PWR_RST_RSP_DEFAULT;
  pwr_rst_req_t pwr_rst_o;
  pwr_clk_rsp_t pwr_clk_i = '{clk_status: 1'b1};
  pwr_clk_req_t pwr_clk_o;
  pwr_otp_rsp_t pwr_otp_i = PWR_OTP_RSP_DEFAULT;
  pwr_otp_req_t pwr_otp_o;
  pwr_lc_rsp_t pwr_lc_i = PWR_LC_RSP_DEFAULT;
  pwr_lc_req_t pwr_lc_o;
  pwr_flash_rsp_t pwr_flash_i = PWR_FLASH_RSP_DEFAULT;
  pwr_flash_req_t pwr_flash_o;
  pwr_cpu_t pwr_cpu_i = PWR_CPU_DEFAULT;
  logic [NumWkups-1:0] wakeups_i = '0;
  logic [NumRstReqs-1:0] rstreqs_i = '0;
  esc_tx_t esc_rst_tx_i = ESC_TX_DEFAULT;
  esc_rx_t esc_rst_rx_o;
  logic intr_wakeup_o;

  bit saw_esc_en = 0;
  bit saw_masked_req = 0;
  bit saw_status = 0;

  always #5 clk_i = ~clk_i;
  always #11 clk_slow_i = ~clk_slow_i;

  always @(posedge clk_i) begin
    if (rst_ni) begin
      if (dut.u_esc_rx.esc_en_o === 1'b1) saw_esc_en = 1;
      if (dut.hw2reg.escalate_reset_status.d === 1'b1) saw_status = 1;
    end
  end

  always @(posedge clk_slow_i) begin
    if (rst_slow_ni) begin
      if (dut.slow_peri_reqs_masked.rstreqs[NumRstReqs] === 1'b1) saw_masked_req = 1;
    end
  end

  task automatic drive_escalation;
    begin
      @(negedge clk_i);
      esc_rst_tx_i.esc_p = 1'b1;
      esc_rst_tx_i.esc_n = 1'b0;
      repeat (4) @(posedge clk_i);
      @(negedge clk_i);
      esc_rst_tx_i = ESC_TX_DEFAULT;
    end
  endtask

  initial begin
    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_slow_ni = 1'b1;

    repeat (4) @(posedge clk_i);
    drive_escalation();
    repeat (24) @(posedge clk_i);

    if (!saw_esc_en) begin
      $fatal(1, "No escalation detected");
    end
    if (!saw_masked_req) begin
      $fatal(1, "Escalation reset did not survive slow-domain masking");
    end
    if (!saw_status) begin
      $fatal(1, "Escalate reset status did not assert");
    end

    $display("TB_ESC_PASS");
    $finish;
  end

  pwrmgr dut (
    .clk_slow_i,
    .clk_i,
    .rst_slow_ni,
    .rst_ni,
    .tl_i,
    .tl_o,
    .pwr_ast_i,
    .pwr_ast_o,
    .pwr_rst_i,
    .pwr_rst_o,
    .pwr_clk_o,
    .pwr_clk_i,
    .pwr_otp_i,
    .pwr_otp_o,
    .pwr_lc_i,
    .pwr_lc_o,
    .pwr_flash_o,
    .pwr_flash_i,
    .esc_rst_tx_i,
    .esc_rst_rx_o,
    .pwr_cpu_i,
    .wakeups_i,
    .rstreqs_i,
    .intr_wakeup_o
  );
endmodule
EOF

if [[ ! -f "${BUILD_DIR}/lowrisc_ip_pwrmgr_0.1.scr" ]]; then
  rm -rf "${SETUP_DIR}"
  mkdir -p "${SETUP_DIR}"
  (
    cd "${SETUP_DIR}" || exit 1
    source /etc/opentitan_tools_path.sh >/dev/null 2>&1 || true
    fusesoc --cores-root /home/opentitan run --tool=vcs --setup lowrisc:ip:pwrmgr:0.1
  ) > "${TB_DIR}/fusesoc_setup.log" 2>&1
  setup_rc=$?
  if [[ ${setup_rc} -ne 0 ]]; then
    emit_result "FAIL"
    exit "${setup_rc}"
  fi
fi

awk '
  /lowrisc_ip_pwrmgr_pkg_0\.1\/rtl\/pwrmgr_pkg\.sv/ && !done {
    print "/home/opentitan/hw/top_earlgrey/ip/pwrmgr/rtl/autogen/pwrmgr_reg_pkg.sv"
    done = 1
  }
  { print }
  END {
    print "/home/opentitan/hw/top_earlgrey/ip/pwrmgr/rtl/autogen/pwrmgr_reg_top.sv"
    print "/home/opentitan/.tb_pwrmgr_escalation/tb.sv"
  }
' "${BUILD_DIR}/lowrisc_ip_pwrmgr_0.1.scr" > "${TB_DIR}/files.f"

rm -rf "${TB_DIR}/simv" "${TB_DIR}/simv.daidir" "${TB_DIR}/csrc"

(
  cd "${BUILD_DIR}" || exit 1
  vcs -full64 -sverilog -top tb -f "${TB_DIR}/files.f" \
    -o "${TB_DIR}/simv" -l "${COMPILE_LOG}"
) > >(tee "${TB_DIR}/compile.stdout") 2>&1
compile_rc=${PIPESTATUS[0]}

run_rc=1
if [[ ${compile_rc} -eq 0 ]]; then
  "${TB_DIR}/simv" -l "${RUN_LOG}" > >(tee "${TB_DIR}/run.stdout") 2>&1
  run_rc=${PIPESTATUS[0]}
fi

if [[ ${compile_rc} -eq 0 && ${run_rc} -eq 0 ]]; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
if [[ ${compile_rc} -ne 0 ]]; then
  exit "${compile_rc}"
fi
exit "${run_rc}"

