#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="prim_fifo_sync_reset_ready"
TB_DIR="/home/opentitan/.tb_prim_fifo_reset"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  logic clk_i;
  logic rst_ni;
  logic clr_i;
  logic wvalid_i;
  logic wready_o;
  logic [7:0] wdata_i;
  logic rvalid_o;
  logic rready_i;
  logic [7:0] rdata_o;
  logic [2:0] depth_o;
  int failures;

  prim_fifo_sync #(
    .Width(8),
    .Pass(1'b0),
    .Depth(4),
    .OutputZeroIfEmpty(1'b1)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .clr_i(clr_i),
    .wvalid_i(wvalid_i),
    .wready_o(wready_o),
    .wdata_i(wdata_i),
    .rvalid_o(rvalid_o),
    .rready_i(rready_i),
    .rdata_o(rdata_o),
    .depth_o(depth_o)
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic check_cond(bit cond, string msg);
    if (!cond) begin
      failures++;
      $display("TB_CHECK_FAIL: %s", msg);
    end
  endtask

  initial begin
    failures = 0;
    rst_ni = 1'b0;
    clr_i = 1'b0;
    wvalid_i = 1'b0;
    wdata_i = 8'h00;
    rready_i = 1'b0;

    #1;
    check_cond(wready_o === 1'b0, $sformatf("wready_o should stay low during reset, got %b", wready_o));
    check_cond(rvalid_o === 1'b0, $sformatf("rvalid_o should stay low during reset, got %b", rvalid_o));
    check_cond(depth_o === 3'd0, $sformatf("depth_o should remain zero during reset, got %0d", depth_o));

    repeat (2) @(posedge clk_i);
    check_cond(wready_o === 1'b0, $sformatf("wready_o should still be low while reset is asserted, got %b", wready_o));
    check_cond(rvalid_o === 1'b0, $sformatf("rvalid_o should still be low while reset is asserted, got %b", rvalid_o));
    check_cond(depth_o === 3'd0, $sformatf("depth_o should remain zero while reset is asserted, got %0d", depth_o));

    rst_ni = 1'b1;
    @(posedge clk_i);
    #1;
    check_cond(wready_o === 1'b1, $sformatf("wready_o should recover after reset release, got %b", wready_o));
    check_cond(rvalid_o === 1'b0, $sformatf("rvalid_o should remain low when FIFO is empty, got %b", rvalid_o));
    check_cond(depth_o === 3'd0, $sformatf("depth_o should remain zero after reset release, got %0d", depth_o));

    if (failures != 0) begin
      $fatal(1, "prim_fifo_sync reset behavior mismatch (%0d failures)", failures);
    end

    $display("TB_CHECK_PASS: prim_fifo_sync reset behavior matches expectation");
    $finish;
  end
endmodule
EOF

