#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="keymgr_key_version_error"
TB_DIR="/home/opentitan/.tb_keymgr_keyver"
LOG="$TB_DIR/dvsim.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > hw/ip/keymgr/dv/env/seq_lib/keymgr_key_version_error_vseq.sv <<'SVEOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_key_version_error_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_key_version_error_vseq)
  `uvm_object_new

  constraint do_op_before_init_c {
    do_op_before_init == 0;
  }

  virtual task wait_for_fail_status();
    csr_spinwait(.ptr(ral.op_status.status), .exp_data(keymgr_pkg::OpWip),
                 .compare_op(CompareOpNe), .spinwait_delay_ns(100));
    csr_rd_check(.ptr(ral.op_status.status), .compare_value(keymgr_pkg::OpDoneFail));
    check_interrupts(.interrupts(1 << IntrOpDone), .check_set(1));
  endtask

  virtual task body();
    `uvm_info(`gfn, "Drive deterministic key version error", UVM_MEDIUM)

    keymgr_advance(.wait_done(1));
    keymgr_advance(.wait_done(1));

    ral.max_creator_key_ver.set(32'h0);
    csr_update(.csr(ral.max_creator_key_ver));
    ral.key_version.set(32'h1);
    csr_update(.csr(ral.key_version));

    ral.control.start.set(1'b1);
    ral.control.operation.set(keymgr_pkg::OpGenSwOut);
    ral.control.dest_sel.set(keymgr_pkg::None);
    csr_update(.csr(ral.control));
    ral.control.start.set(1'b0);

    wait_for_fail_status();
  endtask
endclass : keymgr_key_version_error_vseq
SVEOF

