  if [[ -f "$BUILD_LOG" ]]; then
    cat "$BUILD_LOG"
  fi
}

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
