  logic rvalid_i;
  logic [1:0] rerror_i;

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  initial begin
    rst_ni = 1'b0;
    tl_i = '0;
    gnt_i = 1'b0;
    rdata_i = '0;
    rvalid_i = 1'b0;
    rerror_i = '0;
    #20;
    rst_ni = 1'b1;
    #20;
    $display("TB_PASS");
    $finish;
  end

  tlul_adapter_sram #(
    .SramAw(8),
    .SramDw(32),
    .Outstanding(1),
    .ByteAccess(0),
    .ErrOnRead(0),
    .EnableDataIntgPt(1)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .tl_i(tl_i),
    .tl_o(tl_o),
    .en_ifetch_i(InstrDis),
    .req_o(req_o),
    .gnt_i(gnt_i),
    .we_o(we_o),
    .addr_o(addr_o),
    .wdata_o(wdata_o),
    .wmask_o(wmask_o),
    .intg_error_o(intg_error_o),
    .rdata_i(rdata_i),
    .rvalid_i(rvalid_i),
    .rerror_i(rerror_i)
  );
endmodule
EOF

cat > "$TB_ROOT/tlul_adapter_sram_intg_pt_tb.core" <<'EOF'
