rm -rf "$SCRATCH"
python util/dvsim/dvsim.py \
  "$TB_ROOT/tlul_adapter_sram_intg_pt_sim_cfg.hjson" \
  -i build_check \
  -t vcs \
  --build-only \
  --fixed-seed 1 \
  --max-parallel 1 \
  --scratch-root "$SCRATCH" \
  > "$RUN_LOG" 2>&1
rc=$?

if [[ -x "$SIMV" ]]; then
  print_logs
  emit_result "PASS"
  exit 0
