rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/stubs.sv" <<'EOF'
package prim_util_pkg;
  function automatic integer vbits(input integer value);
    if (value <= 1) begin
      vbits = 1;
    end else begin
      vbits = $clog2(value);
    end
  endfunction
endpackage

package otp_ctrl_reg_pkg;
  parameter int OtpByteAddrWidth = 11;
  parameter int NumSwCfgWindowWords = 16;
endpackage

package lc_ctrl_pkg;
  parameter int TxWidth = 4;
  typedef enum logic [TxWidth-1:0] {
    On  = 4'b1010,
    Off = 4'b0101
  } lc_tx_e;
  typedef lc_tx_e lc_tx_t;
endpackage

package prim_otp_pkg;
  typedef enum logic [1:0] {
    Read  = 2'b00,
    Write = 2'b01
  } cmd_e;

  typedef enum logic [2:0] {
    NoError              = 3'h0,
    MacroError           = 3'h1,
    MacroEccCorrError    = 3'h2,
    MacroEccUncorrError  = 3'h3,
    MacroWriteBlankError = 3'h4,
    AccessError          = 3'h5,
    CheckFailError       = 3'h6,
    FsmStateError        = 3'h7
  } err_e;
endpackage

package otp_ctrl_pkg;
  import prim_util_pkg::vbits;
  import otp_ctrl_reg_pkg::*;

  parameter int ScrmblKeyWidth = 128;
  parameter int ScrmblBlockWidth = 64;
  parameter int SwWindowAddrWidth = vbits(NumSwCfgWindowWords);

  parameter int OtpWidth = 16;
  parameter int OtpAddrWidth = OtpByteAddrWidth - $clog2(OtpWidth/8);
  parameter int OtpSizeWidth = 2;
  parameter int OtpIfWidth = (2**OtpSizeWidth) * OtpWidth;
  parameter int OtpAddrShift = OtpByteAddrWidth - OtpAddrWidth;

  typedef enum logic [7:0] {
    Unlocked = 8'h5A,
    Locked   = 8'hA5
  } access_e;

  typedef struct packed {
    access_e read_lock;
    access_e write_lock;
  } part_access_t;

  typedef enum logic [2:0] {
    NoError              = 3'h0,
    MacroError           = 3'h1,
    MacroEccCorrError    = 3'h2,
    MacroEccUncorrError  = 3'h3,
    MacroWriteBlankError = 3'h4,
    AccessError          = 3'h5,
    CheckFailError       = 3'h6,
    FsmStateError        = 3'h7
  } otp_err_e;
endpackage

package otp_ctrl_part_pkg;
  import otp_ctrl_reg_pkg::*;
  import otp_ctrl_pkg::*;

  typedef enum logic [1:0] {
    Unbuffered,
    Buffered,
    LifeCycle
  } part_variant_e;

  typedef struct packed {
    part_variant_e variant;
    logic [OtpByteAddrWidth-1:0] offset;
    logic [OtpByteAddrWidth-1:0] size;
    logic [1:0] key_sel;
    logic secret;
    logic hw_digest;
    logic write_lock;
    logic read_lock;
  } part_info_t;
endpackage

module prim_buf (
  input  logic in_i,
  output logic out_o
);
  assign out_o = in_i;
endmodule

module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else begin
      q_o <= d_i;
    end
  end
endmodule

module otp_ctrl_ecc_reg #(
  parameter int Width = 64,
  parameter int Depth = 1
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic             wren_i,
  input  logic [31:0]      addr_i,
  input  logic [Width-1:0] wdata_i,
  output logic [Width-1:0] data_o,
  output logic             ecc_err_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      data_o <= '0;
    end else if (wren_i) begin
      data_o <= wdata_i;
    end
  end

  assign ecc_err_o = 1'b0;
endmodule
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
`timescale 1ns/1ps

module tb;
  localparam otp_ctrl_part_pkg::part_info_t PartInfo = '{
    variant:    otp_ctrl_part_pkg::Unbuffered,
    offset:     11'd0,
    size:       11'd64,
    key_sel:    2'b00,
    secret:     1'b0,
    hw_digest:  1'b0,
    write_lock: 1'b0,
    read_lock:  1'b0
  };

  logic clk_i;
  logic rst_ni;
  logic init_req_i;
  logic init_done_o;
  lc_ctrl_pkg::lc_tx_t escalate_en_i;
  otp_ctrl_pkg::otp_err_e error_o;
  otp_ctrl_pkg::part_access_t access_i;
  otp_ctrl_pkg::part_access_t access_o;
  logic [otp_ctrl_pkg::ScrmblBlockWidth-1:0] digest_o;
  logic tlul_req_i;
  logic tlul_gnt_o;
  logic [otp_ctrl_pkg::SwWindowAddrWidth-1:0] tlul_addr_i;
  logic [1:0] tlul_rerror_o;
  logic tlul_rvalid_o;
  logic [31:0] tlul_rdata_o;
  logic otp_req_o;
  prim_otp_pkg::cmd_e otp_cmd_o;
  logic [otp_ctrl_pkg::OtpSizeWidth-1:0] otp_size_o;
  logic [otp_ctrl_pkg::OtpIfWidth-1:0] otp_wdata_o;
  logic [otp_ctrl_pkg::OtpAddrWidth-1:0] otp_addr_o;
  logic otp_gnt_i;
  logic otp_rvalid_i;
  logic [otp_ctrl_pkg::ScrmblBlockWidth-1:0] otp_rdata_i;
  prim_otp_pkg::err_e otp_err_i;

  otp_ctrl_part_unbuf #(
    .Info(PartInfo)
  ) dut (
    .clk_i,
    .rst_ni,
    .init_req_i,
    .init_done_o,
    .escalate_en_i,
    .error_o,
    .access_i,
    .access_o,
    .digest_o,
    .tlul_req_i,
    .tlul_gnt_o,
    .tlul_addr_i,
    .tlul_rerror_o,
    .tlul_rvalid_o,
    .tlul_rdata_o,
    .otp_req_o,
    .otp_cmd_o,
    .otp_size_o,
    .otp_wdata_o,
    .otp_addr_o,
    .otp_gnt_i,
    .otp_rvalid_i,
    .otp_rdata_i,
    .otp_err_i
  );

  initial begin
    clk_i = 1'b0;
    forever #5 clk_i = ~clk_i;
  end

  task automatic wait_for_init_done;
    int i;
    begin
      for (i = 0; i < 10; i++) begin
        @(negedge clk_i);
        #1;
        if (init_done_o === 1'b1) begin
          return;
        end
      end
      $fatal(1, "Partition failed to reach IdleSt after init");
    end
  endtask

  initial begin
    bit saw_gnt;
    int i;

    rst_ni = 1'b0;
    init_req_i = 1'b0;
    escalate_en_i = lc_ctrl_pkg::Off;
    access_i = '{read_lock: otp_ctrl_pkg::Unlocked, write_lock: otp_ctrl_pkg::Unlocked};
    tlul_req_i = 1'b0;
    tlul_addr_i = '0;
    otp_gnt_i = 1'b0;
    otp_rvalid_i = 1'b0;
    otp_rdata_i = '0;
    otp_err_i = prim_otp_pkg::NoError;
    saw_gnt = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    init_req_i = 1'b1;

    @(negedge clk_i);
    init_req_i = 1'b0;
    otp_gnt_i = 1'b1;

    @(negedge clk_i);
    otp_gnt_i = 1'b0;
    otp_rvalid_i = 1'b1;
    otp_rdata_i = 64'h0;
    otp_err_i = prim_otp_pkg::NoError;

    @(negedge clk_i);
    otp_rvalid_i = 1'b0;

    wait_for_init_done();

    escalate_en_i = lc_ctrl_pkg::On;
    @(negedge clk_i);
    escalate_en_i = lc_ctrl_pkg::Off;

    @(negedge clk_i);
    #1;
    if (error_o !== otp_ctrl_pkg::FsmStateError) begin
      $fatal(1, "Expected ErrorSt after escalate, got error_o=%0d", error_o);
    end

    tlul_req_i = 1'b1;
    #1;
    saw_gnt = tlul_gnt_o;

    @(posedge clk_i);
    tlul_req_i = 1'b0;

    for (i = 0; i < 6; i++) begin
      @(negedge clk_i);
      #1;
      saw_gnt |= tlul_gnt_o;
      if (tlul_rvalid_o === 1'b1) begin
        if (tlul_rerror_o !== 2'b11) begin
          $fatal(1, "Expected bus error response, got tlul_rerror_o=%b", tlul_rerror_o);
        end
        if (tlul_rdata_o !== 32'h0000_0000) begin
          $fatal(1, "Expected zero data on bus error, got tlul_rdata_o=0x%08x", tlul_rdata_o);
        end
        $display("TB_PASS: saw_gnt=%0b tlul_rerror_o=%b", saw_gnt, tlul_rerror_o);
        $finish;
      end
    end

    $fatal(1, "Timed out waiting for tlul_rvalid_o in ErrorSt; saw_gnt=%0b", saw_gnt);
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<EOF
+incdir+/home/opentitan/hw/ip/prim/rtl
${TB_DIR}/stubs.sv
/home/opentitan/hw/ip/otp_ctrl/rtl/otp_ctrl_part_unbuf.sv
${TB_DIR}/tb.sv
EOF

vcs -full64 -sverilog -timescale=1ns/1ps +define+VERILATOR \
  -Mdir="${TB_DIR}/csrc" \
  -o "${TB_DIR}/simv" \
  -f "${TB_DIR}/files.f" \
  -l "${BUILD_LOG}"
compile_rc=$?

if [ "${compile_rc}" -ne 0 ]; then
  emit_result "FAIL"
  exit "${compile_rc}"
fi

"${TB_DIR}/simv" -l "${RUN_LOG}"
run_rc=$?

if [ "${run_rc}" -eq 0 ] && grep -q "TB_PASS:" "${RUN_LOG}"; then
  emit_result "PASS"
else
  emit_result "FAIL"
  if [ "${run_rc}" -eq 0 ]; then
    run_rc=1
  fi
fi

exit "${run_rc}"

