#!/bin/bash
set -u

cd /home/opentitan || exit 1

TEST_NAME="keymgr_input_checks_health_state_all_ones"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/edn_pkg_stub.sv" <<'EOF'
package edn_pkg;
  parameter int unsigned ENDPOINT_BUS_WIDTH = 32;
endpackage
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import keymgr_pkg::*;

  logic [2**StageWidth-1:0][31:0] max_key_versions;
  keymgr_stage_e stage_sel;
  hw_key_req_t key;
  logic [31:0] key_version;
  logic [KeyWidth-1:0] creator_seed;
  logic [KeyWidth-1:0] owner_seed;
  logic [DevIdWidth-1:0] devid;
  logic [HealthStateWidth-1:0] health_state;
  logic creator_seed_vld;
  logic owner_seed_vld;
  logic devid_vld;
  logic health_state_vld;
  logic key_version_vld;
  logic key_vld;

  keymgr_input_checks dut (
    .max_key_versions_i(max_key_versions),
    .stage_sel_i(stage_sel),
    .key_i(key),
    .key_version_i(key_version),
    .creator_seed_i(creator_seed),
    .owner_seed_i(owner_seed),
    .devid_i(devid),
    .health_state_i(health_state),
    .creator_seed_vld_o(creator_seed_vld),
    .owner_seed_vld_o(owner_seed_vld),
    .devid_vld_o(devid_vld),
    .health_state_vld_o(health_state_vld),
    .key_version_vld_o(key_version_vld),
    .key_vld_o(key_vld)
  );

  initial begin
    max_key_versions = '0;
    stage_sel = Creator;
    key = '{
      valid: 1'b0,
      key_share0: 256'h1,
      key_share1: 256'h2
    };
    key_version = 32'd0;
    creator_seed = 256'h3;
    owner_seed = 256'h4;
    devid = 256'h5;
    health_state = {HealthStateWidth{1'b1}};

    #1;

    if (creator_seed_vld !== 1'b1 || owner_seed_vld !== 1'b1 ||
        devid_vld !== 1'b1 || key_version_vld !== 1'b1 || key_vld !== 1'b1) begin
      $display("TB_RESULT: FAIL_SANITY");
      $fatal(1, "Sanity check failed for valid baseline inputs");
    end

    if (health_state_vld !== 1'b0) begin
      $display("TB_RESULT: FAIL_BAD_HEALTH_STATE");
      $fatal(1, "Expected all-ones health_state_i to be rejected");
    end

    $display("TB_RESULT: PASS");
    $finish;
  end
endmodule
EOF

set +e
vcs -full64 -sverilog -timescale=1ns/1ps \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  -y /home/opentitan/hw/ip/prim/rtl \
  -y /home/opentitan/hw/ip/keymgr/rtl \
  +libext+.sv \
  "${TB_DIR}/edn_pkg_stub.sv" \
  /home/opentitan/hw/ip/keymgr/rtl/keymgr_reg_pkg.sv \
  /home/opentitan/hw/ip/keymgr/rtl/keymgr_pkg.sv \
  /home/opentitan/hw/ip/keymgr/rtl/keymgr_input_checks.sv \
  "${TB_DIR}/tb.sv" \
  -top tb \
  -Mdir="${TB_DIR}/csrc" \
  -o "${TB_DIR}/simv" \
  -l "${TB_DIR}/compile.log"
rc=$?

if [ "${rc}" -eq 0 ]; then
  "${TB_DIR}/simv" -l "${TB_DIR}/run.log"
  rc=$?
  if grep -q "TB_RESULT: PASS" "${TB_DIR}/run.log" && \
     ! grep -q "TB_RESULT: FAIL" "${TB_DIR}/run.log"; then
    rc=0
  else
    rc=1
  fi
fi
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

#!/bin/bash
set -euo pipefail

cd /home/opentitan

python - <<'PY'
from pathlib import Path

root = Path("/home/opentitan")

utils_path = root / "util/dvsim/utils.py"
utils_text = utils_path.read_text()
old = """    html_text = transform(html_text,
                          external_styles=css_file,
                          cssutils_logging_level=log.ERROR)
"""
new = """    html_text = transform(html_text,
                          external_styles=css_file,
                          cssutils_logging_level=log.ERROR,
                          allow_loading_external_files=True)
"""
if old in utils_text and "allow_loading_external_files=True" not in utils_text:
    utils_path.write_text(utils_text.replace(old, new))

vseq_path = root / "hw/ip/otp_ctrl/dv/env/seq_lib/otp_ctrl_local_escalation_vseq.sv"
vseq_path.write_text("""// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

// Trigger a fatal background check timeout and verify that OTP invalidates
// all buffered outputs, not just the FSM that observed the fatal condition.
class otp_ctrl_local_escalation_vseq extends otp_ctrl_base_vseq;
  `uvm_object_utils(otp_ctrl_local_escalation_vseq)

  `uvm_object_new

  localparam uint CheckPeriod       = 1;
  localparam uint CheckWaitCycles   = ((CheckPeriod + 1) << 8) + 10;
  localparam uint EscalationTimeout = 50;

  task body();
    bit alert_seen;
    bit outputs_invalidated;

    cfg.en_scb = 0;

    `DV_CHECK_EQ(cfg.otp_ctrl_vif.otp_hw_cfg_o.valid, lc_ctrl_pkg::On)
    `DV_CHECK_EQ(cfg.otp_ctrl_vif.lc_data_o.valid, 1'b1)

    csr_wr(ral.integrity_check_period, CheckPeriod);

    csr_spinwait(.ptr(ral.status.check_pending),
                 .exp_data(1),
                 .timeout_ns(cfg.clk_rst_vif.clk_period_ps / 1000 * CheckWaitCycles));
    csr_spinwait(.ptr(ral.status.check_pending), .exp_data(0));

    csr_wr(ral.check_timeout, 1);

    repeat (CheckWaitCycles) begin
      if (cfg.m_alert_agent_cfg["fatal_check_error"].vif.get_alert()) begin
        alert_seen = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    `DV_CHECK_FATAL(alert_seen, "Timeout waiting for fatal_check_error")
    check_fatal_alert_nonblocking("fatal_check_error");

    repeat (EscalationTimeout) begin
      if (cfg.otp_ctrl_vif.otp_hw_cfg_o.valid == lc_ctrl_pkg::Off &&
          cfg.otp_ctrl_vif.lc_data_o.valid == 1'b0) begin
        outputs_invalidated = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    `DV_CHECK_FATAL(outputs_invalidated,
                    "Timed out waiting for OTP outputs to invalidate after a fatal alert")
  endtask

  virtual task post_start();
    if (do_apply_reset) begin
      dut_init();
    end else wait(0);

    #1ps;
    cfg.en_scb = 1;
    super.post_start();
  endtask
endclass
