tb_script:
#!/bin/bash
cd /home/opentitan || exit 1

TEST_NAME="entropy_src_esfinal_full_drop"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
RUN_LOG="${TB_DIR}/fusesoc_run.log"
BUILD_ROOT="${TB_DIR}/build"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}/tb"

cat > "${TB_DIR}/entropy_src_drop_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:entropy_src_drop_tb:0.1"
description: "Minimal entropy_src esfinal-full reproducer"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:entropy_src:0.1
    files:
      - tb/entropy_src_drop_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: entropy_src_drop_tb
    filesets:
      - files_dv
    tools:
      vcs:
        vcs_options:
          - +warn=noLNX_OS_VERUN
EOF

cat > "${TB_DIR}/tb/entropy_src_drop_tb.sv" <<'EOF'
module entropy_src_drop_tb;
  import entropy_src_pkg::*;
  import entropy_src_reg_pkg::*;

  logic clk_i;
  logic rst_ni;

  entropy_src_reg2hw_t reg2hw = '0;
  entropy_src_hw2reg_t hw2reg;

  logic efuse_es_sw_reg_en_i = 1'b0;
  logic rng_fips_o;

  entropy_src_hw_if_req_t entropy_src_hw_if_i = ENTROPY_SRC_HW_IF_REQ_DEFAULT;
  entropy_src_hw_if_rsp_t entropy_src_hw_if_o;

  entropy_src_rng_req_t entropy_src_rng_o;
  entropy_src_rng_rsp_t entropy_src_rng_i = ENTROPY_SRC_RNG_RSP_DEFAULT;

  cs_aes_halt_req_t cs_aes_halt_o;
  cs_aes_halt_rsp_t cs_aes_halt_i = CS_AES_HALT_RSP_DEFAULT;

  entropy_src_xht_req_t entropy_src_xht_o;
  entropy_src_xht_rsp_t entropy_src_xht_i = ENTROPY_SRC_XHT_RSP_DEFAULT;

  logic recov_alert_test_o;
  logic fatal_alert_test_o;
  logic recov_alert_o;
  logic fatal_alert_o;
  logic intr_es_entropy_valid_o;
  logic intr_es_health_test_failed_o;
  logic intr_es_fatal_err_o;

  entropy_src_core dut (
    .clk_i,
    .rst_ni,
    .reg2hw,
    .hw2reg,
    .efuse_es_sw_reg_en_i,
    .rng_fips_o,
    .entropy_src_hw_if_i,
    .entropy_src_hw_if_o,
    .entropy_src_rng_o,
    .entropy_src_rng_i,
    .cs_aes_halt_o,
    .cs_aes_halt_i,
    .entropy_src_xht_o,
    .entropy_src_xht_i,
    .recov_alert_test_o,
    .fatal_alert_test_o,
    .recov_alert_o,
    .fatal_alert_o,
    .intr_es_entropy_valid_o,
    .intr_es_health_test_failed_o,
    .intr_es_fatal_err_o
  );

  always #5 clk_i = ~clk_i;

  task automatic expect_true(bit cond, string msg);
    if (!cond) begin
      $display("TB_FAIL: %s", msg);
      $fatal(1);
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;

    // Drive the bug trigger point directly through the compiled RTL hierarchy.
    force dut.es_enable = 1'b1;
    force dut.es_bypass_mode = 1'b0;
    force dut.any_fail_pulse = 1'b0;
    force dut.health_test_done_pulse = 1'b0;
    force dut.sha3_state_vld = 1'b0;
    force dut.pfifo_precon_pop = 1'b1;
    force dut.sha3_msgfifo_ready = 1'b1;
    force dut.cs_aes_halt_req = 1'b0;
    force dut.sfifo_esfinal_full = 1'b1;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    #1;
    expect_true(dut.pfifo_cond_push === 1'b0,
                "pfifo_cond_push must stay low when sfifo_esfinal_full is asserted");

    @(posedge clk_i);
    #1;
    expect_true(dut.sha3_start === 1'b0,
                "sha3_start must stay low while sfifo_esfinal_full is asserted");

    $display("TB_PASS: esfinal-full path blocks conditioner push and keeps SHA3 idle");
    $finish;
  end
endmodule
EOF

set +e
timeout 1700s fusesoc \
  --cores-root /home/opentitan \
  --cores-root "${TB_DIR}" \
  run \
  --build-root "${BUILD_ROOT}" \
  --target=sim \
  --tool=vcs \
  lowrisc:dv:entropy_src_drop_tb:0.1 2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ ${rc} -eq 0 ]] && grep -q "TB_PASS:" "${RUN_LOG}" && ! grep -q "TB_FAIL:" "${RUN_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

