#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="aon_timer_low_power_count"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/lc_ctrl_pkg_stub.sv" <<'EOF'
package lc_ctrl_pkg;
  parameter int TxWidth = 4;

  typedef enum logic [TxWidth-1:0] {
    On  = 4'b1010,
    Off = 4'b0101
  } lc_tx_e;

  typedef logic [TxWidth-1:0] lc_tx_t;
endpackage
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
`timescale 1ns/1ps

module tb;
  import lc_ctrl_pkg::*;

  logic clk_aon_i = 1'b0;
  logic rst_aon_ni = 1'b0;
  lc_tx_t [2:0] lc_gate_i;
  logic sleep_mode_i;

  logic wkup_enable_o;
  logic [11:0] wkup_prescaler_o;
  logic [31:0] wkup_thold_o;
  logic [31:0] wkup_count_o;
  logic wdog_enable_o;
  logic wdog_pause_o;
  logic [31:0] wdog_bark_thold_o;
  logic [31:0] wdog_bite_thold_o;
  logic [31:0] wdog_count_o;

  logic wkup_ctrl_reg_wr_i;
  logic [12:0] wkup_ctrl_wr_data_i;
  logic wkup_thold_reg_wr_i;
  logic [31:0] wkup_thold_wr_data_i;
  logic wkup_count_reg_wr_i;
  logic [31:0] wkup_count_wr_data_i;
  logic wdog_ctrl_reg_wr_i;
  logic [1:0] wdog_ctrl_wr_data_i;
  logic wdog_bark_thold_reg_wr_i;
  logic [31:0] wdog_bark_thold_wr_data_i;
  logic wdog_bite_thold_reg_wr_i;
  logic [31:0] wdog_bite_thold_wr_data_i;
  logic wdog_count_reg_wr_i;
  logic [31:0] wdog_count_wr_data_i;

  logic wkup_intr_o;
  logic wdog_intr_o;
  logic wdog_reset_req_o;

  bit saw_wkup_intr;
  logic [31:0] off_count;
  logic [31:0] on_count;

  always #5 clk_aon_i = ~clk_aon_i;

  always @(posedge clk_aon_i) begin
    if (wkup_intr_o) saw_wkup_intr = 1'b1;
  end

  task automatic clear_writes;
    begin
      wkup_ctrl_reg_wr_i = 1'b0;
      wkup_ctrl_wr_data_i = '0;
      wkup_thold_reg_wr_i = 1'b0;
      wkup_thold_wr_data_i = '0;
      wkup_count_reg_wr_i = 1'b0;
      wkup_count_wr_data_i = '0;
      wdog_ctrl_reg_wr_i = 1'b0;
      wdog_ctrl_wr_data_i = '0;
      wdog_bark_thold_reg_wr_i = 1'b0;
      wdog_bark_thold_wr_data_i = '0;
      wdog_bite_thold_reg_wr_i = 1'b0;
      wdog_bite_thold_wr_data_i = '0;
      wdog_count_reg_wr_i = 1'b0;
      wdog_count_wr_data_i = '0;
    end
  endtask

  task automatic pulse_wkup_ctrl(input logic [11:0] prescaler, input logic enable);
    begin
      @(negedge clk_aon_i);
      wkup_ctrl_wr_data_i = {prescaler, enable};
      wkup_ctrl_reg_wr_i = 1'b1;
      @(negedge clk_aon_i);
      wkup_ctrl_reg_wr_i = 1'b0;
      wkup_ctrl_wr_data_i = '0;
    end
  endtask

  task automatic pulse_wkup_thold(input logic [31:0] value);
    begin
      @(negedge clk_aon_i);
      wkup_thold_wr_data_i = value;
      wkup_thold_reg_wr_i = 1'b1;
      @(negedge clk_aon_i);
      wkup_thold_reg_wr_i = 1'b0;
      wkup_thold_wr_data_i = '0;
    end
  endtask

  task automatic apply_reset(input lc_tx_t gate_value);
    begin
      clear_writes();
      rst_aon_ni = 1'b0;
      lc_gate_i = '{default: gate_value};
      sleep_mode_i = 1'b0;
      saw_wkup_intr = 1'b0;
      repeat (2) @(negedge clk_aon_i);
      rst_aon_ni = 1'b1;
      @(negedge clk_aon_i);
    end
  endtask

  task automatic start_wakeup_timer;
    begin
      pulse_wkup_thold(32'd2);
      pulse_wkup_ctrl(12'd0, 1'b1);
      sleep_mode_i = 1'b1;
    end
  endtask

  aon_timer_core dut (
    clk_aon_i,
    rst_aon_ni,
    lc_gate_i,
    sleep_mode_i,
    wkup_enable_o,
    wkup_prescaler_o,
    wkup_thold_o,
    wkup_count_o,
    wdog_enable_o,
    wdog_pause_o,
    wdog_bark_thold_o,
    wdog_bite_thold_o,
    wdog_count_o,
    wkup_ctrl_reg_wr_i,
    wkup_ctrl_wr_data_i,
    wkup_thold_reg_wr_i,
    wkup_thold_wr_data_i,
    wkup_count_reg_wr_i,
    wkup_count_wr_data_i,
    wdog_ctrl_reg_wr_i,
    wdog_ctrl_wr_data_i,
    wdog_bark_thold_reg_wr_i,
    wdog_bark_thold_wr_data_i,
    wdog_bite_thold_reg_wr_i,
    wdog_bite_thold_wr_data_i,
    wdog_count_reg_wr_i,
    wdog_count_wr_data_i,
    wkup_intr_o,
    wdog_intr_o,
    wdog_reset_req_o
  );

  initial begin
    clear_writes();
    lc_gate_i = '{default: Off};
    sleep_mode_i = 1'b0;
    saw_wkup_intr = 1'b0;
    off_count = '0;
    on_count = '0;

    apply_reset(Off);
    start_wakeup_timer();
    repeat (8) @(posedge clk_aon_i);
    off_count = wkup_count_o;

    if (!saw_wkup_intr) begin
      $fatal(1, "Wakeup interrupt did not fire with lifecycle gate held at Off");
    end

    if (off_count < 32'd3) begin
      $fatal(1, "Wakeup counter did not keep incrementing in low power with gate Off: %0d",
             off_count);
    end

    apply_reset(On);
    start_wakeup_timer();
    repeat (8) @(posedge clk_aon_i);
    on_count = wkup_count_o;

    if (saw_wkup_intr) begin
      $fatal(1, "Wakeup interrupt fired while lifecycle gate was held at On");
    end

    if (on_count != 32'd0) begin
      $fatal(1, "Wakeup counter advanced in low power with lifecycle gate On: %0d", on_count);
    end

    $display("TB_RESULT: PASS off_count=%0d on_count=%0d", off_count, on_count);
    $finish;
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<EOF
${TB_DIR}/lc_ctrl_pkg_stub.sv
/home/opentitan/hw/ip/aon_timer/rtl/aon_timer_core.sv
${TB_DIR}/tb.sv
EOF

rm -f "${TB_DIR}/simv" "${TB_DIR}/simv.daidir/ucli.key" "${COMPILE_LOG}" "${RUN_LOG}"

set +e
timeout 1800 vcs -full64 -sverilog -timescale=1ns/1ps \
  -f "${TB_DIR}/files.f" \
  -o "${TB_DIR}/simv" \
  -l "${COMPILE_LOG}"
compile_rc=$?

run_rc=$compile_rc
if [ "${compile_rc}" -eq 0 ]; then
  timeout 1800 "${TB_DIR}/simv" -l "${RUN_LOG}"
  run_rc=$?
  if grep -q "TB_RESULT: PASS" "${RUN_LOG}"; then
    run_rc=0
  elif [ "${run_rc}" -eq 0 ]; then
    run_rc=1
  fi
fi
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "${compile_rc}" -eq 0 ] && [ "${run_rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

if [ "${compile_rc}" -ne 0 ]; then
  exit "${compile_rc}"
fi

exit "${run_rc}"

