#!/bin/bash
set -u

cd /home/opentitan

TEST_NAME="rom_ctrl_mux_gnt_rvalid_timing"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
`timescale 1ns/1ps

module tb;
  localparam int AW = 8;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic sel_i = 1'b1;

  logic [AW-1:0] bus_addr_i = '0;
  logic bus_req_i = 1'b0;
  logic bus_gnt_o;
  logic [39:0] bus_rdata_o;
  logic bus_rvalid_o;

  logic [AW-1:0] chk_addr_i = '0;
  logic [39:0] chk_rdata_o;

  logic [AW-1:0] rom_addr_o;
  logic rom_req_o;
  logic [39:0] rom_scr_rdata_i = 40'h0badc0ffee;
  logic [39:0] rom_clr_rdata_i = 40'h123456789a;
  logic rom_rvalid_i;

  logic alert_o;
  logic bus_req_d;
  logic bus_gnt_d;

  always #5 clk_i = ~clk_i;

  rom_ctrl_mux #(
    .AW(AW)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .sel_i(sel_i),
    .bus_addr_i(bus_addr_i),
    .bus_req_i(bus_req_i),
    .bus_gnt_o(bus_gnt_o),
    .bus_rdata_o(bus_rdata_o),
    .bus_rvalid_o(bus_rvalid_o),
    .chk_addr_i(chk_addr_i),
    .chk_rdata_o(chk_rdata_o),
    .rom_addr_o(rom_addr_o),
    .rom_req_o(rom_req_o),
    .rom_scr_rdata_i(rom_scr_rdata_i),
    .rom_clr_rdata_i(rom_clr_rdata_i),
    .rom_rvalid_i(rom_rvalid_i),
    .alert_o(alert_o)
  );

  // The ROM responds one cycle after any request. The key contract is that a bus
  // response is only legal if the matching bus request was granted in the previous cycle.
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      rom_rvalid_i <= 1'b0;
      bus_req_d <= 1'b0;
      bus_gnt_d <= 1'b0;
    end else begin
      rom_rvalid_i <= rom_req_o;

      if (bus_rvalid_o) begin
        if (!(bus_req_d && bus_gnt_d)) begin
          $error("bus_rvalid_o arrived without a previously granted bus request");
          $error("previous bus_req=%0b previous bus_gnt=%0b current sel_i=%0b",
                 bus_req_d, bus_gnt_d, sel_i);
          $fatal(1);
        end

        if (bus_rdata_o !== rom_clr_rdata_i) begin
          $error("bus_rdata_o mismatch: got %h expected %h", bus_rdata_o, rom_clr_rdata_i);
          $fatal(1);
        end

        $display("TB_PASS");
        $finish;
      end

      bus_req_d <= bus_req_i;
      bus_gnt_d <= bus_gnt_o;
    end
  end

  initial begin
    repeat (2) @(posedge clk_i);
    rst_ni <= 1'b1;

    // Keep the checker selected long enough to establish steady checker traffic.
    chk_addr_i <= 8'h55;
    repeat (2) @(posedge clk_i);

    // Handover from checker to bus. A correct mux grants the first bus request
    // immediately; the buggy base design delays grant by one cycle.
    sel_i <= 1'b0;
    bus_addr_i <= 8'h3c;
    bus_req_i <= 1'b1;
    @(posedge clk_i);
    bus_req_i <= 1'b0;

    repeat (5) @(posedge clk_i);
    $error("Timed out waiting for a valid bus response");
    $fatal(1);
  end
endmodule
EOF

set +e
vcs -full64 -sverilog -timescale=1ns/1ps \
  -top tb \
  -o "$TB_DIR/simv" \
  "$TB_DIR/tb.sv" \
  hw/ip/rom_ctrl/rtl/rom_ctrl_mux.sv \
  -l "$TB_DIR/compile.log"
compile_rc=$?

if [ "$compile_rc" -ne 0 ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "$compile_rc"
fi

"$TB_DIR/simv" -l "$TB_DIR/sim.log"
run_rc=$?
final_rc=$run_rc

if [ "$run_rc" -eq 0 ]; then
  if grep -q '^TB_PASS$' "$TB_DIR/sim.log"; then
    final_rc=0
  else
    final_rc=1
  fi
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$final_rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$final_rc"

