tb_script:
#!/bin/bash
cd /home/opentitan
set -u
set -o pipefail
set +e

export PATH="/tools/riscv/bin:/tools/verible/bin:$PATH"

TEST_NAME="aes_control_fatal_alert_clear"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
LOG_FILE="${TB_DIR}/fusesoc_run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/aes_control_fatal_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:aes_control_fatal_tb:0.1"
description: "Minimal aes_control fatal alert reproducer"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:aes:0.6
    files:
      - aes_control_fatal_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: aes_control_fatal_tb
    filesets:
      - files_dv
EOF

cat > "${TB_DIR}/aes_control_fatal_tb.sv" <<'EOF'
module aes_control_fatal_tb;
  import aes_pkg::*;
  import aes_reg_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic ctrl_qe_i;
  logic ctrl_err_storage_i;
  aes_op_e op_i;
  aes_mode_e mode_i;
  ciph_op_e cipher_op_i;
  logic manual_operation_i;
  logic start_i;
  logic key_iv_data_in_clear_i;
  logic data_out_clear_i;
  logic prng_reseed_i;
  logic mux_sel_err_i;
  logic sp_enc_err_i;
  lc_tx_t lc_escalate_en_i;
  logic alert_fatal_i;
  logic [NumRegsKey-1:0] key_init_qe_i [NumSharesKey];
  logic [NumRegsIv-1:0] iv_qe_i;
  logic [NumRegsData-1:0] data_in_qe_i;
  logic [NumRegsData-1:0] data_out_re_i;
  sp2v_e [NumSlicesCtr-1:0] ctr_we_i;
  sp2v_e ctr_ready_i;
  sp2v_e cipher_in_ready_i;
  sp2v_e cipher_out_valid_i;
  sp2v_e cipher_crypt_i;
  sp2v_e cipher_dec_key_gen_i;
  logic cipher_key_clear_i;
  logic cipher_data_out_clear_i;
  logic prng_data_ack_i;
  logic prng_reseed_ack_i;
  logic output_lost_i;

  logic ctrl_we_o;
  logic data_in_we_o;
  sp2v_e data_out_we_o;
  dip_sel_e data_in_prev_sel_o;
  sp2v_e data_in_prev_we_o;
  si_sel_e state_in_sel_o;
  add_si_sel_e add_state_in_sel_o;
  add_so_sel_e add_state_out_sel_o;
  sp2v_e ctr_incr_o;
  sp2v_e cipher_in_valid_o;
  sp2v_e cipher_out_ready_o;
  sp2v_e cipher_crypt_o;
  sp2v_e cipher_dec_key_gen_o;
  logic cipher_key_clear_o;
  logic cipher_data_out_clear_o;
  key_init_sel_e key_init_sel_o;
  sp2v_e [NumRegsKey-1:0] key_init_we_o [NumSharesKey];
  iv_sel_e iv_sel_o;
  sp2v_e [NumSlicesCtr-1:0] iv_we_o;
  logic prng_data_req_o;
  logic prng_reseed_req_o;
  logic start_o;
  logic start_we_o;
  logic key_iv_data_in_clear_o;
  logic key_iv_data_in_clear_we_o;
  logic data_out_clear_o;
  logic data_out_clear_we_o;
  logic prng_reseed_o;
  logic prng_reseed_we_o;
  logic output_valid_o;
  logic output_valid_we_o;
  logic input_ready_o;
  logic input_ready_we_o;
  logic idle_o;
  logic idle_we_o;
  logic stall_o;
  logic stall_we_o;
  logic output_lost_o;
  logic output_lost_we_o;
  logic alert_o;

  aes_control dut (
    .clk_i,
    .rst_ni,
    .ctrl_qe_i,
    .ctrl_we_o,
    .ctrl_err_storage_i,
    .op_i,
    .mode_i,
    .cipher_op_i,
    .manual_operation_i,
    .start_i,
    .key_iv_data_in_clear_i,
    .data_out_clear_i,
    .prng_reseed_i,
    .mux_sel_err_i,
    .sp_enc_err_i,
    .lc_escalate_en_i,
    .alert_fatal_i,
    .alert_o,
    .key_init_qe_i,
    .iv_qe_i,
    .data_in_qe_i,
    .data_out_re_i,
    .data_in_we_o,
    .data_out_we_o,
    .data_in_prev_sel_o,
    .data_in_prev_we_o,
    .state_in_sel_o,
    .add_state_in_sel_o,
    .add_state_out_sel_o,
    .ctr_incr_o,
    .ctr_ready_i,
    .ctr_we_i,
    .cipher_in_valid_o,
    .cipher_in_ready_i,
    .cipher_out_valid_i,
    .cipher_out_ready_o,
    .cipher_crypt_o,
    .cipher_crypt_i,
    .cipher_dec_key_gen_o,
    .cipher_dec_key_gen_i,
    .cipher_key_clear_o,
    .cipher_key_clear_i,
    .cipher_data_out_clear_o,
    .cipher_data_out_clear_i,
    .key_init_sel_o,
    .key_init_we_o,
    .iv_sel_o,
    .iv_we_o,
    .prng_data_req_o,
    .prng_data_ack_i,
    .prng_reseed_req_o,
    .prng_reseed_ack_i,
    .start_o,
    .start_we_o,
    .key_iv_data_in_clear_o,
    .key_iv_data_in_clear_we_o,
    .data_out_clear_o,
    .data_out_clear_we_o,
    .prng_reseed_o,
    .prng_reseed_we_o,
    .output_valid_o,
    .output_valid_we_o,
    .input_ready_o,
    .input_ready_we_o,
    .idle_o,
    .idle_we_o,
    .stall_o,
    .stall_we_o,
    .output_lost_i,
    .output_lost_o,
    .output_lost_we_o
  );

  always #5 clk_i = ~clk_i;

  task automatic check(bit cond, string msg);
    if (!cond) begin
      $display("TB_CHECK_FAIL: %s", msg);
      $fatal(1, msg);
    end
  endtask

  initial begin
    clk_i = 0;
    rst_ni = 0;
    ctrl_qe_i = 0;
    ctrl_err_storage_i = 0;
    op_i = AES_ENC;
    mode_i = AES_ECB;
    cipher_op_i = CIPH_FWD;
    manual_operation_i = 0;
    start_i = 0;
    key_iv_data_in_clear_i = 0;
    data_out_clear_i = 0;
    prng_reseed_i = 0;
    mux_sel_err_i = 0;
    sp_enc_err_i = 0;
    lc_escalate_en_i = Off;
    alert_fatal_i = 0;
    key_init_qe_i = '{default: '0};
    iv_qe_i = '0;
    data_in_qe_i = '0;
    data_out_re_i = '0;
    ctr_ready_i = SP2V_LOW;
    ctr_we_i = {NumSlicesCtr{SP2V_LOW}};
    cipher_in_ready_i = SP2V_LOW;
    cipher_out_valid_i = SP2V_LOW;
    cipher_crypt_i = SP2V_LOW;
    cipher_dec_key_gen_i = SP2V_LOW;
    cipher_key_clear_i = 0;
    cipher_data_out_clear_i = 0;
    prng_data_ack_i = 0;
    prng_reseed_ack_i = 0;
    output_lost_i = 1;

    repeat (3) @(posedge clk_i);
    rst_ni = 1;
    repeat (2) @(posedge clk_i);
    #1;

    check(idle_o === 1'b1, "idle should be visible before fatal alert");
    check(input_ready_o === 1'b1, "input_ready should be visible before fatal alert");
    check(output_lost_o === 1'b1, "output_lost should reflect stored state before fatal alert");
    check(start_we_o === 1'b0, "start_we should be low before fatal alert");

    alert_fatal_i = 1'b1;
    #1;

    check(idle_o === 1'b0, "fatal alert must clear idle status");
    check(idle_we_o === 1'b1, "fatal alert must write idle status");
    check(input_ready_o === 1'b0, "fatal alert must clear input_ready status");
    check(input_ready_we_o === 1'b1, "fatal alert must write input_ready status");
    check(output_lost_o === 1'b0, "fatal alert must clear output_lost status");
    check(output_lost_we_o === 1'b1, "fatal alert must write output_lost status");
    check(output_valid_o === 1'b0, "fatal alert must clear output_valid status");
    check(output_valid_we_o === 1'b1, "fatal alert must write output_valid status");
    check(stall_o === 1'b0, "fatal alert must clear stall status");
    check(stall_we_o === 1'b1, "fatal alert must write stall status");
    check(start_we_o === 1'b1, "fatal alert must clear start trigger");
    check(key_iv_data_in_clear_we_o === 1'b1,
          "fatal alert must clear key_iv_data_in_clear trigger");
    check(data_out_clear_we_o === 1'b1, "fatal alert must clear data_out_clear trigger");
    check(prng_reseed_we_o === 1'b1, "fatal alert must clear prng_reseed trigger");

    $display("TB_CHECK_PASS: fatal alert clears aes_control status and trigger outputs");
    $finish;
  end
endmodule
EOF

fusesoc \
  --cores-root /home/opentitan \
  --cores-root "${TB_DIR}" \
  run \
  --build-root "${TB_DIR}/build" \
  --target=sim \
  --tool=vcs \
  lowrisc:dv:aes_control_fatal_tb:0.1 |& tee "${LOG_FILE}"
fusesoc_rc=${PIPESTATUS[0]}

if [[ ${fusesoc_rc} -eq 0 ]] && \
   grep -q "TB_CHECK_PASS:" "${LOG_FILE}" && \
   ! grep -q "TB_CHECK_FAIL:" "${LOG_FILE}"; then
  test_rc=0
else
