module tb;
  import lc_ctrl_pkg::*;
  import otp_ctrl_pkg::*;
  import otp_ctrl_reg_pkg::*;
  import otp_ctrl_part_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic kdi_en_i = 1'b1;
  lc_tx_t escalate_en_i;
  logic fsm_err_o;
  logic scrmbl_key_seed_valid_i;
  logic [FlashKeySeedWidth-1:0] flash_data_key_seed_i;
  logic [FlashKeySeedWidth-1:0] flash_addr_key_seed_i;
  logic [SramKeySeedWidth-1:0] sram_data_key_seed_i;
  logic edn_req_o;
  logic edn_ack_i;
  logic [EdnDataWidth-1:0] edn_data_i;
  flash_otp_key_req_t flash_otp_key_i;
  flash_otp_key_rsp_t flash_otp_key_o;
  sram_otp_key_req_t [NumSramKeyReqSlots-1:0] sram_otp_key_i;
  sram_otp_key_rsp_t [NumSramKeyReqSlots-1:0] sram_otp_key_o;
  otbn_otp_key_req_t otbn_otp_key_i;
  otbn_otp_key_rsp_t otbn_otp_key_o;
  logic scrmbl_mtx_req_o;
  logic scrmbl_mtx_gnt_i;
  otp_scrmbl_cmd_e scrmbl_cmd_o;
  digest_mode_e scrmbl_mode_o;
  logic [ConstSelWidth-1:0] scrmbl_sel_o;
  logic [ScrmblBlockWidth-1:0] scrmbl_data_o;
  logic scrmbl_valid_o;
  logic scrmbl_ready_i;
  logic scrmbl_valid_i;
  logic [ScrmblBlockWidth-1:0] scrmbl_data_i;
  logic edn_req_seen_q;
  logic ack_observed_q;

  always #5 clk_i = ~clk_i;

  otp_ctrl_kdi dut (
    .clk_i,
    .rst_ni,
    .kdi_en_i,
    .escalate_en_i,
    .fsm_err_o,
    .scrmbl_key_seed_valid_i,
    .flash_data_key_seed_i,
    .flash_addr_key_seed_i,
    .sram_data_key_seed_i,
    .edn_req_o,
    .edn_ack_i,
    .edn_data_i,
    .flash_otp_key_i,
    .flash_otp_key_o,
    .sram_otp_key_i,
    .sram_otp_key_o,
    .otbn_otp_key_i,
    .otbn_otp_key_o,
    .scrmbl_mtx_req_o,
    .scrmbl_mtx_gnt_i,
    .scrmbl_cmd_o,
    .scrmbl_mode_o,
    .scrmbl_sel_o,
    .scrmbl_data_o,
    .scrmbl_valid_o,
    .scrmbl_ready_i,
    .scrmbl_valid_i,
    .scrmbl_data_i
  );

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      edn_req_seen_q <= 1'b0;
      ack_observed_q <= 1'b0;
    end else begin
      if (edn_req_o) begin
        edn_req_seen_q <= 1'b1;
      end
      if (edn_ack_i) begin
        ack_observed_q <= 1'b1;
      end
    end
  end

  always_ff @(posedge clk_i) begin
    if (rst_ni && edn_ack_i && !edn_req_o) begin
      $error("Observed EDN ACK without EDN REQ");
      $fatal(1);
    end
  end

  initial begin
    escalate_en_i = Off;
    scrmbl_key_seed_valid_i = 1'b1;
    flash_data_key_seed_i = 256'h1;
    flash_addr_key_seed_i = 256'h2;
    sram_data_key_seed_i = 128'h3;
    edn_data_i = 64'h0123_4567_89ab_cdef;
    flash_otp_key_i = '0;
    sram_otp_key_i = '{default: '0};
    otbn_otp_key_i = '0;
    scrmbl_mtx_gnt_i = 1'b1;
    scrmbl_ready_i = 1'b1;
    scrmbl_valid_i = 1'b1;
    scrmbl_data_i = 64'hdeaf_beef_feed_cafe;
    edn_ack_i = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    flash_otp_key_i.data_req = 1'b1;

    @(posedge edn_req_o);
    @(negedge clk_i);
    escalate_en_i = On;
    @(negedge clk_i);
    edn_ack_i = 1'b1;
    @(negedge clk_i);
    edn_ack_i = 1'b0;

    wait (fsm_err_o === 1'b1);
    wait (ack_observed_q === 1'b1);
    @(posedge clk_i);

    if (!edn_req_seen_q) begin
      $error("EDN request was never observed");
      $fatal(1);
    end

    $display("Observed delayed EDN ACK while REQ stayed asserted across escalation");
    $finish(0);
  end

  initial begin
    repeat (40) @(posedge clk_i);
    $error("Timed out waiting for EDN req/ack scenario");
    $fatal(1);
  end
endmodule
EOF

