#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="hmac_idle_signal"
TB_DIR="/home/opentitan/.tb_hmac_idle"
BUILD_ROOT="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/hmac_idle_test.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:hmac_idle_test:0.1"
description: "Minimal HMAC idle regression"
filesets:
  files_tb:
    depend:
      - lowrisc:ip:hmac:0.1
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: tb
    filesets:
      - files_tb
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  logic clk;
  logic rst_n;
  tlul_pkg::tl_h2d_t tl_i;
  tlul_pkg::tl_d2h_t tl_o;
  logic intr_hmac_done;
  logic intr_fifo_empty;
  logic intr_hmac_err;
  logic idle_o;

  hmac dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .tl_i(tl_i),
    .tl_o(tl_o),
    .intr_hmac_done_o(intr_hmac_done),
    .intr_fifo_empty_o(intr_fifo_empty),
    .intr_hmac_err_o(intr_hmac_err),
    .idle_o(idle_o)
  );

  initial clk = 1'b0;
  always #5 clk = ~clk;

  initial begin
    tl_i = '0;
    rst_n = 1'b0;
    repeat (5) @(posedge clk);
    rst_n = 1'b1;
    repeat (3) @(posedge clk);
    if (idle_o !== 1'b1) begin
      $display("IDLE_RESET_FAIL idle_o=%b", idle_o);
      $fatal(1);
    end
    force dut.reg_fifo_wvalid = 1'b1;
    repeat (2) @(posedge clk);
    if (idle_o !== 1'b0) begin
      $display("IDLE_STUCK_HIGH idle_o=%b", idle_o);
      $fatal(1);
    end
    release dut.reg_fifo_wvalid;
    repeat (2) @(posedge clk);
    $display("IDLE_BEHAVIOR_OK");
    $finish;
  end
endmodule
EOF

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  source /etc/opentitan_tools_path.sh
fi

