#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="entropy_src_startup_phase"
TB_ROOT="/home/opentitan/.tb_entropy_src_startup_phase"
SCRATCH_ROOT="${TB_ROOT}/scratch"

setup_test_files() {
  mkdir -p "${TB_ROOT}"

  cat > hw/ip/entropy_src/dv/env/seq_lib/entropy_src_startup_phase_vseq.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class entropy_src_startup_phase_vseq extends entropy_src_base_vseq;
  `uvm_object_utils(entropy_src_startup_phase_vseq)

  `uvm_object_new

  localparam bit [7:0] StartupHtStartState = 8'h85;
  localparam bit [7:0] StartupPhase1State  = 8'h74;

  task dut_init(string reset_kind = "HARD");
    do_entropy_src_init = 1'b0;
    super.dut_init(reset_kind);
  endtask

  task body();
    uvm_hdl_data_t state_data;
    bit [7:0] state;
    bit [7:0] prev_state;
    bit seen_startup_ht_start;
    bit seen_startup_phase1;

    cfg.efuse_es_sw_reg_en_vif.drive_pin(.idx(0), .val(1'b1));

    // Keep the boot-phase bypass window intact and only shrink the FIPS window
    // so the startup-only states become observable quickly.
    csr_wr(.ptr(ral.health_test_windows), .value(32'h0060_0001));
    csr_wr(.ptr(ral.rate), .value(32'h1));
    csr_wr(.ptr(ral.entropy_control), .value(32'h1));
    csr_wr(.ptr(ral.conf), .value(32'h2));

    prev_state = '1;
    repeat (512) begin
      if (!uvm_hdl_read("tb.dut.u_entropy_src_core.es_main_sm_state", state_data)) begin
        `uvm_fatal(`gfn, "Failed to read main state machine state")
      end
      state = state_data[7:0];
      if (state != prev_state) begin
        `uvm_info(`gfn, $sformatf("Observed main_sm_state=0x%0h", state), UVM_LOW)
        prev_state = state;
      end
      seen_startup_ht_start |= (state == StartupHtStartState);
      seen_startup_phase1   |= (state == StartupPhase1State);
      if (seen_startup_ht_start && seen_startup_phase1) begin
        csr_wr(.ptr(ral.conf), .value(32'h0));
        cfg.clk_rst_vif.wait_clks(5);
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end

    `DV_CHECK_FATAL(seen_startup_ht_start,
                    $sformatf("Missing startup state 0x%0h", StartupHtStartState))
    `DV_CHECK_FATAL(seen_startup_phase1,
                    $sformatf("Missing startup state 0x%0h", StartupPhase1State))
  endtask
endclass
EOF

  cat > hw/ip/entropy_src/dv/tests/entropy_src_startup_phase_test.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class entropy_src_startup_phase_test extends entropy_src_base_test;
  `uvm_component_utils(entropy_src_startup_phase_test)
  `uvm_component_new

  function void configure_env();
    super.configure_env();
    cfg.en_scb = 0;
    cfg.enable_pct = 0;
    cfg.mode_ptrng_pct = 0;
    cfg.route_software_pct = 100;
    cfg.type_bypass_pct = 0;
    cfg.efuse_es_sw_reg_en_pct = 100;
    `DV_CHECK_RANDOMIZE_FATAL(cfg)
    `uvm_info(`gfn, $sformatf("%s", cfg.convert2string()), UVM_LOW)
  endfunction
endclass
EOF

  grep -q 'entropy_src_startup_phase_vseq.sv' \
    hw/ip/entropy_src/dv/env/seq_lib/entropy_src_vseq_list.sv || \
    printf '%s\n' '`include "entropy_src_startup_phase_vseq.sv"' >> \
      hw/ip/entropy_src/dv/env/seq_lib/entropy_src_vseq_list.sv

  grep -q 'entropy_src_startup_phase_test.sv' hw/ip/entropy_src/dv/tests/entropy_src_test_pkg.sv || \
    perl -0pi -e 's/`include "entropy_src_rng_test\.sv"\n/`include "entropy_src_rng_test.sv"\n  `include "entropy_src_startup_phase_test.sv"\n/' \
      hw/ip/entropy_src/dv/tests/entropy_src_test_pkg.sv

  grep -q 'entropy_src_startup_phase_test.sv' hw/ip/entropy_src/dv/tests/entropy_src_test.core || \
    perl -0pi -e 's/      - entropy_src_rng_test\.sv: \{is_include_file: true\}\n/      - entropy_src_rng_test.sv: {is_include_file: true}\n      - entropy_src_startup_phase_test.sv: {is_include_file: true}\n/' \
      hw/ip/entropy_src/dv/tests/entropy_src_test.core

  grep -q 'entropy_src_startup_phase_vseq.sv' hw/ip/entropy_src/dv/env/entropy_src_env.core || \
    perl -0pi -e 's/      - seq_lib\/entropy_src_rng_vseq\.sv: \{is_include_file: true\}\n/      - seq_lib\/entropy_src_rng_vseq.sv: {is_include_file: true}\n      - seq_lib\/entropy_src_startup_phase_vseq.sv: {is_include_file: true}\n/' \
      hw/ip/entropy_src/dv/env/entropy_src_env.core

  grep -q 'name: entropy_src_startup_phase' hw/ip/entropy_src/dv/entropy_src_sim_cfg.hjson || \
    perl -0pi -e 's/\n    \{\n      name: entropy_src_rng\n      uvm_test: entropy_src_rng_test\n      uvm_test_seq: entropy_src_rng_vseq\n    \}\n/\n    {\n      name: entropy_src_rng\n      uvm_test: entropy_src_rng_test\n      uvm_test_seq: entropy_src_rng_vseq\n    }\n\n    {\n      name: entropy_src_startup_phase\n      uvm_test: entropy_src_startup_phase_test\n      uvm_test_seq: entropy_src_startup_phase_vseq\n    }\n/' \
      hw/ip/entropy_src/dv/entropy_src_sim_cfg.hjson
}

setup_test_files
rm -rf "${SCRATCH_ROOT}"
mkdir -p "${SCRATCH_ROOT}"

timeout 1800 ./util/dvsim/dvsim.py \
  hw/ip/entropy_src/dv/entropy_src_sim_cfg.hjson \
  -i "${TEST_NAME}" \
  -t vcs \
  --fixed-seed 1 \
  --reseed 1 \
  --scratch-root "${SCRATCH_ROOT}"
rc=$?

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

