mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'SV'
module tb;
  import top_pkg::*;
  import tlul_pkg::*;

  tl_h2d_t tl_i;
  tl_h2d_t tl_o;

  tlul_cmd_intg_gen dut (
    .tl_i(tl_i),
    .tl_o(tl_o)
  );

  task automatic run_case(string name,
                          logic [TL_DW-1:0] data,
                          logic [TL_DBW-1:0] mask,
                          logic [TL_AW-1:0] addr);
    logic [TL_DW-1:0] exp_data;
    logic [DataIntgWidth-1:0] exp_data_intg;
    logic [H2DCmdIntgWidth-1:0] exp_cmd_intg;

    tl_i = TL_H2D_DEFAULT;
    tl_i.a_valid = 1'b1;
    tl_i.a_opcode = (&mask) ? PutFullData : PutPartialData;
    tl_i.a_size = TL_SZW'(2);
    tl_i.a_source = '0;
    tl_i.a_address = addr;
    tl_i.a_mask = mask;
    tl_i.a_data = data;
    tl_i.a_user = TL_A_USER_DEFAULT;
    tl_i.a_user.tl_type = DataType;
    #1;

    exp_data = '0;
    for (int i = 0; i < TL_DBW; i++) begin
      exp_data[i*8 +: 8] = mask[i] ? data[i*8 +: 8] : '0;
    end
    exp_data_intg = get_data_intg(exp_data);
    exp_cmd_intg = get_cmd_intg(tl_i);

    if (tl_o.a_data !== exp_data) begin
      $display("RUNTIME_FAIL %s data expected=%08x actual=%08x",
               name, exp_data, tl_o.a_data);
      $fatal(1);
    end
    if (tl_o.a_user.data_intg !== exp_data_intg) begin
      $display("RUNTIME_FAIL %s data_intg expected=%0x actual=%0x",
               name, exp_data_intg, tl_o.a_user.data_intg);
      $fatal(1);
    end
    if (tl_o.a_user.cmd_intg !== exp_cmd_intg) begin
      $display("RUNTIME_FAIL %s cmd_intg expected=%0x actual=%0x",
               name, exp_cmd_intg, tl_o.a_user.cmd_intg);
      $fatal(1);
    end

    $display("RUNTIME_PASS %s", name);
  endtask

  initial begin
    run_case("partial_write", 32'hDEADBEEF, 4'b0101, 32'h00000104);
    run_case("full_write", 32'h12345678, 4'b1111, 32'h00000208);
    $display("RUNTIME_PASS all_cases");
    $finish;
  end
endmodule
SV

