tb_script:
#!/bin/bash

cd /home/opentitan || exit 1
set -euo pipefail

TEST_NAME="kmac_entropy_mode_repro"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
BUILD_ROOT="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/${TEST_NAME}.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:kmac_entropy_mode_repro:0.1"
description: "Standalone reproducer for latched KMAC entropy mode behavior"
filesets:
  files_rtl:
    depend:
      - lowrisc:prim:assert:0.1
      - lowrisc:prim:lfsr:0.1
      - lowrisc:prim:flop
    files:
      - /home/opentitan/hw/ip/kmac/rtl/sha3_pkg.sv
      - /home/opentitan/hw/ip/kmac/rtl/kmac_pkg.sv
      - /home/opentitan/hw/ip/kmac/rtl/kmac_reg_pkg.sv
      - /home/opentitan/hw/ip/kmac/rtl/kmac_entropy.sv
    file_type: systemVerilogSource
  files_dv:
    files:
      - tb.sv
    file_type: systemVerilogSource
targets:
  sim:
    default_tool: vcs
    toplevel: kmac_entropy_mode_repro_tb
    filesets:
      - files_rtl
      - files_dv
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module kmac_entropy_mode_repro_tb;
  import kmac_pkg::*;

  localparam logic [MsgWidth-1:0] InitialSeed = 64'h0123_4567_89ab_cdef;
  localparam logic [MsgWidth-1:0] RefreshSeed = 64'hf1e2_d3c4_b5a6_9788;

  logic clk_i;
  logic rst_ni;

  logic                       entropy_req_o;
  logic                       entropy_ack_i;
  logic [MsgWidth-1:0]        entropy_data_i;
  logic                       rand_valid_o;
  logic [sha3_pkg::StateW-1:0] rand_data_o;
  logic                       rand_consumed_i;
  logic                       in_keyblock_i;
  entropy_mode_e              mode_i;
  logic                       entropy_ready_i;
  logic                       fast_process_i;
  logic                       seed_update_i;
  logic [63:0]                seed_data_i;
  logic                       entropy_refresh_req_i;
  logic [TimerPrescalerW-1:0] wait_timer_prescaler_i;
  logic [EdnWaitTimerW-1:0]   wait_timer_limit_i;
  logic [kmac_reg_pkg::HashCntW-1:0] hash_cnt_o;
  logic                       hash_cnt_clr_i;
  logic [kmac_reg_pkg::HashCntW-1:0] hash_threshold_i;
  err_t                       err_o;
  logic                       err_processed_i;

  kmac_entropy dut (
    .clk_i,
    .rst_ni,
    .entropy_req_o,
    .entropy_ack_i,
    .entropy_data_i,
    .rand_valid_o,
    .rand_data_o,
    .rand_consumed_i,
    .in_keyblock_i,
    .mode_i,
    .entropy_ready_i,
    .fast_process_i,
    .seed_update_i,
    .seed_data_i,
    .entropy_refresh_req_i,
    .wait_timer_prescaler_i,
    .wait_timer_limit_i,
    .hash_cnt_o,
    .hash_cnt_clr_i,
    .hash_threshold_i,
    .err_o,
    .err_processed_i
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic step(input int cycles);
    repeat (cycles) @(posedge clk_i);
  endtask

  task automatic fail_test(input string msg);
    $display("TB_FAILURE: %s", msg);
    $fatal(1, "%s", msg);
  endtask

  task automatic wait_for_entropy_req(input string reason);
    int cycles;
    for (cycles = 0; cycles < 200; cycles++) begin
      if (entropy_req_o === 1'b1) return;
      @(posedge clk_i);
    end
    fail_test($sformatf("Timeout waiting for entropy request: %s", reason));
  endtask

  task automatic wait_for_rand_valid(input string reason);
    int cycles;
    for (cycles = 0; cycles < 400; cycles++) begin
      if (rand_valid_o === 1'b1) return;
      @(posedge clk_i);
    end
    fail_test($sformatf("Timeout waiting for rand_valid_o high: %s", reason));
  endtask

  task automatic wait_for_rand_invalid(input string reason);
    int cycles;
    for (cycles = 0; cycles < 100; cycles++) begin
      if (rand_valid_o === 1'b0) return;
      @(posedge clk_i);
    end
    fail_test($sformatf("Timeout waiting for rand_valid_o low: %s", reason));
  endtask

  task automatic issue_entropy_seed(input logic [MsgWidth-1:0] seed);
    wait_for_entropy_req("seed handshake");
    entropy_data_i = seed;
    entropy_ack_i = 1'b1;
    @(posedge clk_i);
    entropy_ack_i = 1'b0;
    entropy_data_i = '0;
  endtask

  initial begin
    rst_ni = 1'b0;
    entropy_ack_i = 1'b0;
    entropy_data_i = '0;
    rand_consumed_i = 1'b0;
    in_keyblock_i = 1'b0;
    mode_i = EntropyModeEdn;
    entropy_ready_i = 1'b1;
    fast_process_i = 1'b0;
    seed_update_i = 1'b0;
    seed_data_i = '0;
    entropy_refresh_req_i = 1'b0;
    wait_timer_prescaler_i = '0;
    wait_timer_limit_i = '0;
    hash_cnt_clr_i = 1'b0;
    hash_threshold_i = '0;
    err_processed_i = 1'b0;

    step(5);
    rst_ni = 1'b1;

    issue_entropy_seed(InitialSeed);
    wait_for_rand_valid("initial seed expansion");
    if (err_o.valid) begin
      fail_test($sformatf("Unexpected error after initial seed. code=%0h info=%0h",
                          err_o.code, err_o.info));
    end
    if (rand_data_o[63:0] !== InitialSeed) begin
      fail_test($sformatf("Initial seed mismatch. expected=%h got=%h",
                          InitialSeed, rand_data_o[63:0]));
    end

    mode_i = EntropyModeNone;
    entropy_refresh_req_i = 1'b1;
    @(posedge clk_i);
    entropy_refresh_req_i = 1'b0;

    issue_entropy_seed(RefreshSeed);
    wait_for_rand_invalid("refresh should clear old randomness");
    wait_for_rand_valid("refresh seed expansion");

    if (err_o.valid) begin
      fail_test($sformatf("Unexpected error after refresh. code=%0h info=%0h",
                          err_o.code, err_o.info));
    end

    if (rand_data_o[63:0] !== RefreshSeed) begin
      fail_test($sformatf("Refresh seed mismatch after mode change. expected=%h got=%h",
                          RefreshSeed, rand_data_o[63:0]));
    end

    $display("TB_PASS: Reproducer observed refreshed seed %h", rand_data_o[63:0]);
    $finish;
  end
endmodule
EOF

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  # Needed when prepare installs toolchain or Verible outside the default image PATH.
  # shellcheck disable=SC1091
  source /etc/opentitan_tools_path.sh || true
fi

set +e
fusesoc --cores-root /home/opentitan \
  --cores-root "${TB_DIR}" \
  run --no-export --build-root "${BUILD_ROOT}" --target=sim --tool=vcs \
  lowrisc:dv:kmac_entropy_mode_repro:0.1 2>&1 | tee "${RUN_LOG}"
tool_rc=${PIPESTATUS[0]}
set -e

result_rc=1
if [[ "${tool_rc}" -eq 0 ]] && grep -q "TB_PASS:" "${RUN_LOG}" && ! grep -q "TB_FAILURE:" "${RUN_LOG}"; then
  result_rc=0
fi

echo "HWE_BENCH_RESULTS_START"
if [[ "${result_rc}" -eq 0 ]]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${result_rc}"

