tb_script:
#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="sigverify_key_invalid_vcs"
TB_DIR="/home/opentitan/.tb_sigverify_key_invalid"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/otp_ctrl_regs.h" <<'EOF'
#ifndef OTP_CTRL_REGS_H_
#define OTP_CTRL_REGS_H_

#define OTP_CTRL_PARAM_CREATOR_SW_CFG_KEY_IS_VALID_OFFSET 0x108
#define OTP_CTRL_PARAM_CREATOR_SW_CFG_KEY_IS_VALID_SIZE 8

#endif
EOF

cat > "$TB_DIR/sigverify_dpi.c" <<'EOF'
#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

#include "sw/device/silicon_creator/lib/error.h"
#include "sw/device/silicon_creator/mask_rom/sigverify_keys.h"

enum {
  kExpectedBadKey = (3u << 24) | (0x5653u << 8) | 3u,
};

uint32_t otp_read32(uint32_t address) {
  (void)address;
  return 0x4b4b4ba5u;
}

int run_sigverify_test(void) {
  const sigverify_rsa_key_t *key = NULL;
  uint32_t key_id = kSigVerifyRsaKeys[1].n.data[0];
  rom_error_t err = sigverify_rsa_key_get(key_id, &key);
  if (err != (rom_error_t)kExpectedBadKey || key != NULL) {
    fprintf(stderr, "unexpected sigverify result: err=0x%08x key=%p\n",
            (unsigned)err, (void *)key);
    exit(1);
  }
  return 0;
}
EOF

cat > "$TB_DIR/sigverify_support.c" <<'EOF'
#include <stdint.h>

#include "sw/device/silicon_creator/lib/sigverify_rsa_key.h"

uint32_t sigverify_rsa_key_id_get(const sigverify_rsa_buffer_t *modulus) {
  return modulus->data[0];
}
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import "DPI-C" function int run_sigverify_test();

  initial begin
    int rc;
    rc = run_sigverify_test();
    if (rc != 0) begin
      $display("unexpected rc=%0d", rc);
      $finish;
    end
    $finish;
  end
endmodule
EOF

vcs -full64 -sverilog -timescale=1ns/1ps \
  -o "$TB_DIR/simv" \
  -l "$TB_DIR/compile.log" \
  -cc gcc \
  -cpp g++ \
  -CFLAGS "-std=c11 -I$TB_DIR -I/home/opentitan" \
  "$TB_DIR/tb.sv" \
  "$TB_DIR/sigverify_dpi.c" \
  "$TB_DIR/sigverify_support.c" \
  /home/opentitan/sw/device/silicon_creator/mask_rom/sigverify_keys.c
compile_rc=$?

if [ "$compile_rc" -eq 0 ]; then
  "$TB_DIR/simv" -l "$TB_DIR/sim.log"
  rc=$?
else
  rc=$compile_rc
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"
exit "$rc"

