    cfg.en_scb = 0;
  endtask

  virtual task body();
    bit [TL_DW-1:0] first_ctrl;
    bit [TL_DW-1:0] second_ctrl;
    bit [TL_DW-1:0] read_ctrl;
    bit             alert_triggered;
    string          alert_name;

    alert_name = ral.ctrl_shadowed.get_update_err_alert_name();
    first_ctrl = '0;
    second_ctrl = '0;
    alert_triggered = 0;

    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));

    // Keep all fields identical across the two writes except manual_operation.
    // On the fixed design, operation still commits while manual_operation is blocked.
    first_ctrl[0] = 1'b1;
    first_ctrl[6:1] = aes_pkg::AES_ECB;
    first_ctrl[9:7] = aes_pkg::AES_128;
    first_ctrl[10] = 1'b1;

    second_ctrl = first_ctrl;
    second_ctrl[10] = 1'b0;

    csr_wr(.ptr(ral.ctrl_shadowed), .value(first_ctrl), .en_shadow_wr(0), .blocking(1),
           .predict(0));
    shadow_reg_wr(ral.ctrl_shadowed, second_ctrl, alert_triggered);

    `DV_SPINWAIT(if (!alert_triggered) begin
                   while (!cfg.m_alert_agent_cfg[alert_name].vif.get_alert()) begin
                     cfg.clk_rst_vif.wait_clks(1);
                   end
                 end,
                 $sformatf("%0s update_err alert not detected", alert_name))
    `DV_SPINWAIT(cfg.m_alert_agent_cfg[alert_name].vif.wait_ack_complete();,
                 $sformatf("timeout for alert:%0s", alert_name))

    csr_rd(.ptr(ral.ctrl_shadowed), .value(read_ctrl), .blocking(1));

    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.operation, read_ctrl), 1'b1)
    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.manual_operation, read_ctrl), 1'b0)
    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.mode, read_ctrl), aes_pkg::AES_ECB)
    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.key_len, read_ctrl), aes_pkg::AES_128)
  endtask

endclass
SV

