SIM_BIN_NAME="tbgen_dv_rv_dm_lc_tb_0.1"

set +e
fusesoc --cores-root . --cores-root "$TB_DIR" run \
  --target=sim \
  --tool=vcs \
  --build-root "$TB_DIR/build" \
  --setup --build \
  tbgen:dv:rv_dm_lc_tb:0.1 2>&1 | tee "${LOG_DIR}/fusesoc.log"
build_rc=${PIPESTATUS[0]}
set -e

sim_rc=1
if [ "$build_rc" -eq 0 ]; then
  SIM_BIN="$(find "$TB_DIR/build" -maxdepth 3 -type f -name "$SIM_BIN_NAME" | head -n1)"
  if [ -n "$SIM_BIN" ]; then
    SIM_DIR="$(dirname "$SIM_BIN")"
    set +e
    (
      cd "$SIM_DIR"
      "./$(basename "$SIM_BIN")" -l vcs.log
    ) 2>&1 | tee "${LOG_DIR}/sim.log"
    sim_rc=${PIPESTATUS[0]}
    set -e
  else
    echo "[ERROR] Built simulator binary not found: ${SIM_BIN_NAME}" | tee "${LOG_DIR}/sim.log"
  fi
fi

test_rc=1
if [ "$build_rc" -eq 0 ] && [ -f "${LOG_DIR}/sim.log" ]; then
  if grep -q "Observed unauthorized SBA request while lc_hw_debug_en_i=Off" "${LOG_DIR}/sim.log"; then
    test_rc=1
  elif grep -q "No SBA request observed while lc_hw_debug_en_i=Off" "${LOG_DIR}/sim.log"; then
    test_rc=0
  elif [ "$sim_rc" -ne 0 ]; then
    test_rc=1
  fi
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$test_rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

