#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="alert_handler_shadowed_clear"
TB_DIR="/home/opentitan/.tb_alert_handler_shadow"
BUILD_DIR="$TB_DIR/build"
LOG="$TB_DIR/fusesoc.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/alert_handler_shadow_tb.core" <<'CORE_EOF'
CAPI=2:
name: "local:dv:alert_handler_shadow_tb:0.1"
description: "Minimal VCS TB for alert_handler shadow clear semantics"
filesets:
  files_tb:
    depend:
      - lowrisc:ip:tlul:0.1
      - lowrisc:prim:all:0.1
      - lowrisc:ip:alert_handler_reg:0.1
    files:
      - ../hw/ip/alert_handler/rtl/alert_pkg.sv
      - ../hw/ip/alert_handler/rtl/alert_handler_reg_wrap.sv
      - alert_handler_shadow_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: alert_handler_shadow_tb
    filesets:
