module alert_handler_shadow_tb;
  import top_pkg::*;
  import tlul_pkg::*;
  import alert_pkg::*;

  localparam logic [31:0] CLASSD_CLR_ADDR = 32'h0000_017c;

  logic clk;
  logic rst_n;
  logic rst_shadowed_n;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  logic [N_CLASSES-1:0] irq;
  alert_crashdump_t crashdump;
  hw2reg_wrap_t hw2reg_wrap;
  reg2hw_wrap_t reg2hw_wrap;
  logic fatal_integ_alert;
  int classd_clr_pulses;

  alert_handler_reg_wrap dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .rst_shadowed_ni(rst_shadowed_n),
    .tl_i(tl_i),
    .tl_o(tl_o),
    .irq_o(irq),
    .latch_crashdump_i(1'b0),
    .crashdump_o(crashdump),
    .hw2reg_wrap(hw2reg_wrap),
    .reg2hw_wrap(reg2hw_wrap),
    .fatal_integ_alert_o(fatal_integ_alert)
  );

  initial clk = 0;
  always #5 clk = ~clk;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      classd_clr_pulses <= 0;
    end else if (reg2hw_wrap.class_clr[3]) begin
      classd_clr_pulses <= classd_clr_pulses + 1;
      $display("TRACE: classd_clr pulse at %0t", $time);
    end
  end

  task automatic tl_write(input logic [31:0] addr, input logic [31:0] data);
    tl_h2d_t req;
    req = TL_H2D_DEFAULT;
    req.a_valid = 1'b1;
    req.a_opcode = PutFullData;
    req.a_size = 2;
    req.a_source = '0;
    req.a_address = addr;
    req.a_mask = '1;
    req.a_data = data;
    req.a_user = TL_A_USER_DEFAULT;
    req.a_user.cmd_intg = tlul_pkg::get_cmd_intg(req);
    req.a_user.data_intg = tlul_pkg::get_data_intg(data);

    @(posedge clk);
    tl_i <= req;
    do begin
      @(posedge clk);
    end while (!tl_o.a_ready);
    tl_i <= TL_H2D_DEFAULT;
    do begin
      @(posedge clk);
    end while (!tl_o.d_valid);
    if (tl_o.d_error) begin
      $fatal(1, "TL write error at addr 0x%08x", addr);
    end
  endtask

  task automatic expect_no_pulse_after_first_write;
    int start_count;
    start_count = classd_clr_pulses;
    repeat (4) @(posedge clk);
    if (classd_clr_pulses != start_count) begin
      $fatal(1, "Unexpected classd_clr pulse after first write");
    end
  endtask

  task automatic expect_single_pulse_after_second_write;
    int start_count;
    start_count = classd_clr_pulses;
    repeat (6) @(posedge clk);
    if (classd_clr_pulses != start_count + 1) begin
      $fatal(1, "Expected one classd_clr pulse after second write, got %0d -> %0d",
             start_count, classd_clr_pulses);
    end
  endtask

  initial begin
    tl_i = TL_H2D_DEFAULT;
    hw2reg_wrap = '0;
    rst_n = 1'b0;
    rst_shadowed_n = 1'b0;
    repeat (5) @(posedge clk);
    rst_n = 1'b1;
    rst_shadowed_n = 1'b1;
    repeat (2) @(posedge clk);

    tl_write(CLASSD_CLR_ADDR, 32'h1);
    expect_no_pulse_after_first_write();

    tl_write(CLASSD_CLR_ADDR, 32'h1);
    expect_single_pulse_after_second_write();

    $display("TB_PASS");
    $finish;
  end
endmodule
TB_EOF

