tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="sw_silicon_creator_lib_shutdown_finalize_rma_unittest"
WORK_DIR="/home/opentitan/.tb_shutdown_finalize_rma_unittest"
GEN_DIR="${WORK_DIR}/gen"
RESULT_STATUS="FAIL"

rm -rf "${WORK_DIR}"
mkdir -p "${GEN_DIR}"

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  source /etc/opentitan_tools_path.sh
fi

gen_header() {
  local input="$1"
  local output="$2"
  python util/regtool.py --cdefines -o "${output}" "${input}"
}

gen_header hw/top_earlgrey/ip/alert_handler/data/autogen/alert_handler.hjson \
  "${GEN_DIR}/alert_handler_regs.h"
gen_header hw/ip/flash_ctrl/data/flash_ctrl.hjson \
  "${GEN_DIR}/flash_ctrl_regs.h"
gen_header hw/ip/keymgr/data/keymgr.hjson \
  "${GEN_DIR}/keymgr_regs.h"
gen_header hw/ip/lc_ctrl/data/lc_ctrl.hjson \
  "${GEN_DIR}/lc_ctrl_regs.h"
gen_header hw/ip/otp_ctrl/data/otp_ctrl.hjson \
  "${GEN_DIR}/otp_ctrl_regs.h"
gen_header hw/ip/sram_ctrl/data/sram_ctrl.hjson \
  "${GEN_DIR}/sram_ctrl_regs.h"

cat > "${WORK_DIR}/shutdown_finalize_rma_test.cc" <<'EOF'
#include <csetjmp>
#include <cstdarg>
#include <cstdint>
#include <cstdio>

#include "sw/device/silicon_creator/lib/drivers/alert.h"
#include "sw/device/silicon_creator/lib/shutdown.h"

#include "hw/top_earlgrey/sw/autogen/top_earlgrey.h"
#include "lc_ctrl_regs.h"
#include "otp_ctrl_regs.h"

namespace {

jmp_buf g_shutdown_env;
uint32_t g_last_reported_error = 0xffffffffu;
uint32_t g_lc_state = static_cast<uint32_t>(kLcStateRma);
uint32_t g_otp_reporting = static_cast<uint32_t>(kShutdownErrorRedactModule);
bool g_escalated = false;
bool g_keymgr_killed = false;
bool g_flash_killed = false;
bool g_hang_called = false;

void ResetTestState() {
  g_last_reported_error = 0xffffffffu;
  g_lc_state = static_cast<uint32_t>(kLcStateRma);
  g_otp_reporting = static_cast<uint32_t>(kShutdownErrorRedactModule);
  g_escalated = false;
  g_keymgr_killed = false;
  g_flash_killed = false;
  g_hang_called = false;
}

bool RunRmaScenario() {
  ResetTestState();

  const rom_error_t kReason = kErrorUartBadBaudRate;
  const uint32_t expected =
      shutdown_redact(kReason, kShutdownErrorRedactNone);

  if (setjmp(g_shutdown_env) == 0) {
    shutdown_finalize(kReason);
    std::fprintf(stderr, "shutdown_finalize returned unexpectedly\n");
    return false;
  }

  if (!g_escalated || !g_keymgr_killed || !g_flash_killed || !g_hang_called) {
    std::fprintf(stderr,
                 "shutdown sequence incomplete: escalate=%d keymgr=%d flash=%d "
                 "hang=%d\n",
                 g_escalated, g_keymgr_killed, g_flash_killed, g_hang_called);
    return false;
  }

  if (g_last_reported_error != expected) {
    std::fprintf(stderr, "expected 0x%08x, got 0x%08x\n", expected,
                 g_last_reported_error);
    return false;
  }

  std::printf("observed boot_fault: 0x%08x\n", g_last_reported_error);
  return true;
}

}  // namespace

extern "C" {

void unmocked_shutdown_report_error(rom_error_t reason) __attribute__((weak));

size_t base_printf(const char *format, ...) {
  char buffer[128];
  va_list args;
  va_start(args, format);
  const int written = std::vsnprintf(buffer, sizeof(buffer), format, args);
  va_end(args);

  unsigned int value = 0;
  if (std::sscanf(buffer, "boot_fault: 0x%x", &value) == 1) {
    g_last_reported_error = value;
  }

  std::fputs(buffer, stdout);
  if (written < 0) {
    return 0;
  }
  return static_cast<size_t>(written);
}

uint8_t abs_mmio_read8(uint32_t addr) {
  (void)addr;
  return 0;
}

void abs_mmio_write8(uint32_t addr, uint8_t value) {
  (void)addr;
  (void)value;
}

void abs_mmio_write8_shadowed(uint32_t addr, uint8_t value) {
  (void)addr;
  (void)value;
}

uint32_t abs_mmio_read32(uint32_t addr) {
  if (addr == TOP_EARLGREY_LC_CTRL_BASE_ADDR + LC_CTRL_LC_STATE_REG_OFFSET) {
    return g_lc_state;
  }
  if (addr == TOP_EARLGREY_OTP_CTRL_CORE_BASE_ADDR +
                  OTP_CTRL_SW_CFG_WINDOW_REG_OFFSET +
                  OTP_CTRL_PARAM_ROM_ERROR_REPORTING_OFFSET) {
    return g_otp_reporting;
  }
  return 0;
}

void abs_mmio_write32(uint32_t addr, uint32_t value) {
  (void)addr;
  (void)value;
}

void abs_mmio_write32_shadowed(uint32_t addr, uint32_t value) {
  (void)addr;
  (void)value;
}

uint32_t otp_read32(uint32_t address) {
  if (address == OTP_CTRL_PARAM_ROM_ERROR_REPORTING_OFFSET) {
    return g_otp_reporting;
  }
  return 0;
}

rom_error_t alert_configure(size_t index, alert_class_t cls,
                            alert_enable_t enabled) {
  (void)index;
  (void)cls;
  (void)enabled;
  return kErrorOk;
}

rom_error_t alert_local_configure(size_t index, alert_class_t cls,
                                  alert_enable_t enabled) {
  (void)index;
  (void)cls;
  (void)enabled;
  return kErrorOk;
}

rom_error_t alert_class_configure(alert_class_t cls,
                                  const alert_class_config_t *config) {
  (void)cls;
  (void)config;
  return kErrorOk;
}

void shutdown_report_error(rom_error_t reason) {
  if (unmocked_shutdown_report_error != nullptr) {
    unmocked_shutdown_report_error(reason);
    return;
  }

  const uint32_t redacted = shutdown_redact(
      reason,
      static_cast<shutdown_error_redact_t>(
          otp_read32(OTP_CTRL_PARAM_ROM_ERROR_REPORTING_OFFSET)));
  base_printf("boot_fault: 0x%08x\n", redacted);
}

void shutdown_software_escalate(void) { g_escalated = true; }

void shutdown_keymgr_kill(void) { g_keymgr_killed = true; }

void shutdown_flash_kill(void) { g_flash_killed = true; }

void shutdown_hang(void) {
  g_hang_called = true;
  longjmp(g_shutdown_env, 1);
}

}  // extern "C"

int main() { return RunRmaScenario() ? 0 : 1; }
EOF

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

finalize() {
  local rc=$?
  emit_result "${RESULT_STATUS}"
  trap - EXIT
  exit "${rc}"
}

trap finalize EXIT

BUILD_LOG="${WORK_DIR}/build.log"
RUN_LOG="${WORK_DIR}/run.log"

set +e
{
  gcc -std=c11 -DOT_OFF_TARGET_TEST -DMOCK_ABS_MMIO \
    -I/home/opentitan \
    -I"${GEN_DIR}" \
    -c /home/opentitan/sw/device/silicon_creator/lib/shutdown.c \
    -o "${WORK_DIR}/shutdown.o"

  gcc -std=c11 \
    -I/home/opentitan \
    -c /home/opentitan/sw/device/lib/base/bitfield.c \
    -o "${WORK_DIR}/bitfield.o"

  g++ -std=c++17 -DOT_OFF_TARGET_TEST -DMOCK_ABS_MMIO \
    -I/home/opentitan \
    -I"${GEN_DIR}" \
    -c "${WORK_DIR}/shutdown_finalize_rma_test.cc" \
    -o "${WORK_DIR}/shutdown_finalize_rma_test.o"

  g++ "${WORK_DIR}/shutdown.o" \
    "${WORK_DIR}/bitfield.o" \
    "${WORK_DIR}/shutdown_finalize_rma_test.o" \
    -o "${WORK_DIR}/shutdown_finalize_rma_test"
} >"${BUILD_LOG}" 2>&1
BUILD_RC=$?
set -e

cat "${BUILD_LOG}"

if [[ ${BUILD_RC} -ne 0 ]]; then
  exit "${BUILD_RC}"
fi

set +e
"${WORK_DIR}/shutdown_finalize_rma_test" >"${RUN_LOG}" 2>&1
RUN_RC=$?
set -e

cat "${RUN_LOG}"

if [[ ${RUN_RC} -eq 0 ]]; then
  RESULT_STATUS="PASS"
fi

exit "${RUN_RC}"

