tb_script:
#!/bin/bash
set -uo pipefail

cd /home/opentitan

TB_NAME="alert_handler_crashdump_phase0"
TB_DIR="/home/opentitan/.tb_alert_handler_crashdump_phase0"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
SIMV="${TB_DIR}/simv"

print_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TB_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_stubs.sv" <<'EOF'
module prim_buf #(parameter int Width = 1) (
  input  logic [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);
  assign out_o = in_i;
endmodule

module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = 0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) q_o <= ResetValue;
    else q_o <= d_i;
  end
endmodule
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import alert_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic en_i;
  logic clr_i;
  logic accu_trig_i;
  logic accu_fail_i;
  logic timeout_en_i;
  logic [EscCntDw-1:0] timeout_cyc_i;
  logic [N_ESC_SEV-1:0] esc_en_i;
  logic [N_ESC_SEV-1:0][PHASE_DW-1:0] esc_map_i;
  logic [N_PHASES-1:0][EscCntDw-1:0] phase_cyc_i;
  logic [PHASE_DW-1:0] crashdump_phase_i;
  logic latch_crashdump_o;
  logic esc_trig_o;
  logic [EscCntDw-1:0] esc_cnt_o;
  logic [N_ESC_SEV-1:0] esc_sig_req_o;
  cstate_e esc_state_o;

  bit started;
  bit saw_good_latch;
  bit saw_bad_latch;

  alert_handler_esc_timer dut (
    .clk_i,
    .rst_ni,
    .en_i,
    .clr_i,
    .accu_trig_i,
    .accu_fail_i,
    .timeout_en_i,
    .timeout_cyc_i,
    .esc_en_i,
    .esc_map_i,
    .phase_cyc_i,
    .crashdump_phase_i,
    .latch_crashdump_o,
    .esc_trig_o,
    .esc_cnt_o,
    .esc_sig_req_o,
    .esc_state_o
  );

  initial clk_i = 0;
  always #5 clk_i = ~clk_i;

  always @(*) begin
    if (started && latch_crashdump_o) begin
      if (esc_state_o == Phase0) begin
        saw_good_latch = 1'b1;
      end else begin
        saw_bad_latch = 1'b1;
        $display("TB_FAIL: BAD_LATCH t=%0t state=%0d", $time, esc_state_o);
      end
    end
  end

  initial begin
    rst_ni = 0;
    en_i = 0;
    clr_i = 0;
    accu_trig_i = 0;
    accu_fail_i = 0;
    timeout_en_i = '0;
    timeout_cyc_i = '0;
    esc_en_i = '0;
    esc_map_i = '0;
    phase_cyc_i = '{32'd4, 32'd4, 32'd4, 32'd4};
    crashdump_phase_i = 2'b00;
    started = 0;
    saw_good_latch = 0;
    saw_bad_latch = 0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1;
    en_i = 1;

    @(negedge clk_i);
    started = 1;
    accu_trig_i = 1;

    @(negedge clk_i);
    accu_trig_i = 0;

    repeat (2) @(posedge clk_i);

    if (saw_bad_latch) begin
      $fatal(1, "TB_FAIL: Observed crashdump latch before Phase0 state became visible");
    end

    if (!saw_good_latch) begin
      $fatal(1, "TB_FAIL: Did not observe crashdump latch aligned with Phase0 state");
    end

    $display("TB_SUCCESS");
    $finish;
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<EOF
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/.tb_alert_handler_crashdump_phase0/prim_stubs.sv
/home/opentitan/hw/ip/alert_handler/rtl/alert_handler_reg_pkg.sv
/home/opentitan/hw/ip/alert_handler/rtl/alert_pkg.sv
/home/opentitan/hw/ip/alert_handler/rtl/alert_handler_esc_timer.sv
/home/opentitan/.tb_alert_handler_crashdump_phase0/tb.sv
EOF

compile_rc=1
sim_rc=1

vcs -full64 -sverilog +define+SYNTHESIS \
  -Mdir="${TB_DIR}/csrc" \
  -o "${SIMV}" \
  -f "${TB_DIR}/files.f" \
  -l "${COMPILE_LOG}"
compile_rc=$?

if [[ ${compile_rc} -eq 0 ]]; then
  "${SIMV}" -l "${RUN_LOG}"
  sim_rc=$?
fi

# VCS may still exit zero after $fatal in this environment, so use an explicit pass marker.
if [[ ${compile_rc} -eq 0 ]] && [[ -f "${RUN_LOG}" ]] && grep -Fq "TB_SUCCESS" "${RUN_LOG}"; then
  print_result "PASS"
  exit 0
fi

if [[ -f "${RUN_LOG}" ]]; then
  tail -n 40 "${RUN_LOG}"
elif [[ -f "${COMPILE_LOG}" ]]; then
  tail -n 40 "${COMPILE_LOG}"
fi

print_result "FAIL"
exit 1

