  logic [31:0] sys_int_enable_reg_i;
  logic [7:0] sys_int_vector_reg_i;
  logic [31:0] sys_int_status_reg_i;
  logic [31:0] sys_intf_capability_reg_i;
  logic [31:0] sys_status_reg_i;
  logic [31:0] sys_id_reg_i;
  logic [7:0] sys_rid_reg_i;
