  logic sys_rdfifo_notempty_o;
  logic [2:0] sys_rdfifo_depth_o;
  logic [2:0] sys_wrfifo_depth_o;

  logic [7:0] response_bytes [0:4];
  integer idx;

  spi_tpm dut (
    .clk_in_i(clk_in_i),
    .clk_out_i(clk_out_i),
    .sys_clk_i(sys_clk_i),
    .sys_rst_ni(sys_rst_ni),
    .scan_rst_ni(scan_rst_ni),
    .scanmode_i(scanmode_i),
    .csb_i(csb_i),
    .mosi_i(mosi_i),
    .miso_o(miso_o),
    .miso_en_o(miso_en_o),
    .tpm_cap_o(tpm_cap_o),
    .cfg_tpm_en_i(cfg_tpm_en_i),
    .cfg_tpm_mode_i(cfg_tpm_mode_i),
    .cfg_tpm_hw_reg_dis_i(cfg_tpm_hw_reg_dis_i),
    .cfg_tpm_reg_chk_dis_i(cfg_tpm_reg_chk_dis_i),
    .cfg_tpm_invalid_locality_i(cfg_tpm_invalid_locality_i),
    .sys_access_reg_i(sys_access_reg_i),
    .sys_int_enable_reg_i(sys_int_enable_reg_i),
    .sys_int_vector_reg_i(sys_int_vector_reg_i),
    .sys_int_status_reg_i(sys_int_status_reg_i),
    .sys_intf_capability_reg_i(sys_intf_capability_reg_i),
    .sys_status_reg_i(sys_status_reg_i),
    .sys_id_reg_i(sys_id_reg_i),
