    .sys_wrfifo_rdata_o(sys_wrfifo_rdata_o),
    .sys_wrfifo_rready_i(sys_wrfifo_rready_i),
    .sys_rdfifo_wvalid_i(sys_rdfifo_wvalid_i),
    .sys_rdfifo_wdata_i(sys_rdfifo_wdata_i),
    .sys_rdfifo_wready_o(sys_rdfifo_wready_o),
    .sys_cmdaddr_notempty_o(sys_cmdaddr_notempty_o),
    .sys_rdfifo_notempty_o(sys_rdfifo_notempty_o),
    .sys_rdfifo_depth_o(sys_rdfifo_depth_o),
    .sys_wrfifo_depth_o(sys_wrfifo_depth_o)
  );

  initial begin
    clk_in_i = 1'b0;
    forever #5 clk_in_i = ~clk_in_i;
  end

  initial begin
    clk_out_i = 1'b1;
    forever #5 clk_out_i = ~clk_out_i;
  end

  initial begin
    sys_clk_i = 1'b0;
    forever #7 sys_clk_i = ~sys_clk_i;
  end

