        mosi_i = tx_byte[bit_idx];
        @(posedge clk_in_i);
        #1;
        @(posedge clk_out_i);
        #1;
        rx_byte[bit_idx] = miso_o;
      end
    end
  endtask

  task automatic xfer_word(input logic [31:0] tx_word);
    logic [7:0] unused_rx;
    begin
      xfer_byte(tx_word[31:24], unused_rx);
      xfer_byte(tx_word[23:16], unused_rx);
      xfer_byte(tx_word[15:8], unused_rx);
      xfer_byte(tx_word[7:0], unused_rx);
    end
  endtask

