    scan_rst_ni = 1'b1;
    scanmode_i = Off;
    csb_i = 1'b1;
    mosi_i = 1'b0;
    cfg_tpm_en_i = 1'b1;
    cfg_tpm_mode_i = 1'b0;
    cfg_tpm_hw_reg_dis_i = 1'b0;
    cfg_tpm_reg_chk_dis_i = 1'b0;
    cfg_tpm_invalid_locality_i = 1'b1;
    sys_access_reg_i = 40'h0000000020;
    sys_int_enable_reg_i = '0;
    sys_int_vector_reg_i = '0;
    sys_int_status_reg_i = '0;
    sys_intf_capability_reg_i = '0;
    sys_status_reg_i = '0;
    sys_id_reg_i = 32'hA5A5_5A5A;
    sys_rid_reg_i = 8'h42;
    sys_cmdaddr_rready_i = 1'b0;
    sys_wrfifo_rready_i = 1'b0;
    sys_rdfifo_wvalid_i = 1'b0;
    sys_rdfifo_wdata_i = '0;

    repeat (4) @(posedge clk_in_i);
    sys_rst_ni = 1'b1;
    repeat (4) @(posedge clk_in_i);

    csb_i = 1'b0;
    #1;
    xfer_word(InvalidAccessReadCmd);
    for (idx = 0; idx < 5; idx++) begin
      xfer_byte(8'hA5, response_bytes[idx]);
    end
    csb_i = 1'b1;
    repeat (2) @(posedge clk_in_i);

    $display("TRACE rsp=%02x %02x %02x %02x %02x",
             response_bytes[0], response_bytes[1], response_bytes[2],
             response_bytes[3], response_bytes[4]);

    for (idx = 1; idx < 5; idx++) begin
      if (response_bytes[idx] !== 8'hFF) begin
        $error("Expected invalid locality to return 0xFF, byte[%0d]=0x%02x",
               idx, response_bytes[idx]);
        $fatal(1);
      end
    end

    $display("TRACE invalid locality read returned 0xFF bytes as expected");
    $finish;
  end

  initial begin
    #5000;
    $error("Timeout waiting for invalid locality response");
    $fatal(1);
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<EOF
${TB_DIR}/prim_assert.sv
${TB_DIR}/lc_ctrl_pkg.sv
${TB_DIR}/spi_device_pkg.sv
${TB_DIR}/prim_clock_mux2.sv
${TB_DIR}/prim_edge_detector.sv
${TB_DIR}/prim_fifo_async.sv
${TB_DIR}/prim_slicer.sv
/home/opentitan/hw/ip/spi_device/rtl/spi_tpm.sv
${TB_DIR}/tb.sv
EOF

set +e
vcs -full64 -sverilog -timescale=1ns/1ps -f "${TB_DIR}/files.f" -o "${SIMV}" -l "${COMPILE_LOG}"
compile_rc=$?
if [ "${compile_rc}" -eq 0 ]; then
  timeout 45s "${SIMV}" -l "${RUN_LOG}"
  run_rc=$?
else
  run_rc=${compile_rc}
fi
set -e

if [ "${run_rc}" -eq 0 ] && grep -q "TRACE invalid locality read returned 0xFF bytes as expected" "${RUN_LOG}"; then
  TEST_STATUS="PASS"
else
  run_rc=1
fi

exit "${run_rc}"

