tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  # Ensure the toolchain and Verible are available even in a fresh shell.
  source /etc/opentitan_tools_path.sh
fi

TEST_NAME="pwrmgr_esc_timeout"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
BUILD_ROOT="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

report_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/${TEST_NAME}.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:pwrmgr_esc_timeout_tb:0.1"
description: "Minimal pwrmgr escalation timeout reproducer"
filesets:
  files_tb:
    depend:
      - lowrisc:ip:pwrmgr
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: tb
    filesets:
      - files_tb
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import pwrmgr_pkg::*;
  import pwrmgr_reg_pkg::*;
  import tlul_pkg::*;
  import prim_alert_pkg::*;
  import rom_ctrl_pkg::*;

  logic clk_i = 0;
  logic clk_slow_i = 0;
  logic clk_esc_i = 0;
  logic rst_ni = 0;
  logic rst_slow_ni = 0;
  logic rst_main_ni = 0;
  bit esc_clk_run = 1'b1;

  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  alert_rx_t [NumAlerts-1:0] alert_rx_i;
  alert_tx_t [NumAlerts-1:0] alert_tx_o;
  pwr_ast_rsp_t pwr_ast_i;
  pwr_ast_req_t pwr_ast_o;
  pwr_rst_rsp_t pwr_rst_i;
  pwr_rst_req_t pwr_rst_o;
  pwr_clk_rsp_t pwr_clk_i;
  pwr_clk_req_t pwr_clk_o;
  pwr_otp_rsp_t pwr_otp_i;
  pwr_otp_req_t pwr_otp_o;
  pwr_lc_rsp_t pwr_lc_i;
  pwr_lc_req_t pwr_lc_o;
  pwr_flash_t pwr_flash_i;
  pwr_cpu_t pwr_cpu_i;
  logic [NumWkups-1:0] wakeups_i;
  logic [NumRstReqs-1:0] rstreqs_i;
  logic strap_o;
  logic low_power_o;
  pwrmgr_data_t rom_ctrl_i;
  prim_mubi_pkg::mubi4_t sw_rst_req_i;
  prim_esc_pkg::esc_tx_t esc_rst_tx_i;
  prim_esc_pkg::esc_rx_t esc_rst_rx_o;
  lc_ctrl_pkg::lc_tx_t fetch_en_o;
  logic intr_wakeup_o;

  always #5 clk_i = ~clk_i;
  always #17 clk_slow_i = ~clk_slow_i;
  always #5 if (esc_clk_run) clk_esc_i = ~clk_esc_i;

  always_comb begin
    pwr_ast_i = PWR_AST_RSP_DEFAULT;
    pwr_ast_i.main_pok = pwr_ast_o.main_pd_n;
    pwr_ast_i.core_clk_val = pwr_ast_o.core_clk_en;
    pwr_ast_i.io_clk_val = pwr_ast_o.io_clk_en;
    pwr_ast_i.usb_clk_val = pwr_ast_o.usb_clk_en;
  end

  always_comb begin
    pwr_rst_i = PWR_RST_RSP_DEFAULT;
    pwr_rst_i.rst_lc_src_n = ~pwr_rst_o.rst_lc_req;
    pwr_rst_i.rst_sys_src_n = ~pwr_rst_o.rst_sys_req;
  end

  always_comb begin
    pwr_clk_i.main_status = pwr_clk_o.main_ip_clk_en;
    pwr_clk_i.io_status = pwr_clk_o.io_ip_clk_en;
    pwr_clk_i.usb_status = pwr_clk_o.usb_ip_clk_en;
  end

  initial begin
    tl_i = TL_H2D_DEFAULT;
    alert_rx_i = '{default: ALERT_RX_DEFAULT};
    pwr_otp_i = PWR_OTP_RSP_DEFAULT;
    pwr_lc_i = PWR_LC_RSP_DEFAULT;
    pwr_flash_i = PWR_FLASH_DEFAULT;
    pwr_cpu_i = PWR_CPU_DEFAULT;
    wakeups_i = WAKEUPS_DEFAULT;
    rstreqs_i = RSTREQS_DEFAULT;
    rom_ctrl_i = PWRMGR_DATA_DEFAULT;
    sw_rst_req_i = prim_mubi_pkg::MuBi4False;
    esc_rst_tx_i = prim_esc_pkg::ESC_TX_DEFAULT;

    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_slow_ni = 1'b1;
    rst_main_ni = 1'b1;
  end

  initial begin
    repeat (2000) @(posedge clk_i);
    $error("Timed out waiting for pwrmgr escalation timeout behavior");
    $fatal(1, "TB_FAIL timeout waiting for pwrmgr escalation timeout behavior");
  end

  initial begin
    wait (fetch_en_o == lc_ctrl_pkg::On && pwr_clk_o.main_ip_clk_en == 1'b1);
    repeat (8) @(posedge clk_i);
    wait (clk_esc_i == 1'b0);
    $display("TB: reached active state, stopping clk_esc_i low");
    esc_clk_run = 1'b0;
    repeat (400) begin
      @(posedge clk_i);
      if (pwr_rst_o.rstreqs[ResetEscIdx] &&
          fetch_en_o != lc_ctrl_pkg::On &&
          pwr_rst_o.reset_cause == pwrmgr_pkg::HwReq) begin
        $display("TB: observed escalation timeout reset request");
        $display("TB_PASS");
        $finish;
      end
    end
    $error("Expected ResetEscIdx request after stopping clk_esc_i, but it never arrived");
    $fatal(1, "TB_FAIL expected ResetEscIdx request after stopping clk_esc_i, but it never arrived");
  end

  pwrmgr dut (
    .clk_slow_i,
    .clk_i,
    .rst_slow_ni,
    .rst_ni,
    .rst_main_ni,
    .clk_esc_i,
    .rst_esc_ni(rst_ni),
    .tl_i,
    .tl_o,
    .alert_rx_i,
    .alert_tx_o,
    .pwr_ast_i,
    .pwr_ast_o,
    .pwr_rst_i,
    .pwr_rst_o,
    .pwr_clk_o,
    .pwr_clk_i,
    .pwr_otp_i,
    .pwr_otp_o,
    .pwr_lc_i,
    .pwr_lc_o,
    .pwr_flash_i,
    .pwr_cpu_i,
    .fetch_en_o,
    .wakeups_i,
    .rstreqs_i,
    .strap_o,
    .low_power_o,
    .rom_ctrl_i,
    .sw_rst_req_i,
    .esc_rst_tx_i,
    .esc_rst_rx_o,
    .intr_wakeup_o
  );
endmodule
EOF

set +e
/usr/bin/time -f "TIME:%E" timeout 1800s \
  fusesoc --cores-root /home/opentitan --cores-root "${TB_DIR}" run \
    --no-export --build-root "${BUILD_ROOT}" \
    --flag=fileset_top --target=sim --tool=vcs \
    lowrisc:dv:pwrmgr_esc_timeout_tb 2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
set -e

if [[ ${rc} -eq 124 ]]; then
  report_result "FAIL"
  exit 124
fi

if grep -q "TB_FAIL" "${RUN_LOG}"; then
  report_result "FAIL"
  exit 1
fi

if grep -q "TB_PASS" "${RUN_LOG}"; then
  report_result "PASS"
  exit 0
fi

report_result "FAIL"
exit 1

#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="mubi_sync_stability"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
RUN_LOG="${TB_DIR}/run.log"
CORE_NAME="lowrisc:dv:${TEST_NAME}:0.1"
BUILD_DIR="/home/opentitan/build/lowrisc_dv_${TEST_NAME}_0.1"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}" "${BUILD_DIR}"
mkdir -p "${TB_DIR}/tb"

cat > "${TB_DIR}/${TEST_NAME}.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:mubi_sync_stability:0.1"
description: "Minimal VCS testbench for prim_mubi4_sync StabilityCheck"
filesets:
  files_rtl:
    depend:
      - lowrisc:prim:all:0.1
      - lowrisc:prim:mubi:0.1
      - lowrisc:prim:sec_anchor:0.1
    file_type: systemVerilogSource

  files_dv:
    files:
      - tb/mubi_sync_stability_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: mubi_sync_stability_tb
    filesets:
      - files_rtl
      - files_dv
    tools:
      vcs:
        vcs_options:
          - +warn=noLNX_OS_VERUN
EOF

cat > "${TB_DIR}/tb/mubi_sync_stability_tb.sv" <<'EOF'
module mubi_sync_stability_tb;
  import prim_mubi_pkg::*;

  logic clk_i;
  logic rst_ni;
  mubi4_t mubi_i;
  mubi4_t [0:0] mubi_o;

  prim_mubi4_sync #(
    .NumCopies(1),
    .AsyncOn(1'b1),
    .StabilityCheck(1'b1),
    .ResetValue(MuBi4False)
  ) dut (
    .clk_i,
    .rst_ni,
    .mubi_i,
    .mubi_o
  );

  always #5 clk_i = ~clk_i;

  task automatic expect_value(input string step, input mubi4_t expected);
    #1;
    if (mubi_o[0] !== expected) begin
      $error("%s expected %h got %h", step, expected, mubi_o[0]);
      $fatal(1);
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    mubi_i = MuBi4False;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    repeat (3) begin
      @(posedge clk_i);
      expect_value("warmup", MuBi4False);
    end

    @(negedge clk_i);
    mubi_i = mubi4_t'(4'h6);
    @(posedge clk_i);
    expect_value("invalid_seen_stage1", MuBi4False);

    @(negedge clk_i);
    mubi_i = MuBi4True;
    @(posedge clk_i);
    expect_value("invalid_filtered", MuBi4False);

    @(posedge clk_i);
    expect_value("first_true_filtered", MuBi4False);

    @(posedge clk_i);
    expect_value("stable_true_visible", MuBi4True);

    $display("MUBI_SYNC_STABILITY_TEST_PASS");
    $finish;
  end
endmodule
EOF

set +e
fusesoc --cores-root=. --cores-root="${TB_DIR}" run --target=sim --tool=vcs "${CORE_NAME}" 2>&1 | tee "${RUN_LOG}"
cmd_rc=${PIPESTATUS[0]}
set -e

echo "INFO: fusesoc_rc=${cmd_rc}"

if grep -q "MUBI_SYNC_STABILITY_TEST_PASS" "${RUN_LOG}"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

