  import lc_ctrl_pkg::*;

  logic clk_i = 1'b0;
  logic clk_slow_i = 1'b0;
  logic rst_ni = 1'b0;
  logic rst_slow_ni = 1'b0;
  logic req_pwrup_i = 1'b0;
  pwrup_cause_e pwrup_cause_i = Por;
  logic ack_pwrup_o;
  logic req_pwrdn_o;
  logic ack_pwrdn_i = 1'b0;
  logic low_power_entry_i = 1'b0;
  logic main_pd_ni = 1'b1;
  logic [TotalResetWidth-1:0] reset_reqs_i = '0;
  logic fsm_invalid_i = 1'b0;
  logic clr_slow_req_o;
  logic clr_slow_ack_i = 1'b0;
  logic usb_ip_clk_en_i = 1'b1;
  logic usb_ip_clk_status_o;
  logic wkup_o;
  logic fall_through_o;
  logic abort_o;
  logic clr_hint_o;
  logic clr_cfg_lock_o;
  pwr_rst_req_t pwr_rst_o;
  pwr_rst_rsp_t pwr_rst_i;
  pwr_clk_req_t ips_clk_en_o;
  pwr_clk_rsp_t clk_en_status_i;
  logic otp_init_o;
  logic otp_done_i = 1'b1;
  logic otp_idle_i = 1'b1;
  logic lc_init_o;
  logic lc_done_i = 1'b1;
  logic lc_idle_i = 1'b1;
  logic flash_idle_i = 1'b1;
  logic [3:0] rom_ctrl_done_i = 4'b0000;
  logic [3:0] rom_ctrl_good_i = 4'b0000;
  logic strap_o;
  logic low_power_o;
  lc_tx_t fetch_en_o;

  pwrmgr_fsm dut (
    .clk_i,
    .rst_ni,
    .clk_slow_i,
    .rst_slow_ni,
    .req_pwrup_i,
    .pwrup_cause_i,
    .ack_pwrup_o,
    .req_pwrdn_o,
    .ack_pwrdn_i,
    .low_power_entry_i,
    .main_pd_ni,
    .reset_reqs_i,
    .fsm_invalid_i,
    .clr_slow_req_o,
    .clr_slow_ack_i,
    .usb_ip_clk_en_i,
    .usb_ip_clk_status_o,
    .wkup_o,
    .fall_through_o,
    .abort_o,
    .clr_hint_o,
    .clr_cfg_lock_o,
    .pwr_rst_o,
    .pwr_rst_i,
    .ips_clk_en_o,
    .clk_en_status_i,
    .otp_init_o,
    .otp_done_i,
    .otp_idle_i,
    .lc_init_o,
    .lc_done_i,
    .lc_idle_i,
    .flash_idle_i,
    .rom_ctrl_done_i,
    .rom_ctrl_good_i,
    .strap_o,
    .low_power_o,
    .fetch_en_o
  );

  always #5 clk_i = ~clk_i;
  always #17 clk_slow_i = ~clk_slow_i;

  task automatic wait_for_state(input fast_pwr_state_e exp_state, input int max_cycles,
                                input string state_name);
    int cycles;
    begin
      for (cycles = 0; cycles < max_cycles; cycles++) begin
        @(posedge clk_i);
        if (dut.state_q == exp_state) return;
      end
      $display("TB_FAIL: timeout waiting for %s, saw state %0h", state_name, dut.state_q);
      $fatal(1);
    end
  endtask

  initial begin
    pwr_rst_i = '{rst_lc_src_n: {PowerDomains{1'b1}},
                  rst_sys_src_n: {PowerDomains{1'b1}}};
    clk_en_status_i = '{main_status: 1'b1, io_status: 1'b1, usb_status: 1'b1};

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_slow_ni = 1'b1;
    req_pwrup_i = 1'b1;

    wait_for_state(FastPwrStateAckPwrUp, 200, "AckPwrUp");
    @(posedge clk_i);
    req_pwrup_i = 1'b0;

    wait_for_state(FastPwrStateRomCheck, 200, "RomCheck");
    rom_ctrl_done_i = 4'b0001;
    rom_ctrl_good_i = 4'b0001;

    repeat (4) @(posedge clk_i);

    if (dut.state_q == FastPwrStateActive) begin
      $display("TB_FAIL: invalid mubi pattern advanced FSM to Active");
      $fatal(1);
    end

    if (dut.state_q != FastPwrStateRomCheck) begin
      $display("TB_FAIL: unexpected state %0h", dut.state_q);
      $fatal(1);
    end

    $display("TB_PASS: invalid mubi pattern rejected in RomCheck");
    $finish;
  end
endmodule
EOF

