tb_script:
#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="prim_clock_meas_timeout_margin"
TB_DIR="/home/opentitan/.tb_prim_clock_meas_timeout"
COMPILE_LOG="$TB_DIR/compile.log"
RUN_LOG="$TB_DIR/run.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input                    clk_i,
  input                    rst_ni,
  input        [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) q_o <= ResetValue;
    else q_o <= d_i;
  end
endmodule

module prim_flop_2sync #(
  parameter int Width = 16,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input                    clk_i,
  input                    rst_ni,
  input        [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  logic [Width-1:0] stage1;
  prim_flop #(.Width(Width), .ResetValue(ResetValue)) u_stage1 (
    .clk_i,
    .rst_ni,
    .d_i,
    .q_o(stage1)
  );
  prim_flop #(.Width(Width), .ResetValue(ResetValue)) u_stage2 (
    .clk_i,
    .rst_ni,
    .d_i(stage1),
    .q_o
  );
endmodule

module prim_clock_meas_timeout_tb;
  localparam time ClkPeriod = 2ns;
  localparam time RefPeriod = 10ns;
  localparam int CheckRefCycles = 7;

  logic clk_i = 0;
  logic clk_ref_i = 0;
  logic clk_i_en = 1;
  logic rst_ni = 0;
  logic rst_ref_ni = 0;
  logic en_i = 0;
  logic valid_o;
  logic fast_o;
  logic slow_o;
  logic timeout_clk_ref_o;
  logic ref_timeout_clk_o;
  logic [3:0] max_cnt;
  logic [3:0] min_cnt;

  always #(RefPeriod/2) clk_ref_i = ~clk_ref_i;
  always #(ClkPeriod/2) if (clk_i_en) clk_i = ~clk_i;

  prim_clock_meas #(
    .Cnt(16),
    .RefCnt(1),
    .ClkTimeOutChkEn(1),
    .RefTimeOutChkEn(1)
  ) dut (
    .clk_i,
    .rst_ni,
    .clk_ref_i,
    .rst_ref_ni,
    .en_i,
    .max_cnt,
    .min_cnt,
    .valid_o,
    .fast_o,
    .slow_o,
    .timeout_clk_ref_o,
    .ref_timeout_clk_o
  );

  initial begin
    max_cnt = '1;
    min_cnt = '0;

    repeat (4) @(posedge clk_ref_i);
    rst_ni = 1'b1;
    rst_ref_ni = 1'b1;
    en_i = 1'b1;

    // Let the ref-domain enable synchronize and a few request/ack rounds complete
    // before we halt the measured clock.
    repeat (8) @(posedge clk_ref_i);
    @(posedge clk_i);
    #1ps;
    clk_i_en = 1'b0;

    repeat (CheckRefCycles) @(posedge clk_ref_i);
    if (ref_timeout_clk_o !== 1'b1) begin
      $fatal(1, "Timeout was not asserted within %0d reference cycles after stopping clk_i", CheckRefCycles);
    end

    $display("RUNTIME_SIGNATURE: timeout asserted in %0d reference cycles", CheckRefCycles);
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/files.f" <<'EOF'
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv
/home/opentitan/hw/ip/prim/rtl/prim_sync_reqack.sv
/home/opentitan/hw/ip/prim/rtl/prim_pulse_sync.sv
/home/opentitan/hw/ip/prim/rtl/prim_clock_timeout.sv
/home/opentitan/hw/ip/prim/rtl/prim_clock_meas.sv
/home/opentitan/.tb_prim_clock_meas_timeout/tb.sv
EOF

vcs -full64 -sverilog -timescale=1ns/1ps \
  -f "$TB_DIR/files.f" \
  -top prim_clock_meas_timeout_tb \
  -o "$TB_DIR/simv" \
  -l "$COMPILE_LOG"
compile_rc=$?

if [ "$compile_rc" -eq 0 ]; then
  "$TB_DIR/simv" -l "$RUN_LOG"
  run_rc=$?
else
  run_rc=$compile_rc
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$compile_rc" -eq 0 ] && [ "$run_rc" -eq 0 ] && \
   grep -q "RUNTIME_SIGNATURE:" "$RUN_LOG" && \
   ! grep -q "^Fatal:" "$RUN_LOG"; then
  echo "TEST: $TEST_NAME ... PASS"
  rc=0
else
  echo "TEST: $TEST_NAME ... FAIL"
  rc=1
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

