tb_script:
#!/bin/bash

set -uo pipefail

cd /home/opentitan || exit 1

TEST_NAME="flash_ctrl_lcmgr_rma_before_init"
TB_DIR="/home/opentitan/.tb_flash_ctrl_lcmgr_rma_before_init"
TB_FILE="$TB_DIR/flash_ctrl_lcmgr_rma_tb.sv"
BUILD_DIR="$TB_DIR/build/lowrisc_ip_flash_ctrl_0.1/default-vcs"
RESULT_STATUS="FAIL"
RESULT_RC=1

emit_result() {
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $RESULT_STATUS"
  echo "HWE_BENCH_RESULTS_END"
}

finish() {
  trap - EXIT
  emit_result
  exit "$RESULT_RC"
}

trap finish EXIT

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_FILE" <<'EOF'
module flash_ctrl_lcmgr_rma_tb;
  import flash_ctrl_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic rst_otp_ni = 1'b0;
  logic init_i = 1'b0;
  logic provision_en_i = 1'b0;
  flash_ctrl_reg_pkg::flash_ctrl_reg2hw_control_reg_t ctrl_o;
  logic req_o;
  logic [BusAddrByteW-1:0] addr_o;
  logic done_i = 1'b1;
  flash_ctrl_err_t err_i = '0;
  logic rready_o;
  logic rvalid_i = 1'b1;
  logic wvalid_o;
  logic wready_i = 1'b1;
  logic [BusWidth-1:0] rdata_i = 32'hA5A55A5A;
  logic [BusWidth-1:0] wdata_o;
  lc_tx_t rma_req_i = Off;
  lc_tx_t rma_ack_o;
  logic [NumSeeds-1:0][SeedWidth-1:0] seeds_o;
  flash_lcmgr_phase_e phase_o;
  logic fatal_err_o;
  logic seed_err_o;
  logic rd_buf_en_o;
  otp_ctrl_pkg::flash_otp_key_req_t otp_key_req_o;
  otp_ctrl_pkg::flash_otp_key_rsp_t otp_key_rsp_i = '0;
  flash_key_t addr_key_o;
  flash_key_t data_key_o;
  flash_key_t rand_addr_key_o;
  flash_key_t rand_data_key_o;
  logic edn_req_o;
  logic edn_ack_i = 1'b0;
  logic lfsr_en_o;
  logic [BusWidth-1:0] rand_i = 32'hA5A55A5A;
  logic init_busy_o;
  int unsigned cycles = 0;

  always #5 clk_i = ~clk_i;

  initial begin
    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_otp_ni = 1'b1;
    repeat (5) @(posedge clk_i);
    rma_req_i = On;
  end

  always @(posedge clk_i) begin
    cycles <= cycles + 1;
    if ((cycles % 250000) == 0) begin
      $display("TB_PROGRESS: cycle=%0d phase=%0d ack=%0b req=%0b fatal=%0b",
               cycles, phase_o, rma_ack_o, req_o, fatal_err_o);
    end
    if (rma_ack_o == On) begin
      $display("TB_RESULT: PASS cycle=%0d", cycles);
      $finish;
    end
    if (cycles > 3000000) begin
      $fatal(1,
             "TB_RESULT: TIMEOUT cycle=%0d phase=%0d ack=%0b req=%0b fatal=%0b",
             cycles, phase_o, rma_ack_o, req_o, fatal_err_o);
    end
  end

  flash_ctrl_lcmgr dut (
    .clk_i,
    .rst_ni,
    .clk_otp_i(clk_i),
    .rst_otp_ni,
    .init_i,
    .provision_en_i,
    .ctrl_o,
    .req_o,
    .addr_o,
    .done_i,
    .err_i,
    .rready_o,
    .rvalid_i,
    .wvalid_o,
    .wready_i,
    .rdata_i,
    .wdata_o,
    .rma_req_i,
    .rma_ack_o,
    .seeds_o,
    .phase_o,
    .fatal_err_o,
    .seed_err_o,
    .rd_buf_en_o,
    .otp_key_req_o,
    .otp_key_rsp_i,
    .addr_key_o,
    .data_key_o,
    .rand_addr_key_o,
    .rand_data_key_o,
    .edn_req_o,
    .edn_ack_i,
    .lfsr_en_o,
    .rand_i,
    .init_busy_o
  );
endmodule
EOF

set +e

cd "$TB_DIR" || exit 1
fusesoc --cores-root /home/opentitan run \
  --flag=fileset_ip \
  --setup \
  --target=default \
  --tool=vcs \
  lowrisc:ip:flash_ctrl:0.1 \
  >"$TB_DIR/fusesoc.log" 2>&1
rc=$?
if [ "$rc" -ne 0 ]; then
  RESULT_RC="$rc"
  cat "$TB_DIR/fusesoc.log"
  exit "$RESULT_RC"
fi

cd "$BUILD_DIR" || {
  RESULT_RC=1
  cat "$TB_DIR/fusesoc.log"
  exit 1
}

vcs -full64 -sverilog -timescale=1ns/1ps -licqueue \
  -f lowrisc_ip_flash_ctrl_0.1.scr \
  "$TB_FILE" \
  -top flash_ctrl_lcmgr_rma_tb \
  -l "$TB_DIR/compile.log" \
  -o simv
rc=$?
if [ "$rc" -ne 0 ]; then
  RESULT_RC="$rc"
  cat "$TB_DIR/compile.log"
  exit "$RESULT_RC"
fi

./simv 2>&1 | tee "$TB_DIR/run.log"
rc=${PIPESTATUS[0]}
if [ "$rc" -eq 0 ] && grep -q "TB_RESULT: PASS" "$TB_DIR/run.log"; then
  RESULT_STATUS="PASS"
  RESULT_RC=0
else
  RESULT_RC=1
fi
exit "$RESULT_RC"

