#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="adc_ctrl_np_match_reset"
TB_DIR="/home/opentitan/.tb_adc_ctrl_np_match"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
`timescale 1ns/1ps
`define ASSERT_DEFAULT_CLK clk_aon_i
`define ASSERT_DEFAULT_RST !rst_aon_ni
`include "/home/opentitan/hw/ip/prim/rtl/prim_assert_dummy_macros.svh"
`include "/home/opentitan/hw/ip/adc_ctrl/rtl/adc_ctrl_reg_pkg.sv"
`include "/home/opentitan/hw/ip/adc_ctrl/rtl/adc_ctrl_fsm.sv"

module tb;
  import adc_ctrl_reg_pkg::*;

  logic clk_aon_i;
  logic rst_aon_ni;
  logic cfg_fsm_rst_i;
  logic cfg_adc_enable_i;
  logic cfg_oneshot_mode_i;
  logic cfg_lp_mode_i;
  logic [3:0] cfg_pwrup_time_i;
  logic [23:0] cfg_wakeup_time_i;
  logic [7:0] cfg_lp_sample_cnt_i;
  logic [15:0] cfg_np_sample_cnt_i;
  logic [NumAdcFilter-1:0] adc_ctrl_match_i;
  logic [9:0] adc_d_i;
  logic adc_d_val_i;
  logic adc_pd_o;
  logic [1:0] adc_chn_sel_o;
  logic chn0_val_we_o;
  logic chn1_val_we_o;
  logic [9:0] chn0_val_o;
  logic [9:0] chn1_val_o;
  logic adc_ctrl_done_o;
  logic oneshot_done_o;
  logic saw_done;

  adc_ctrl_fsm dut (
    .clk_aon_i,
    .rst_aon_ni,
    .cfg_fsm_rst_i,
    .cfg_adc_enable_i,
    .cfg_oneshot_mode_i,
    .cfg_lp_mode_i,
    .cfg_pwrup_time_i,
    .cfg_wakeup_time_i,
    .cfg_lp_sample_cnt_i,
    .cfg_np_sample_cnt_i,
    .adc_ctrl_match_i,
    .adc_d_i,
    .adc_d_val_i,
    .adc_pd_o,
    .adc_chn_sel_o,
    .chn0_val_we_o,
    .chn1_val_we_o,
    .chn0_val_o,
    .chn1_val_o,
    .adc_ctrl_done_o,
    .oneshot_done_o
  );

  always #5 clk_aon_i = ~clk_aon_i;

  always @(posedge clk_aon_i) begin
    if (adc_ctrl_done_o) begin
      saw_done <= 1'b1;
    end
  end

  task automatic wait_for_state(input logic expect_pd, input logic [1:0] expect_sel,
                                input string state_name);
    int cycles;
    begin
      for (cycles = 0; cycles < 100; cycles++) begin
        @(negedge clk_aon_i);
        if ((adc_pd_o == expect_pd) && (adc_chn_sel_o == expect_sel)) begin
          return;
        end
      end
      $fatal(1, "Timed out waiting for %s (pd=%0b sel=%0b, got pd=%0b sel=%0b)",
             state_name, expect_pd, expect_sel, adc_pd_o, adc_chn_sel_o);
    end
  endtask

  task automatic do_sample_pair(input logic [NumAdcFilter-1:0] match_value,
                                input int eval_hold_cycles);
    int i;
    begin
      adc_ctrl_match_i = match_value;

      wait_for_state(1'b0, 2'b01, "channel0 sample");
      adc_d_val_i = 1'b1;
      @(posedge clk_aon_i);

      wait_for_state(1'b0, 2'b00, "channel transition");
      adc_d_val_i = 1'b0;
      @(posedge clk_aon_i);

      wait_for_state(1'b0, 2'b10, "channel1 sample");
      adc_d_val_i = 1'b1;
      @(posedge clk_aon_i);

      for (i = 0; i < eval_hold_cycles; i++) begin
        wait_for_state(1'b0, 2'b00, "eval hold");
        adc_d_val_i = 1'b1;
        @(posedge clk_aon_i);
      end

      wait_for_state(1'b0, 2'b00, "eval complete");
      adc_d_val_i = 1'b0;
      @(posedge clk_aon_i);
      @(negedge clk_aon_i);
    end
  endtask

  initial begin
    clk_aon_i = 1'b0;
    rst_aon_ni = 1'b0;
    cfg_fsm_rst_i = 1'b0;
    cfg_adc_enable_i = 1'b0;
    cfg_oneshot_mode_i = 1'b0;
    cfg_lp_mode_i = 1'b1;
    cfg_pwrup_time_i = 4'd0;
    cfg_wakeup_time_i = 24'd0;
    cfg_lp_sample_cnt_i = 8'd1;
    cfg_np_sample_cnt_i = 16'd2;
    adc_ctrl_match_i = '0;
    adc_d_i = 10'd0;
    adc_d_val_i = 1'b0;
    saw_done = 1'b0;

    repeat (2) @(negedge clk_aon_i);
    rst_aon_ni = 1'b1;
    @(negedge clk_aon_i);
    cfg_adc_enable_i = 1'b1;

    do_sample_pair(8'b0000_0001, 0);
    if (saw_done) begin
      $fatal(1, "adc_ctrl_done_o asserted during LP-to-NP setup");
    end
    saw_done = 1'b0;

    do_sample_pair(8'b0000_0001, 0);
    if (saw_done) begin
      $fatal(1, "adc_ctrl_done_o asserted after only one stable NP match");
    end
    saw_done = 1'b0;

    do_sample_pair(8'b0000_0010, 1);
    if (saw_done) begin
      $fatal(1, "adc_ctrl_done_o asserted when the non-zero match set changed");
    end
    saw_done = 1'b0;

    do_sample_pair(8'b0000_0010, 0);
    if (saw_done) begin
      $fatal(1, "adc_ctrl_done_o asserted one NP sample too early after reset");
    end
    saw_done = 1'b0;

    do_sample_pair(8'b0000_0010, 0);
    if (!saw_done) begin
      $fatal(1, "adc_ctrl_done_o never asserted after two stable NP samples");
    end

    $display("TESTBENCH_PASS");
    $finish(0);
  end
endmodule
EOF

vcs -full64 -sverilog "$TB_DIR/tb.sv" -o "$TB_DIR/simv" -l "$TB_DIR/compile.log"
compile_rc=$?
run_rc=0
result_rc=0

if [ "$compile_rc" -eq 0 ]; then
  "$TB_DIR/simv" -l "$TB_DIR/run.log"
  run_rc=$?
fi

result_rc=$compile_rc
if [ "$result_rc" -eq 0 ] && [ "$run_rc" -ne 0 ]; then
  result_rc=$run_rc
fi

if [ "$result_rc" -eq 0 ] && [ -f "$TB_DIR/run.log" ]; then
  grep -q "TESTBENCH_PASS" "$TB_DIR/run.log"
  if [ "$?" -ne 0 ]; then
    result_rc=1
  fi
fi

if [ -f "$TB_DIR/compile.log" ]; then
  tail -n 120 "$TB_DIR/compile.log"
fi

if [ -f "$TB_DIR/run.log" ]; then
  tail -n 120 "$TB_DIR/run.log"
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$result_rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$result_rc"

