  logic entropy_bit_vld_i;
  logic clear_i;
  logic active_i;
  logic [RegWidth-1:0] thresh_i;
  logic window_wrap_pulse_i;
  logic [RegWidth-1:0] test_cnt_o;
  logic test_fail_pulse_o;
