    .test_fail_pulse_o(test_fail_pulse_o),
    .count_err_o(count_err_o)
  );

  always #5 clk_i = ~clk_i;

  task automatic send_symbol(input logic [RngBusWidth-1:0] symbol);
    begin
      @(negedge clk_i);
      entropy_bit_i = symbol;
      entropy_bit_vld_i = 1'b1;
      window_wrap_pulse_i = 1'b0;
      @(negedge clk_i);
      entropy_bit_vld_i = 1'b0;
    end
  endtask

  initial begin
