    entropy_bit_vld_i = 1'b0;
    clear_i = 1'b0;
    active_i = 1'b0;
    thresh_i = Threshold;
    window_wrap_pulse_i = 1'b0;

    repeat (2) @(negedge clk_i);
    rst_ni = 1'b1;
    active_i = 1'b1;

    repeat (11) begin
      send_symbol(RepeatedSymbol);
    end

    window_wrap_pulse_i = 1'b1;
    #1;

    if (count_err_o !== 1'b0) begin
      $display("TB_CHECK: FAIL count_err_o asserted unexpectedly");
      $fatal(2, "count_err_o asserted unexpectedly");
    end

    if (test_cnt_o !== ExpectedCount) begin
      $display("TB_CHECK: FAIL expected test_cnt_o=%0d, got %0d", ExpectedCount, test_cnt_o);
      $fatal(2, "expected test_cnt_o=%0d, got %0d", ExpectedCount, test_cnt_o);
    end

    if (test_fail_pulse_o !== 1'b1) begin
      $display("TB_CHECK: FAIL expected test_fail_pulse_o to assert when wrap follows the threshold-crossing sample");
      $fatal(2, "expected test_fail_pulse_o to assert when wrap follows the threshold-crossing sample");
    end

    @(negedge clk_i);
    window_wrap_pulse_i = 1'b0;
    #1;

    $display("TB_CHECK: PASS bucket health test flags the window-ending threshold crossing");
    $finish;
  end
endmodule
EOF

