#!/bin/bash
set +e

cd /home/opentitan
source /etc/opentitan_tools_path.sh

cat > hw/ip/aes/dv/env/seq_lib/aes_fatal_lockup_vseq.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class aes_fatal_lockup_vseq extends aes_base_vseq;
  `uvm_object_utils(aes_fatal_lockup_vseq)
  `uvm_object_new

  localparam bit [5:0] CipherCtrlStateRound = 6'b111101;
  localparam bit [5:0] CipherCtrlStateError = 6'b010111;
  localparam int unsigned MaxPollCycles = 200;

  localparam string FatalModePath =
      "tb.dut.u_aes_core.u_ctrl_reg_shadowed.u_ctrl_reg_shadowed_mode.committed_q";

  virtual function string find_cipher_state_path();
    string path;

    for (int i = 0; i < Sp2VWidth; i++) begin
      path = $sformatf({"tb.dut.u_aes_core.u_aes_cipher_core.u_aes_cipher_control.gen_fsm[%0d].",
                        "gen_fsm_p.u_aes_cipher_control_fsm_i.u_aes_cipher_control_fsm.",
                        "aes_cipher_ctrl_cs"}, i);
      if (uvm_hdl_check_path(path)) return path;

      path = $sformatf({"tb.dut.u_aes_core.u_aes_cipher_core.u_aes_cipher_control.gen_fsm[%0d].",
                        "gen_fsm_n.u_aes_cipher_control_fsm_i.u_aes_cipher_control_fsm.",
                        "aes_cipher_ctrl_cs"}, i);
      if (uvm_hdl_check_path(path)) return path;
    end

    `uvm_fatal(`gfn, "Unable to locate AES cipher control FSM state path")
    return "";
  endfunction

  virtual task wait_for_cipher_state(string path, bit [5:0] exp_state);
    uvm_hdl_data_t fsm_state;

    for (int i = 0; i < MaxPollCycles; i++) begin
      if (!uvm_hdl_read(path, fsm_state)) begin
        `uvm_fatal(`gfn, $sformatf("Failed to read cipher FSM state from %s", path))
      end
      if (fsm_state[5:0] == exp_state) return;
      cfg.clk_rst_vif.wait_clks(1);
    end

    `uvm_fatal(`gfn, $sformatf("Cipher FSM never reached expected state 0x%0h", exp_state))
  endtask

  virtual task wait_for_fatal_status(ref status_t status);
    for (int i = 0; i < MaxPollCycles; i++) begin
      csr_rd(.ptr(ral.status), .value(status), .blocking(1));
      if (status.alert_fatal_fault) return;
      cfg.clk_rst_vif.wait_clks(1);
    end

    `uvm_fatal(`gfn, "Timed out waiting for AES fatal alert status")
  endtask

  virtual task run_clean_message();
    bit [7:0][31:0] key [2];
    bit [3:0][31:0] iv;
    bit [3:0][31:0] data;
    bit [3:0][31:0] cipher_text;
    bit do_b2b;

    key[0] = '{
      32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff,
      32'h0f1e2d3c, 32'h4b5a6978, 32'h8796a5b4, 32'hc3d2e1f0
    };
    key[1] = '{default: 32'h0};
    iv = '{default: 32'h0};
    data = '{
      32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff
    };
    cipher_text = '{default: 32'h0};
    do_b2b = 1'b0;

    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));
    set_operation(aes_pkg::AES_ENC);
    set_mode(aes_pkg::AES_ECB);
    set_key_len(aes_pkg::AES_256);
    set_manual_operation(1'b0);
    write_key(key, do_b2b);
    write_iv(iv, do_b2b);
    add_data(data, do_b2b);
    csr_spinwait(.ptr(ral.status.output_valid), .exp_data(1'b1));
    read_data(cipher_text, do_b2b);
    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));
  endtask

  task body();
    bit [7:0][31:0] key [2];
    bit [3:0][31:0] iv;
    bit [3:0][31:0] data;
    bit do_b2b;
    bit has_ctrl_mode_assert;
    status_t status;
    string cipher_state_path;
    uvm_hdl_data_t fsm_state;
    uvm_hdl_data_t malformed_mode;

    expect_fatal_alerts = 1'b1;
    cfg.num_messages = 1;
    cfg.num_corrupt_messages = 0;
    cfg.split_cnt = 0;

    cipher_state_path = find_cipher_state_path();
    has_ctrl_mode_assert = uvm_hdl_check_path("tb.dut.u_aes_core.u_aes_control.AesModeValid");

    key[0] = '{
      32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff,
      32'h0f1e2d3c, 32'h4b5a6978, 32'h8796a5b4, 32'hc3d2e1f0
    };
    key[1] = '{default: 32'h0};
    iv = '{default: 32'h0};
    data = '{
      32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff
    };
    do_b2b = 1'b0;

    cfg.m_tl_agent_cfg.d_ready_delay_min = 0;
    cfg.m_tl_agent_cfg.d_ready_delay_max = 0;

    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));
    set_operation(aes_pkg::AES_ENC);
    set_mode(aes_pkg::AES_ECB);
    set_key_len(aes_pkg::AES_256);
    set_manual_operation(1'b0);
    write_key(key, do_b2b);
    write_iv(iv, do_b2b);

    fork
      begin : start_operation
        add_data(data, do_b2b);
      end
      begin : inject_and_check
        wait_for_cipher_state(cipher_state_path, CipherCtrlStateRound);
        cfg.clk_rst_vif.wait_clks(1);

        if (!uvm_hdl_check_path(FatalModePath)) begin
          `uvm_fatal(`gfn, "Unable to locate AES mode shadow register path")
        end

        malformed_mode = '0;
        malformed_mode[5:0] = 6'b110000;

        $assertoff(0, "tb.dut.u_aes_core.AesModeValid");
        if (has_ctrl_mode_assert) $assertoff(0, "tb.dut.u_aes_core.u_aes_control.AesModeValid");
        if (!uvm_hdl_force(FatalModePath, malformed_mode)) begin
          `uvm_fatal(`gfn, "Failed to inject malformed AES mode")
        end

        wait_for_fatal_status(status);
        cfg.clk_rst_vif.wait_clks(2);

        if (!uvm_hdl_read(cipher_state_path, fsm_state)) begin
          `uvm_fatal(`gfn, $sformatf("Failed to read cipher FSM state from %s", cipher_state_path))
        end

        if (fsm_state[5:0] != CipherCtrlStateError) begin
          `uvm_fatal(`gfn, $sformatf(
              "Cipher FSM did not lock on fatal alert. state=0x%0h status=%s",
              fsm_state[5:0], status2string(status)))
        end

        void'(uvm_hdl_release(FatalModePath));
        $asserton(0, "tb.dut.u_aes_core.AesModeValid");
        if (has_ctrl_mode_assert) $asserton(0, "tb.dut.u_aes_core.u_aes_control.AesModeValid");
      end
    join

    dut_init("HARD");
    cfg.num_messages = 1;
    cfg.num_corrupt_messages = 0;
    cfg.split_cnt = 0;
    run_clean_message();
    expect_fatal_alerts = 1'b0;
    wait_no_outstanding_access();
  endtask
endclass
