tb_script:
#!/bin/bash
cd /home/opentitan
set -uo pipefail

TEST_NAME="usb_iso_control_override"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
TB_SRC="${TB_DIR}/${TEST_NAME}_tb.sv"
PRIM_FLOP_SRC="${TB_DIR}/prim_flop.sv"
COMPILE_LOG="${TB_DIR}/compile.log"
SIM_LOG="${TB_DIR}/sim.log"

mkdir -p "${TB_DIR}"
rm -rf "${TB_DIR}/simv" "${TB_DIR}/simv.daidir" "${TB_DIR}/csrc" "${TB_DIR}/ucli.key"
rm -f "${TB_SRC}" "${PRIM_FLOP_SRC}" "${COMPILE_LOG}" "${SIM_LOG}"

cat > "${PRIM_FLOP_SRC}" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else begin
      q_o <= d_i;
    end
  end
endmodule
EOF

cat > "${TB_SRC}" <<'EOF'
module usb_iso_control_override_tb;
  import usb_consts_pkg::*;

  localparam int unsigned NumEps = 2;
  localparam int unsigned ClksPerBit = 4;
  localparam int unsigned MaxWaitClks = 512;
  localparam int unsigned ShortPktMaxClks = 108;

  logic clk_48mhz = 1'b0;
  logic rst_ni = 1'b0;
  logic link_reset = 1'b0;
  logic link_active = 1'b1;
  logic [6:0] dev_addr = 7'h12;
  logic cfg_eop_single_bit = 1'b0;
  logic cfg_rx_differential = 1'b0;
  logic tx_osc_test_mode = 1'b0;
  logic [NumEps-1:0] data_toggle_clear = '0;

  logic [3:0] out_ep_current;
  logic out_ep_data_put;
  logic [2:0] out_ep_put_addr;
  logic [7:0] out_ep_data;
  logic out_ep_newpkt;
  logic out_ep_acked;
  logic out_ep_rollback;
  logic [NumEps-1:0] out_ep_setup;
  logic [NumEps-1:0] out_ep_enabled = 2'b10;
  logic [NumEps-1:0] out_ep_control = 2'b10;
  logic [NumEps-1:0] out_ep_full = '0;
  logic [NumEps-1:0] out_ep_stall = '0;
  logic [NumEps-1:0] out_ep_iso = '0;

  logic [3:0] in_ep_current;
  logic in_ep_rollback;
  logic in_ep_xact_end;
  logic [2:0] in_ep_get_addr;
  logic in_ep_data_get;
  logic in_ep_newpkt;
  logic [NumEps-1:0] in_ep_enabled = 2'b10;
  logic [NumEps-1:0] in_ep_stall = '0;
  logic [NumEps-1:0] in_ep_has_data = '0;
  logic [7:0] in_ep_data = 8'h00;
  logic [NumEps-1:0] in_ep_data_done = '0;
  logic [NumEps-1:0] in_ep_iso = 2'b10;

  logic sof_valid;
  logic [10:0] frame_index;
  logic rx_jjj_det;
  logic rx_j_det;
  logic rx_crc_err;
  logic rx_pid_err;
  logic rx_bitstuff_err;

  logic usb_d = 1'b1;
  logic usb_dp = 1'b1;
  logic usb_dn = 1'b0;
  logic usb_d_o;
  logic usb_se0_o;
  logic usb_oe_o;

  usb_fs_nb_pe #(
    .NumOutEps(NumEps),
    .NumInEps(NumEps),
    .MaxPktSizeByte(8)
  ) dut (
    .clk_48mhz_i(clk_48mhz),
    .rst_ni(rst_ni),
    .link_reset_i(link_reset),
    .link_active_i(link_active),
    .dev_addr_i(dev_addr),
    .cfg_eop_single_bit_i(cfg_eop_single_bit),
    .cfg_rx_differential_i(cfg_rx_differential),
    .tx_osc_test_mode_i(tx_osc_test_mode),
    .data_toggle_clear_i(data_toggle_clear),
    .out_ep_current_o(out_ep_current),
    .out_ep_data_put_o(out_ep_data_put),
    .out_ep_put_addr_o(out_ep_put_addr),
    .out_ep_data_o(out_ep_data),
    .out_ep_newpkt_o(out_ep_newpkt),
    .out_ep_acked_o(out_ep_acked),
    .out_ep_rollback_o(out_ep_rollback),
    .out_ep_setup_o(out_ep_setup),
    .out_ep_enabled_i(out_ep_enabled),
    .out_ep_control_i(out_ep_control),
    .out_ep_full_i(out_ep_full),
    .out_ep_stall_i(out_ep_stall),
    .out_ep_iso_i(out_ep_iso),
    .in_ep_current_o(in_ep_current),
    .in_ep_rollback_o(in_ep_rollback),
    .in_ep_xact_end_o(in_ep_xact_end),
    .in_ep_get_addr_o(in_ep_get_addr),
    .in_ep_data_get_o(in_ep_data_get),
    .in_ep_newpkt_o(in_ep_newpkt),
    .in_ep_enabled_i(in_ep_enabled),
    .in_ep_stall_i(in_ep_stall),
    .in_ep_has_data_i(in_ep_has_data),
    .in_ep_data_i(in_ep_data),
    .in_ep_data_done_i(in_ep_data_done),
    .in_ep_iso_i(in_ep_iso),
    .sof_valid_o(sof_valid),
    .frame_index_o(frame_index),
    .rx_jjj_det_o(rx_jjj_det),
    .rx_j_det_o(rx_j_det),
    .rx_crc_err_o(rx_crc_err),
    .rx_pid_err_o(rx_pid_err),
    .rx_bitstuff_err_o(rx_bitstuff_err),
    .usb_d_i(usb_d),
    .usb_dp_i(usb_dp),
    .usb_dn_i(usb_dn),
    .usb_d_o(usb_d_o),
    .usb_se0_o(usb_se0_o),
    .usb_oe_o(usb_oe_o)
  );

  always #10 clk_48mhz = ~clk_48mhz;

  function automatic logic [4:0] crc5_token(input logic [10:0] token);
    logic [4:0] crc;
    int i;
    begin
      crc = 5'h1f;
      for (i = 0; i < 11; i++) begin
        if ((token[i] ^ crc[0]) == 1'b1) begin
          crc = (crc >> 1) ^ 5'h14;
        end else begin
          crc = crc >> 1;
        end
      end
      crc5_token = crc ^ 5'h1f;
    end
  endfunction

  task automatic drive_j();
    begin
      usb_dp = 1'b1;
      usb_dn = 1'b0;
      usb_d = 1'b1;
      repeat (ClksPerBit) @(posedge clk_48mhz);
    end
  endtask

  task automatic drive_k();
    begin
      usb_dp = 1'b0;
      usb_dn = 1'b1;
      usb_d = 1'b0;
      repeat (ClksPerBit) @(posedge clk_48mhz);
    end
  endtask

  task automatic drive_se0();
    begin
      usb_dp = 1'b0;
      usb_dn = 1'b0;
      usb_d = 1'b0;
      repeat (ClksPerBit) @(posedge clk_48mhz);
    end
  endtask

  task automatic drive_nrzi_bit(input bit bit_value,
                                ref bit line_is_j,
                                ref int unsigned ones_seen);
    begin
      if (ones_seen == 6) begin
        line_is_j = ~line_is_j;
        if (line_is_j) drive_j();
        else drive_k();
        ones_seen = 0;
      end

      if (!bit_value) begin
        line_is_j = ~line_is_j;
        ones_seen = 0;
      end else begin
        ones_seen++;
      end

      if (line_is_j) drive_j();
      else drive_k();
    end
  endtask

  task automatic drive_byte(input logic [7:0] data,
                            ref bit line_is_j,
                            ref int unsigned ones_seen);
    int i;
    begin
      for (i = 0; i < 8; i++) begin
        drive_nrzi_bit(data[i], line_is_j, ones_seen);
      end
    end
  endtask

  task automatic drive_in_token(input logic [6:0] addr,
                                input logic [3:0] endp);
    logic [10:0] token_data;
    logic [4:0] token_crc;
    logic [15:0] token_payload;
    logic [7:0] pid_byte;
    bit line_is_j;
    int unsigned ones_seen;
    begin
      line_is_j = 1'b1;
      ones_seen = 0;
      pid_byte = {~UsbPidIn, UsbPidIn};
      token_data = {endp, addr};
      token_crc = crc5_token(token_data);
      token_payload = {token_crc, token_data};

      repeat (8) @(posedge clk_48mhz);
      drive_byte(8'b1000_0000, line_is_j, ones_seen);
      drive_byte(pid_byte, line_is_j, ones_seen);
      drive_byte(token_payload[7:0], line_is_j, ones_seen);
      drive_byte(token_payload[15:8], line_is_j, ones_seen);
      drive_se0();
      drive_se0();
      drive_j();
    end
  endtask

  initial begin
    int unsigned wait_clks;
    int unsigned tx_active_clks;

    repeat (4) @(posedge clk_48mhz);
    rst_ni = 1'b1;
    repeat (8) @(posedge clk_48mhz);

    drive_in_token(7'h12, 4'd1);

    tx_active_clks = 0;
    for (wait_clks = 0; wait_clks < MaxWaitClks; wait_clks++) begin
      @(posedge clk_48mhz);
      if (usb_oe_o === 1'b1) begin
        tx_active_clks = 1;
        while (usb_oe_o === 1'b1) begin
          @(posedge clk_48mhz);
          tx_active_clks++;
          if (tx_active_clks > MaxWaitClks) begin
            $fatal(1, "Transmit response exceeded %0d clocks", MaxWaitClks);
          end
        end
        break;
      end
    end

    if (tx_active_clks == 0) begin
      $display("TB_CHECK: FAIL");
      $fatal(1, "Expected a device response to the IN token");
    end

    $display("Observed transmit window: %0d clocks", tx_active_clks);

    if (tx_active_clks > ShortPktMaxClks) begin
      $display("TB_CHECK: FAIL");
      $fatal(1,
             "Expected a short handshake packet, observed a longer data-style response (%0d clocks)",
             tx_active_clks);
    end

    $display("TB_CHECK: PASS");
    $display("Observed expected short handshake response");
    $finish(0);
  end
endmodule
EOF

set +e
timeout 1800 vcs -full64 -sverilog \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  -o "${TB_DIR}/simv" \
  -Mdir="${TB_DIR}/csrc" \
  -l "${COMPILE_LOG}" \
  "${PRIM_FLOP_SRC}" \
  /home/opentitan/hw/ip/usb_fs_nb_pe/rtl/usb_consts_pkg.sv \
  /home/opentitan/hw/ip/usb_fs_nb_pe/rtl/usb_fs_nb_in_pe.sv \
  /home/opentitan/hw/ip/usb_fs_nb_pe/rtl/usb_fs_nb_out_pe.sv \
  /home/opentitan/hw/ip/usb_fs_nb_pe/rtl/usb_fs_rx.sv \
  /home/opentitan/hw/ip/usb_fs_nb_pe/rtl/usb_fs_tx.sv \
  /home/opentitan/hw/ip/usb_fs_nb_pe/rtl/usb_fs_tx_mux.sv \
  /home/opentitan/hw/ip/usb_fs_nb_pe/rtl/usb_fs_nb_pe.sv \
  "${TB_SRC}"
compile_rc=$?

if [ "${compile_rc}" -eq 0 ]; then
  timeout 1800 "${TB_DIR}/simv" -l "${SIM_LOG}"
  sim_rc=$?
  if [ "${sim_rc}" -eq 0 ]; then
    if grep -q "TB_CHECK: PASS" "${SIM_LOG}" && ! grep -q "TB_CHECK: FAIL" "${SIM_LOG}"; then
      sim_rc=0
    else
      sim_rc=1
    fi
  fi
else
  sim_rc="${compile_rc}"
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${compile_rc}" -eq 0 ] && [ "${sim_rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

if [ "${compile_rc}" -ne 0 ]; then
  exit "${compile_rc}"
fi
exit "${sim_rc}"

