tb_script:
#!/bin/bash

cd /home/opentitan || exit 1
set -u

TEST_NAME="tlul_socket_blanking"
TB_DIR="/home/opentitan/.tb_tlul_socket_blank"
BUILD_DIR="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tlul_socket_blank_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:tlul_socket_blank_tb:0.1"
description: "Minimal VCS testbench for tlul_socket_1n blanking"

filesets:
  files_dv:
    depend:
      - lowrisc:tlul:socket_1n
    files:
      - tlul_socket_blank_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    filesets:
      - files_dv
    toplevel: tlul_socket_blank_tb
    tools:
      vcs:
        vcs_options:
          - "-timescale=1ns/1ps"
EOF

cat > "${TB_DIR}/tlul_socket_blank_tb.sv" <<'EOF'
`timescale 1ns/1ps

module tlul_socket_blank_tb;
  import tlul_pkg::*;

  localparam int unsigned N = 2;
  localparam logic [top_pkg::TL_DW-1:0] BlankedData = {top_pkg::TL_DW{1'b1}};

  logic clk_i;
  logic rst_ni;
  logic [$clog2(N + 1)-1:0] dev_select_i;
  tl_h2d_t tl_h_i;
  tl_d2h_t tl_h_o;
  tl_h2d_t tl_d_o [N];
  tl_d2h_t tl_d_i [N];
  tl_a_user_t exp_blanked_auser;

  always #5 clk_i = ~clk_i;

  always_comb begin
    for (int i = 0; i < N; i++) begin
      tl_d_i[i] = '0;
      tl_d_i[i].a_ready = 1'b1;
    end

    exp_blanked_auser = '{
      rsvd: tl_h_i.a_user.rsvd,
      instr_type: tl_h_i.a_user.instr_type,
      cmd_intg: ~tlul_pkg::get_cmd_intg(tl_h_i),
      data_intg: ~tlul_pkg::get_data_intg(BlankedData)
    };
  end

  tlul_socket_1n #(
    .N(N),
    .DReqDepth({N{4'h0}})
  ) dut (
    .clk_i,
    .rst_ni,
    .tl_h_i,
    .tl_h_o,
    .tl_d_o,
    .tl_d_i,
    .dev_select_i
  );

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    dev_select_i = '0;
    tl_h_i = tlul_pkg::TL_H2D_DEFAULT;
    tl_h_i.d_ready = 1'b1;

    repeat (3) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (3) @(posedge clk_i);

    @(negedge clk_i);
    tl_h_i.a_valid = 1'b1;
    tl_h_i.a_opcode = PutFullData;
    tl_h_i.a_param = '0;
    tl_h_i.a_size = top_pkg::TL_SZW'(2);
    tl_h_i.a_source = top_pkg::TL_AIW'(3);
    tl_h_i.a_address = top_pkg::TL_AW'(32'h0000_0084);
    tl_h_i.a_mask = {top_pkg::TL_DBW{1'b1}};
    tl_h_i.a_data = 32'h1357_2468;
    tl_h_i.a_user = '{
      rsvd: 5'h15,
      instr_type: prim_mubi_pkg::MuBi4True,
      cmd_intg: 7'h55,
      data_intg: 7'h2a
    };
    dev_select_i = '0;

    #1;

    if (tl_d_o[0].a_valid !== 1'b1) begin
      $error("selected device did not see a valid request");
      $fatal(1);
    end

    if (tl_d_o[0].a_data !== tl_h_i.a_data || tl_d_o[0].a_user !== tl_h_i.a_user) begin
      $error("selected device request payload changed unexpectedly");
      $fatal(1);
    end

    if (tl_d_o[1].a_valid !== 1'b0) begin
      $error("unselected device observed a valid request");
      $fatal(1);
    end

    if (tl_d_o[1].a_data !== BlankedData) begin
      $error("unselected device data was not blanked: %h", tl_d_o[1].a_data);
      $fatal(1);
    end

    if (tl_d_o[1].a_user !== exp_blanked_auser) begin
      $error("unselected device user payload was not blanked");
      $display("expected=%h actual=%h", exp_blanked_auser, tl_d_o[1].a_user);
      $fatal(1);
    end

    $display("BLANK_CHECK_PASS");
    $finish;
  end
endmodule
EOF

set +e
timeout 1800s fusesoc \
  --cores-root=/home/opentitan \
  --cores-root="${TB_DIR}" \
  run \
  --build-root="${BUILD_DIR}" \
  --target=sim \
  --tool=vcs \
  lowrisc:dv:tlul_socket_blank_tb:0.1 \
  2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
set -e

if [ "${rc}" -eq 0 ] && grep -q "BLANK_CHECK_PASS" "${RUN_LOG}"; then
  emit_result "PASS"
  exit 0
fi

if [ "${rc}" -eq 124 ]; then
  emit_result "FAIL"
  exit 124
fi

emit_result "FAIL"
exit 1

