    .data_valid_i,
    .sbaddress_o(sbaddress_to_sba),
    .sbaddress_i(sbaddress_from_sba),
    .sbaddress_write_valid_o,
    .sbreadonaddr_o,
    .sbautoincrement_o,
    .sbaccess_o,
    .sbreadondata_o,
    .sbdata_o(sbdata_to_sba),
    .sbdata_read_valid_o,
    .sbdata_write_valid_o,
    .sbdata_i(sbdata_from_sba),
    .sbdata_valid_i(sbdata_valid_from_sba),
    .sbbusy_i(sbbusy_from_sba),
    .sberror_valid_i(sberror_valid_from_sba),
    .sberror_i(sberror_from_sba)
  );

  dm_sba #(
    .BusWidth(32)
  ) u_dm_sba (
    .clk_i,
    .rst_ni,
    .dmactive_i(dmactive_o),
    .master_req_o,
    .master_add_o,
    .master_we_o,
    .master_wdata_o,
    .master_be_o,
    .master_gnt_i,
    .master_r_valid_i,
    .master_r_rdata_i,
    .sbaddress_i(sbaddress_to_sba),
    .sbaddress_write_valid_i(sbaddress_write_valid_o),
    .sbreadonaddr_i(sbreadonaddr_o),
    .sbaddress_o(sbaddress_from_sba),
    .sbautoincrement_i(sbautoincrement_o),
    .sbaccess_i(sbaccess_o),
    .sbreadondata_i(sbreadondata_o),
    .sbdata_i(sbdata_to_sba),
    .sbdata_read_valid_i(sbdata_read_valid_o),
    .sbdata_write_valid_i(sbdata_write_valid_o),
    .sbdata_o(sbdata_from_sba),
    .sbdata_valid_o(sbdata_valid_from_sba),
    .sbbusy_o(sbbusy_from_sba),
    .sberror_valid_o(sberror_valid_from_sba),
    .sberror_o(sberror_from_sba)
  );

  initial clk_i = 0;
  always #5 clk_i = ~clk_i;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      master_r_valid_i <= 1'b0;
      seen_req <= 1'b0;
      seen_be <= '0;
      seen_wdata <= '0;
    end else begin
      master_r_valid_i <= master_req_o;
      if (master_req_o && master_we_o && !seen_req) begin
        seen_req <= 1'b1;
        seen_be <= master_be_o;
        seen_wdata <= master_wdata_o;
      end
    end
  end

  assign master_gnt_i = 1'b1;
  assign master_r_rdata_i = 32'h11223344;

  task automatic dmi_write(input logic [6:0] addr, input logic [31:0] data);
    begin
      @(negedge clk_i);
      dmi_req_i.addr = addr;
      dmi_req_i.op = DTM_WRITE;
      dmi_req_i.data = data;
      dmi_req_valid_i = 1'b1;
      do @(posedge clk_i); while (!dmi_req_ready_o);
      @(negedge clk_i);
      dmi_req_valid_i = 1'b0;
      dmi_req_i = '0;
      do @(posedge clk_i); while (!dmi_resp_valid_o);
      resp_data = dmi_resp_o.data;
    end
  endtask

  initial begin
    testmode_i = 1'b0;
    dmi_req_valid_i = 1'b0;
    dmi_req_i = '0;
    dmi_resp_ready_i = 1'b1;
    halted_i = '0;
    unavailable_i = '0;
    resumeack_i = '0;
    hartinfo_i = '0;
    cmderror_valid_i = 1'b0;
    cmderror_i = CmdErrNone;
    cmdbusy_i = 1'b0;
    data_i = '0;
    data_valid_i = 1'b0;
    rst_ni = 1'b0;
    dmi_rst_ni = 1'b0;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    dmi_rst_ni = 1'b1;
    repeat (5) @(posedge clk_i);

    dmi_write(DMControl[6:0], 32'h0000_0001);
    repeat (2) @(posedge clk_i);
    if (dmactive_o !== 1'b1) begin
      $display("TB_ERROR: dmactive did not assert");
      $fatal(1);
    end

    dmi_write(SBCS[6:0], 32'h0000_0000);
    dmi_write(SBAddress0[6:0], 32'h0000_0001);
    dmi_write(SBData0[6:0], 32'h0000_00A5);

    repeat (10) @(posedge clk_i);
    if (!seen_req) begin
      $display("TB_ERROR: no SBA write request observed");
      $fatal(1);
    end

    if (seen_be !== 4'b0010) begin
      $display("TB_ERROR: expected byte enable 0010 for 8-bit write at addr 1, got %b", seen_be);
      $fatal(1);
    end

    if (seen_wdata !== 32'h0000_A500) begin
      $display("TB_ERROR: expected shifted write data 0x0000A500, got 0x%08x", seen_wdata);
      $fatal(1);
    end

    if (!$value$plusargs("success_file=%s", success_file)) begin
      $display("TB_ERROR: missing success_file plusarg");
      $fatal(1);
    end

    success_fd = $fopen(success_file, "w");
    if (success_fd == 0) begin
      $display("TB_ERROR: failed to create success stamp %s", success_file);
      $fatal(1);
    end

    $fdisplay(success_fd, "PASS");
    $fclose(success_fd);
    $display("TB_SUCCESS: observed 8-bit SBA write with be=%b wdata=0x%08x", seen_be, seen_wdata);
    $finish;
  end
endmodule
