#!/bin/bash
set -uo pipefail

TEST_NAME="keymgr_spurious_done"
TB_DIR="/home/opentitan/.tb_keymgr_spurious_done"
RUN_LOG="${TB_DIR}/dvsim.log"
rc=1

print_result() {
  echo "HWE_BENCH_RESULTS_START"
  if [ "${rc}" -eq 0 ]; then
    echo "TEST: ${TEST_NAME} ... PASS"
  else
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
}

trap print_result EXIT

cd /home/opentitan || exit 1

mkdir -p "${TB_DIR}"

cat > hw/ip/keymgr/dv/env/seq_lib/keymgr_sync_async_fault_cross_vseq.sv <<'SVEOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_sync_async_fault_cross_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_sync_async_fault_cross_vseq)
  `uvm_object_new

  task body();
    bit [TL_DW-1:0] fault_status;

    expect_fatal_alerts = 1;
    cfg.en_scb = 0;
    cfg.keymgr_vif.en_chk = 0;
    cfg.m_keymgr_kmac_agent_cfg.zero_delays = 1;

    $assertoff(0, "tb.keymgr_kmac_intf");

    cfg.clk_rst_vif.wait_clks(5);
    inject_spurious_done();
    cfg.clk_rst_vif.wait_clks(5);

    csr_rd(.ptr(ral.fault_status), .value(fault_status));
    `DV_CHECK_NE(fault_status, 0)

    keymgr_advance(.wait_done(0));
    csr_spinwait(.ptr(ral.op_status.status), .exp_data(keymgr_pkg::OpWip),
                 .timeout_ns(100_000), .compare_op(CompareOpNe),
                 .spinwait_delay_ns($urandom_range(0, 100)));
    csr_rd_check(.ptr(ral.op_status), .compare_value(keymgr_pkg::OpDoneFail));
    read_current_state();
    `DV_CHECK_EQ(current_state, keymgr_pkg::StInvalid)
  endtask : body

  task inject_spurious_done();
    `uvm_info(`gfn, "Injecting spurious KMAC done in idle window", UVM_LOW)
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_done <= 1'b1;
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_error <= 1'b0;
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_digest_share0 <= '0;
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_digest_share1 <= '0;
    @(cfg.m_keymgr_kmac_agent_cfg.vif.device_cb);
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_done <= 1'b0;
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_error <= 'x;
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_digest_share0 <= 'x;
    cfg.m_keymgr_kmac_agent_cfg.vif.device_cb.rsp_digest_share1 <= 'x;
  endtask : inject_spurious_done

  virtual function bit get_check_en();
    return 0;
  endfunction

  task post_start();
    super.post_start();
    cfg.en_scb = 1;
    cfg.keymgr_vif.en_chk = 1;
    $asserton(0, "tb.keymgr_kmac_intf");
  endtask
endclass : keymgr_sync_async_fault_cross_vseq
SVEOF

./util/dvsim/dvsim.py hw/ip/keymgr/dv/keymgr_sim_cfg.hjson \
