#!/bin/bash
set -euo pipefail

cd /home/opentitan

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  # Toolchain and Verible are installed during prepare stage.
  source /etc/opentitan_tools_path.sh
fi

TEST_NAME="keymgr_recov_alert_index"
VSEQ_DIR="/home/opentitan/hw/ip/keymgr/dv/env/seq_lib"
VSEQ_FILE="${VSEQ_DIR}/${TEST_NAME}_vseq.sv"
VSEQ_LIST="/home/opentitan/hw/ip/keymgr/dv/env/seq_lib/keymgr_vseq_list.sv"
ENV_CORE="/home/opentitan/hw/ip/keymgr/dv/env/keymgr_env.core"
SIM_CFG="/home/opentitan/hw/ip/keymgr/dv/keymgr_sim_cfg.hjson"

cat > "${VSEQ_FILE}" <<'EOF'
class keymgr_recov_alert_index_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_recov_alert_index_vseq)
  `uvm_object_new

  virtual task pre_start();
    do_keymgr_init = 1'b0;
    super.pre_start();
    en_auto_alerts_response = 0;
    cfg.en_scb = 0;
  endtask

  task body();
    bit [TL_DW-1:0] alert_req;
    bit idx0_seen = 1'b0;
    bit idx1_seen = 1'b0;
    dv_base_reg alert_test_csr;
    uvm_reg_field recov_field;
    string idx0_name;
    string idx1_name;

    alert_test_csr = ral.get_dv_base_reg_by_name("alert_test");
    recov_field = ral.get_field_by_name("recov_operation_err");
    idx0_name = cfg.list_of_alerts[0];
    idx1_name = cfg.list_of_alerts[1];

    alert_req = 1'b1 << recov_field.get_lsb_pos();
    csr_wr(.ptr(alert_test_csr), .value(alert_req));
    `uvm_info(`gfn, $sformatf("Force recov alert with alert_test value 0x%0h", alert_req),
              UVM_MEDIUM)

    repeat (50) begin
      cfg.clk_rst_vif.wait_clks(1);
      idx0_seen |= cfg.m_alert_agent_cfg[idx0_name].vif.get_alert();
      idx1_seen |= cfg.m_alert_agent_cfg[idx1_name].vif.get_alert();
    end

    `DV_CHECK_EQ(idx0_seen, 1'b1,
                 $sformatf("recov alert should assert physical alert index 0 (%0s)", idx0_name))
    `DV_CHECK_EQ(idx1_seen, 1'b0,
                 $sformatf("recov alert must not assert physical alert index 1 (%0s)", idx1_name))
  endtask
endclass
EOF

if ! grep -q "${TEST_NAME}_vseq" "${VSEQ_LIST}"; then
  sed -i '/`include "keymgr_stress_all_vseq.sv"/a `include "keymgr_recov_alert_index_vseq.sv"' \
    "${VSEQ_LIST}"
fi

if ! grep -q "${TEST_NAME}_vseq" "${ENV_CORE}"; then
  sed -i '/seq_lib\/keymgr_stress_all_vseq.sv: {is_include_file: true}/a\      - seq_lib/keymgr_recov_alert_index_vseq.sv: {is_include_file: true}' \
    "${ENV_CORE}"
fi

if ! grep -q "name: ${TEST_NAME}" "${SIM_CFG}"; then
  perl -0pi -e 's/\n    \{\n      name: keymgr_stress_all\n      uvm_test_seq: keymgr_stress_all_vseq\n    \}\n/\n    {\n      name: keymgr_recov_alert_index\n      uvm_test_seq: keymgr_recov_alert_index_vseq\n    }\n\n    {\n      name: keymgr_stress_all\n      uvm_test_seq: keymgr_stress_all_vseq\n    }\n/' \
    "${SIM_CFG}"
fi

set +e
timeout 1800s ./util/dvsim/dvsim.py hw/ip/keymgr/dv/keymgr_sim_cfg.hjson \
  -i "${TEST_NAME}" \
  -t vcs \
  --fixed-seed 1 \
  --local
rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ "${rc}" -eq 0 ]]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME=spi_device_busy_block

emit_result() {
  local rc=$1
  echo "HWE_BENCH_RESULTS_START"
  if [[ ${rc} -eq 0 ]]; then
    echo "TEST: ${TEST_NAME} ... PASS"
  else
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
}

trap 'rc=$?; emit_result "${rc}"; exit "${rc}"' EXIT

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  # Keep toolchain and Verible on PATH if the shell has not sourced them yet.
  source /etc/opentitan_tools_path.sh
fi

WORKDIR=/home/opentitan/.tb_spi_device_busy_block
SEQ_FILE="${WORKDIR}/spi_device_pass_busy_block_vseq.sv"
SIM_CFG="${WORKDIR}/spi_device_busy_block_sim_cfg.hjson"
VSEQ_LIST=hw/ip/spi_device/dv/env/seq_lib/spi_device_vseq_list.sv
LOG_DIR="${WORKDIR}/logs"

rm -rf "${WORKDIR}"
mkdir -p "${LOG_DIR}"

cat > "${SEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class spi_device_pass_busy_block_vseq extends spi_device_pass_base_vseq;
  `uvm_object_utils(spi_device_pass_busy_block_vseq)
  `uvm_object_new

  localparam bit [7:0] PassCmd = 8'hA5;
  localparam bit [23:0] PassAddr = 24'h123456;
  localparam string PassEnPath = "tb.pass_out.passthrough_en";

  virtual task body();
    bit [31:0] device_word_rsp;
    bit [31:0] address_command;
    uvm_hdl_data_t pass_en;
    int unsigned cmd_info_idx;

    spi_device_passthrough_init();
    cfg.clk_rst_vif.wait_clks(20);

    `DV_CHECK_FATAL(uvm_hdl_check_path(PassEnPath))
    `DV_CHECK_FATAL(uvm_hdl_read(PassEnPath, pass_en))
    `DV_CHECK_EQ(pass_en[0], 1'b1, "Passthrough should start enabled")

    cmd_info_idx = spi_device_pkg::CmdInfoReserveStart;
    ral.cmd_info[cmd_info_idx].valid.set(1'b1);
    ral.cmd_info[cmd_info_idx].opcode.set(PassCmd);
    ral.cmd_info[cmd_info_idx].addr_mode.set(Addr3B);
    ral.cmd_info[cmd_info_idx].addr_swap_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].mbyte_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].dummy_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].dummy_size.set('0);
    ral.cmd_info[cmd_info_idx].payload_en.set(4'b0001);
    ral.cmd_info[cmd_info_idx].payload_dir.set(PayloadIn);
    ral.cmd_info[cmd_info_idx].payload_swap_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].upload.set(1'b1);
    ral.cmd_info[cmd_info_idx].busy.set(1'b1);
    csr_update(.csr(ral.cmd_info[cmd_info_idx]));

    order_cmd_bits(PassCmd, PassAddr, address_command);
    spi_host_xfer_word(address_command, device_word_rsp);

    cfg.clk_rst_vif.wait_clks(50);
    csr_rd_check(.ptr(ral.flash_status), .compare_value(32'h1));

    `DV_CHECK_FATAL(uvm_hdl_read(PassEnPath, pass_en))
    `DV_CHECK_EQ(pass_en[0], 1'b0, "Passthrough must be blocked while BUSY is set")
  endtask
endclass
EOF

if ! grep -Fq 'spi_device_pass_busy_block_vseq.sv' "${VSEQ_LIST}"; then
  printf '\n`include "%s"\n' "${SEQ_FILE}" >> "${VSEQ_LIST}"
fi

python - <<'PY'
from pathlib import Path

src = Path("/home/opentitan/hw/ip/spi_device/dv/spi_device_sim_cfg.hjson")
dst = Path("/home/opentitan/.tb_spi_device_busy_block/spi_device_busy_block_sim_cfg.hjson")
text = src.read_text(encoding="utf-8")
needle = """    {\n      name: spi_device_pass_cmd_filtering\n      uvm_test_seq: spi_device_pass_cmd_filtering_vseq\n    }\n"""
replacement = needle + """\n    {\n      name: spi_device_busy_block\n      uvm_test_seq: spi_device_pass_busy_block_vseq\n    }\n"""
if needle not in text:
    raise SystemExit("Unable to find spi_device_pass_cmd_filtering test entry")
dst.write_text(text.replace(needle, replacement, 1), encoding="utf-8")
PY

set +e
timeout 1800 python util/dvsim/dvsim.py "${SIM_CFG}" \
  -i spi_device_busy_block \
  -t vcs \
  --fixed-seed 1 \
  --max-parallel 1 \
  --local \
  --purge \
  --branch tb_spi_device_busy_block \
  --scratch-root "${WORKDIR}/scratch" \
  --run-opts +test_timeout_ns=1500000000 \
  --run-opts +drain_time_ns=1000 \
  2>&1 | tee "${LOG_DIR}/dvsim.log"
rc=${PIPESTATUS[0]}
set -e

exit "${rc}"

