tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="keymgr_cmd_consistency"
TB_ROOT="/home/opentitan/.tb_${TEST_NAME}"
SEQ_NAME="${TEST_NAME}_vseq"
SEQ_SRC="${TB_ROOT}/${SEQ_NAME}.sv"
VSEQ_LIST="/home/opentitan/hw/ip/keymgr/dv/env/seq_lib/keymgr_vseq_list.sv"
LOG_FILE="${TB_ROOT}/dvsim.log"

mkdir -p "${TB_ROOT}"

cat > "${SEQ_SRC}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_cmd_consistency_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_cmd_consistency_vseq)
  `uvm_object_new

  localparam int MaxWaitClks = 20000;
  localparam bit [9:0] KmacIfStOpWait = 10'b1000101001;
  localparam bit [7:0] CtrlOpStWait = 8'b11111110;

  task body();
    bit [TL_DW-1:0] fault_status;

    `uvm_info(`gfn, "Trigger command consistency fault", UVM_MEDIUM)

    repeat (2) keymgr_advance();

    cfg.en_scb = 0;
    cfg.keymgr_vif.en_chk = 0;

    fork
      begin
        wait_for_cmd_swap_window();
        force_bit("tb.dut.u_ctrl.id_en_o", 1'b0);
        force_bit("tb.dut.u_ctrl.gen_en_o", 1'b1);
        repeat (2) @(posedge cfg.clk_rst_vif.clk);
        release_bit("tb.dut.u_ctrl.gen_en_o");
        release_bit("tb.dut.u_ctrl.id_en_o");
      end
      begin
        keymgr_generate(.operation(keymgr_pkg::OpGenId),
                        .key_dest(keymgr_pkg::None),
                        .wait_done(0));
      end
    join

    csr_spinwait(.ptr(ral.op_status.status), .exp_data(keymgr_pkg::OpWip),
                 .timeout_ns(1_000_000), .compare_op(CompareOpNe), .spinwait_delay_ns(0));
    cfg.clk_rst_vif.wait_clks(2);
    csr_rd_check(.ptr(ral.op_status), .compare_value(keymgr_pkg::OpDoneFail));
    csr_rd(.ptr(ral.fault_status), .value(fault_status));
    `DV_CHECK_EQ(fault_status[keymgr_pkg::FaultKmacCmd], 1'b1)
    csr_rd_check(.ptr(ral.working_state), .compare_value(keymgr_pkg::StInvalid));
  endtask

  task wait_for_cmd_swap_window();
    int cycles;
    uvm_hdl_data_t kmac_state;
    uvm_hdl_data_t ctrl_state;
    uvm_hdl_data_t id_en;
    uvm_hdl_data_t gen_en;
    uvm_hdl_data_t adv_en;

    for (cycles = 0; cycles < MaxWaitClks; cycles++) begin
      read_hdl("tb.dut.u_kmac_if.state_raw_q", kmac_state);
      read_hdl("tb.dut.u_ctrl.op_state_raw_q", ctrl_state);
      read_hdl("tb.dut.u_ctrl.id_en_o", id_en);
      read_hdl("tb.dut.u_ctrl.gen_en_o", gen_en);
      read_hdl("tb.dut.u_ctrl.adv_en_o", adv_en);
      if (kmac_state[9:0] == KmacIfStOpWait &&
          ctrl_state[7:0] == CtrlOpStWait &&
          id_en[0] == 1'b1 &&
          gen_en[0] == 1'b0 &&
          adv_en[0] == 1'b0) begin
        return;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end

    `uvm_fatal(`gfn, "Timed out waiting for command swap window")
  endtask

  function void read_hdl(string path, output uvm_hdl_data_t value);
    if (!uvm_hdl_read(path, value)) begin
      `uvm_fatal(`gfn, $sformatf("Failed to read %0s", path))
    end
  endfunction

  function void force_bit(string path, bit value);
    uvm_hdl_data_t hdl_value;

    hdl_value = '0;
    hdl_value[0] = value;
    if (!uvm_hdl_force(path, hdl_value)) begin
      `uvm_fatal(`gfn, $sformatf("Failed to force %0s", path))
    end
  endfunction

  function void release_bit(string path);
    if (!uvm_hdl_release(path)) begin
      `uvm_fatal(`gfn, $sformatf("Failed to release %0s", path))
    end
  endfunction

  virtual function bit get_check_en();
    return 0;
  endfunction

  task post_start();
    expect_fatal_alerts = 1;
    super.post_start();
    cfg.en_scb = 1;
    cfg.keymgr_vif.en_chk = 1;
  endtask
endclass
EOF

python - <<'PY'
from pathlib import Path

seq_src = Path("/home/opentitan/.tb_keymgr_cmd_consistency/keymgr_cmd_consistency_vseq.sv")
vseq_list = Path("/home/opentitan/hw/ip/keymgr/dv/env/seq_lib/keymgr_vseq_list.sv")
block_begin = "// MSWE TB CMD CONSISTENCY BEGIN\n"
block_end = "// MSWE TB CMD CONSISTENCY END\n"

text = vseq_list.read_text(encoding="utf-8")
if block_begin in text and block_end in text:
    prefix, rest = text.split(block_begin, 1)
    _, suffix = rest.split(block_end, 1)
    text = prefix.rstrip() + "\n" + suffix.lstrip("\n")

text = text.replace('`include "keymgr_side_ctrl_sel_consistency_vseq.sv"\n', "")
text = text.rstrip() + "\n\n" + block_begin + seq_src.read_text(encoding="utf-8").rstrip() + "\n" + block_end + "\n"
vseq_list.write_text(text, encoding="utf-8")
PY

set +e
timeout 1800 ./util/dvsim/dvsim.py hw/ip/keymgr/dv/keymgr_sim_cfg.hjson \
  -i keymgr_smoke \
  -t vcs \
  --local \
  --max-parallel 1 \
  --purge \
  --no-rerun \
  --scratch-root "${TB_ROOT}/scratch" \
  --branch "mswe-tb" \
  --fixed-seed 1 \
  --run-opts "+UVM_TEST_SEQ=${SEQ_NAME}" \
  |& tee "${LOG_FILE}"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ ${rc} -eq 0 ]]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit ${rc}

