#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="aes_auto_start_after_clear"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
HELPER="$TB_DIR/apply_test.py"
SETUP_LOG="$TB_DIR/setup.log"
DV_LOG="$TB_DIR/dvsim.log"

mkdir -p "$TB_DIR"

cat > "$HELPER" <<'PY'
from pathlib import Path


ROOT = Path("/home/opentitan")


def add_after_once(path: Path, needle: str, insert: str) -> None:
    text = path.read_text()
    if insert in text:
        return
    if needle not in text:
        raise RuntimeError(f"needle not found in {path}: {needle!r}")
    path.write_text(text.replace(needle, needle + insert, 1))


(ROOT / "hw/ip/aes/dv/env/seq_lib/aes_auto_start_after_clear_vseq.sv").write_text(
    """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class aes_auto_start_after_clear_vseq extends aes_base_vseq;
  `uvm_object_utils(aes_auto_start_after_clear_vseq)

  `uvm_object_new

  bit [255:0] init_key[2] = '{
    256'h000102030405060708090A0B0C0D0E0F00000000000000000000000000000000,
    256'h0
  };
  bit [3:0][31:0] init_iv = 128'h0F0E0D0C0B0A09080706050403020100;
  bit [3:0][31:0] data_before_clear = 128'hDEADBEEFFEEDBEEFC001D00DCAFEBABE;
  bit [3:0][31:0] data_after_clear  = 128'h00112233445566778899AABBCCDDEEFF;
  bit [3:0][31:0] cipher_text;
  clear_t clear = '{default: 0};
  status_t status;
  bit do_b2b = 0;

  task automatic check_no_auto_start();
    repeat (10) begin
      csr_rd(.ptr(ral.status), .value(status), .blocking(1));
      if ((!status.idle && !status.alert_fatal_fault) || status.output_valid) begin
        `uvm_fatal(`gfn,
                   $sformatf("AES started before DATA_IN_3 was rewritten after clear: %s",
                             status2string(status)))
      end
      cfg.clk_rst_vif.wait_clks(5);
    end
  endtask

  task body();
    `uvm_info(`gfn, "STARTING AES AUTO START AFTER CLEAR SEQUENCE", UVM_LOW)

    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));

    set_operation(AES_ENC);
    set_mode(AES_CFB);
    set_key_len(AES_128);
    set_manual_operation(1'b0);

    csr_wr(.ptr(ral.data_in[3]), .value(data_before_clear[3]), .blocking(1));

    clear.key_iv_data_in = 1'b1;
    clear_regs(clear);
    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));

    write_key(init_key, do_b2b);
    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));
    write_iv(init_iv, do_b2b);
    csr_spinwait(.ptr(ral.status.input_ready), .exp_data(1'b1));

    csr_wr(.ptr(ral.data_in[0]), .value(data_after_clear[0]), .blocking(1));
    csr_wr(.ptr(ral.data_in[1]), .value(data_after_clear[1]), .blocking(1));
    csr_wr(.ptr(ral.data_in[2]), .value(data_after_clear[2]), .blocking(1));

    check_no_auto_start();

    csr_wr(.ptr(ral.data_in[3]), .value(data_after_clear[3]), .blocking(1));

    csr_spinwait(.ptr(ral.status.output_valid), .exp_data(1'b1));
    read_data(cipher_text, do_b2b);
    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));

    `uvm_info(`gfn, "AES remained idle until the final data word was rewritten", UVM_LOW)
  endtask
endclass
"""
)

(ROOT / "hw/ip/aes/dv/tests/aes_auto_start_after_clear_test.sv").write_text(
    """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class aes_auto_start_after_clear_test extends aes_base_test;
  `uvm_component_utils(aes_auto_start_after_clear_test)
  `uvm_component_new

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    configure_env();
  endfunction

  virtual function void configure_env();
    super.configure_env();
    cfg.en_scb = 0;
    cfg.error_types = 0;
    `DV_CHECK_RANDOMIZE_FATAL(cfg)
  endfunction
endclass
"""
)

add_after_once(
    ROOT / "hw/ip/aes/dv/env/aes_env.core",
    "      - seq_lib/aes_manual_config_err_vseq.sv: {is_include_file: true}\n",
    "      - seq_lib/aes_auto_start_after_clear_vseq.sv: {is_include_file: true}\n",
)

add_after_once(
    ROOT / "hw/ip/aes/dv/env/seq_lib/aes_vseq_list.sv",
    '`include "aes_manual_config_err_vseq.sv"\n',
    '`include "aes_auto_start_after_clear_vseq.sv"\n',
)

add_after_once(
    ROOT / "hw/ip/aes/dv/tests/aes_test_pkg.sv",
    '  `include "aes_manual_config_err_test.sv"\n',
    '  `include "aes_auto_start_after_clear_test.sv"\n',
)

add_after_once(
    ROOT / "hw/ip/aes/dv/tests/aes_test.core",
    "      - aes_manual_config_err_test.sv: {is_include_file: true}\n",
    "      - aes_auto_start_after_clear_test.sv: {is_include_file: true}\n",
)

add_after_once(
    ROOT / "hw/ip/aes/dv/aes_base_sim_cfg.hjson",
    """    {
      name: aes_clear
      uvm_test: aes_clear_test
      uvm_test_seq: aes_stress_vseq
    }
""",
    """    {
      name: aes_auto_start_after_clear
      uvm_test: aes_auto_start_after_clear_test
      uvm_test_seq: aes_auto_start_after_clear_vseq
      reseed: 1
    }
""",
)
PY

