class kmac_prefix_regwen_lock_vseq extends kmac_smoke_vseq;
  `uvm_object_utils(kmac_prefix_regwen_lock_vseq)
  `uvm_object_new

  constraint single_trans_c {
    num_trans == 1;
  }

  constraint force_kmac_c {
    kmac_en == 1;
    key_len == Key128;
    strength == sha3_pkg::L128;
    output_len == 32;
    msg.size() == 4;
  }

  task body();
    bit [TL_DW-1:0] orig_prefix0;
    bit [TL_DW-1:0] mutated_prefix0;
    bit [TL_DW-1:0] observed_prefix0;
    uvm_reg prefix0_csr;

    kmac_init();
    set_prefix();
    write_key_shares();

    prefix0_csr = ral.get_reg_by_name("prefix_0");
    csr_rd(.ptr(prefix0_csr), .value(orig_prefix0));

    issue_cmd(CmdStart);
    wait (cfg.kmac_vif.idle_o != prim_mubi_pkg::MuBi4True);
    cfg.clk_rst_vif.wait_clks(1);

    mutated_prefix0 = orig_prefix0 ^ 32'h00ff_00ff;
    if (mutated_prefix0 == orig_prefix0) mutated_prefix0 = orig_prefix0 ^ 32'hff00_ff00;

    csr_wr(.ptr(prefix0_csr), .value(mutated_prefix0));
    csr_utils_pkg::wait_no_outstanding_access();
    csr_rd(.ptr(prefix0_csr), .value(observed_prefix0), .backdoor(1'b1));

    if (observed_prefix0 != orig_prefix0) begin
      `uvm_fatal(`gfn, $sformatf("prefix_0 changed while operation was active: expected 0x%0x got 0x%0x",
                                 orig_prefix0, observed_prefix0))
    end

    `uvm_info(`gfn, $sformatf("prefix_0 stayed locked at 0x%0x", observed_prefix0), UVM_LOW)

    // Reset after the lock check so the test ends cleanly without relying on later KMAC flow.
    dut_init("HARD");
  endtask : body
endclass : kmac_prefix_regwen_lock_vseq
SVEOF

