#!/bin/bash
cd /home/opentitan
set -euo pipefail

TEST_NAME="flash_ctrl_host_cmd_intg_alert"
COMMON_FILE="/home/opentitan/hw/ip/flash_ctrl/dv/env/seq_lib/flash_ctrl_common_vseq.sv"
SCRATCH_ROOT="/home/opentitan/.tb_flash_ctrl_host_cmd_intg"

python - <<'PY'
from pathlib import Path

path = Path("/home/opentitan/hw/ip/flash_ctrl/dv/env/seq_lib/flash_ctrl_common_vseq.sv")
text = path.read_text(encoding="utf-8")
custom = """

class flash_ctrl_host_cmd_intg_alert_vseq extends flash_ctrl_base_vseq;
  `uvm_object_utils(flash_ctrl_host_cmd_intg_alert_vseq)
  `uvm_object_new

  virtual task body();
    bit [TL_AW-1:0] flash_addr;
    cip_tl_seq_item req;

    `DV_CHECK_FATAL(cfg.ral_models[cfg.flash_ral_name].mem_ranges.size > 0,
                    "flash host interface memory range is not available")

    set_tl_assert_en(.enable(0));

    cfg.tl_intg_alert_name = "fatal_std_err";
    cfg.tl_intg_alert_fields.delete();
    cfg.tl_intg_alert_fields[ral.std_fault_status.reg_intg_err] = 1;

    csr_rd_check(.ptr(ral.std_fault_status.reg_intg_err), .compare_value(0));

    flash_addr = cfg.ral_models[cfg.flash_ral_name].mem_ranges[0].start_addr;
    `uvm_create_on(req, p_sequencer.tl_sequencer_hs[cfg.flash_ral_name])
    start_item(req);
    `DV_CHECK_RANDOMIZE_WITH_FATAL(req,
                                   a_valid_delay == 0;
                                   a_addr == flash_addr;
                                   a_data == '0;
                                   a_mask == '1;
                                   a_opcode == tlul_pkg::Get;)
    req.tl_intg_err_type = TlIntgErrCmd;
    req.set_instr_type(MuBi4False);
    finish_item(req);

    check_tl_intg_error_response();
    dut_init("HARD");

    set_tl_assert_en(.enable(1));
  endtask : body

endclass : flash_ctrl_host_cmd_intg_alert_vseq
"""

if "class flash_ctrl_host_cmd_intg_alert_vseq extends flash_ctrl_base_vseq;" not in text:
    path.write_text(text.rstrip() + custom + "\n", encoding="utf-8")
PY

set +e
timeout 1800 python util/dvsim/dvsim.py \
  hw/ip/flash_ctrl/dv/flash_ctrl_sim_cfg.hjson \
  -i flash_ctrl_smoke \
  -t vcs \
  --local \
  --max-parallel 1 \
  --scratch-root "${SCRATCH_ROOT}" \
  --branch tbgen \
  --fixed-seed 1 \
  --build-seed 1 \
  --reseed 1 \
  --purge \
  --no-rerun \
  --run-opts +UVM_TEST_SEQ=flash_ctrl_host_cmd_intg_alert_vseq +en_scb=0
rc=$?
set -e

if [ "${rc}" -eq 0 ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
else
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
fi

exit "${rc}"

