tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan || exit 1

TEST_NAME="spi_p2s_dummy_cycle_gate"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
TB_SRC="${TB_DIR}/tb.sv"
FILES_F="${TB_DIR}/files.f"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
PASS_SENTINEL="${TB_DIR}/sim.pass"
FAIL_SENTINEL="${TB_DIR}/sim.fail"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_SRC}" <<'EOF'
`timescale 1ns/1ps

module tb;
  import spi_device_pkg::*;

  string pass_sentinel = "/home/opentitan/.tb_spi_p2s_dummy_cycle_gate/sim.pass";
  string fail_sentinel = "/home/opentitan/.tb_spi_p2s_dummy_cycle_gate/sim.fail";

  logic clk_i = 0;
  logic rst_ni = 0;
  logic data_valid_i = 0;
  spi_byte_t data_i = 8'hA5;
  logic data_sent_o;
  logic csb_i = 0;
  logic [3:0] s_en_o;
  logic [3:0] s_o;
  logic cpha_i = 1'b1;
  logic order_i = 1'b0;
  io_mode_e io_mode_i = SingleIO;

  spi_p2s dut (
    .clk_i,
    .rst_ni,
    .data_valid_i,
    .data_i,
    .data_sent_o,
    .csb_i,
    .s_en_o,
    .s_o,
    .cpha_i,
    .order_i,
    .io_mode_i
  );

  always #5 clk_i = ~clk_i;

  task automatic tb_fail(input string msg);
    begin
      $display("TB_CHECK_FAIL %0s", msg);
      void'($system({"touch ", fail_sentinel}));
      $finish;
    end
  endtask

  initial begin
    #500;
    tb_fail("timeout waiting for spi_p2s check to complete");
  end

  initial begin
    repeat (2) @(posedge clk_i);
    @(negedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    io_mode_i = DualIO;
    data_valid_i = 1'b1;

    // Drain an initial byte so the next valid phase starts after a payload-sized transfer.
    repeat (8) @(posedge clk_i);
    #1;
    if (data_sent_o !== 1'b0) begin
      tb_fail($sformatf("data_sent_o unexpectedly high after initial transfer, got %b",
                        data_sent_o));
    end

    // Four dummy cycles for a Fast Read Dual transaction must not advance the transfer.
    data_valid_i = 1'b0;
    repeat (4) begin
      @(posedge clk_i);
      #1;
      if (data_sent_o !== 1'b0) begin
        tb_fail($sformatf("data_sent_o asserted during dummy cycles, got %b",
                          data_sent_o));
      end
      if (s_en_o !== 4'b0000) begin
        tb_fail($sformatf("s_en_o should be 0000 during dummy cycles, got %b", s_en_o));
      end
    end

    data_valid_i = 1'b1;

    @(posedge clk_i);
    #1;
    if (s_en_o !== 4'b0011) begin
      tb_fail($sformatf("expected DualIO enable 0011 when payload resumes, got %b", s_en_o));
    end
    if (data_sent_o !== 1'b0) begin
      tb_fail($sformatf("data_sent_o asserted too early after dummy cycles, got %b",
                        data_sent_o));
    end

    @(posedge clk_i);
    #1;
    if (data_sent_o !== 1'b1) begin
      tb_fail($sformatf("expected data_sent_o after two valid DualIO beats, got %b",
                        data_sent_o));
    end

    $display("TB_CHECK_PASS");
    void'($system({"touch ", pass_sentinel}));
    $finish;
  end
endmodule
EOF

cat > "${FILES_F}" <<EOF
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/hw/ip/spi_device/rtl/spi_device_reg_pkg.sv
/home/opentitan/hw/ip/spi_device/rtl/spi_device_pkg.sv
/home/opentitan/hw/ip/prim/rtl/prim_assert.sv
/home/opentitan/hw/ip/spi_device/rtl/spi_p2s.sv
${TB_SRC}
EOF

set +e
vcs -full64 -sverilog -timescale=1ns/1ps +define+SYNTHESIS \
  -f "${FILES_F}" \
  -o "${TB_DIR}/simv" \
  -l "${COMPILE_LOG}"
compile_rc=$?
set -e

if [ "${compile_rc}" -ne 0 ]; then
  tail -n 80 "${COMPILE_LOG}" || true
  emit_result "FAIL"
  exit 1
fi

rm -f "${PASS_SENTINEL}" "${FAIL_SENTINEL}"

set +e
"${TB_DIR}/simv" -l "${RUN_LOG}"
sim_rc=$?
set -e

if [ -f "${PASS_SENTINEL}" ] && [ ! -f "${FAIL_SENTINEL}" ]; then
  emit_result "PASS"
  exit 0
fi

tail -n 80 "${RUN_LOG}" || true
emit_result "FAIL"
exit 1

