#!/bin/bash
set -uo pipefail

cd /home/opentitan || exit 1

TEST_NAME="spi_device_wren_wrdi_status"
TB_DIR="/home/opentitan/.tb_spi_device_wren"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
WORK_LOG="${TB_DIR}/work.log"

rc=1
stage="setup"
result_emitted=0

print_result() {
  local status="$1"

  if [ "${result_emitted}" -ne 0 ]; then
    return
  fi

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  result_emitted=1
}

dump_log_tail() {
  local log_file="$1"
  local label="$2"

  if [ -f "${log_file}" ]; then
    echo "===== ${label} (tail) ====="
    tail -n 80 "${log_file}"
  fi
}

dump_failure_context() {
  if [ "${rc}" -eq 0 ]; then
    return
  fi

  echo "[ERROR] tb_script failed during stage: ${stage}"
  echo "[INFO] Live setup output is mirrored in ${WORK_LOG}"

  case "${stage}" in
    setup)
      ;;
    compile)
      dump_log_tail "${COMPILE_LOG}" "compile.log"
      ;;
    run)
      dump_log_tail "${RUN_LOG}" "run.log"
      ;;
    *)
      dump_log_tail "${COMPILE_LOG}" "compile.log"
      dump_log_tail "${RUN_LOG}" "run.log"
      ;;
  esac
}

on_exit() {
  local exit_code=$?

  if [ "${result_emitted}" -ne 0 ]; then
    return
  fi

  if [ "${exit_code}" -ne 0 ] && [ "${rc}" -eq 0 ]; then
    rc="${exit_code}"
  fi

  dump_failure_context
  print_result "FAIL"
}

finish() {
  rc="$1"

  if [ "${rc}" -ne 0 ]; then
    dump_failure_context
    print_result "FAIL"
  else
    print_result "PASS"
  fi

  trap - EXIT
  exit "${rc}"
}

trap on_exit EXIT

rm -rf "${TB_DIR}"
