#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "hw/top_earlgrey/sw/autogen/top_earlgrey.h"
#include "spi_device_regs.h"
#include "sw/device/lib/base/bitfield.h"
#include "sw/device/silicon_creator/lib/drivers/spi_device.h"

#define MMIO_WORDS 8192
static uint32_t mmio_space[MMIO_WORDS];

static size_t idx_from_addr(uint32_t addr) {
  return (size_t)((addr - TOP_EARLGREY_SPI_DEVICE_BASE_ADDR) / 4u);
}

uint8_t abs_mmio_read8(uint32_t addr) {
  uint32_t word = mmio_space[idx_from_addr(addr & ~3u)];
  return (word >> ((addr & 3u) * 8u)) & 0xffu;
}

void abs_mmio_write8(uint32_t addr, uint8_t value) {
  size_t idx = idx_from_addr(addr & ~3u);
  uint32_t shift = (addr & 3u) * 8u;
  uint32_t mask = 0xffu << shift;
  mmio_space[idx] = (mmio_space[idx] & ~mask) | ((uint32_t)value << shift);
}

void abs_mmio_write8_shadowed(uint32_t addr, uint8_t value) {
  abs_mmio_write8(addr, value);
  abs_mmio_write8(addr, value);
}

uint32_t abs_mmio_read32(uint32_t addr) {
  return mmio_space[idx_from_addr(addr)];
}

void abs_mmio_write32(uint32_t addr, uint32_t value) {
  mmio_space[idx_from_addr(addr)] = value;
}

void abs_mmio_write32_shadowed(uint32_t addr, uint32_t value) {
  abs_mmio_write32(addr, value);
  abs_mmio_write32(addr, value);
}

#include "sw/device/silicon_creator/lib/drivers/spi_device.c"

int main(void) {
  memset(mmio_space, 0, sizeof(mmio_space));
  mmio_space[idx_from_addr(TOP_EARLGREY_SPI_DEVICE_BASE_ADDR +
                           SPI_DEVICE_CONTROL_REG_OFFSET)] = 0xffffffffu;

  spi_device_init();

  uint32_t wren = mmio_space[idx_from_addr(TOP_EARLGREY_SPI_DEVICE_BASE_ADDR +
                                           SPI_DEVICE_CMD_INFO_WREN_REG_OFFSET)];
  uint32_t wrdi = mmio_space[idx_from_addr(TOP_EARLGREY_SPI_DEVICE_BASE_ADDR +
                                           SPI_DEVICE_CMD_INFO_WRDI_REG_OFFSET)];

  printf("%u 0x%02x %u 0x%02x\n",
         bitfield_bit32_read(wren, SPI_DEVICE_CMD_INFO_WREN_VALID_BIT),
         bitfield_field32_read(wren, SPI_DEVICE_CMD_INFO_WREN_OPCODE_FIELD),
         bitfield_bit32_read(wrdi, SPI_DEVICE_CMD_INFO_WRDI_VALID_BIT),
         bitfield_field32_read(wrdi, SPI_DEVICE_CMD_INFO_WRDI_OPCODE_FIELD));
  return 0;
}
EOF

