tb_script:
#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="spi_passthrough_sck_gate"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/prim_clock_gating.sv" <<'EOF'
module prim_clock_gating #(
  parameter bit NoFpgaGate = 1'b0,
  parameter bit FpgaBufGlobal = 1'b1
) (
  input        clk_i,
  input        en_i,
  input        test_en_i,
  output logic clk_o
);
  assign clk_o = (en_i || test_en_i) ? clk_i : 1'b0;
endmodule
EOF

cat > "$TB_DIR/prim_assert_stub.sv" <<'EOF'
`define ASSERT_I(__name, __prop)
`define ASSERT(__name, __prop)
`define ASSERT_KNOWN(__name, __sig)
`define ASSUME(__name, __prop)
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import spi_device_pkg::*;

  logic clk_i;
  logic clk_out_i;
  logic rst_ni;

  logic [255:0] cfg_cmd_filter_i;
  logic [31:0] cfg_addr_mask_i;
  logic [31:0] cfg_addr_value_i;
  logic [31:0] cfg_payload_mask_i;
  logic [31:0] cfg_payload_data_i;
  logic        cfg_addr_4b_en_i;
  spi_mode_e   spi_mode_i;
  logic        passthrough_block_i;
  cmd_info_t [NumTotalCmdInfo-1:0] cmd_info_i;

  logic        host_sck_i;
  logic        host_csb_i;
  logic [3:0]  host_s_i;
  logic [3:0]  host_s_o;
  logic [3:0]  host_s_en_o;

  passthrough_req_t passthrough_o;
  passthrough_rsp_t passthrough_i;

  logic mailbox_hit_i;
  logic event_cmd_filtered_o;

  spi_passthrough dut (
    .clk_i,
    .rst_ni,
    .clk_out_i,
    .cfg_cmd_filter_i,
    .cfg_addr_mask_i,
    .cfg_addr_value_i,
    .cfg_payload_mask_i,
    .cfg_payload_data_i,
    .cfg_addr_4b_en_i,
    .spi_mode_i,
    .passthrough_block_i,
    .cmd_info_i,
    .host_sck_i,
    .host_csb_i,
    .host_s_i,
    .host_s_o,
    .host_s_en_o,
    .passthrough_o,
    .passthrough_i,
    .mailbox_hit_i,
    .event_cmd_filtered_o
  );

  assign clk_out_i = ~host_sck_i;
  assign clk_i = host_sck_i;

  task automatic fail_now(input string msg);
    $display("TB_FAIL: %s", msg);
    $fatal(1);
  endtask

  task automatic drive_bit(input bit value);
    host_s_i[0] = value;
    #5;
    host_sck_i = 1'b1;
    #1;
    #4;
    host_sck_i = 1'b0;
    #1;
    #4;
  endtask

  task automatic send_byte(input byte value);
    for (int i = 7; i >= 0; i--) begin
      drive_bit(value[i]);
    end
  endtask

  initial begin
    cfg_cmd_filter_i     = '1;
    cfg_addr_mask_i      = '0;
    cfg_addr_value_i     = '0;
    cfg_payload_mask_i   = '0;
    cfg_payload_data_i   = '0;
    cfg_addr_4b_en_i     = 1'b0;
    spi_mode_i           = PassThrough;
    passthrough_block_i  = 1'b0;
    cmd_info_i           = '0;
    host_sck_i           = 1'b0;
    host_csb_i           = 1'b1;
    host_s_i             = '0;
    passthrough_i        = '0;
    mailbox_hit_i        = 1'b0;
    rst_ni               = 1'b0;

    #20;
    rst_ni = 1'b1;
    #10;

    host_csb_i = 1'b0;
    #2;
    if (passthrough_o.csb !== 1'b0) begin
      fail_now("passthrough CSB did not follow the host before filtering");
    end

    send_byte(8'h03);
    #2;

    #10;
    if (passthrough_o.csb !== 1'b1) begin
      fail_now("passthrough CSB was not deasserted after a filtered command");
    end

    repeat (4) begin
      host_s_i[0] = $urandom_range(0, 1);
      #5;
      host_sck_i = 1'b1;
      #1;
      if (passthrough_o.sck !== 1'b0) begin
        fail_now("downstream SCK toggled after the command was filtered");
      end
      #4;
      host_sck_i = 1'b0;
      #5;
    end

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

vcs -full64 -sverilog -timescale=1ns/1ps -licqueue \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  -l "$TB_DIR/compile.log" \
  /home/opentitan/hw/ip/spi_device/rtl/spi_device_reg_pkg.sv \
  /home/opentitan/hw/ip/spi_device/rtl/spi_device_pkg.sv \
  "$TB_DIR/prim_assert_stub.sv" \
  "$TB_DIR/prim_clock_gating.sv" \
  /home/opentitan/hw/ip/spi_device/rtl/spi_passthrough.sv \
  "$TB_DIR/tb.sv"
compile_rc=$?

if [ $compile_rc -ne 0 ]; then
  cat "$TB_DIR/compile.log"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit $compile_rc
fi

"$TB_DIR/simv" -l "$TB_DIR/sim.log"
run_rc=$?

echo "HWE_BENCH_RESULTS_START"
if grep -q "TB_PASS" "$TB_DIR/sim.log" \
  && ! grep -Eq "TB_FAIL|Fatal:" "$TB_DIR/sim.log"; then
  tail -n 20 "$TB_DIR/sim.log"
  echo "TEST: $TEST_NAME ... PASS"
else
  tail -n 80 "$TB_DIR/sim.log"
  echo "TEST: $TEST_NAME ... FAIL"
  if [ $run_rc -eq 0 ]; then
    run_rc=1
  fi
fi
echo "HWE_BENCH_RESULTS_END"

exit $run_rc

