cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import alert_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic rst_shadowed_ni;
  logic latch_any;
  logic [N_CLASSES-1:0] latch_bus;

  tlul_pkg::tl_h2d_t tl_i;
  tlul_pkg::tl_d2h_t tl_o;
  logic [N_CLASSES-1:0] irq_o;
  hw2reg_wrap_t hw2reg_wrap;
  reg2hw_wrap_t reg2hw_wrap;
  alert_crashdump_t crashdump_o;
  logic fatal_integ_alert_o;
  alert_crashdump_t first_snapshot;

  assign latch_bus = {N_CLASSES{latch_any}};

  alert_handler_reg_wrap dut (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .tl_i,
    .tl_o,
    .irq_o,
    .latch_crashdump_i(latch_bus),
    .crashdump_o,
    .hw2reg_wrap,
    .reg2hw_wrap,
    .fatal_integ_alert_o
  );

  always #5 clk_i = ~clk_i;

  task automatic clear_stub_regs();
    tb_ctrl_pkg::reg2hw_stub = '0;
  endtask

  task automatic drive_first_escalation();
    hw2reg_wrap = '0;
    hw2reg_wrap.alert_cause[0] = 1'b1;
    hw2reg_wrap.class_accum_cnt[0] = 16'h0011;
    hw2reg_wrap.class_esc_cnt[0] = 32'h11111111;
    hw2reg_wrap.class_esc_state[0] = Phase0;
  endtask

  task automatic drive_second_escalation();
    hw2reg_wrap = '0;
    hw2reg_wrap.alert_cause[1] = 1'b1;
    hw2reg_wrap.class_accum_cnt[1] = 16'h0022;
    hw2reg_wrap.class_esc_cnt[1] = 32'h22222222;
    hw2reg_wrap.class_esc_state[1] = Phase0;
  endtask

  task automatic pulse_latch();
    latch_any = 1'b1;
    @(posedge clk_i);
    #1;
    latch_any = 1'b0;
  endtask

  task automatic pulse_classd_clear();
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.q = 1'b1;
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.qe = 1'b1;
    @(posedge clk_i);
    #1;
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.q = 1'b0;
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.qe = 1'b0;
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    rst_shadowed_ni = 1'b0;
    tl_i = '0;
    hw2reg_wrap = '0;
    latch_any = 1'b0;
    clear_stub_regs();

    repeat (3) @(posedge clk_i);
    #1;
    rst_ni = 1'b1;
    rst_shadowed_ni = 1'b1;
    repeat (2) @(posedge clk_i);
    #1;

    drive_first_escalation();
    pulse_latch();
    repeat (1) @(posedge clk_i);
    #1;
    first_snapshot = crashdump_o;

    if (first_snapshot.class_esc_cnt[0] !== 32'h11111111 ||
        first_snapshot.class_esc_state[0] !== Phase0) begin
      $fatal(1, "failed to capture initial crashdump snapshot");
    end

    pulse_classd_clear();
    drive_second_escalation();
    pulse_latch();
    repeat (1) @(posedge clk_i);
    #1;

    if (crashdump_o !== first_snapshot) begin
      $fatal(1, "crashdump changed after unrelated clear re-armed latch");
    end

    $display("TB PASS");
    $finish;
  end
endmodule
EOF

timeout 1200s vcs -full64 -sverilog \
  "$TB_DIR/tlul_pkg_stub.sv" \
  hw/top_earlgrey/ip_autogen/alert_handler/rtl/alert_handler_reg_pkg.sv \
  hw/top_earlgrey/ip_autogen/alert_handler/rtl/alert_pkg.sv \
  "$TB_DIR/tb_ctrl_pkg.sv" \
  "$TB_DIR/prim_intr_hw_stub.sv" \
  "$TB_DIR/alert_handler_reg_top_stub.sv" \
  hw/top_earlgrey/ip_autogen/alert_handler/rtl/alert_handler_reg_wrap.sv \
  "$TB_DIR/tb.sv" \
  -o "$SIMV" \
  -l "$COMPILE_LOG"
compile_rc=$?

run_rc=1
pass=0
exit_code=1
if [ $compile_rc -eq 0 ]; then
  timeout 1200s "$SIMV" -l "$RUN_LOG"
  run_rc=$?
  # VCS may still exit with 0 after $fatal, so gate PASS on the explicit success marker.
  if [ $run_rc -eq 0 ] && grep -q "TB PASS" "$RUN_LOG"; then
    pass=1
  fi
fi

echo "HWE_BENCH_RESULTS_START"
if [ $compile_rc -eq 0 ] && [ $pass -eq 1 ]; then
  echo "TEST: alert_handler_crashdump_latch ... PASS"
  exit_code=0
else
  echo "TEST: alert_handler_crashdump_latch ... FAIL"
  if [ $compile_rc -ne 0 ]; then
    exit_code=$compile_rc
  elif [ $run_rc -ne 0 ]; then
    exit_code=$run_rc
  fi
fi
echo "HWE_BENCH_RESULTS_END"

exit $exit_code

