fi

TEST_NAME="spi_device_last_read_addr"
WORK_DIR="/home/opentitan/.tb_${TEST_NAME}"
SEQ_FILE="hw/ip/spi_device/dv/env/seq_lib/${TEST_NAME}_vseq.sv"
VSEQ_LIST="hw/ip/spi_device/dv/env/seq_lib/spi_device_vseq_list.sv"
ENV_CORE="hw/ip/spi_device/dv/env/spi_device_env.core"
