RUN_LOG="${WORK_DIR}/dvsim_stdout.log"
rc=1

finish() {
  echo "HWE_BENCH_RESULTS_START"
  if [ "$rc" -eq 0 ]; then
    echo "TEST: ${TEST_NAME} ... PASS"
  else
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
}

trap finish EXIT

mkdir -p "$WORK_DIR"

cat > "$SEQ_FILE" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class spi_device_last_read_addr_vseq extends spi_device_intercept_vseq;
  `uvm_object_utils(spi_device_last_read_addr_vseq)
  `uvm_object_new

  localparam bit [31:0] TestStartAddr = READ_BUFFER_START_ADDR + 32'h24;
  localparam int unsigned TestPayloadSize = 2;

  constraint device_mode_c {
    device_mode == FlashMode;
  }

  task body();
    spi_device_flash_pass_init();

    // Keep address translation deterministic so LAST_READ_ADDR reflects the host-visible address.
    ral.addr_swap_mask.mask.set('0);
    csr_update(ral.addr_swap_mask);
    ral.addr_swap_data.data.set('0);
    csr_update(ral.addr_swap_data);
    ral.payload_swap_mask.mask.set('0);
    csr_update(ral.payload_swap_mask);
    ral.payload_swap_data.data.set('0);
    csr_update(ral.payload_swap_data);

    // This case intentionally isolates the plain read-buffer path described in the prompt.
    // Some in-tree collateral still assumes stale A + N semantics; this test checks the
    // observable post-transaction behavior directly as LAST_READ_ADDR = A + N - 1.
    ral.cfg.addr_4b_en.set(0);
    ral.cfg.mailbox_en.set(0);
    csr_update(ral.cfg);
    cfg.spi_host_agent_cfg.flash_addr_4b_en = 0;
    cfg.spi_device_agent_cfg.flash_addr_4b_en = 0;

    cfg_cmd_filter(0, READ_NORMAL);
    send_targeted_read(READ_NORMAL, TestPayloadSize, TestStartAddr);
    cfg.clk_rst_vif.wait_clks(10);

    csr_rd_check(.ptr(ral.last_read_addr), .compare_value(TestStartAddr + TestPayloadSize - 1));
  endtask

  task send_targeted_read(bit [7:0] op, uint payload_size, bit [31:0] addr);
    spi_host_flash_seq m_spi_host_seq;
    bit [7:0] byte_addr_q[$];
    int num_addr_bytes;

    `uvm_create_on(m_spi_host_seq, p_sequencer.spi_sequencer_h)
    num_addr_bytes = cfg.spi_host_agent_cfg.get_num_addr_byte(op);
    if (num_addr_bytes == 4) begin
      byte_addr_q.push_back(addr[31:24]);
    end
    if (num_addr_bytes > 0) begin
      byte_addr_q = {byte_addr_q, addr[23:16], addr[15:8], addr[7:0]};
    end

    `DV_CHECK_RANDOMIZE_WITH_FATAL(m_spi_host_seq,
                                   opcode == op;
                                   address_q.size() == byte_addr_q.size();
                                   foreach (byte_addr_q[i]) address_q[i] == byte_addr_q[i];
                                   payload_q.size() == payload_size;
                                   read_size == payload_size;)
    `uvm_send(m_spi_host_seq)
  endtask
endclass : spi_device_last_read_addr_vseq
EOF

