#!/bin/bash
set -euo pipefail

cd /home/opentitan

TB_NAME="spi_device_addr_4b_short_idle"
TB_DIR="/home/opentitan/.tb_${TB_NAME}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/${TB_NAME}_vseq.sv" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class spi_device_addr_4b_short_idle_vseq extends spi_device_pass_base_vseq;
  `uvm_object_utils(spi_device_addr_4b_short_idle_vseq)
  `uvm_object_new

  localparam int SyncWaitClks = 64;
  localparam int LongIdleNs = 1000;
  localparam int ShortIdleNs = 0;

  constraint device_mode_c {
    device_mode == FlashMode;
  }

  virtual task body();
    allow_set_cmd_info_invalid = 0;
    allow_use_invalid_opcode = 0;
    allow_addr_swap = 0;
    allow_payload_swap = 0;
    allow_intercept = 1;
    allow_upload = 0;
    allow_write_enable_disable = 0;
    allow_addr_cfg_cmd = 1;

    spi_freq_faster = 1;
    core_spi_freq_ratio = 4;
    sck_polarity = 0;
    sck_phase = 0;
    host_bit_dir = 0;
    device_bit_dir = 0;

    spi_device_flash_pass_init();

    ral.intercept_en.status.set(1);
    csr_update(.csr(ral.intercept_en));

    cfg_cmd_filter(0, EN4B);
    cfg_cmd_filter(0, EX4B);
    cfg_cmd_filter(0, READ_STATUS_1);

    repeat (4) begin
      set_idle(LongIdleNs);
      drive_cfg_cmd_and_check(EN4B, 1'b1);

      set_idle(ShortIdleNs);
      drive_cfg_cmd_and_check(EX4B, 1'b0);

      set_idle(LongIdleNs);
      drive_cfg_cmd_and_check(EX4B, 1'b0);

      set_idle(ShortIdleNs);
      drive_cfg_cmd_and_check(EN4B, 1'b1);
    end
  endtask

  task automatic set_idle(uint idle_ns);
    cfg.spi_host_agent_cfg.min_idle_ns_after_csb_drop = idle_ns;
    cfg.spi_host_agent_cfg.max_idle_ns_after_csb_drop = idle_ns;
  endtask

  task automatic drive_cfg_cmd_and_check(bit [7:0] cfg_cmd_opcode, bit expected_mode);
    bit [TL_DW-1:0] addr_4b_mode;

    `uvm_info(`gfn,
              $sformatf("Driving opcode 0x%0h with idle %0dns, expecting addr_4b_en=%0d",
                        cfg_cmd_opcode, cfg.spi_host_agent_cfg.min_idle_ns_after_csb_drop,
                        expected_mode),
              UVM_MEDIUM)

    spi_host_xfer_flash_item(cfg_cmd_opcode, 0, '0, 0);
    spi_host_xfer_flash_item(READ_STATUS_1, 1, '0, 0);

    cfg.clk_rst_vif.wait_clks(SyncWaitClks);
    csr_rd(.ptr(ral.cfg.addr_4b_en), .value(addr_4b_mode));

    if (addr_4b_mode[0] !== expected_mode) begin
      `uvm_fatal(`gfn,
                 $sformatf("addr_4b_en mismatch after opcode 0x%0h: expected %0d got 0x%0h",
                           cfg_cmd_opcode, expected_mode, addr_4b_mode))
    end

    cfg.spi_host_agent_cfg.flash_addr_4b_en = expected_mode;
    cfg.spi_device_agent_cfg.flash_addr_4b_en = expected_mode;
  endtask
endclass
EOF

