#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="pwrmgr_ndm_reset_no_resample"
TB_DIR="/home/opentitan/.tb_pwrmgr_ndm_strap"
RUN_LOG="$TB_DIR/fusesoc_run.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import pwrmgr_pkg::*;
  import pwrmgr_reg_pkg::*;
  import lc_ctrl_pkg::*;
  import prim_mubi_pkg::*;

  logic clk_i = 0;
  logic rst_ni = 0;
  logic clk_slow_i = 0;
  logic rst_slow_ni = 0;

  logic req_pwrup_i;
  pwrup_cause_e pwrup_cause_i;
  logic ack_pwrup_o;
  logic req_pwrdn_o;
  logic ack_pwrdn_i;
  logic low_power_entry_i;
  logic main_pd_ni;
  logic [TotalResetWidth-1:0] reset_reqs_i;
  logic fsm_invalid_i;
  logic clr_slow_req_o;
  logic clr_slow_ack_i;
  logic usb_ip_clk_en_i;
  logic usb_ip_clk_status_o;
  logic wkup_o;
  logic fall_through_o;
  logic abort_o;
  logic clr_hint_o;
  logic clr_cfg_lock_o;
  pwr_rst_req_t pwr_rst_o;
  pwr_rst_rsp_t pwr_rst_i;
  pwr_clk_req_t ips_clk_en_o;
  pwr_clk_rsp_t clk_en_status_i;
  logic otp_init_o;
  logic otp_done_i;
  logic otp_idle_i;
  logic lc_init_o;
  logic lc_done_i;
  logic lc_idle_i;
  lc_tx_t lc_dft_en_i;
  lc_tx_t lc_hw_debug_en_i;
  logic flash_idle_i;
  mubi4_t rom_ctrl_done_i;
  mubi4_t rom_ctrl_good_i;
  logic strap_o;
  logic low_power_o;
  lc_tx_t fetch_en_o;
  logic [PowerDomains-1:0] rst_lc_src_model;
  logic [PowerDomains-1:0] rst_sys_src_self_model;
  logic ndm_sys_req;

  int strap_count = 0;

  always #5 clk_i = ~clk_i;
  always #7 clk_slow_i = ~clk_slow_i;

  assign ndm_sys_req = reset_reqs_i[ResetNdmIdx] && (pwr_rst_o.reset_cause == ResetNone);

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      rst_lc_src_model <= 0;
      rst_sys_src_self_model <= 0;
    end else begin
      rst_lc_src_model <= ~pwr_rst_o.rst_lc_req;
      rst_sys_src_self_model <= ~(pwr_rst_o.rst_sys_req | {PowerDomains{ndm_sys_req}});
    end
  end

  always_comb begin
    pwr_rst_i.rst_lc_src_n = rst_lc_src_model;
    pwr_rst_i.rst_sys_src_n = rst_lc_src_model & rst_sys_src_self_model;
    clk_en_status_i.main_status = ips_clk_en_o.main_ip_clk_en;
    clk_en_status_i.io_status = ips_clk_en_o.io_ip_clk_en;
    clk_en_status_i.usb_status = ips_clk_en_o.usb_ip_clk_en;
  end

  always @(posedge clk_i) begin
    if (strap_o) begin
      strap_count <= strap_count + 1;
      $display("INFO: strap pulse %0d at time %0t state=%0h", strap_count + 1, $time, dut.state_q);
    end
  end

  task automatic wait_for_state(fast_pwr_state_e exp_state, int max_cycles, string label);
    int i;
    for (i = 0; i < max_cycles; i++) begin
      @(posedge clk_i);
      if (dut.state_q == exp_state) return;
    end
    $fatal(1, "Timeout waiting for %s, state=%0h strap_count=%0d", label, dut.state_q, strap_count);
  endtask

  pwrmgr_fsm dut (
    .clk_i,
    .rst_ni,
    .clk_slow_i,
    .rst_slow_ni,
    .req_pwrup_i,
    .pwrup_cause_i,
    .ack_pwrup_o,
    .req_pwrdn_o,
    .ack_pwrdn_i,
    .low_power_entry_i,
    .main_pd_ni,
    .reset_reqs_i,
    .fsm_invalid_i,
    .clr_slow_req_o,
    .clr_slow_ack_i,
    .usb_ip_clk_en_i,
    .usb_ip_clk_status_o,
    .wkup_o,
    .fall_through_o,
    .abort_o,
    .clr_hint_o,
    .clr_cfg_lock_o,
    .pwr_rst_o,
    .pwr_rst_i,
    .ips_clk_en_o,
    .clk_en_status_i,
    .otp_init_o,
    .otp_done_i,
    .otp_idle_i,
    .lc_init_o,
    .lc_done_i,
    .lc_idle_i,
    .lc_dft_en_i,
    .lc_hw_debug_en_i,
    .flash_idle_i,
    .rom_ctrl_done_i,
    .rom_ctrl_good_i,
    .strap_o,
    .low_power_o,
    .fetch_en_o
  );

  initial begin
    req_pwrup_i = 0;
    pwrup_cause_i = Por;
    ack_pwrdn_i = 0;
    low_power_entry_i = 0;
    main_pd_ni = 1;
    reset_reqs_i = 0;
    fsm_invalid_i = 0;
    clr_slow_ack_i = 1;
    usb_ip_clk_en_i = 0;
    otp_done_i = 1;
    otp_idle_i = 1;
    lc_done_i = 1;
    lc_idle_i = 1;
    lc_dft_en_i = Off;
    lc_hw_debug_en_i = Off;
    flash_idle_i = 1;
    rom_ctrl_done_i = MuBi4True;
    rom_ctrl_good_i = MuBi4True;

    repeat (5) @(posedge clk_i);
    rst_ni = 1;
    rst_slow_ni = 1;

    req_pwrup_i = 1;
    wait_for_state(FastPwrStateAckPwrUp, 100, "first ack");
    wait (ack_pwrup_o == 1);
    @(posedge clk_i);
    req_pwrup_i = 0;

    wait_for_state(FastPwrStateActive, 100, "first active");
    repeat (2) @(posedge clk_i);
    if (strap_count != 1) begin
      $fatal(1, "Expected one strap pulse after cold boot, got %0d", strap_count);
    end

    reset_reqs_i[ResetNdmIdx] = 1;
    wait_for_state(FastPwrStateResetPrep, 100, "reset prep");
    wait (pwr_rst_i.rst_lc_src_n == 0 && pwr_rst_i.rst_sys_src_n == 0);
    @(posedge clk_i);
    reset_reqs_i[ResetNdmIdx] = 0;

    wait_for_state(FastPwrStateActive, 200, "second active");
    repeat (4) @(posedge clk_i);

    if (strap_count != 1) begin
      $fatal(1, "strap_count=%0d after ndm reset", strap_count);
    end

    $display("TB_PASS strap_count=%0d", strap_count);
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/pwrmgr_ndm_strap_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:pwrmgr_ndm_strap_tb:0.1"
description: "Minimal pwrmgr_fsm strap sampling regression"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:pwrmgr_pkg:0.1
      - lowrisc:ip:lc_ctrl_pkg:0.1
      - lowrisc:prim:assert:0.1
      - lowrisc:prim:lc_sender:0.1
      - lowrisc:prim:sec_anchor:0.1
      - lowrisc:prim:flop
      - lowrisc:prim:flop_2sync
      - lowrisc:prim:sparse_fsm
      - lowrisc:prim:mubi:0.1
    files:
      - ../hw/ip/pwrmgr/rtl/pwrmgr_fsm.sv
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: tb
    filesets:
      - files_dv
EOF

fusesoc \
  --cores-root /home/opentitan \
  --cores-root "$TB_DIR" \
  run \
  --no-export \
  --build-root "$TB_DIR/build" \
  --flag=fileset_ip \
  --target=sim \
  --tool=vcs \
  lowrisc:dv:pwrmgr_ndm_strap_tb:0.1 > "$RUN_LOG" 2>&1
RUN_RC=$?

if [[ $RUN_RC -eq 0 ]] && grep -q "TB_PASS strap_count=1" "$RUN_LOG" && ! grep -q "Fatal:" "$RUN_LOG"; then
  tail -n 120 "$RUN_LOG"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

tail -n 200 "$RUN_LOG"
echo "HWE_BENCH_RESULTS_START"
echo "TEST: $TEST_NAME ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

