  while (!is_cause && polls < 20000) {
    CHECK_DIF_OK(dif_alert_handler_alert_is_cause(
        &alert_handler, peripheral->alert_ids[0], &is_cause));
    if (!is_cause) {
      busy_spin_micros(1);
