tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan

TB_NAME="edn_output_err_code"
TB_DIR="/home/opentitan/.tb_${TB_NAME}"
mkdir -p "$TB_DIR"
rm -rf "$TB_DIR/scratch"

set +e
(
  set -euo pipefail

  cat > hw/ip/edn/dv/env/seq_lib/edn_output_err_code_vseq.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class edn_output_err_code_vseq extends edn_base_vseq;
  `uvm_object_utils(edn_output_err_code_vseq)
  `uvm_object_new

  task body();
    bit [31:0] err_code_val;

    expect_fatal_alerts = 1'b1;

    csr_wr(.ptr(ral.err_code_test), .value(32'd2));
    cfg.clk_rst_vif.wait_clks(50);
    csr_rd(.ptr(ral.err_code), .value(err_code_val));

    `DV_CHECK_EQ(err_code_val[2], 1'b1,
                 $sformatf("Expected ERR_CODE bit 2 to assert after ERR_CODE_TEST writes 2, got 0x%0h",
                           err_code_val))
  endtask
endclass
EOF

  cat > hw/ip/edn/dv/tests/edn_output_err_code_test.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class edn_output_err_code_test extends edn_intr_test;
  `uvm_component_utils(edn_output_err_code_test)
  `uvm_component_new

  function void configure_env();
    super.configure_env();

    cfg.enable = prim_mubi_pkg::MuBi4True;
    cfg.boot_req_mode = prim_mubi_pkg::MuBi4False;
    cfg.auto_req_mode = prim_mubi_pkg::MuBi4False;
    cfg.cmd_fifo_rst = prim_mubi_pkg::MuBi4False;
    cfg.force_disable = 1'b0;
    cfg.num_endpoints = edn_env_pkg::MIN_NUM_ENDPOINTS;

    `uvm_info(`gfn, $sformatf("%s", cfg.convert2string()), UVM_LOW)
  endfunction
endclass
EOF

  python3 - <<'PY'
from pathlib import Path

def ensure_contains(path_str: str, anchor: str, snippet: str) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if snippet in text:
        return
    if anchor not in text:
        raise SystemExit(f"Anchor not found in {path}: {anchor}")
    path.write_text(text.replace(anchor, anchor + "\n" + snippet), encoding="utf-8")

def ensure_before(path_str: str, anchor: str, snippet: str) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if snippet in text:
        return
    if anchor not in text:
        raise SystemExit(f"Anchor not found in {path}: {anchor}")
    path.write_text(text.replace(anchor, snippet + "\n" + anchor), encoding="utf-8")

ensure_contains(
    "hw/ip/edn/dv/env/seq_lib/edn_vseq_list.sv",
    '`include "edn_err_vseq.sv"',
    '`include "edn_output_err_code_vseq.sv"',
)
ensure_contains(
    "hw/ip/edn/dv/env/edn_env.core",
    '      - seq_lib/edn_err_vseq.sv: {is_include_file: true}',
    '      - seq_lib/edn_output_err_code_vseq.sv: {is_include_file: true}',
)
ensure_contains(
    "hw/ip/edn/dv/tests/edn_test_pkg.sv",
    '`include "edn_intr_test.sv"',
    '`include "edn_output_err_code_test.sv"',
)
ensure_contains(
    "hw/ip/edn/dv/tests/edn_test.core",
    '      - edn_intr_test.sv: {is_include_file: true}',
    '      - edn_output_err_code_test.sv: {is_include_file: true}',
)
ensure_before(
    "hw/ip/edn/dv/edn_sim_cfg.hjson",
    "    {\n      name: edn_disable",
    """    {
      name: edn_output_err_code
      uvm_test: edn_output_err_code_test
      uvm_test_seq: edn_output_err_code_vseq
      reseed: 1
    }
""".rstrip(),
)
PY

  timeout --foreground 1800s python3 ./util/dvsim/dvsim.py \
    hw/ip/edn/dv/edn_sim_cfg.hjson \
    -i edn_output_err_code \
    -t vcs \
    --fixed-seed 1 \
    --build-seed 1 \
    --scratch-root "$TB_DIR/scratch" \
    --build-timeout-mins 20 \
    --run-timeout-mins 20 \
    --max-parallel 1 \
    --print-interval 30
)
rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TB_NAME} ... PASS"
else
  echo "TEST: ${TB_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

