    text = text.replace(anchor_line, anchor_line + include_line)
    vseq_list.write_text(text, encoding="utf-8")

sim_cfg = Path("hw/ip/flash_ctrl/dv/flash_ctrl_base_sim_cfg.hjson")
test_name = "flash_ctrl_rma_mid_read"
if test_name not in sim_cfg.read_text(encoding="utf-8"):
    anchor = """    {
      name: flash_ctrl_host_ctrl_arb
      uvm_test_seq: flash_ctrl_host_ctrl_arb_vseq
