    }
"""
    text = sim_cfg.read_text(encoding="utf-8")
    if anchor not in text:
        raise SystemExit("missing host_ctrl_arb anchor in flash_ctrl_base_sim_cfg.hjson")
    sim_cfg.write_text(text.replace(anchor, insert), encoding="utf-8")
