#!/bin/bash
cd /home/opentitan || exit 1
set -u -o pipefail

TEST_NAME="kmac_wait_timer_update"
TB_DIR="/home/opentitan/.tb_kmac_wait_timer"
SIM_CFG="${TB_DIR}/kmac_masked_repro_sim_cfg.hjson"
VSEQ_FILE="hw/ip/kmac/dv/env/seq_lib/kmac_entropy_refresh_vseq.sv"
SCRATCH_DIR="/home/opentitan/scratch/HEAD/kmac_masked-sim-vcs"

rm -rf "${TB_DIR}" "${SCRATCH_DIR}"
mkdir -p "${TB_DIR}"

cat > "${SIM_CFG}" <<'EOF'
{
  import_cfgs: ["{proj_root}/hw/ip/kmac/dv/kmac_masked_sim_cfg.hjson"]
  tests: [
    {
      name: kmac_throughput
      uvm_test_seq: kmac_smoke_vseq
      reseed: 1
    }
  ]
}
EOF

cat > "${VSEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class kmac_entropy_refresh_vseq extends kmac_base_vseq;

  `uvm_object_utils(kmac_entropy_refresh_vseq)
  `uvm_object_new

  localparam bit [15:0] UpdatedWaitTimer = 16'h28de;
  localparam int unsigned EdnDelayCycles = 200;

  virtual task pre_start();
    do_kmac_init = 0;
    super.pre_start();
    cfg.en_scb = 0;
  endtask

  virtual task body();
    bit [TL_DW-1:0] intr_state;

    `uvm_info(`gfn, "Trigger wait_timer update during an outstanding EDN request", UVM_LOW)

    enable_intr = '0;
    enable_intr[KmacErr]  = 1'b1;
    kmac_err_type = kmac_pkg::ErrNone;
    kmac_en = 0;
    xof_en = 0;
    hash_mode = sha3_pkg::Sha3;
    strength = sha3_pkg::L256;
    output_len = 0;
    msg_endian = 0;
    state_endian = 0;
    key_len = Key256;
    reg_en_sideload = 0;
    provide_sideload_key = 0;
    entropy_mode = EntropyModeEdn;
    static_entropy_mode = EntropyModeEdn;
    entropy_fast_process = 0;
    entropy_ready = 1;
    entropy_timer_en = 0;
    entropy_wait_timer = '0;
    prescaler_val = '0;
    hash_threshold = 0;
    hash_cnt_clr = 0;
    entropy_req = 0;
    en_unsupported_modestrength = 0;
    msg_mask = 0;
    key_share = '0;

    fname_len = 0;
    fname_arr = new[0];
    custom_str_len = 0;
    custom_str_arr = new[0];
    msg = new[0];

    cfg.m_edn_pull_agent_cfgs[0].zero_delays = 0;
    cfg.m_edn_pull_agent_cfgs[0].device_delay_min = EdnDelayCycles;
    cfg.m_edn_pull_agent_cfgs[0].device_delay_max = EdnDelayCycles;
    cfg.m_edn_pull_agent_cfgs[0].req_lo_delay_min = 0;
    cfg.m_edn_pull_agent_cfgs[0].req_lo_delay_max = 0;
    cfg.m_edn_pull_agent_cfgs[0].ack_lo_delay_min = 0;
    cfg.m_edn_pull_agent_cfgs[0].ack_lo_delay_max = 0;

    kmac_init();
    csr_wr(.ptr(ral.cmd.entropy_req), .value(1'b1));

    `DV_SPINWAIT(wait (cfg.m_edn_pull_agent_cfgs[0].vif.req == 1'b1 &&
                       cfg.m_edn_pull_agent_cfgs[0].vif.ack == 1'b0);,
                 "Wait for a pending EDN request")
    csr_wr(.ptr(ral.entropy_period.wait_timer), .value(UpdatedWaitTimer));
    csr_rd_check(.ptr(ral.entropy_period.wait_timer), .compare_value(UpdatedWaitTimer));
    cfg.clk_rst_vif.wait_clks(20);

    csr_rd(.ptr(ral.intr_state), .value(intr_state));
    if (intr_state[KmacErr]) begin
      `uvm_fatal(`gfn, "wait_timer update unexpectedly triggered kmac_err")
    end

    `DV_SPINWAIT(wait (cfg.m_edn_pull_agent_cfgs[0].vif.req == 1'b0);,
                 "Wait for the EDN request to complete")
    cfg.clk_rst_vif.wait_clks(20);
    csr_rd_check(.ptr(ral.intr_state.kmac_err), .compare_value(1'b0));
  endtask

endclass
EOF

timeout 1800s ./util/dvsim/dvsim.py "${SIM_CFG}" \
  -i kmac_entropy_refresh \
