tb_script:
#!/bin/bash
cd /home/opentitan || exit 1

set -u
set -o pipefail

TEST_NAME="kmac_capacity_sideload_visibility"
TB_DIR="/home/opentitan/.tb_kmac_capacity"
BUILD_DIR="${TB_DIR}/build"
LOG_DIR="${TB_DIR}/logs"
RUN_LOG="${LOG_DIR}/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}" "${LOG_DIR}"

cat > "${TB_DIR}/kmac_capacity_tb.core" <<'EOF'
CAPI=2:
name: "local:dv:kmac_capacity_tb:0.1"
description: "Minimal KMAC capacity visibility testbench"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:kmac:0.1
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: tb
    filesets:
      - files_dv
    tools:
      vcs:
        vcs_options:
          - "+define+SYNTHESIS"
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import kmac_pkg::*;
  import keymgr_pkg::*;
  import prim_mubi_pkg::*;
  import lc_ctrl_pkg::*;

  localparam int unsigned NumAppIntf = kmac_pkg::NumAppIntf;

  logic clk_i;
  logic rst_ni;
  logic [MaxKeyLen-1:0] reg_key_data_i [1];
  key_len_e reg_key_len_i;
  logic [sha3_pkg::NSRegisterSize*8-1:0] reg_prefix_i;
  logic reg_kmac_en_i;
  sha3_pkg::sha3_mode_e reg_sha3_mode_i;
  sha3_pkg::keccak_strength_e reg_keccak_strength_i;
  logic sw_valid_i;
  logic [sha3_pkg::MsgWidth-1:0] sw_data_i;
  logic [sha3_pkg::MsgWidth-1:0] sw_mask_i;
  logic sw_ready_o;
  keymgr_pkg::hw_key_req_t keymgr_key_i;
  app_req_t [NumAppIntf-1:0] app_i;
  app_rsp_t [NumAppIntf-1:0] app_o;
  logic [MaxKeyLen-1:0] key_data_o [1];
  key_len_e key_len_o;
  logic kmac_valid_o;
  logic [sha3_pkg::MsgWidth-1:0] kmac_data_o;
  logic [sha3_pkg::MsgWidth-1:0] kmac_mask_o;
  logic kmac_ready_i;
  logic kmac_en_o;
  logic [sha3_pkg::NSRegisterSize*8-1:0] sha3_prefix_o;
  sha3_pkg::sha3_mode_e sha3_mode_o;
  sha3_pkg::keccak_strength_e keccak_strength_o;
  logic keccak_state_valid_i;
  logic [sha3_pkg::StateW-1:0] keccak_state_i [1];
  logic reg_state_valid_o;
  logic [sha3_pkg::StateW-1:0] reg_state_o [1];
  logic keymgr_key_en_i;
  kmac_cmd_e sw_cmd_i;
  prim_mubi_pkg::mubi4_t absorbed_i;
  kmac_cmd_e cmd_o;
  prim_mubi_pkg::mubi4_t absorbed_o;
  logic app_active_o;
  prim_mubi_pkg::mubi4_t entropy_ready_i;
  logic error_i;
  logic err_processed_i;
  kmac_pkg::err_t error_o;
  lc_ctrl_pkg::lc_tx_t lc_escalate_en_i;
  logic sparse_fsm_error_o;

  kmac_app dut (
    .*
  );

  always #5 clk_i = ~clk_i;

  task automatic check_non_sideload_visible;
    logic [sha3_pkg::StateW-1:0] exp_state;
    begin
      exp_state = {
        512'h0123_4567_89ab_cdef_fedc_ba98_7654_3210_55aa_aa55_0f0f_f0f0_dead_beef_cafe_babe_1357_9bdf_2468_ace0,
        1088'h1122_3344_5566_7788_99aa_bbcc_ddee_ff00_0123_4567_89ab_cdef_fedc_ba98_7654_3210_1111_2222_3333_4444_5555_6666_7777_8888_9999_aaaa_bbbb_cccc_dddd_eeee_ffff_0001
      };
      keymgr_key_en_i = 1'b0;
      reg_keccak_strength_i = sha3_pkg::L256;
      keccak_state_i[0] = exp_state;
      #1;
      if (!reg_state_valid_o) begin
        $error("reg_state_valid_o should be asserted for SW-visible state");
        $fatal(1);
      end
      if (reg_state_o[0] !== exp_state) begin
        $error("non-sideload path unexpectedly modified keccak state");
        $fatal(1);
      end
    end
  endtask

  task automatic check_sideload_capacity_hidden;
    logic [sha3_pkg::StateW-1:0] exp_state;
    logic [sha3_pkg::StateW-1:0] masked_state;
    begin
      exp_state = {
        512'hf0e1_d2c3_b4a5_9687_7869_5a4b_3c2d_1e0f_0ff0_1ee1_2dd2_3cc3_4bb4_5aa5_6996_7887,
        1088'h89ab_cdef_0123_4567_7654_3210_fedc_ba98_0bad_f00d_dead_beef_feed_face_c001_d00d_aaaa_bbbb_cccc_dddd_eeee_ffff_1234_5678_9abc_def0_2468_ace0_1357_9bdf
      };
      masked_state = exp_state;
      masked_state[sha3_pkg::StateW-1 -: 512] = '0;
      keymgr_key_en_i = 1'b1;
      reg_keccak_strength_i = sha3_pkg::L256;
      keccak_state_i[0] = exp_state;
      #1;
      if (!reg_state_valid_o) begin
        $error("reg_state_valid_o should stay asserted when sideload is enabled");
        $fatal(1);
      end
      if (reg_state_o[0] !== masked_state) begin
        $error("capacity bytes are still visible to software when sideload is enabled");
        $display("EXPECTED_MASKED=%h", masked_state);
        $display("ACTUAL=%h", reg_state_o[0]);
        $fatal(1);
      end
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    reg_key_data_i = '{default: '0};
    reg_key_len_i = Key128;
    reg_prefix_i = '0;
    reg_kmac_en_i = 1'b1;
    reg_sha3_mode_i = sha3_pkg::Sha3;
    reg_keccak_strength_i = sha3_pkg::L256;
    sw_valid_i = 1'b0;
    sw_data_i = '0;
    sw_mask_i = '0;
    keymgr_key_i = '0;
    app_i = '{default: APP_REQ_DEFAULT};
    kmac_ready_i = 1'b0;
    keccak_state_valid_i = 1'b1;
    keccak_state_i = '{default: '0};
    keymgr_key_en_i = 1'b0;
    sw_cmd_i = CmdNone;
    absorbed_i = MuBi4False;
    entropy_ready_i = MuBi4True;
    error_i = 1'b0;
    err_processed_i = 1'b0;
    lc_escalate_en_i = Off;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    @(posedge clk_i);

    force dut.mux_sel_buf_output_logic = kmac_pkg::SelSw;

    check_non_sideload_visible();
    check_sideload_capacity_hidden();

    $display("KMAC_CAPACITY_CHECK_PASS");
    $finish;
  end
endmodule
EOF

set +e
timeout 1700s fusesoc \
  --cores-root /home/opentitan \
  --cores-root "${TB_DIR}" \
  run \
  --no-export \
  --build-root "${BUILD_DIR}" \
  --target=sim \
  --tool=vcs \
  --setup \
  --build \
  --run \
  local:dv:kmac_capacity_tb:0.1 \
  2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
set -e

if [[ ${rc} -eq 0 ]] && grep -q "KMAC_CAPACITY_CHECK_PASS" "${RUN_LOG}"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

