SEQ_FILE="hw/ip/lc_ctrl/dv/env/seq_lib/${TEST_NAME}_vseq.sv"
VSEQ_LIST="hw/ip/lc_ctrl/dv/env/seq_lib/lc_ctrl_vseq_list.sv"
ENV_CORE="hw/ip/lc_ctrl/dv/env/lc_ctrl_env.core"
SIM_CFG="hw/ip/lc_ctrl/dv/lc_ctrl_base_sim_cfg.hjson"
RESULT="FAIL"

emit_result() {
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${RESULT}"
  echo "HWE_BENCH_RESULTS_END"
}

trap emit_result EXIT

rm -rf "${TB_ROOT}"
mkdir -p "${TB_ROOT}"

cat > "${SEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class lc_ctrl_claim_transition_if_regwen_vseq extends lc_ctrl_base_vseq;
  `uvm_object_utils(lc_ctrl_claim_transition_if_regwen_vseq)
  `uvm_object_new

  virtual task pre_start();
    super.pre_start();
    cfg.en_scb = 0;
  endtask

  virtual task drive_otp_i(bit rand_otp_i = 1);
    lc_state = LcStRaw;
    lc_cnt   = LcCnt0;
    cfg.lc_ctrl_vif.init(.lc_state(lc_state), .lc_cnt(lc_cnt), .otp_device_id(cfg.otp_device_id),
                         .otp_manuf_state(cfg.otp_manuf_state),
                         .otp_vendor_test_status(cfg.otp_vendor_test_status));
  endtask

  virtual task wait_for_transition_regwen(bit exp);
    uvm_reg_data_t val = '0;
    repeat (20) begin
      csr_rd(ral.transition_regwen, val);
      if (val == exp) break;
      cfg.clk_rst_vif.wait_clks(5);
    end
    `DV_CHECK_EQ(val, exp)
  endtask

  virtual task body();
    csr_rd_check(.ptr(ral.claim_transition_if_regwen), .compare_value(1));

    csr_wr(.ptr(ral.claim_transition_if), .value(CLAIM_TRANS_VAL));
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.claim_transition_if), .compare_value(CLAIM_TRANS_VAL));
    wait_for_transition_regwen(1);

    csr_wr(.ptr(ral.claim_transition_if), .value(0));
    cfg.clk_rst_vif.wait_clks(5);
    wait_for_transition_regwen(0);

    csr_wr(.ptr(ral.claim_transition_if_regwen), .value(0));
    csr_rd_check(.ptr(ral.claim_transition_if_regwen), .compare_value(0));

    csr_wr(.ptr(ral.claim_transition_if), .value(CLAIM_TRANS_VAL), .check(UVM_NO_CHECK), .predict(0));
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.claim_transition_if), .compare_value(0));
    wait_for_transition_regwen(0);
  endtask
endclass
EOF

