module prim_count #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic             clr_i,
  input  logic             set_i,
  input  logic [Width-1:0] set_cnt_i,
  input  logic             incr_en_i,
  input  logic             decr_en_i,
  input  logic [Width-1:0] step_i,
  output logic [Width-1:0] cnt_o,
  output logic [Width-1:0] cnt_next_o,
  output logic             err_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      cnt_o <= ResetValue;
    end else if (clr_i) begin
      cnt_o <= ResetValue;
    end else if (set_i) begin
      cnt_o <= set_cnt_i;
    end else if (incr_en_i) begin
      cnt_o <= cnt_o + step_i;
    end else if (decr_en_i) begin
      cnt_o <= cnt_o - step_i;
    end
  end

  assign cnt_next_o = cnt_o;
  assign err_o = 1'b0;
endmodule

module prim_fifo_sync #(
  parameter int Width = 1,
  parameter bit Pass = 1'b0,
  parameter int Depth = 4,
  parameter bit OutputZeroIfEmpty = 1'b1
) (
  input  logic                          clk_i,
  input  logic                          rst_ni,
  input  logic                          clr_i,
  input  logic                          wvalid_i,
  output logic                          wready_o,
  input  logic [Width-1:0]              wdata_i,
  output logic                          rvalid_o,
  input  logic                          rready_i,
  output logic [Width-1:0]              rdata_o,
  output logic                          full_o,
  output logic [$clog2(Depth+1)-1:0]    depth_o,
  output logic                          err_o
);
  localparam int PtrWidth = (Depth > 1) ? $clog2(Depth) : 1;

  logic [Width-1:0] mem [0:Depth-1];
  logic [PtrWidth-1:0] rd_ptr_q;
  logic [PtrWidth-1:0] wr_ptr_q;
  logic [Width-1:0] last_rdata_q;
  logic [$clog2(Depth+1)-1:0] count_q;

  assign wready_o = (count_q != Depth);
  assign rvalid_o = (count_q != 0);
  assign full_o = (count_q == Depth);
  assign depth_o = count_q;
  assign err_o = (wvalid_i && full_o) || (rready_i && !rvalid_o);
  assign rdata_o = rvalid_o ? mem[rd_ptr_q] : (OutputZeroIfEmpty ? '0 : last_rdata_q);

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      rd_ptr_q <= '0;
      wr_ptr_q <= '0;
      count_q <= '0;
      last_rdata_q <= '0;
    end else if (clr_i) begin
      rd_ptr_q <= '0;
      wr_ptr_q <= '0;
      count_q <= '0;
      last_rdata_q <= '0;
    end else begin
      if (wvalid_i && !full_o) begin
        mem[wr_ptr_q] <= wdata_i;
        if (Depth > 1) begin
          wr_ptr_q <= (wr_ptr_q == Depth - 1) ? '0 : (wr_ptr_q + 1'b1);
        end
      end

      if (rready_i && rvalid_o) begin
        last_rdata_q <= mem[rd_ptr_q];
        if (Depth > 1) begin
          rd_ptr_q <= (rd_ptr_q == Depth - 1) ? '0 : (rd_ptr_q + 1'b1);
        end
      end

      case ({wvalid_i && !full_o, rready_i && rvalid_o})
        2'b10: count_q <= count_q + 1'b1;
        2'b01: count_q <= count_q - 1'b1;
        default: count_q <= count_q;
      endcase
    end
  end
endmodule
SV

