#!/bin/bash
set +e

cd /home/opentitan || exit 1

TEST_NAME="lc_ctrl volatile_raw_unlock persists"
SCRATCH_ROOT="/home/opentitan/.tb_lc_ctrl_volatile_raw_unlock"
SEQ_FILE="/home/opentitan/hw/ip/lc_ctrl/dv/env/seq_lib/lc_ctrl_volatile_raw_unlock_vseq.sv"
ENV_CORE="/home/opentitan/hw/ip/lc_ctrl/dv/env/lc_ctrl_env.core"
VSEQ_LIST="/home/opentitan/hw/ip/lc_ctrl/dv/env/seq_lib/lc_ctrl_vseq_list.sv"
SIM_CFG="/home/opentitan/hw/ip/lc_ctrl/dv/lc_ctrl_sim_cfg.hjson"

python - <<'PY'
from pathlib import Path

seq_text = """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class lc_ctrl_volatile_raw_unlock_vseq extends lc_ctrl_base_vseq;
  `uvm_object_utils(lc_ctrl_volatile_raw_unlock_vseq)

  `uvm_object_new

  virtual task pre_start();
    super.pre_start();
    cfg.en_scb = 0;
    cfg.err_inj = 0;
  endtask

  virtual task drive_otp_i(bit rand_otp_i = 1);
    lc_state = LcStRaw;
    lc_cnt   = LcCnt0;

    cfg.lc_ctrl_vif.init(.lc_state(lc_state), .lc_cnt(lc_cnt), .otp_device_id(cfg.otp_device_id),
                         .otp_manuf_state(cfg.otp_manuf_state),
                         .otp_vendor_test_status(cfg.otp_vendor_test_status));
  endtask

  task body();
    lc_ctrl_state_pkg::lc_token_t token_val;

    cfg.set_test_phase(LcCtrlDutReady);
    csr_rd_check(.ptr(ral.status.ready), .compare_value(1));

    csr_wr(ral.claim_transition_if, CLAIM_TRANS_VAL);
    csr_rd_check(.ptr(ral.claim_transition_if), .compare_value(CLAIM_TRANS_VAL));
    csr_wr(ral.transition_ctrl, 'h2);
    csr_wr(ral.transition_target, {DecLcStateNumRep{DecLcStTestUnlocked0}});

    token_val = lc_ctrl_state_pkg::RndCnstRawUnlockTokenHashed;
    foreach (ral.transition_token[i]) begin
      csr_wr(ral.transition_token[i], token_val[TL_DW-1:0]);
      token_val = token_val >> TL_DW;
    end

    cfg.set_test_phase(LcCtrlWaitTransition);
    csr_wr(ral.transition_cmd, 'h1);

    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.lc_state), .compare_value({DecLcStateNumRep{DecLcStTestUnlocked0}}));
    csr_rd_check(.ptr(ral.lc_transition_cnt), .compare_value(1));
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.lc_state), .compare_value({DecLcStateNumRep{DecLcStTestUnlocked0}}));
    csr_rd_check(.ptr(ral.lc_transition_cnt), .compare_value(1));
  endtask

endclass : lc_ctrl_volatile_raw_unlock_vseq
"""


def insert_once(path_str: str, anchor: str, addition: str) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if addition in text:
        return
    if anchor not in text:
        raise SystemExit(f"failed to find anchor in {path}")
    path.write_text(text.replace(anchor, anchor + addition, 1), encoding="utf-8")


Path("/home/opentitan/hw/ip/lc_ctrl/dv/env/seq_lib").mkdir(parents=True, exist_ok=True)
Path("/home/opentitan/hw/ip/lc_ctrl/dv/env/seq_lib/lc_ctrl_volatile_raw_unlock_vseq.sv").write_text(
    seq_text,
    encoding="utf-8",
)

insert_once(
    "/home/opentitan/hw/ip/lc_ctrl/dv/env/lc_ctrl_env.core",
    "      - seq_lib/lc_ctrl_base_vseq.sv: {is_include_file: true}\n",
    "      - seq_lib/lc_ctrl_volatile_raw_unlock_vseq.sv: {is_include_file: true}\n",
)
insert_once(
    "/home/opentitan/hw/ip/lc_ctrl/dv/env/seq_lib/lc_ctrl_vseq_list.sv",
    '`include "lc_ctrl_base_vseq.sv"\n',
    '`include "lc_ctrl_volatile_raw_unlock_vseq.sv"\n',
)
insert_once(
    "/home/opentitan/hw/ip/lc_ctrl/dv/lc_ctrl_sim_cfg.hjson",
    "    {\n      name: lc_ctrl_smoke\n      uvm_test_seq: lc_ctrl_smoke_vseq\n    }\n",
    "\n    {\n      name: lc_ctrl_volatile_raw_unlock\n      uvm_test_seq: lc_ctrl_volatile_raw_unlock_vseq\n      reseed: 1\n    }\n",
)
PY
prep_rc=$?

if [ "$prep_rc" -ne 0 ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "$prep_rc"
fi

export PATH="/tools/riscv/bin:$PATH"

timeout 1800 python util/dvsim/dvsim.py hw/ip/lc_ctrl/dv/lc_ctrl_sim_cfg.hjson \
  -i lc_ctrl_volatile_raw_unlock \
  -t vcs \
  --local \
  --purge \
  --max-parallel 1 \
  --build-timeout-mins 20 \
  --run-timeout-mins 10 \
  --fixed-seed 1 \
  --build-seed 1 \
  --scratch-root "$SCRATCH_ROOT"
rc=$?

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="usbdev_suspend_data_toggle_retention"
TB_DIR="/home/opentitan/.tb_usbdev_suspend_data_toggle_retention"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
`timescale 1ns/1ps

module tb;
  import usb_consts_pkg::*;

  localparam logic [6:0] DevAddr = 7'h2a;
  localparam int unsigned Endpoint = 1;

  logic clk_48mhz_i;
  logic rst_ni;
  logic link_reset_i;
  logic link_active_i;
  logic [6:0] dev_addr_i;

  logic [3:0] out_ep_current_o;
  logic out_ep_data_put_o;
  logic [4:0] out_ep_put_addr_o;
  logic [7:0] out_ep_data_o;
  logic out_ep_newpkt_o;
  logic out_ep_acked_o;
  logic out_ep_rollback_o;
  logic [1:0] out_ep_setup_o;
  logic [1:0] out_ep_enabled_i;
  logic [1:0] out_ep_control_i;
  logic [1:0] out_ep_full_i;
  logic [1:0] out_ep_stall_i;
  logic [1:0] out_ep_iso_i;
  logic [1:0] data_toggle_clear_i;

  logic rx_pkt_start_i;
  logic rx_pkt_end_i;
  logic rx_pkt_valid_i;
  logic [3:0] rx_pid_i;
  logic [6:0] rx_addr_i;
  logic [3:0] rx_endp_i;
  logic rx_data_put_i;
  logic [7:0] rx_data_i;

  logic tx_pkt_start_o;
  logic tx_pkt_end_i;
  logic [3:0] tx_pid_o;

  usb_fs_nb_out_pe #(
    .NumOutEps(2),
    .MaxOutPktSizeByte(32)
  ) dut (
    .clk_48mhz_i(clk_48mhz_i),
    .rst_ni(rst_ni),
    .link_reset_i(link_reset_i),
    .link_active_i(link_active_i),
    .dev_addr_i(dev_addr_i),
    .out_ep_current_o(out_ep_current_o),
    .out_ep_data_put_o(out_ep_data_put_o),
    .out_ep_put_addr_o(out_ep_put_addr_o),
    .out_ep_data_o(out_ep_data_o),
    .out_ep_newpkt_o(out_ep_newpkt_o),
    .out_ep_acked_o(out_ep_acked_o),
    .out_ep_rollback_o(out_ep_rollback_o),
    .out_ep_setup_o(out_ep_setup_o),
    .out_ep_enabled_i(out_ep_enabled_i),
    .out_ep_control_i(out_ep_control_i),
    .out_ep_full_i(out_ep_full_i),
    .out_ep_stall_i(out_ep_stall_i),
    .out_ep_iso_i(out_ep_iso_i),
    .data_toggle_clear_i(data_toggle_clear_i),
    .rx_pkt_start_i(rx_pkt_start_i),
    .rx_pkt_end_i(rx_pkt_end_i),
    .rx_pkt_valid_i(rx_pkt_valid_i),
    .rx_pid_i(rx_pid_i),
    .rx_addr_i(rx_addr_i),
    .rx_endp_i(rx_endp_i),
    .rx_data_put_i(rx_data_put_i),
    .rx_data_i(rx_data_i),
    .tx_pkt_start_o(tx_pkt_start_o),
    .tx_pkt_end_i(tx_pkt_end_i),
    .tx_pid_o(tx_pid_o)
  );

  initial clk_48mhz_i = 1'b0;
  always #10 clk_48mhz_i = ~clk_48mhz_i;

  task automatic clear_rx_inputs();
    rx_pkt_start_i = 1'b0;
    rx_pkt_end_i = 1'b0;
    rx_pkt_valid_i = 1'b0;
    rx_pid_i = '0;
    rx_addr_i = '0;
    rx_endp_i = '0;
    rx_data_put_i = 1'b0;
    rx_data_i = '0;
  endtask

  task automatic tick();
    @(posedge clk_48mhz_i);
    #1;
  endtask

  task automatic drive_idle_cycle();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    tick();
  endtask

  task automatic send_out_token();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_pkt_end_i = 1'b1;
    rx_pkt_valid_i = 1'b1;
    rx_pid_i = UsbPidOut;
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    tick();
    if (!out_ep_newpkt_o || out_ep_current_o != Endpoint[3:0]) begin
      $fatal(1, "OUT token was not latched for endpoint %0d", Endpoint);
    end
  endtask

  task automatic start_data_phase();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_pkt_start_i = 1'b1;
    tick();
  endtask

  task automatic push_data_byte(input logic [7:0] value);
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    rx_data_put_i = 1'b1;
    rx_data_i = value;
    tick();
    if (!out_ep_data_put_o || out_ep_data_o != value) begin
      $fatal(1, "Payload byte was not accepted");
    end
  endtask

  task automatic finish_data_packet(
    input logic [3:0] data_pid,
    output logic rollback_seen,
    output logic ack_commit_seen
  );
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_pkt_end_i = 1'b1;
    rx_pkt_valid_i = 1'b1;
    rx_pid_i = data_pid;
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    #1;
    rollback_seen = out_ep_rollback_o && tx_pkt_start_o && (tx_pid_o == UsbPidAck);
    @(posedge clk_48mhz_i);
    #1;
    ack_commit_seen = out_ep_acked_o && tx_pkt_start_o && (tx_pid_o == UsbPidAck);
  endtask

  task automatic fail_test(input string message);
    $display("TB_FAIL: %0s", message);
    $finish;
  endtask

  task automatic send_out_transfer(
    input logic [3:0] data_pid,
    input bit expect_commit
  );
    logic rollback_seen;
    logic ack_commit_seen;

    send_out_token();
    drive_idle_cycle();
    start_data_phase();
    push_data_byte(8'ha5);
    finish_data_packet(data_pid, rollback_seen, ack_commit_seen);
    drive_idle_cycle();

    if (expect_commit) begin
      if (rollback_seen || !ack_commit_seen) begin
        fail_test($sformatf("Expected committed %0s packet, saw rollback=%0b commit=%0b",
                            (data_pid == UsbPidData0) ? "DATA0" : "DATA1",
                            rollback_seen, ack_commit_seen));
      end
    end else begin
      if (!rollback_seen || ack_commit_seen) begin
        fail_test($sformatf("Expected retransmit handling for %0s packet, saw rollback=%0b commit=%0b",
                            (data_pid == UsbPidData0) ? "DATA0" : "DATA1",
                            rollback_seen, ack_commit_seen));
      end
    end
  endtask

  initial begin
    rst_ni = 1'b0;
    link_reset_i = 1'b0;
    link_active_i = 1'b1;
    dev_addr_i = DevAddr;
    out_ep_enabled_i = 2'b10;
    out_ep_control_i = 2'b00;
    out_ep_full_i = 2'b00;
    out_ep_stall_i = 2'b00;
    out_ep_iso_i = 2'b00;
    data_toggle_clear_i = 2'b00;
    tx_pkt_end_i = 1'b0;
    clear_rx_inputs();

    repeat (3) tick();
    rst_ni = 1'b1;
    repeat (2) tick();

    // First DATA0 packet commits and moves the endpoint toggle to DATA1.
    send_out_transfer(UsbPidData0, 1'b1);

    // A suspend window must not clear the OUT data toggle.
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    link_active_i = 1'b0;
    tick();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    link_active_i = 1'b1;
    tick();

    // After resume, the next new packet for the endpoint may legitimately be DATA1.
    // The buggy base revision treats it as a retransmission and rolls it back.
    send_out_transfer(UsbPidData1, 1'b1);

    $display("TB_PASS: USB OUT data toggle was retained across suspend");
    $finish(0);
  end
