tb_script:
#!/bin/bash
set +e

cd /home/opentitan || exit 1

TB_ROOT=/home/opentitan/.tb_usbdev_pre
mkdir -p "$TB_ROOT"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: usbdev_pre_pid ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

cat > "$TB_ROOT/tb.sv" <<'EOF'
module tb;
  logic clk_i;
  logic rst_ni;
  logic link_reset_i;
  logic cfg_eop_single_bit_i;
  logic cfg_use_diff_rcvr_i;
  logic cfg_pinflip_i;
  logic diff_rx_ok_i;
  logic usb_d_i;
  logic usb_dp_i;
  logic usb_dn_i;
  logic tx_en_i;
  logic bit_strobe_o;
  logic pkt_start_o;
  logic pkt_end_o;
  logic [3:0] pid_o;
  logic [6:0] addr_o;
  logic [3:0] endp_o;
  logic [10:0] frame_num_o;
  logic rx_data_put_o;
  logic [7:0] rx_data_o;
  logic valid_packet_o;
  logic rx_idle_det_o;
  logic rx_j_det_o;
  logic crc_error_o;
  logic pid_error_o;
  logic bitstuff_error_o;

  localparam int ClocksPerBit = 4;
  localparam int TrailBits = 10;
  localparam bit LineJ = 1'b1;
  localparam bit LineK = 1'b0;

  usb_fs_rx dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .link_reset_i(link_reset_i),
    .cfg_eop_single_bit_i(cfg_eop_single_bit_i),
    .cfg_use_diff_rcvr_i(cfg_use_diff_rcvr_i),
    .cfg_pinflip_i(cfg_pinflip_i),
    .diff_rx_ok_i(diff_rx_ok_i),
    .usb_d_i(usb_d_i),
    .usb_dp_i(usb_dp_i),
    .usb_dn_i(usb_dn_i),
    .tx_en_i(tx_en_i),
    .bit_strobe_o(bit_strobe_o),
    .pkt_start_o(pkt_start_o),
    .pkt_end_o(pkt_end_o),
    .pid_o(pid_o),
    .addr_o(addr_o),
    .endp_o(endp_o),
    .frame_num_o(frame_num_o),
    .rx_data_put_o(rx_data_put_o),
    .rx_data_o(rx_data_o),
    .valid_packet_o(valid_packet_o),
    .rx_idle_det_o(rx_idle_det_o),
    .rx_j_det_o(rx_j_det_o),
    .crc_error_o(crc_error_o),
    .pid_error_o(pid_error_o),
    .bitstuff_error_o(bitstuff_error_o)
  );

  always #10 clk_i = ~clk_i;

  task automatic drive_line(input bit is_j);
    begin
      usb_d_i  = is_j;
      usb_dp_i = is_j;
      usb_dn_i = ~is_j;
      repeat (ClocksPerBit) @(posedge clk_i);
    end
  endtask

  task automatic drive_sync();
    begin
      drive_line(LineK);
      drive_line(LineJ);
      drive_line(LineK);
      drive_line(LineJ);
      drive_line(LineK);
      drive_line(LineK);
    end
  endtask

  task automatic drive_pre_pid();
    bit current_line;
    bit [7:0] pid_bits;
    int idx;
    begin
      current_line = LineK;
      pid_bits = 8'b00111100;
      for (idx = 0; idx < 8; idx++) begin
        if (pid_bits[idx] == 1'b0) begin
          current_line = ~current_line;
        end
        drive_line(current_line);
      end
    end
  endtask

  int pkt_end_seen;
  int bitstuff_seen;

  always @(posedge clk_i) begin
    if (pkt_end_o) begin
      pkt_end_seen <= pkt_end_seen + 1;
    end
    if (bitstuff_error_o) begin
      bitstuff_seen <= bitstuff_seen + 1;
    end
  end

  initial begin
    clk_i = 0;
    rst_ni = 0;
    link_reset_i = 0;
    cfg_eop_single_bit_i = 0;
    cfg_use_diff_rcvr_i = 1;
    cfg_pinflip_i = 0;
    diff_rx_ok_i = 1;
    tx_en_i = 0;
    usb_d_i = LineJ;
    usb_dp_i = 1;
    usb_dn_i = 0;
    pkt_end_seen = 0;
    bitstuff_seen = 0;

    repeat (8) @(posedge clk_i);
    rst_ni = 1;
    repeat (4) @(posedge clk_i);

    repeat (8) drive_line(LineJ);
    drive_sync();
    drive_pre_pid();
    repeat (TrailBits) drive_line(LineK);
    repeat (20) @(posedge clk_i);

    if (bitstuff_seen != 0) begin
      $display("TB_STATUS: FAIL unexpected bitstuff error after PRE PID");
      $finish;
    end
    if (pkt_end_seen == 0) begin
      $display("TB_STATUS: FAIL receiver did not retire PRE packet");
      $finish;
    end

    $display("TB_STATUS: PASS pkt_end_seen=%0d bitstuff_seen=%0d", pkt_end_seen, bitstuff_seen);
    $finish;
  end
endmodule
EOF

COMPILE_LOG="$TB_ROOT/compile.log"
RUN_LOG="$TB_ROOT/run.log"

rm -rf "$TB_ROOT/simv" "$TB_ROOT/simv.daidir" "$COMPILE_LOG" "$RUN_LOG"

vcs -full64 -sverilog -timescale=1ns/1ps -licqueue \
  -o "$TB_ROOT/simv" \
  hw/ip/usbdev/rtl/usb_consts_pkg.sv \
  hw/ip/usbdev/rtl/usb_fs_rx.sv \
  "$TB_ROOT/tb.sv" \
  -l "$COMPILE_LOG"
compile_rc=$?

if [ $compile_rc -ne 0 ]; then
  cat "$COMPILE_LOG"
  emit_result "FAIL"
  exit $compile_rc
fi

"$TB_ROOT/simv" -l "$RUN_LOG"
run_rc=$?
cat "$RUN_LOG"

if [ $run_rc -eq 0 ] && grep -q '^TB_STATUS: PASS' "$RUN_LOG"; then
  emit_result "PASS"
  exit 0
else
  emit_result "FAIL"
  exit 1
fi

