    default_tool: vcs
    toplevel: tb
    filesets:
      - files_tb
    tools:
      vcs:
        vcs_options:
          - -timescale=1ns/1ps
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  timeunit 1ns;
  timeprecision 1ps;

  import keymgr_pkg::*;
  import keymgr_dpe_pkg::*;
  import keymgr_dpe_reg_pkg::*;

  localparam int LocalEntropyRounds = KeyWidth / RandWidth;

  logic clk_i;
  logic rst_ni;
  logic en_i;
  logic regfile_intg_err_i;
  logic shadowed_update_err_i;
  logic shadowed_storage_err_i;
  logic reseed_cnt_err_i;
  logic sideload_sel_err_i;
  logic sideload_fsm_err_i;
  logic op_start_i;
  keymgr_dpe_ops_e op_i;
  logic [DpeNumSlotsWidth-1:0] slot_src_sel_i;
  logic [DpeNumSlotsWidth-1:0] slot_dst_sel_i;
  keymgr_dpe_policy_t slot_policy_i;
  logic [KeyVersionWidth-1:0] max_key_version_i;
  logic [KeyVersionWidth-1:0] key_version_i;
  logic key_version_vld_o;
  logic op_done_o;
  keymgr_op_status_e status_o;
  logic [ErrLastPos-1:0] error_o;
  logic [FaultLastPos-1:0] fault_o;
  logic data_hw_en_o;
  logic data_sw_en_o;
  logic data_valid_o;
  logic wipe_key_o;
  keymgr_dpe_exposed_working_state_e working_state_o;
  logic unlock_after_advance_o;
  logic init_o;
  hw_key_req_t root_key_i;
  prim_mubi_pkg::mubi4_t hw_sel_o;
  logic adv_en_o;
  logic gen_en_o;
  hw_key_req_t key_o;
  keymgr_dpe_slot_t active_key_slot_o;
  logic kmac_done_i;
  logic kmac_input_invalid_i;
  logic kmac_fsm_err_i;
  logic kmac_op_err_i;
  logic kmac_done_err_i;
  logic kmac_cmd_err_i;
  logic [Shares-1:0][KeyWidth-1:0] kmac_data_i;
  logic [Shares-1:0][RandWidth-1:0] entropy_i;
  logic prng_reseed_ack_i;
  logic prng_reseed_req_o;
  logic prng_en_o;

  logic [Shares-1:0][KeyWidth-1:0] expected_random_key;

  keymgr_dpe_ctrl dut (
    .clk_i,
    .rst_ni,
    .en_i,
    .regfile_intg_err_i,
    .shadowed_update_err_i,
    .shadowed_storage_err_i,
    .reseed_cnt_err_i,
    .sideload_sel_err_i,
    .sideload_fsm_err_i,
    .op_start_i,
    .op_i,
    .slot_src_sel_i,
    .slot_dst_sel_i,
    .slot_policy_i,
    .max_key_version_i,
    .key_version_i,
    .key_version_vld_o,
    .op_done_o,
    .status_o,
    .error_o,
    .fault_o,
    .data_hw_en_o,
    .data_sw_en_o,
    .data_valid_o,
    .wipe_key_o,
    .working_state_o,
    .unlock_after_advance_o,
    .init_o,
    .root_key_i,
    .hw_sel_o,
    .adv_en_o,
    .gen_en_o,
    .key_o,
    .active_key_slot_o,
    .kmac_done_i,
    .kmac_input_invalid_i,
    .kmac_fsm_err_i,
    .kmac_op_err_i,
    .kmac_done_err_i,
    .kmac_cmd_err_i,
    .kmac_data_i,
    .entropy_i,
    .prng_reseed_ack_i,
    .prng_reseed_req_o,
    .prng_en_o
  );

  always #5 clk_i = ~clk_i;

  task automatic fail_test(input string reason);
    $display("TB_FAIL: %s", reason);
    $fatal(1, "keymgr_dpe erase sideload check failed");
  endtask

  task automatic wait_for_available();
    int cycles;
    for (cycles = 0; cycles < 48; cycles++) begin
      @(posedge clk_i);
      if (working_state_o == StWorkDpeAvailable && active_key_slot_o.valid === 1'b1) begin
        return;
      end
    end
    fail_test("timed out waiting for keymgr_dpe_ctrl to reach available state");
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    en_i = 1'b1;
    regfile_intg_err_i = 1'b0;
    shadowed_update_err_i = 1'b0;
    shadowed_storage_err_i = 1'b0;
    reseed_cnt_err_i = 1'b0;
    sideload_sel_err_i = 1'b0;
    sideload_fsm_err_i = 1'b0;
    op_start_i = 1'b0;
    op_i = OpDpeAdvance;
    slot_src_sel_i = '0;
    slot_dst_sel_i = '0;
    slot_policy_i = '0;
    max_key_version_i = '1;
    key_version_i = '0;
    root_key_i = '0;
    root_key_i.valid = 1'b1;
    root_key_i.key[0] = 256'h00112233445566778899aabbccddeeff0123456789abcdeffedcba9876543210;
    root_key_i.key[1] = 256'h89abcdef01234567fedcba987654321000112233445566778899aabbccddeeff;
    kmac_done_i = 1'b0;
    kmac_input_invalid_i = 1'b0;
    kmac_fsm_err_i = 1'b0;
    kmac_op_err_i = 1'b0;
    kmac_done_err_i = 1'b0;
    kmac_cmd_err_i = 1'b0;
    kmac_data_i = '0;
    entropy_i[0] = 32'h13579bdf;
    entropy_i[1] = 32'h2468ace0;
    prng_reseed_ack_i = 1'b0;

    expected_random_key[0] = {LocalEntropyRounds{entropy_i[0]}};
    expected_random_key[1] = {LocalEntropyRounds{entropy_i[1]}};

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    // Drive the public initialization sequence so slot 0 contains a valid root key.
    @(negedge clk_i);
    op_i = OpDpeAdvance;
    slot_src_sel_i = '0;
    slot_dst_sel_i = '0;
    op_start_i = 1'b1;
    prng_reseed_ack_i = 1'b1;

    @(posedge clk_i);
    op_start_i = 1'b0;

    wait_for_available();
    prng_reseed_ack_i = 1'b0;

    if (active_key_slot_o.valid !== 1'b1) begin
      fail_test("slot 0 never became valid after initialization");
    end

    // A legal erase must not expose the internal slot key on the sideload interface.
    @(negedge clk_i);
    op_i = OpDpeErase;
    slot_src_sel_i = '0;
    slot_dst_sel_i = '0;
    op_start_i = 1'b1;

    #1;

    if (key_o.valid !== 1'b0) begin
      fail_test($sformatf("erase leaked key valid bit: %0b", key_o.valid));
    end

    if (key_o.key !== expected_random_key) begin
      fail_test($sformatf("erase leaked non-random key share0=%h share1=%h",
                          key_o.key[0], key_o.key[1]));
    end

    @(posedge clk_i);
    op_start_i = 1'b0;

    $display("TB_PASS: erase keeps sideload ctrl on randomized data");
    $finish;
  end
endmodule
EOF

set +e
fusesoc --cores-root /home/opentitan --cores-root "${TB_DIR}" \
  run --build-root "${BUILD_DIR}" --target=sim --tool=vcs \
  local:dv:keymgr_dpe_erase_sideload:0.1 |& tee "${LOG}"
rc=${PIPESTATUS[0]}
