from pathlib import Path

root = Path("/home/opentitan")


def replace(path_str: str, old: str, new: str) -> None:
    path = root / path_str
    text = path.read_text(encoding="utf-8")
    if old in text:
        text = text.replace(old, new)
        path.write_text(text, encoding="utf-8")


