    "lc_keymgr_dpe_en_i",
    "lc_keymgr_en_i",
)

keymgr_if = root / "hw/ip/keymgr_dpe/dv/env/keymgr_dpe_if.sv"
text = keymgr_if.read_text(encoding="utf-8")
debug_decl = """  wire debug_invalid_adv_data = tb.dut.invalid_data[keymgr_pkg::OpAdvance];

"""
anchor = """  // connect EDN for assertion check
"""
if "debug_invalid_adv_data" not in text:
    text = text.replace(anchor, debug_decl + anchor)
    keymgr_if.write_text(text, encoding="utf-8")

vseq_path = root / "hw/ip/keymgr_dpe/dv/env/seq_lib/keymgr_dpe_invalid_advance_vseq.sv"
vseq_path.write_text(
    """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_dpe_invalid_advance_vseq extends keymgr_dpe_base_vseq;
  `uvm_object_utils(keymgr_dpe_invalid_advance_vseq)
  `uvm_object_new

  constraint invalid_advance_setup_c {
    do_op_before_init == 0;
    is_key_version_err == 0;
  }

  virtual task pre_start();
    super.pre_start();
    cfg.en_scb = 0;
  endtask

  virtual function bit get_check_en();
    return 0;
  endfunction

  virtual task clear_op_side_effects();
    bit [TL_DW-1:0] rd_val;

    read_current_state();
    csr_rd(.ptr(ral.err_code), .value(rd_val));
    if (rd_val != 0) begin
      csr_wr(.ptr(ral.err_code), .value(rd_val));
    end
    csr_rd(.ptr(ral.intr_state), .value(rd_val));
    if (rd_val != 0) begin
      csr_wr(.ptr(ral.intr_state), .value(rd_val));
    end
  endtask

  virtual task wait_op_done_expect_status(keymgr_pkg::keymgr_op_status_e exp_status);
    bit [TL_DW-1:0] rd_val;

    csr_spinwait(.ptr(ral.op_status.status), .exp_data(keymgr_pkg::OpWip),
                 .compare_op(CompareOpNe), .spinwait_delay_ns($urandom_range(0, 100)));
    csr_rd(.ptr(ral.op_status), .value(rd_val));
    `DV_CHECK_EQ(rd_val[2:0], exp_status)
    clear_op_side_effects();
  endtask

  virtual task program_control(keymgr_dpe_pkg::keymgr_dpe_ops_e op, int src_slot, int dst_slot);
    sema_update_control_csr.get();
    ral.control_shadowed.operation.set(op);
    ral.control_shadowed.slot_src_sel.set(src_slot);
    ral.control_shadowed.slot_dst_sel.set(dst_slot);
    csr_update(.csr(ral.control_shadowed));
    sema_update_control_csr.put();
  endtask

  virtual task issue_erase(int slot);
    program_control(.op(keymgr_dpe_pkg::OpDpeErase), .src_slot(slot), .dst_slot(slot));
    csr_wr(.ptr(ral.start), .value(1));
    wait_op_done_expect_status(keymgr_pkg::OpDoneSuccess);
  endtask

  virtual task wait_for_invalid_advance_request_and_check();
    int wait_cycles;

    forever begin
      @(posedge cfg.keymgr_dpe_vif.clk);
      if (cfg.keymgr_dpe_vif.kmac_data_req.valid) begin
        `DV_CHECK_EQ(cfg.keymgr_dpe_vif.debug_invalid_adv_data, 1'b1)
        return;
      end
      wait_cycles++;
      if (wait_cycles > 10000) begin
        `uvm_fatal(`gfn, "Timed out waiting for invalid advance KMAC request")
      end
    end
  endtask

  virtual task issue_invalid_advance(int slot);
    program_control(.op(keymgr_dpe_pkg::OpDpeAdvance), .src_slot(slot), .dst_slot(slot));
    csr_wr(.ptr(ral.start), .value(1));
    wait_op_done_expect_status(keymgr_pkg::OpDoneFail);
  endtask

  task body();
    cfg.en_scb = 0;

    program_control(.op(keymgr_dpe_pkg::OpDpeAdvance), .src_slot(0), .dst_slot(0));
    csr_wr(.ptr(ral.start), .value(1));
    wait_op_done_expect_status(keymgr_pkg::OpDoneSuccess);

    issue_erase(.slot(0));

    fork
      begin
        wait_for_invalid_advance_request_and_check();
      end
      begin
        issue_invalid_advance(.slot(0));
      end
    join
  endtask
endclass
""",
    encoding="utf-8",
)

