#!/bin/bash
cd /home/opentitan || exit 1
set +e
set -o pipefail

export PATH="/tools/riscv/bin:/tools/verible/bin:$PATH"

TEST_NAME="rv_dm_gated_blank_resp"
TB_ROOT="/home/opentitan/.tb_${TEST_NAME}"
CORE_ROOT="${TB_ROOT}/core"
BUILD_ROOT="${TB_ROOT}/build"
LOG_DIR="${TB_ROOT}/logs"
LOG_FILE="${LOG_DIR}/fusesoc.log"

rm -rf "${TB_ROOT}"
mkdir -p "${CORE_ROOT}" "${BUILD_ROOT}" "${LOG_DIR}"

cat > "${CORE_ROOT}/tb.sv" <<'EOF'
module tb;
  import lc_ctrl_pkg::*;
  import prim_alert_pkg::*;
  import prim_mubi_pkg::*;
  import rv_dm_reg_pkg::*;
  import tlul_pkg::*;

  logic clk_i;
  logic rst_ni;

  lc_tx_t lc_hw_debug_en_i;
  lc_tx_t pinmux_hw_debug_en_i;
  prim_mubi_pkg::mubi4_t scanmode_i;
  logic ndmreset_req_o;
  logic dmactive_o;
  logic [NrHarts-1:0] debug_req_o;
  logic [NrHarts-1:0] unavailable_i;

  tl_h2d_t regs_tl_d_i;
  tl_d2h_t regs_tl_d_o;
  tl_h2d_t mem_tl_d_i;
  tl_d2h_t mem_tl_d_o;
  tl_h2d_t sba_tl_h_o;
  tl_d2h_t sba_tl_h_i;
  alert_rx_t [NumAlerts-1:0] alert_rx_i;
  alert_tx_t [NumAlerts-1:0] alert_tx_o;
  tl_h2d_t dmi_tl_h2d_i;
  tl_d2h_t dmi_tl_d2h_o;

  rv_dm dut (
    .clk_i,
    .rst_ni,
    .lc_hw_debug_en_i,
    .pinmux_hw_debug_en_i,
    .scanmode_i,
    .ndmreset_req_o,
    .dmactive_o,
    .debug_req_o,
    .unavailable_i,
    .regs_tl_d_i,
    .regs_tl_d_o,
    .mem_tl_d_i,
    .mem_tl_d_o,
    .sba_tl_h_o,
    .sba_tl_h_i,
    .alert_rx_i,
    .alert_tx_o,
    .dmi_tl_h2d_i,
    .dmi_tl_d2h_o
  );

  always #5 clk_i = ~clk_i;

  task automatic init_inputs();
    regs_tl_d_i = TL_H2D_DEFAULT;
    mem_tl_d_i = TL_H2D_DEFAULT;
    sba_tl_h_i = TL_D2H_DEFAULT;
    dmi_tl_h2d_i = TL_H2D_DEFAULT;
    dmi_tl_h2d_i.d_ready = 1'b1;
    unavailable_i = '0;
    alert_rx_i = '0;
    lc_hw_debug_en_i = On;
    pinmux_hw_debug_en_i = Off;
    scanmode_i = MuBi4False;
  endtask

  task automatic send_dmi_get();
    dmi_tl_h2d_i = TL_H2D_DEFAULT;
    dmi_tl_h2d_i.d_ready = 1'b1;
    dmi_tl_h2d_i.a_valid = 1'b1;
    dmi_tl_h2d_i.a_opcode = Get;
    dmi_tl_h2d_i.a_size = 2;
    dmi_tl_h2d_i.a_mask = '1;
    dmi_tl_h2d_i.a_address = '0;
    dmi_tl_h2d_i.a_user = TL_A_USER_DEFAULT;
    wait (dmi_tl_d2h_o.a_ready === 1'b1);
    @(posedge clk_i);
    dmi_tl_h2d_i.a_valid = 1'b0;
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    init_inputs();

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (5) @(posedge clk_i);

    send_dmi_get();
    wait (dmi_tl_d2h_o.d_valid === 1'b1);

    $display("TB: d_error=%0b d_data=0x%08h", dmi_tl_d2h_o.d_error, dmi_tl_d2h_o.d_data);

    if (dmi_tl_d2h_o.d_error !== 1'b0) begin
      $fatal(1, "Expected blank non-error response when DMI is gated");
    end
    if (dmi_tl_d2h_o.d_data !== '0) begin
      $fatal(1, "Expected zero data when DMI is gated");
    end

    $display("TB: blank gated response observed");
    repeat (2) @(posedge clk_i);
    $finish;
  end
endmodule
EOF

cat > "${CORE_ROOT}/${TEST_NAME}.core" <<'EOF'
