      - files_dv
EOF

fusesoc --cores-root /home/opentitan --cores-root "${CORE_ROOT}" run --no-export \
  --build-root "${BUILD_ROOT}" \
  --target sim \
  --tool vcs \
  lowrisc:dv:rv_dm_gated_blank_resp:0.1 \
  2>&1 | tee "${LOG_FILE}"
rc=${PIPESTATUS[0]}

RUN_LOG="$(find "${BUILD_ROOT}" -name vcs.log | head -n1)"
if [ -n "${RUN_LOG}" ]; then
  if grep -q "TB: blank gated response observed" "${RUN_LOG}" && ! grep -q "Fatal:" "${RUN_LOG}"; then
    rc=0
  else
    rc=1
  fi
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

