RUN_LOG="${TB_DIR}/dvsim.log"

mkdir -p "${TB_DIR}"
rm -rf "${SCRATCH_ROOT}"

cat > "${VSEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_dpe_disable_vseq extends keymgr_dpe_base_vseq;
  `uvm_object_utils(keymgr_dpe_disable_vseq)
  `uvm_object_new

  constraint do_op_before_init_c {
    do_op_before_init == 0;
  }

  constraint initial_slot_vals_c {
    soft src_slot == 0;
    soft dst_slot == 0;
  }

  virtual task keymgr_dpe_disable(bit wait_done = 1);
    sema_update_control_csr.get();
    `uvm_info(`gfn, "Disable key manager DPE", UVM_MEDIUM)

    ral.control_shadowed.operation.set(keymgr_dpe_pkg::OpDpeDisable);
    ral.control_shadowed.slot_src_sel.set(src_slot);
    ral.control_shadowed.slot_dst_sel.set(dst_slot);
    csr_update(.csr(ral.control_shadowed));
    csr_wr(.ptr(ral.start), .value(1));

    sema_update_control_csr.put();

    if (wait_done) begin
      wait_op_done();
      if (get_check_en()) begin
        `DV_CHECK_EQ(current_state, keymgr_dpe_pkg::StWorkDpeDisabled)
      end
    end
  endtask

  task body();
    `uvm_info(`gfn, "Key Manager DPE Disable Start", UVM_HIGH)

    policy.allow_child = 1;
    policy.exportable = 0;
    policy.retain_parent = 0;
    src_slot = 0;
    dst_slot = 0;

    keymgr_dpe_advance();
    if (get_check_en()) begin
      `DV_CHECK_EQ(current_state, keymgr_dpe_pkg::StWorkDpeAvailable)
    end

    keymgr_dpe_disable();
  endtask
endclass
EOF

if ! grep -q 'keymgr_dpe_disable_vseq.sv' "${VSEQ_LIST}"; then
  printf '\n`include "keymgr_dpe_disable_vseq.sv"\n' >> "${VSEQ_LIST}"
fi

python - <<'PY'
from pathlib import Path

env_core = Path("hw/ip/keymgr_dpe/dv/env/keymgr_dpe_env.core")
env_core_text = env_core.read_text(encoding="utf-8")
if "seq_lib/keymgr_dpe_disable_vseq.sv" not in env_core_text:
    old = '      - seq_lib/keymgr_dpe_smoke_vseq.sv: {is_include_file: true}\n'
    new = old + '      - seq_lib/keymgr_dpe_disable_vseq.sv: {is_include_file: true}\n'
    if old not in env_core_text:
        raise SystemExit("failed to patch keymgr_dpe_env.core")
    env_core.write_text(env_core_text.replace(old, new, 1), encoding="utf-8")

path = Path("hw/ip/keymgr_dpe/dv/keymgr_dpe_sim_cfg.hjson")
text = path.read_text(encoding="utf-8")
if "name: keymgr_dpe_disable" not in text:
    old = """  tests: [
    {
      name: keymgr_dpe_smoke
      uvm_test_seq: keymgr_dpe_smoke_vseq
    }
  ]
"""
    new = """  tests: [
    {
      name: keymgr_dpe_smoke
      uvm_test_seq: keymgr_dpe_smoke_vseq
    }
    {
      name: keymgr_dpe_disable
      uvm_test_seq: keymgr_dpe_disable_vseq
    }
  ]
"""
    if old not in text:
        raise SystemExit("failed to patch keymgr_dpe_sim_cfg.hjson")
    text = text.replace(old, new, 1)
    path.write_text(text, encoding="utf-8")

scoreboard = Path("hw/ip/keymgr_dpe/dv/env/keymgr_dpe_scoreboard.sv")
scoreboard_text = scoreboard.read_text(encoding="utf-8")
old = """              // keymgr_dpe should request 2 EDN data during advancing from StWorkDpeReset
              // function `used` returns the number of entries put into the FIFO
              `DV_CHECK_EQ(edn_fifos[0].used(), 2)
"""
new = """              if (get_operation() == keymgr_dpe_pkg::OpDpeAdvance) begin
                // keymgr_dpe should request 2 EDN data during advancing from StWorkDpeReset
                // function `used` returns the number of entries put into the FIFO
                `DV_CHECK_EQ(edn_fifos[0].used(), 2)
              end
"""
if old in scoreboard_text:
    scoreboard_text = scoreboard_text.replace(old, new, 1)

old = """              current_state = get_next_state(current_state);
              void'(ral.intr_state.predict(.value(1 << int'(IntrOpDone))));

              if (get_operation() == keymgr_dpe_pkg::OpDpeAdvance) begin
"""
new = """              current_state = get_next_state(current_state);
              void'(ral.intr_state.predict(.value(1 << int'(IntrOpDone))));

              if (get_operation() == keymgr_dpe_pkg::OpDpeDisable &&
                  current_op_status == keymgr_pkg::OpDoneSuccess) begin
                foreach (current_internal_key[slot]) begin
                  current_internal_key[slot] = '0;
                end
              end

              if (get_operation() == keymgr_dpe_pkg::OpDpeAdvance) begin
"""
if old in scoreboard_text:
    scoreboard_text = scoreboard_text.replace(old, new, 1)

scoreboard.write_text(scoreboard_text, encoding="utf-8")
PY

timeout 1800 \
