#!/bin/bash
cd /home/opentitan || exit 1

set +e
set -o pipefail

TEST_NAME="spid_status_continuous_polling"
SCRATCH_ROOT="/home/opentitan/.tb_spid_status_rotate"
RUN_LOG="${SCRATCH_ROOT}/dvsim.log"
TB_PATH="hw/ip/spi_device/pre_dv/tb/spid_status_tb.sv"

mkdir -p "${SCRATCH_ROOT}"

cat > "${TB_PATH}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

module spid_status_tb;

  import spi_device_pkg::*;
  import spid_common::*;

  localparam time ClkPeriod = 10000;
  localparam time SckPeriod = 14000;
  localparam logic [23:0] ForcedStatus = 24'hBE_AA_28;

  wire clk, rst_n;
  clk_rst_if main_clk (
    .clk,
    .rst_n
  );

  wire sck, sck_rst_n;
  clk_rst_if sck_clk (
    .clk   (sck),
    .rst_n (sck_rst_n)
  );

  spi_if sif(sck);

  virtual spi_if.tb tb_sif = sif.tb;

  logic [3:0] dut_sd_en, dut_sd;

  for (genvar i = 0; i < 4; i++) begin : g_dut_sif
    assign sif.sd_out[i] = dut_sd_en[i] ? dut_sd[i] : 1'bz;
  end

  wire gated_sck = (~sif.csb) ? sck : 1'b0;
  wire gated_sck_inverted = ~gated_sck;
  logic rst_spi_n;
  assign rst_spi_n = sck_rst_n && ~sif.csb;

  sel_datapath_e dut_sel_dp;
  logic [CmdInfoIdxW-1:0] cmd_info_idx;
  cmd_info_t cmd_info;

  logic sys_status_we;
  logic [23:0] sys_status_in, sys_status_out;
  logic busy_set;
  spi_mode_e spi_mode;

  logic s2p_valid;
  spi_byte_t s2p_data;

  logic p2s_valid, p2s_sent;
  logic [7:0] p2s_data;
  io_mode_e dut_iomode, s2p_iomode;
  logic sck_we_set, sck_we_clr;

  task automatic read_status_bytes(
    input  spi_data_t opcode,
    input  int unsigned count,
    output spi_queue_t response
  );
    spi_fifo_t txn[$];

    txn.push_back('{data: opcode, dir: DirIn,  mode: IoSingle});
    for (int unsigned i = 0; i < count; i++) begin
      txn.push_back('{data: '0, dir: DirOut, mode: IoNone});
    end

    response = {};
    spi_transaction(tb_sif, txn, response);
  endtask

  task automatic check_repeated_status(
    input spi_data_t opcode,
    input spi_data_t expected
  );
    spi_queue_t response;
    read_status_bytes(opcode, 3, response);

    if (response.size() != 3) begin
      $error("opcode 0x%0h returned %0d bytes", opcode, response.size());
      $fatal(1);
    end

    foreach (response[i]) begin
      if (response[i] !== expected) begin
        $error("opcode 0x%0h byte[%0d] expected 0x%0h got 0x%0h",
               opcode, i, expected, response[i]);
        $fatal(1);
      end
    end

    $display("opcode 0x%0h returned repeated byte 0x%0h", opcode, expected);
  endtask

  initial begin
    sck_clk.set_period_ps(SckPeriod);
    sck_clk.set_active();
    main_clk.set_period_ps(ClkPeriod);
    main_clk.set_active();

    sif.csb = 1'b1;
    sif.sd_in = 'z;
    busy_set = 1'b0;
    sys_status_we = 1'b0;
    sys_status_in = '0;
    spi_mode = FlashMode;

    sck_clk.apply_reset();
    main_clk.apply_reset();

    fork
      begin
        #20us;
        $display("TEST TIMED OUT!!");
        $fatal(1);
      end
      begin
        repeat (10) @(sck_clk.cbn);
