#!/bin/bash
set +e
set -o pipefail

cd /home/opentitan || exit 1

TB_ROOT=/home/opentitan/.tb_i2c_clock_period
DV_LOG="${TB_ROOT}/dvsim.log"

report_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: i2c_host_perf_clock_period ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_ROOT}"
mkdir -p "${TB_ROOT}"

cat > /home/opentitan/hw/ip/i2c/dv/env/seq_lib/i2c_host_perf_vseq.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

// Directed performance sequence used by the multi-swe-bench harness.
// It programs deterministic host timing values, measures the SCL period on the
// bus, and checks that the observed period matches the fixed RTL behavior.
class i2c_host_perf_vseq extends i2c_rx_tx_vseq;
  `uvm_object_utils(i2c_host_perf_vseq)
  `uvm_object_new

  localparam int unsigned CycleTolerance = 1;

  real last_posedge_ns;
  bit first_scl_posedge = 1'b1;
  uint observed_period_ps;
  uint expected_period_ps;

  virtual task pre_start();
    // Disable scoreboard / monitor checks so the test outcome is driven only by
    // the timing bug under investigation.
    cfg.en_scb = 0;
    super.pre_start();

    num_runs_c.constraint_mode(0);
    timing_val_c.constraint_mode(0);
    num_runs.rand_mode(0);
    num_trans.rand_mode(0);
    num_wr_bytes.rand_mode(0);
    rw_bit.rand_mode(0);
    fmt_fifo_access_dly.rand_mode(0);
    rx_fifo_access_dly.rand_mode(0);
    clear_intr_dly.rand_mode(0);
    thigh.rand_mode(0);
    tlow.rand_mode(0);
    t_r.rand_mode(0);
    t_f.rand_mode(0);
    thd_sta.rand_mode(0);
    tsu_sta.rand_mode(0);
    tsu_sto.rand_mode(0);
    tsu_dat.rand_mode(0);
    thd_dat.rand_mode(0);
    t_buf.rand_mode(0);
    t_timeout.rand_mode(0);
    e_timeout.rand_mode(0);
    t_sda_unstable.rand_mode(0);
    t_sda_interference.rand_mode(0);
    t_scl_interference.rand_mode(0);
  endtask

  virtual task monitor_scl_period();
    real current_posedge_ns;

    fork
      forever begin
        @(posedge cfg.m_i2c_agent_cfg.vif.scl_i);
        if (first_scl_posedge) begin
          last_posedge_ns = $realtime;
          first_scl_posedge = 1'b0;
        end else begin
          current_posedge_ns = $realtime;
          observed_period_ps = uint'((current_posedge_ns - last_posedge_ns) * 1000.0);
          last_posedge_ns = current_posedge_ns;
        end
      end
    join_none
  endtask

  virtual task body();
    uint clk_period_ps;
    uint expected_period_cycles;
    uint tolerance_ps;

    initialization();
    clk_period_ps = cfg.clk_rst_vif.clk_period_ps;

    num_runs = 1;
    num_trans = 1;
    num_wr_bytes = 2;
    rw_bit = 1'b0;
    fmt_fifo_access_dly = 0;
    rx_fifo_access_dly = 0;
    clear_intr_dly = 0;
    e_timeout = 0;
    t_timeout = 1;
    t_sda_unstable = 0;
    t_sda_interference = 0;
    t_scl_interference = 0;

    thd_sta = cfg.seq_cfg.get_thdsta_min(Fast, clk_period_ps);
    tsu_sta = cfg.seq_cfg.get_tsusta_min(Fast, clk_period_ps);
    tsu_sto = cfg.seq_cfg.get_tsusto_min(Fast, clk_period_ps);
    tsu_dat = cfg.seq_cfg.get_tsudat_min(Fast, clk_period_ps);
    thd_dat = cfg.seq_cfg.get_thddat_min(Fast, clk_period_ps);
    if (thd_dat == 0) thd_dat = 1;
    t_r = cfg.seq_cfg.get_tr_min(Fast, clk_period_ps);
    if (t_r == 0) t_r = 1;
    t_f = cfg.seq_cfg.get_tf_max(Fast, clk_period_ps);
    if (t_f == 0) t_f = 1;
    thigh = cfg.seq_cfg.get_thigh_min(Fast, clk_period_ps);
    if (thigh < 3) thigh = 3;
    tlow = cfg.seq_cfg.get_tlow_min(Fast, clk_period_ps);
    if (tlow < (t_r + tsu_dat + thd_dat + 2)) begin
      tlow = t_r + tsu_dat + thd_dat + 2;
    end
    if (tlow < 3) tlow = 3;
    t_buf = tsu_sta - t_r + 1;
    if (t_buf == 0) t_buf = 1;

    // One fall-time contribution still appears in the end-to-end SCL period
    // outside tClockPulse. The bug adds an extra t_f on top of this.
    expected_period_cycles = t_r + (2 * t_f) + thigh + tlow + 3;
    expected_period_ps = expected_period_cycles * clk_period_ps;
    tolerance_ps = CycleTolerance * clk_period_ps;

    `uvm_info(`gfn,
              $sformatf("clk_period_ps=%0d expected_period_cycles=%0d expected_period_ps=%0d t_r=%0d t_f=%0d thigh=%0d tlow=%0d",
                        clk_period_ps, expected_period_cycles, expected_period_ps, t_r, t_f,
                        thigh, tlow),
              UVM_LOW)
    print_time_property();
    monitor_scl_period();
    host_send_trans(.max_trans(num_trans), .trans_type(WriteOnly), .read(1'b0));

    if (observed_period_ps == 0) begin
      `uvm_fatal(`gfn, "Failed to sample an SCL period from the DUT")
    end

    `uvm_info(`gfn,
              $sformatf("observed_period_ps=%0d expected_period_ps=%0d tolerance_ps=%0d",
                        observed_period_ps, expected_period_ps, tolerance_ps),
              UVM_LOW)

    if ((observed_period_ps > expected_period_ps + tolerance_ps) ||
        (observed_period_ps + tolerance_ps < expected_period_ps)) begin
      `uvm_error(`gfn,
                 $sformatf("Observed SCL period %0d ps mismatches expected %0d ps (tol=%0d ps)",
                           observed_period_ps, expected_period_ps, tolerance_ps))
    end
  endtask
endclass : i2c_host_perf_vseq
EOF

python util/dvsim/dvsim.py hw/ip/i2c/dv/i2c_sim_cfg.hjson \
  -i i2c_host_perf \
  -t vcs \
  --local \
  --max-parallel 1 \
  --fixed-seed 1 \
  --build-seed 1 \
  --no-rerun \
  --build-timeout-mins 20 \
  --run-timeout-mins 10 \
  --purge \
  --scratch-root "${TB_ROOT}" \
  2>&1 | tee "${DV_LOG}"
rc=${PIPESTATUS[0]}

if [ "${rc}" -eq 0 ]; then
  report_result PASS
else
  report_result FAIL
fi
exit "${rc}"

