trap cleanup EXIT

python - <<'PY'
from pathlib import Path

vseq_path = Path("hw/ip/i2c/dv/env/seq_lib/i2c_acq_fifo_depth_vseq.sv")
vseq_path.write_text(
    """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class i2c_acq_fifo_depth_vseq extends i2c_target_smoke_vseq;
  `uvm_object_utils(i2c_acq_fifo_depth_vseq)
  `uvm_object_new

  localparam int unsigned StopTimeoutNs = 20_000_000;
  localparam int unsigned PayloadBytes = 80;

  virtual task pre_start();
    super.pre_start();
    cfg.wr_pct = 1;
    cfg.rd_pct = 0;
    cfg.rs_pct = 0;
    cfg.min_data = PayloadBytes;
    cfg.max_data = PayloadBytes;
    cfg.spinwait_timeout_ns = StopTimeoutNs;
    cfg.long_spinwait_timeout_ns = StopTimeoutNs;
  endtask

  virtual task body();
    i2c_target_base_seq m_i2c_host_seq;
    i2c_item txn_q[$];

    initialization();
    get_timing_values();
    program_registers();
    cfg.m_i2c_agent_cfg.got_stop = 0;

    `uvm_create_obj(i2c_target_base_seq, m_i2c_host_seq)
    create_txn(txn_q);
    fetch_txn(txn_q, m_i2c_host_seq.req_q);

    fork
      begin
        m_i2c_host_seq.start(p_sequencer.i2c_sequencer_h);
      end
      begin
        `DV_WAIT(cfg.m_i2c_agent_cfg.got_stop,
                 "got_stop wait timeout occurred!",
                 StopTimeoutNs,
                 "i2c_acq_fifo_depth_vseq")
      end
    join

    process_acq();
  endtask
endclass
""",
    encoding="utf-8",
)

vseq_list = Path("hw/ip/i2c/dv/env/seq_lib/i2c_vseq_list.sv")
