if include_line not in vseq_list_text:
    vseq_list.write_text(vseq_list_text + include_line, encoding="utf-8")

core = Path("hw/ip/i2c/dv/env/i2c_env.core")
core_line = "      - seq_lib/i2c_acq_fifo_depth_vseq.sv: {is_include_file: true}\n"
