if core_line not in core_text:
    core_marker = "      - seq_lib/i2c_glitch_vseq.sv: {is_include_file: true}\n"
    if core_marker not in core_text:
        raise SystemExit("Failed to locate i2c_env.core insertion point")
    core.write_text(core_text.replace(core_marker, core_marker + core_line), encoding="utf-8")

sim_cfg = Path("hw/ip/i2c/dv/i2c_sim_cfg.hjson")
