// Drive a deterministic NACK on the first data-byte ACK after the address phase.
class i2c_target_may_nack_seq extends i2c_base_seq;
  `uvm_object_utils(i2c_target_may_nack_seq)
  `uvm_object_new

  virtual task body();
    case (cfg.if_mode)
