tb_script:
#!/bin/bash
cd /home/opentitan || exit 1

TB_DIR=/home/opentitan/.tb_keymgr_decoy
TEST_NAME=keymgr_idle_decoy_values

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'SV'
module tb;
  import keymgr_pkg::*;
  import kmac_pkg::*;

  localparam int DigestCopies = kmac_pkg::AppDigestW / RandWidth;
  localparam int DecoyCopies = KmacDataIfWidth / RandWidth;

  logic clk_i;
  logic rst_ni;
  logic [AdvDataWidth-1:0] adv_data_i;
  logic [IdDataWidth-1:0] id_data_i;
  logic [GenDataWidth-1:0] gen_data_i;
  logic [3:0] inputs_invalid_i;
  logic inputs_invalid_o;
  logic adv_en_i;
  logic id_en_i;
  logic gen_en_i;
  logic done_o;
  logic [Shares-1:0][kmac_pkg::AppDigestW-1:0] data_o;
  kmac_pkg::app_req_t kmac_data_o;
  kmac_pkg::app_rsp_t kmac_data_i;
  logic prng_en_o;
  logic [Shares-1:0][RandWidth-1:0] entropy_i;
  logic fsm_error_o;
  logic kmac_error_o;
  logic kmac_done_error_o;
  logic cmd_error_o;

  keymgr_kmac_if dut (
    .clk_i,
    .rst_ni,
    .adv_data_i,
    .id_data_i,
    .gen_data_i,
    .inputs_invalid_i,
    .inputs_invalid_o,
    .adv_en_i,
    .id_en_i,
    .gen_en_i,
    .done_o,
    .data_o,
    .kmac_data_o,
    .kmac_data_i,
    .prng_en_o,
    .entropy_i,
    .fsm_error_o,
    .kmac_error_o,
    .kmac_done_error_o,
    .cmd_error_o
  );

  always #5 clk_i = ~clk_i;

  function automatic logic [kmac_pkg::AppDigestW-1:0] expand_digest(input logic [RandWidth-1:0] value);
    expand_digest = {DigestCopies{value}};
  endfunction

  function automatic logic [KmacDataIfWidth-1:0] expand_kmac(input logic [RandWidth-1:0] value);
    expand_kmac = {DecoyCopies{value}};
  endfunction

  task automatic check_expectation(input string name, input logic cond, inout int fails);
    if (!cond) begin
      $display("CHECK_FAIL: %s", name);
      fails++;
    end else begin
      $display("CHECK_PASS: %s", name);
    end
  endtask

  initial begin
    int fails;
    logic [RandWidth-1:0] permuted_share1;

    clk_i = 1'b0;
    rst_ni = 1'b0;
    adv_data_i = '0;
    id_data_i = '0;
    gen_data_i = '0;
    inputs_invalid_i = '0;
    adv_en_i = 1'b0;
    id_en_i = 1'b0;
    gen_en_i = 1'b0;
    kmac_data_i = APP_RSP_DEFAULT;
    entropy_i[0] = 32'h0123_4567;
    entropy_i[1] = 32'h89ab_cdef;
    fails = 0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    #1;

    permuted_share1 = perm_data(entropy_i[1], RndCnstRandPermDefault);
    $display("INFO: permuted_share1=0x%08h", permuted_share1);

    check_expectation("idle done low", done_o === 1'b0, fails);
    check_expectation("idle prng disabled", prng_en_o === 1'b0, fails);
    check_expectation("share0 decoy matches entropy0", data_o[0] === expand_digest(entropy_i[0]), fails);
    check_expectation("share1 decoy matches entropy1", data_o[1] === expand_digest(entropy_i[1]), fails);
    check_expectation("sideload shares differ", data_o[0] !== data_o[1], fails);
    check_expectation("kmac decoy uses permuted entropy1", kmac_data_o.data === expand_kmac(permuted_share1), fails);

    if (fails != 0) begin
      $display("TB_RESULT: FAIL (%0d checks failed)", fails);
      $fatal(1, "idle decoy checks failed");
    end

    $display("TB_RESULT: PASS");
    $finish;
  end
endmodule
SV

cat > "$TB_DIR/files.f" <<'SV'
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/hw/ip/entropy_src/rtl/entropy_src_pkg.sv
/home/opentitan/hw/ip/csrng/rtl/csrng_pkg.sv
/home/opentitan/hw/ip/edn/rtl/edn_pkg.sv
/home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv
/home/opentitan/hw/ip/keymgr/rtl/keymgr_reg_pkg.sv
/home/opentitan/hw/ip/keymgr/rtl/keymgr_pkg.sv
/home/opentitan/hw/ip/kmac/rtl/sha3_pkg.sv
/home/opentitan/hw/ip/kmac/rtl/kmac_pkg.sv
/home/opentitan/hw/ip/prim_generic/rtl/prim_generic_flop.sv
/home/opentitan/hw/vendor/lowrisc_ibex/dv/uvm/core_ibex/common/prim/prim_flop.sv
/home/opentitan/hw/ip/prim/rtl/prim_sparse_fsm_flop.sv
/home/opentitan/hw/ip/prim/rtl/prim_count.sv
/home/opentitan/hw/ip/keymgr/rtl/keymgr_kmac_if.sv
/home/opentitan/.tb_keymgr_decoy/tb.sv
SV

set +e
vcs -full64 -sverilog +define+SYNTHESIS \
  -f "$TB_DIR/files.f" \
  -Mdir="$TB_DIR/csrc" \
  -l "$TB_DIR/compile.log" \
  -o "$TB_DIR/simv"
compile_rc=$?
tb_pass=1

if [ $compile_rc -eq 0 ]; then
  "$TB_DIR/simv" -l "$TB_DIR/run.log"
fi

if [ $compile_rc -eq 0 ] && [ -f "$TB_DIR/run.log" ] \
  && grep -q "TB_RESULT: PASS" "$TB_DIR/run.log" \
  && ! grep -q "TB_RESULT: FAIL" "$TB_DIR/run.log"; then
  tb_pass=0
fi

echo "HWE_BENCH_RESULTS_START"

if [ $compile_rc -eq 0 ] && [ $tb_pass -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: $TEST_NAME ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

