   // See comment above on how FIFO popping can be improved in the future
   logic rd_stage_fifo_err;
   prim_fifo_sync #(
-    .Width   (PlainDataWidth + 3 + NumBuf),
+    .Width   (PlainDataWidth + 4 + NumBuf),
     .Pass    (0),
     .Depth   (2),
     .OutputZeroIfEmpty (1),
@@ -532,12 +533,12 @@ module flash_phy_rd
