tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="flash_phy_rd_fifo_sync_bug"
TBROOT="/home/opentitan/.tb_flash_phy_rd_sync_bug"
BUILDROOT="$TBROOT/build"
LOG="$TBROOT/console.log"

mkdir -p "$TBROOT"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

cat > "$TBROOT/flash_phy_rd_fifo_sync_bug.core" <<'EOF'
CAPI=2:
name: "local:tb:flash_phy_rd_fifo_sync_bug:0.1"
description: "Minimal flash_phy_rd stale-mask FIFO reproducer"

filesets:
  files_tb:
    depend:
      - lowrisc:ip:flash_ctrl:0.1
    files:
      - flash_phy_rd_fifo_sync_bug_tb.sv
    file_type: systemVerilogSource

targets:
  default:
    default_tool: vcs
    toplevel: flash_phy_rd_fifo_sync_bug_tb
    filesets:
      - files_tb
EOF

cat > "$TBROOT/flash_phy_rd_fifo_sync_bug_tb.sv" <<'EOF'
module flash_phy_rd_fifo_sync_bug_tb;
  import flash_ctrl_pkg::*;

  localparam int unsigned DataW = flash_phy_pkg::DataWidth;
  localparam int unsigned PlainIntgW = flash_phy_pkg::PlainIntgWidth;
  localparam int unsigned FullDataW = flash_phy_pkg::FullDataWidth;
  localparam int unsigned BusBankAddrW = flash_phy_pkg::BusBankAddrW;
  localparam int unsigned InfoTypesW = flash_phy_pkg::InfoTypesWidth;
  localparam int unsigned BusFullW = flash_phy_pkg::BusFullWidth;
  localparam int unsigned BankAddrW = flash_phy_pkg::BankAddrW;

  localparam logic [DataW-1:0] MaskA = 64'h0123_4567_89ab_cdef;
  localparam logic [DataW-1:0] MaskB = 64'hdead_beef_0123_4567;
  localparam logic [DataW-1:0] RawB  = 64'h1122_3344_5566_7788;
  localparam logic [PlainIntgW-1:0] PlainIntgB = 4'ha;
  localparam logic [FullDataW-1:0] ErasedWord = {FullDataW{1'b1}};
  localparam logic [FullDataW-1:0] DataWordB  = {8'h00, PlainIntgB, RawB};

  logic clk_i;
  logic rst_ni;
  logic buf_en_i;
  logic req_i;
  logic descramble_i;
  logic ecc_i;
  logic prog_i;
  logic pg_erase_i;
  logic bk_erase_i;
  logic [BusBankAddrW-1:0] addr_i;
  flash_ctrl_pkg::flash_part_e part_i;
  logic [InfoTypesW-1:0] info_sel_i;
  logic rdy_o;
  logic data_valid_o;
  logic data_err_o;
  logic relbl_ecc_err_o;
  logic intg_ecc_err_o;
  logic [BusFullW-1:0] data_o;
  logic idle_o;
  logic arb_err_i;
  logic calc_req_o;
  logic descramble_req_o;
  logic [BankAddrW-1:0] calc_addr_o;
  logic [DataW-1:0] scrambled_data_o;
  logic calc_ack_i;
  logic descramble_ack_i;
  logic [DataW-1:0] mask_i;
  logic [DataW-1:0] descrambled_data_i;
  logic req_o;
  logic ack_i;
  logic done_i;
  logic [FullDataW-1:0] data_i;
  logic ecc_single_err_o;
  logic [BusBankAddrW-1:0] ecc_addr_o;
  logic fifo_err_o;

  int rsp_count;
  logic [DataW-1:0] expected_b;

  flash_phy_rd dut (
    .clk_i,
    .rst_ni,
    .buf_en_i,
    .req_i,
    .descramble_i,
    .ecc_i,
    .prog_i,
    .pg_erase_i,
    .bk_erase_i,
    .addr_i,
    .part_i,
    .info_sel_i,
    .rdy_o,
    .data_valid_o,
    .data_err_o,
    .relbl_ecc_err_o,
    .intg_ecc_err_o,
    .data_o,
    .idle_o,
    .arb_err_i,
    .calc_req_o,
    .descramble_req_o,
    .calc_addr_o,
    .scrambled_data_o,
    .calc_ack_i,
    .descramble_ack_i,
    .mask_i,
    .descrambled_data_i,
    .req_o,
    .ack_i,
    .done_i,
    .data_i,
    .ecc_single_err_o,
    .ecc_addr_o,
    .fifo_err_o
  );

  defparam dut.u_rsp_order_fifo.gen_normal_fifo.u_fifo_cnt.gen_secure_ptrs.u_wptr.EnableAlertTriggerSVA = 0;
  defparam dut.u_rsp_order_fifo.gen_normal_fifo.u_fifo_cnt.gen_secure_ptrs.u_rptr.EnableAlertTriggerSVA = 0;
  defparam dut.u_rd_storage.gen_normal_fifo.u_fifo_cnt.gen_secure_ptrs.u_wptr.EnableAlertTriggerSVA = 0;
  defparam dut.u_rd_storage.gen_normal_fifo.u_fifo_cnt.gen_secure_ptrs.u_rptr.EnableAlertTriggerSVA = 0;

  function automatic logic [DataW-1:0] rotl1(input logic [DataW-1:0] value);
    rotl1 = {value[DataW-2:0], value[DataW-1]};
  endfunction

  function automatic logic [DataW-1:0] model_output(
      input logic [DataW-1:0] raw_data,
      input logic [DataW-1:0] mask);
    logic [DataW-1:0] scrambled;
    begin
      scrambled = raw_data ^ mask;
      model_output = rotl1(scrambled) ^ mask;
    end
  endfunction

  assign descrambled_data_i = rotl1(scrambled_data_o);

  always #5 clk_i = ~clk_i;

  task automatic pulse_calc_ack(input logic [DataW-1:0] mask, input int wait_cycles);
    begin
      repeat (wait_cycles) @(posedge clk_i);
      wait (calc_req_o === 1'b1);
      mask_i <= mask;
      calc_ack_i <= 1'b1;
      @(posedge clk_i);
      calc_ack_i <= 1'b0;
      mask_i <= '0;
    end
  endtask

  task automatic issue_read(
      input logic [BusBankAddrW-1:0] addr,
      input logic [FullDataW-1:0] flash_word,
      input logic [DataW-1:0] mask,
      input int mask_wait_cycles);
    begin
      req_i <= 1'b1;
      descramble_i <= 1'b1;
      addr_i <= addr;
      wait (req_o === 1'b1);
      @(posedge clk_i);
      ack_i <= 1'b1;
      @(posedge clk_i);
      ack_i <= 1'b0;
      req_i <= 1'b0;
      repeat (1) @(posedge clk_i);
      data_i <= flash_word;
      done_i <= 1'b1;
      @(posedge clk_i);
      done_i <= 1'b0;
      data_i <= '0;
      fork
        pulse_calc_ack(mask, mask_wait_cycles);
      join_none
    end
  endtask

  always @(posedge clk_i) begin
    if (!rst_ni) begin
      rsp_count <= 0;
    end else if (data_valid_o) begin
      rsp_count <= rsp_count + 1;
      $display("RSP[%0d] time=%0t data_low=%h mask=%h data_err=%0b", rsp_count + 1,
               $time, dut.data_out_muxed[DataW-1:0], dut.mask, data_err_o);
      if (rsp_count == 1) begin
        if (dut.data_out_muxed[DataW-1:0] !== expected_b) begin
          $fatal(1,
                 "Second response mismatch. expected=%h got=%h stale_mask=%h",
                 expected_b, dut.data_out_muxed[DataW-1:0], dut.mask);
        end
        $display("TESTBENCH PASS expected=%h got=%h", expected_b, dut.data_out_muxed[DataW-1:0]);
        repeat (2) @(posedge clk_i);
        $finish;
      end
    end
  end

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    buf_en_i = 1'b0;
    req_i = 1'b0;
    descramble_i = 1'b0;
    ecc_i = 1'b0;
    prog_i = 1'b0;
    pg_erase_i = 1'b0;
    bk_erase_i = 1'b0;
    addr_i = '0;
    part_i = FlashPartData;
    info_sel_i = '0;
    arb_err_i = 1'b0;
    calc_ack_i = 1'b0;
    descramble_ack_i = 1'b1;
    mask_i = '0;
    ack_i = 1'b0;
    done_i = 1'b0;
    data_i = '0;
    expected_b = model_output(RawB, MaskB);

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    issue_read('h0, ErasedWord, MaskA, 4);
    wait (rsp_count == 1);
    wait (calc_req_o == 1'b0);
    repeat (2) @(posedge clk_i);

    issue_read('h8, DataWordB, MaskB, 4);
  end

  initial begin
    repeat (200) @(posedge clk_i);
    $fatal(1, "Timeout waiting for second response");
  end
endmodule
EOF

rm -rf "$BUILDROOT"

timeout 1800 fusesoc \
  --cores-root /home/opentitan \
  --cores-root "$TBROOT" \
  run --build-root "$BUILDROOT" \
  --flag fileset_ip \
  --no-export \
  local:tb:flash_phy_rd_fifo_sync_bug:0.1 \
  2>&1 | tee "$LOG"
rc=${PIPESTATUS[0]}

if [ "$rc" -eq 124 ]; then
  emit_result "FAIL"
  exit 124
fi

if grep -q "TESTBENCH PASS" "$LOG"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

