module tb;
  import aes_pkg::*;

  localparam int W = WidthPRDSBox;

  logic clk;
  logic rst_n;
  logic cfg_valid;
  ciph_op_e op;
  sp2v_e en;
  logic prd_we;
  sp2v_e out_req;
  sp2v_e out_ack;
  logic clear;
  logic [3:0] round;
  key_len_e key_len;
  logic [7:0][31:0] key_i [2];
  logic [7:0][31:0] key_o [2];
  logic [WidthPRDKey-1:0] prd_i;
  logic err_o;
  logic [4*W-1:0] expected_prd_bits;

  aes_key_expand #(
    .AES192Enable(1'b1),
    .SecMasking(1'b1),
    .SecSBoxImpl(SBoxImplDom)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .cfg_valid_i(cfg_valid),
    .op_i(op),
    .en_i(en),
    .prd_we_i(prd_we),
    .out_req_o(out_req),
    .out_ack_i(out_ack),
    .clear_i(clear),
    .round_i(round),
    .key_len_i(key_len),
    .key_i(key_i),
    .key_o(key_o),
    .prd_i(prd_i),
    .err_o(err_o)
  );

  always #5 clk = ~clk;

  function automatic [4*W-1:0] prd_bits_now;
    begin
      prd_bits_now = {
        dut.in_prd[3][W-1:0],
        dut.in_prd[2][W-1:0],
        dut.in_prd[1][W-1:0],
        dut.in_prd[0][W-1:0]
      };
    end
  endfunction

  task automatic fail(input string msg);
    begin
      $fatal(1, "TBFAIL: %s", msg);
    end
  endtask

  initial begin
    clk = 1'b0;
    rst_n = 1'b0;
    cfg_valid = 1'b0;
    op = CIPH_FWD;
    en = SP2V_LOW;
    prd_we = 1'b0;
    out_ack = SP2V_HIGH;
    clear = 1'b0;
    round = 4'd0;
    key_len = AES_128;
    key_i[0] = '{32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff,
                 32'h01234567, 32'h89abcdef, 32'hfedcba98, 32'h76543210};
    key_i[1] = '{default: 32'h0};
    prd_i = 32'h0000_0000;

    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    @(negedge clk);
    en = SP2V_HIGH;
    prd_we = 1'b1;
    clear = 1'b1;
    round = 4'd0;
    prd_i = 32'h1020_3040;

    @(posedge clk);
    #1;
    expected_prd_bits = prd_bits_now();
    if (expected_prd_bits !== 32'h1020_3040) begin
      fail($sformatf("unexpected initial sampled prd bits: %h", expected_prd_bits));
    end

    @(negedge clk);
    prd_we = 1'b0;
    clear = 1'b0;
    round = 4'd1;
    prd_i = 32'h5566_7788;

    repeat (3) begin
      @(posedge clk);
      #1;
      if (prd_bits_now() !== expected_prd_bits) begin
        fail($sformatf("prd bits changed without prd_we: exp=%h got=%h",
                       expected_prd_bits, prd_bits_now()));
      end
      @(negedge clk);
      prd_i = {prd_i[23:0], prd_i[31:24]} ^ 32'h0f0f_0f0f;
    end

    repeat (20) begin
      @(posedge clk);
      #1;
      if (out_req == SP2V_HIGH) begin
        $display("TBPASS: key_expand buffered PRD bits remained stable");
        $finish;
      end
    end

    fail("timeout waiting for out_req_o");
  end
endmodule
EOF

