tb_script:
#!/bin/bash
cd /home/opentitan
set -uo pipefail

TB_DIR=/home/opentitan/.tb_keymgr_adv_payload
BUILD_ROOT="$TB_DIR/build"
BUILD_LOG="$TB_DIR/fusesoc_build.log"
RUN_LOG="$TB_DIR/sim_run.log"
SIM_BIN="$BUILD_ROOT/sim-vcs/local_dv_keymgr_adv_payload_tb_0.1"
TEST_NAME=keymgr_adv_payload_reorg

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/keymgr_adv_payload_tb.sv" <<'EOF'
module keymgr_adv_payload_tb;
  import keymgr_pkg::*;
  import keymgr_reg_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic rst_shadowed_ni = 1'b0;
  logic clk_edn_i = 1'b0;
  logic rst_edn_ni = 1'b0;

  tlul_pkg::tl_h2d_t tl_i = '0;
  tlul_pkg::tl_d2h_t tl_o;

  hw_key_req_t aes_key_o;
  hw_key_req_t kmac_key_o;
  otbn_key_req_t otbn_key_o;

  kmac_pkg::app_req_t kmac_data_o;
  kmac_pkg::app_rsp_t kmac_data_i = '0;

  lc_ctrl_pkg::lc_tx_t lc_keymgr_en_i = lc_ctrl_pkg::On;
  lc_ctrl_pkg::lc_keymgr_div_t lc_keymgr_div_i = 128'h5CFBD765CE33F34E123456789ABCDEF0;
  otp_ctrl_pkg::otp_keymgr_key_t otp_key_i = otp_ctrl_pkg::OTP_KEYMGR_KEY_DEFAULT;
  otp_ctrl_pkg::otp_device_id_t otp_device_id_i =
      256'h00112233445566778899AABBCCDDEEFF102132435465768798A9BACBDCEDFE0F;
  flash_ctrl_pkg::keymgr_flash_t flash_i = flash_ctrl_pkg::KEYMGR_FLASH_DEFAULT;

  edn_pkg::edn_req_t edn_o;
  edn_pkg::edn_rsp_t edn_i = '0;

  rom_ctrl_pkg::keymgr_data_t rom_digest_i = '{
    data: 256'hA20A046CF42E6EAC560A3F82BFA76285B5C1D4AEA7C915E49A32D1C89BE0F507,
    valid: 1'b1
  };

  logic intr_op_done_o;
  prim_alert_pkg::alert_rx_t [NumAlerts-1:0] alert_rx_i = '0;
  prim_alert_pkg::alert_tx_t [NumAlerts-1:0] alert_tx_o;

  logic [AdvDataWidth-1:0] exp_creator;
  logic [AdvDataWidth-1:0] exp_owner_int;
  logic [AdvDataWidth-1:0] exp_owner;

  keymgr dut (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .clk_edn_i,
    .rst_edn_ni,
    .tl_i,
    .tl_o,
    .aes_key_o,
    .kmac_key_o,
    .otbn_key_o,
    .kmac_data_o,
    .kmac_data_i,
    .kmac_en_masking_i(1'b1),
    .lc_keymgr_en_i,
    .lc_keymgr_div_i,
    .otp_key_i,
    .otp_device_id_i,
    .flash_i,
    .edn_o,
    .edn_i,
    .rom_digest_i,
    .intr_op_done_o,
    .alert_rx_i,
    .alert_tx_o
  );

  always #5 clk_i = ~clk_i;
  always #7 clk_edn_i = ~clk_edn_i;

  task automatic check_eq(string name, logic [AdvDataWidth-1:0] got,
                          logic [AdvDataWidth-1:0] exp);
    if (got !== exp) begin
      $display("CHECK_%s_FAIL got=%0h exp=%0h", name, got, exp);
      $fatal(1, "Mismatch for %s", name);
    end
    $display("CHECK_%s_PASS", name);
  endtask

  initial begin
    force dut.cdi_sel = '0;
    force dut.reg2hw.sealing_sw_binding[0].q = 32'h11110000;
    force dut.reg2hw.sealing_sw_binding[1].q = 32'h11110001;
    force dut.reg2hw.sealing_sw_binding[2].q = 32'h11110002;
    force dut.reg2hw.sealing_sw_binding[3].q = 32'h11110003;
    force dut.reg2hw.sealing_sw_binding[4].q = 32'h11110004;
    force dut.reg2hw.sealing_sw_binding[5].q = 32'h11110005;
    force dut.reg2hw.sealing_sw_binding[6].q = 32'h11110006;
    force dut.reg2hw.sealing_sw_binding[7].q = 32'h11110007;
    force dut.reg2hw.attest_sw_binding[0].q = 32'hEEEEFFFF;
    force dut.reg2hw.attest_sw_binding[1].q = 32'hEEEEFFFE;
    force dut.reg2hw.attest_sw_binding[2].q = 32'hEEEEFFFD;
    force dut.reg2hw.attest_sw_binding[3].q = 32'hEEEEFFFC;
    force dut.reg2hw.attest_sw_binding[4].q = 32'hEEEEFFFB;
    force dut.reg2hw.attest_sw_binding[5].q = 32'hEEEEFFFA;
    force dut.reg2hw.attest_sw_binding[6].q = 32'hEEEEFFF9;
    force dut.reg2hw.attest_sw_binding[7].q = 32'hEEEEFFF8;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_shadowed_ni = 1'b1;
    rst_edn_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    exp_creator = AdvDataWidth'({dut.sw_binding, otp_device_id_i, lc_keymgr_div_i,
                                 rom_digest_i.data, dut.revision_seed});
    exp_owner_int = AdvDataWidth'({dut.sw_binding, dut.creator_seed});
    exp_owner = AdvDataWidth'({dut.sw_binding, dut.owner_seed});

    check_eq("CREATOR", dut.adv_matrix[Creator], exp_creator);
    check_eq("OWNER_INT", dut.adv_matrix[OwnerInt], exp_owner_int);
    check_eq("OWNER", dut.adv_matrix[Owner], exp_owner);

    $display("ADV_PAYLOAD_CHECK_PASS");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/keymgr_adv_payload_tb.core" <<'EOF'
CAPI=2:
name: "local:dv:keymgr_adv_payload_tb:0.1"
description: "Minimal keymgr advance payload check"

filesets:
  files_dv:
    depend:
      - lowrisc:ip:keymgr
    files:
      - keymgr_adv_payload_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    toplevel: keymgr_adv_payload_tb
    filesets:
      - files_dv
    default_tool: vcs
EOF

set +e
fusesoc --cores-root /home/opentitan --cores-root "$TB_DIR" \
  run --no-export --build-root "$BUILD_ROOT" --setup --build \
  --target=sim --tool=vcs local:dv:keymgr_adv_payload_tb:0.1 \
  2>&1 | tee "$BUILD_LOG"
build_rc=${PIPESTATUS[0]}

if [ "$build_rc" -eq 0 ] && [ -x "$SIM_BIN" ]; then
  "$SIM_BIN" -l "$RUN_LOG"
  sim_rc=$?
else
  sim_rc=1
fi
set -e

if [ "$build_rc" -eq 0 ] && [ "$sim_rc" -eq 0 ] && \
   [ -f "$RUN_LOG" ] && grep -q "ADV_PAYLOAD_CHECK_PASS" "$RUN_LOG"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

