  logic [383:0] ctr_drbg_cmd_adata_o;
  logic [255:0] ctr_drbg_cmd_key_o;
  logic [127:0] ctr_drbg_cmd_v_o;
  logic [31:0] ctr_drbg_cmd_rc_o;
  logic cmd_upd_req_o;
  logic upd_cmd_rdy_i;
  logic [2:0] cmd_upd_ccmd_o;
  logic [3:0] cmd_upd_inst_id_o;
  logic [383:0] cmd_upd_pdata_o;
  logic [255:0] cmd_upd_key_o;
  logic [127:0] cmd_upd_v_o;
  logic upd_cmd_ack_i;
  logic cmd_upd_rdy_o;
  logic [2:0] upd_cmd_ccmd_i;
  logic [3:0] upd_cmd_inst_id_i;
  logic [255:0] upd_cmd_key_i;
  logic [127:0] upd_cmd_v_i;
  logic [2:0] ctr_drbg_cmd_sfifo_cmdreq_err_o;
  logic [2:0] ctr_drbg_cmd_sfifo_rcstage_err_o;
