    .ctr_drbg_cmd_fips_o,
    .ctr_drbg_cmd_adata_o,
    .ctr_drbg_cmd_key_o,
    .ctr_drbg_cmd_v_o,
    .ctr_drbg_cmd_rc_o,
    .cmd_upd_req_o,
    .upd_cmd_rdy_i,
    .cmd_upd_ccmd_o,
    .cmd_upd_inst_id_o,
    .cmd_upd_pdata_o,
    .cmd_upd_key_o,
    .cmd_upd_v_o,
    .upd_cmd_ack_i,
    .cmd_upd_rdy_o,
    .upd_cmd_ccmd_i,
    .upd_cmd_inst_id_i,
    .upd_cmd_key_i,
    .upd_cmd_v_i,
    .ctr_drbg_cmd_sfifo_cmdreq_err_o,
    .ctr_drbg_cmd_sfifo_rcstage_err_o,
    .ctr_drbg_cmd_sfifo_keyvrc_err_o
  );

  always #5 clk_i = ~clk_i;

  initial begin
    clk_i = 0;
    rst_ni = 0;
    ctr_drbg_cmd_enable_i = 0;
    ctr_drbg_cmd_req_i = 0;
    ctr_drbg_cmd_ccmd_i = INS;
    ctr_drbg_cmd_inst_id_i = '0;
    ctr_drbg_cmd_glast_i = 1'b1;
    ctr_drbg_cmd_entropy_i = '0;
