#!/bin/bash
set -u

cd /home/opentitan || exit 1

TEST_NAME="cert_serial_short_len"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local status="$1"
  local rc="$2"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

if grep -q 'uint8_t \*expected_sn_bytes' sw/device/silicon_creator/lib/cert/cert.h; then
  cat > "${TB_DIR}/repro.c" <<'EOF'
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "sw/device/silicon_creator/lib/cert/cert.h"
#include "sw/device/silicon_creator/lib/error.h"

static uint32_t cert_words[kCertX509Asn1FirstWordsWithSerialNumber] = {0};
static flash_ctrl_error_code_t error_code = {0};

rom_error_t flash_ctrl_info_read(const flash_ctrl_info_page_t *info_page,
                                 uint32_t offset, uint32_t word_count,
                                 void *data) {
  (void)info_page;
  (void)offset;
  memcpy(data, cert_words, word_count * sizeof(uint32_t));
  return kErrorOk;
}

void flash_ctrl_error_code_get(flash_ctrl_error_code_t *out) { *out = error_code; }

rom_error_t flash_ctrl_info_erase(const flash_ctrl_info_page_t *info_page,
                                  flash_ctrl_erase_type_t erase_type) {
  (void)info_page;
  (void)erase_type;
  return kErrorOk;
}

int main(void) {
  uint8_t *bytes = (uint8_t *)cert_words;
  uint8_t expected[20] = {
      0x00, 0x01, 0x02, 0x03, 0x04,
      0x05, 0x06, 0x07, 0x08, 0x09,
      0x0a, 0x0b, 0x0c, 0x0d, 0x0e,
      0x0f, 0x10, 0x11, 0x12, 0x13,
  };
  hardened_bool_t matches = kHardenedBoolFalse;

  bytes[13] = 0x02;
  bytes[14] = 19;
  for (int i = 0; i < 19; ++i) {
    bytes[15 + i] = (uint8_t)(i + 1);
  }

  rom_error_t err = cert_x509_asn1_check_serial_number(
      &(flash_ctrl_info_page_t){0}, expected, &matches);
  printf("err=%08x matches=%u\n", err, matches);
  return (err == kErrorOk && matches == kHardenedBoolTrue) ? 0 : 1;
}
EOF
else
  cat > "${TB_DIR}/repro.c" <<'EOF'
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "sw/device/silicon_creator/lib/cert/cert.h"
#include "sw/device/silicon_creator/lib/error.h"

static uint32_t cert_words[kCertX509Asn1FirstWordsWithSerialNumber] = {0};
static flash_ctrl_error_code_t error_code = {0};

rom_error_t flash_ctrl_info_read(const flash_ctrl_info_page_t *info_page,
                                 uint32_t offset, uint32_t word_count,
                                 void *data) {
  (void)info_page;
  (void)offset;
  memcpy(data, cert_words, word_count * sizeof(uint32_t));
  return kErrorOk;
}

void flash_ctrl_error_code_get(flash_ctrl_error_code_t *out) { *out = error_code; }

rom_error_t flash_ctrl_info_erase(const flash_ctrl_info_page_t *info_page,
                                  flash_ctrl_erase_type_t erase_type) {
  (void)info_page;
  (void)erase_type;
  return kErrorOk;
}

int main(void) {
  uint8_t *bytes = (uint8_t *)cert_words;
  uint32_t expected[5] = {
      0x04030201,
      0x08070605,
      0x0c0b0a09,
      0x100f0e0d,
      0x13121100,
  };
  hardened_bool_t matches = kHardenedBoolFalse;

  bytes[13] = 0x02;
  bytes[14] = 19;
  for (int i = 0; i < 19; ++i) {
    bytes[15 + i] = (uint8_t)(i + 1);
  }

  rom_error_t err = cert_x509_asn1_check_serial_number(
      &(flash_ctrl_info_page_t){0}, expected, &matches);
  printf("err=%08x matches=%u\n", err, matches);
  return (err == kErrorOk && matches == kHardenedBoolTrue) ? 0 : 1;
}
EOF
fi

