gcc -std=gnu11 -Wall -Wextra -I/home/opentitan \
  -c "${TB_DIR}/repro.c" -o "${TB_DIR}/repro.o" >"${COMPILE_LOG}" 2>&1
rc=$?
if [ "${rc}" -ne 0 ]; then
  emit_result "FAIL" "${rc}"
fi

gcc -std=gnu11 -fgnu89-inline -Wall -Wextra -I/home/opentitan \
  -c /home/opentitan/sw/device/silicon_creator/lib/cert/cert.c \
  -o "${TB_DIR}/cert.o" >>"${COMPILE_LOG}" 2>&1
rc=$?
if [ "${rc}" -ne 0 ]; then
  emit_result "FAIL" "${rc}"
fi

gcc "${TB_DIR}/repro.o" "${TB_DIR}/cert.o" \
  -o "${TB_DIR}/repro" >>"${COMPILE_LOG}" 2>&1
rc=$?
if [ "${rc}" -ne 0 ]; then
  emit_result "FAIL" "${rc}"
fi

"${TB_DIR}/repro" >"${RUN_LOG}" 2>&1
rc=$?

if [ "${rc}" -eq 0 ]; then
  emit_result "PASS" 0
fi

emit_result "FAIL" "${rc}"

