module tb;
  import spi_device_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic data_valid_i;
  spi_byte_t data_i;
  spi_mode_e spi_mode_i;
  cmd_info_t [NumTotalCmdInfo-1:0] cmd_info_i;
  logic sck_status_busy_i;

  io_mode_e io_mode_o;
  sel_datapath_e sel_dp_o;
  sel_datapath_e cmd_only_sel_dp_o;
  cmd_info_t cmd_info_o;
  logic [CmdInfoIdxW-1:0] cmd_info_idx_o;
  cmd_info_t cmd_only_info_o;
  logic [CmdInfoIdxW-1:0] cmd_only_info_idx_o;
  logic cmd_sync_pulse_o;
  logic cfg_intercept_en_status_i;
  logic cfg_intercept_en_jedec_i;
  logic cfg_intercept_en_sfdp_i;
  logic cmd_read_pipeline_sel_o;
  logic intercept_status_o;
  logic intercept_jedec_o;
  logic intercept_sfdp_o;
  logic cmd_config_req_o;
  logic [4:0] cmd_config_idx_o;

  spi_cmdparse dut (.*);

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

