patch_dv_files() {
python - <<'PY'
from pathlib import Path


def replace_once(text: str, old: str, new: str) -> str:
    if old not in text:
        raise SystemExit(f"missing pattern: {old[:80]!r}")
    return text.replace(old, new, 1)


root = Path("/home/opentitan")

vseq = """// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class csrng_ack_error_fifo_flush_vseq extends csrng_base_vseq;
  `uvm_object_utils(csrng_ack_error_fifo_flush_vseq)
  `uvm_object_new

  localparam uint App = HW_APP0;

  csrng_item cs_item;
  bit        extra_ack_seen;

  task body();
    super.body();

    for (int i = 0; i < NUM_HW_APPS; i++) begin
      m_edn_push_seq[i] = push_pull_host_seq#(csrng_pkg::CSRNG_CMD_WIDTH)::type_id::create(
          $sformatf("m_edn_push_seq[%0d]", i));
    end

    cfg.m_edn_agent_cfg[App].cmd_zero_delays = 1'b1;
    cfg.m_edn_agent_cfg[App].m_cmd_push_agent_cfg.zero_delays = 1'b1;

    // Send an invalid header with one extra data word. On the buggy RTL, that leftover word is
    // interpreted as a second command header and triggers an unexpected extra ACK.
    cs_item = csrng_item::type_id::create("invalid_cmd_item");
    cs_item.acmd  = csrng_pkg::INV;
    cs_item.clen  = 4'h1;
    cs_item.flags = MuBi4True;
    cs_item.glen  = 12'h0;
    cs_item.cmd_data_q.delete();
    cs_item.cmd_data_q.push_back(32'h0000_0000);
    send_cmd_req(App, cs_item, .exp_sts(CMD_STS_INVALID_ACMD));

    extra_ack_seen = 1'b0;
    repeat (20) begin
      @(cfg.m_edn_agent_cfg[App].vif.mon_cb);
      if (cfg.m_edn_agent_cfg[App].vif.mon_cb.cmd_rsp.csrng_rsp_ack) begin
        extra_ack_seen = 1'b1;
        break;
      end
    end
    `DV_CHECK_EQ_FATAL(extra_ack_seen, 1'b0)

    cs_item = csrng_item::type_id::create("valid_cmd_item");
    cs_item.acmd  = csrng_pkg::UNI;
    cs_item.clen  = 4'h0;
    cs_item.flags = MuBi4True;
    cs_item.glen  = 12'h0;
    cs_item.cmd_data_q.delete();
    send_cmd_req(App, cs_item);
  endtask
endclass
"""

