        '`include "csrng_regwen_test.sv"\n',
        '`include "csrng_ack_error_fifo_flush_test.sv"\n`include "csrng_regwen_test.sv"\n',
    )
    test_pkg_path.write_text(text)

test_core_path = root / "hw/ip/csrng/dv/tests/csrng_test.core"
text = test_core_path.read_text()
