        "    {\n      name: csrng_regwen\n      uvm_test: csrng_regwen_test\n      uvm_test_seq: csrng_regwen_vseq\n    }\n\n"
        "    {\n      name: csrng_ack_error_fifo_flush\n      uvm_test: csrng_ack_error_fifo_flush_test\n      uvm_test_seq: csrng_ack_error_fifo_flush_vseq\n      reseed: 1\n    }\n",
    )
    sim_cfg_path.write_text(text)

scoreboard_path = root / "hw/ip/csrng/dv/env/csrng_scoreboard.sv"
text = scoreboard_path.read_text()
if "`gmv(ral.fips_force)[app]" in text:
    text = replace_once(
        text,
        "    bit [CSRNG_BUS_WIDTH-1:0] seed_material;\n    bit compliance_previous = cfg.compliance[app];\n",
        "    bit [CSRNG_BUS_WIDTH-1:0] seed_material;\n"
        "    bit [3:0]                 fips_force_val = `gmv(ral.fips_force);\n"
        "    bit compliance_previous = cfg.compliance[app];\n",
    )
    text = replace_once(
        text,
        "    cfg.compliance[app]     = fips || ((`gmv(ral.ctrl.fips_force_enable) == MuBi4True) &&\n"
        "                                        `gmv(ral.fips_force)[app]);\n",
        "    cfg.compliance[app]     = fips || ((`gmv(ral.ctrl.fips_force_enable) == MuBi4True) &&\n"
        "                                        fips_force_val[app]);\n",
    )
    text = replace_once(
        text,
        "    bit [CSRNG_BUS_WIDTH-1:0]   seed_material;\n    bit compliance_previous = cfg.compliance[app];\n",
        "    bit [CSRNG_BUS_WIDTH-1:0]   seed_material;\n"
        "    bit [3:0]                   fips_force_val = `gmv(ral.fips_force);\n"
        "    bit compliance_previous = cfg.compliance[app];\n",
    )
    text = replace_once(
        text,
        "  function void ctr_drbg_uninstantiate(uint app);\n    `uvm_info(`gfn, $sformatf(\"Uninstantiate of app %0d\", app), UVM_MEDIUM)\n",
        "  function void ctr_drbg_uninstantiate(uint app);\n"
        "    bit [3:0] fips_force_val = `gmv(ral.fips_force);\n"
        "    `uvm_info(`gfn, $sformatf(\"Uninstantiate of app %0d\", app), UVM_MEDIUM)\n",
