    hw/ip/csrng/dv/csrng_sim_cfg.hjson \
    -i "$TEST_NAME" \
    -t vcs \
    --fixed-seed 1 \
    --build-seed 1 \
    2>&1 | tee "$LOG"
  return ${PIPESTATUS[0]}
}

run_test
rc=$?

echo "HWE_BENCH_RESULTS_START"
