RUN_LOG="$TB_DIR/run.log"

rm -rf "$TB_DIR" "$BUILD_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/prim_flop.sv" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input clk_i,
  input rst_ni,
  input [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  if (ResetValue == '0) begin : gen_fast_q
    always @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) q_o <= ResetValue;
      else q_o <= #1 d_i;
    end
  end else begin : gen_slow_q
    always @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) q_o <= ResetValue;
      else q_o <= #3 d_i;
    end
  end
endmodule
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  localparam int Width = 2;

  logic clk_i;
  logic rst_ni;
  logic clr_i;
  logic set_i;
  logic [Width-1:0] set_cnt_i;
  logic incr_en_i;
  logic decr_en_i;
  logic [Width-1:0] step_i;
  logic commit_i;
  logic [Width-1:0] cnt_o;
  logic [Width-1:0] cnt_after_commit_o;
  logic err_o;
  int err_pulses;

  prim_count #(
    .Width(Width),
    .ResetValue('0),
    .EnableAlertTriggerSVA(0)
  ) dut (
    .clk_i,
    .rst_ni,
    .clr_i,
    .set_i,
    .set_cnt_i,
    .incr_en_i,
    .decr_en_i,
    .step_i,
    .commit_i,
    .cnt_o,
    .cnt_after_commit_o,
    .err_o
  );

  initial clk_i = 0;
  always #5 clk_i = ~clk_i;

  always @(posedge err_o) begin
    err_pulses++;
    $display("ERR pulse at %0t cnt_o=%0d cnt_after_commit_o=%0d", $time, cnt_o,
             cnt_after_commit_o);
  end

  task automatic drive_idle();
    clr_i = 0;
    set_i = 0;
    set_cnt_i = '0;
    incr_en_i = 0;
    decr_en_i = 0;
    step_i = 'd1;
    commit_i = 0;
  endtask

  initial begin
    err_pulses = 0;
    drive_idle();
    rst_ni = 0;
    repeat (2) @(negedge clk_i);
    rst_ni = 1;

    repeat (3) begin
      @(negedge clk_i);
      incr_en_i = 1;
      commit_i = 1;
      step_i = 'd1;
      @(negedge clk_i);
      drive_idle();
    end

    repeat (2) @(negedge clk_i);
    if (err_pulses != 0) begin
      $fatal(1, "err_o pulsed %0d times during legal count updates", err_pulses);
    end
    $display("PASS no err_o pulses observed");
    $finish;
  end
endmodule
EOF

