      $fatal(1, "TB_RESULT: FAIL tap_strap0 pull_en after reset release is %0b, expected 1", dut.mio_pad_attr_q[Tap0PadIdx].pull_en);
    end

    $display("TB_RESULT: PASS pinmux_reset_tb observed pull_en=1 for tap strap 0");
    $finish;
  end
endmodule
EOF

