tb_script:
#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="ac_range_check_perm_priority"
TB_DIR="/home/opentitan/.tb_ac_range_check_perm_priority"
BUILD_ROOT="${TB_DIR}/build"
BUILD_DIR="${BUILD_ROOT}/default-vcs"
SETUP_LOG="${TB_DIR}/setup.log"
BUILD_LOG="${TB_DIR}/build.log"
SIM_LOG="${TB_DIR}/sim.log"
SIM_BIN="${BUILD_DIR}/local_tb_ac_range_check_perm_priority_0.1"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

export XDG_CONFIG_HOME="${TB_DIR}/xdg_config"
export XDG_CACHE_HOME="${TB_DIR}/xdg_cache"
export XDG_DATA_HOME="${TB_DIR}/xdg_data"
mkdir -p "${XDG_CONFIG_HOME}" "${XDG_CACHE_HOME}" "${XDG_DATA_HOME}"

cat > "${TB_DIR}/ac_range_check_perm_priority_tb.core" <<'EOF'
CAPI=2:
name: local:tb:ac_range_check_perm_priority:0.1
description: Directed VCS test for ac_range_check permission priority bug
filesets:
  files_tb:
    depend:
      - lowrisc:darjeeling_ip:ac_range_check:0.1
    files:
      - tb.sv
    file_type: systemVerilogSource
targets:
  default:
    filesets:
      - files_tb
    toplevel: tb
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import tlul_pkg::*;
  import prim_mubi_pkg::*;
  import ac_range_check_reg_pkg::*;
  import top_racl_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic rst_shadowed_ni;
  prim_alert_pkg::alert_rx_t [NumAlerts-1:0] alert_rx_i;
  prim_alert_pkg::alert_tx_t [NumAlerts-1:0] alert_tx_o;
  racl_policy_vec_t racl_policies_i;
  racl_error_log_t racl_error_o;
  logic intr_deny_cnt_reached_o;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  prim_mubi_pkg::mubi8_t range_check_overwrite_i;
  tl_h2d_t ctn_tl_h2d_i;
  tl_d2h_t ctn_tl_d2h_o;
  tl_h2d_t ctn_filtered_tl_h2d_o;
  tl_d2h_t ctn_filtered_tl_d2h_i;
  ac_range_check_reg2hw_t forced_reg2hw;

  ac_range_check dut (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .alert_rx_i,
    .alert_tx_o,
    .racl_policies_i,
    .racl_error_o,
    .intr_deny_cnt_reached_o,
    .tl_i,
    .tl_o,
    .range_check_overwrite_i,
    .ctn_tl_h2d_i,
    .ctn_tl_d2h_o,
    .ctn_filtered_tl_h2d_o,
    .ctn_filtered_tl_d2h_i
  );

  always #5 clk_i = ~clk_i;

  task automatic update_intg(ref tl_h2d_t req);
    req.a_user.cmd_intg = tlul_pkg::get_cmd_intg(req);
    req.a_user.data_intg = tlul_pkg::get_data_intg(req.a_data);
  endtask

  task automatic check_ok(bit cond, string msg);
    if (!cond) begin
      $error("%s", msg);
      $fatal(1);
    end
  endtask

  initial begin
    tl_h2d_t req;
    clk_i = 1'b0;
    rst_ni = 1'b0;
    rst_shadowed_ni = 1'b0;
    alert_rx_i = '0;
    racl_policies_i = '0;
    tl_i = TL_H2D_DEFAULT;
    ctn_tl_h2d_i = TL_H2D_DEFAULT;
    ctn_filtered_tl_d2h_i = TL_D2H_DEFAULT;
    range_check_overwrite_i = prim_mubi_pkg::MuBi8False;
    forced_reg2hw = '0;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_shadowed_ni = 1'b1;

    forced_reg2hw.log_config.log_enable.q = 1'b1;

    forced_reg2hw.range_base[0].q = 30'd0;
    forced_reg2hw.range_limit[0].q = 30'd8;
    forced_reg2hw.range_perm[0].enable.q = MuBi4True;
    forced_reg2hw.range_perm[0].read_access.q = MuBi4False;
    forced_reg2hw.range_perm[0].write_access.q = MuBi4True;
    forced_reg2hw.range_perm[0].execute_access.q = MuBi4False;
    forced_reg2hw.range_perm[0].log_denied_access.q = MuBi4True;
    forced_reg2hw.range_racl_policy_shadowed[0].read_perm.q = 16'h0001;
    forced_reg2hw.range_racl_policy_shadowed[0].write_perm.q = 16'h0001;

    forced_reg2hw.range_base[1].q = 30'd0;
    forced_reg2hw.range_limit[1].q = 30'd16;
    forced_reg2hw.range_perm[1].enable.q = MuBi4True;
    forced_reg2hw.range_perm[1].read_access.q = MuBi4True;
    forced_reg2hw.range_perm[1].write_access.q = MuBi4False;
    forced_reg2hw.range_perm[1].execute_access.q = MuBi4False;
    forced_reg2hw.range_perm[1].log_denied_access.q = MuBi4True;
    forced_reg2hw.range_racl_policy_shadowed[1].read_perm.q = 16'h0001;
    forced_reg2hw.range_racl_policy_shadowed[1].write_perm.q = 16'h0001;

    force dut.reg2hw = forced_reg2hw;

    repeat (2) @(posedge clk_i);

    req = TL_H2D_DEFAULT;
    req.a_valid = 1'b1;
    req.a_opcode = Get;
    req.a_size = 2'd2;
    req.a_source = '0;
    req.a_address = 32'h0000_0010;
    req.a_mask = 4'hf;
    req.a_data = '0;
    req.a_user.instr_type = MuBi4False;
    req.a_user.rsvd = '0;
    update_intg(req);
    ctn_tl_h2d_i = req;

    #1;
    check_ok(ctn_filtered_tl_h2d_o.a_valid === 1'b0,
             "Read request should be squashed by higher-priority deny range");
    check_ok(dut.hw2reg.log_status.deny_range_index.d === 5'd0,
             "Denied read should log range index 0");

    @(posedge clk_i);
    #1;
    check_ok(ctn_tl_d2h_o.d_valid === 1'b1,
             "Denied read should produce a loopback response");
    check_ok(ctn_tl_d2h_o.d_error === 1'b1,
