    ctn_tl_h2d_i = TL_H2D_DEFAULT;
    @(posedge clk_i);

    req = TL_H2D_DEFAULT;
    req.a_valid = 1'b1;
    req.a_opcode = PutFullData;
    req.a_size = 2'd2;
    req.a_source = '0;
    req.a_address = 32'h0000_0010;
    req.a_mask = 4'hf;
    req.a_data = 32'h1234_5678;
    req.a_user.instr_type = MuBi4False;
    req.a_user.rsvd = '0;
    update_intg(req);
    ctn_tl_h2d_i = req;

