#!/bin/bash
cd /home/opentitan
set -euo pipefail

WORKDIR=/home/opentitan/.tb_usbdev_rxenable_out
SCRATCH_ROOT="$WORKDIR/scratch"
LOG="$WORKDIR/dvsim.log"

mkdir -p "$WORKDIR"
rm -rf "$SCRATCH_ROOT"

cat > hw/ip/usbdev/dv/env/seq_lib/usbdev_av_empty_vseq.sv <<'EOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class usbdev_av_empty_vseq extends usbdev_base_vseq;
  `uvm_object_utils(usbdev_av_empty_vseq)

  `uvm_object_new

  localparam int unsigned NEndpointsLocal = usbdev_reg_pkg::NEndpoints;
  localparam bit [NEndpointsLocal-1:0] EpAll = {NEndpointsLocal{1'b1}};
  localparam bit [NEndpointsLocal-1:0] EpOdd = {((NEndpointsLocal + 1) / 2){2'b10}};
  localparam bit [NEndpointsLocal-1:0] EpEven = EpOdd >> 1;

  task pre_start();
    do_agent_connect = 1'b1;
    do_agent_activate = 1'b0;
    do_usbdev_init = 1'b0;
    super.pre_start();
  endtask

  task automatic write_rxenable(bit [31:0] wr_data);
    bit [31:0] reg_addr;
    reg_addr = ral.default_map.get_base_addr() + usbdev_reg_pkg::USBDEV_RXENABLE_OUT_OFFSET;
    tl_access(.addr(reg_addr), .write(1'b1), .data(wr_data));
  endtask

  task automatic check_rxenable(bit [31:0] exp_data, string msg);
    bit [31:0] reg_addr;
    bit [31:0] rd_data;
    reg_addr = ral.default_map.get_base_addr() + usbdev_reg_pkg::USBDEV_RXENABLE_OUT_OFFSET;
    rd_data = '0;
    tl_access(.addr(reg_addr), .write(1'b0), .data(rd_data));
    `DV_CHECK_EQ_FATAL(rd_data, exp_data, msg)
  endtask

  task body();
    write_rxenable(EpAll);
    check_rxenable(EpAll, "full enable write failed");

    // Preserve one half of the endpoints while clearing the other half.
    // The fixed design interprets the upper half-word as a write mask.
    write_rxenable(EpOdd << 16);
    check_rxenable(EpOdd, "conditional clear did not preserve the masked endpoints");

    write_rxenable(EpEven);
    check_rxenable(EpEven, "plain overwrite did not update endpoint enables");
  endtask

endclass : usbdev_av_empty_vseq
EOF

set +e
python ./util/dvsim/dvsim.py hw/ip/usbdev/dv/usbdev_sim_cfg.hjson \
  -i usbdev_av_empty \
  -t vcs \
  --local \
  --scratch-root "$SCRATCH_ROOT" \
  --fixed-seed 1 \
  --build-seed 1 \
  --max-parallel 1 \
  --no-rerun \
  --purge \
  --build-timeout-mins 20 \
  --run-timeout-mins 5 \
  -v l \
  2>&1 | tee "$LOG"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: usbdev_rxenable_out_conditional ... PASS"
else
  echo "TEST: usbdev_rxenable_out_conditional ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

#!/bin/bash
set -euo pipefail

cd /home/opentitan

TB_NAME="otp_ctrl_dai_zeroize_release"
TB_DIR="/home/opentitan/.tb_otp_ctrl_zeroize"
LOG_DIR="${TB_DIR}/logs"
RUN_LOG="${LOG_DIR}/run.log"

mkdir -p "${TB_DIR}" "${LOG_DIR}"
rm -rf "${TB_DIR}/build"

cat > "${TB_DIR}/otp_ctrl_dai_zeroize_tb.sv" <<'SVEOF'
module otp_ctrl_dai_zeroize_tb;
  import prim_mubi_pkg::*;
  import lc_ctrl_pkg::*;
  import otp_ctrl_pkg::*;
  import otp_ctrl_reg_pkg::*;
  import otp_ctrl_part_pkg::*;
  import otp_ctrl_top_specific_pkg::*;

  localparam int unsigned ExpectedCount = ZeroizationValidBound - 1;
  localparam logic [ScrmblBlockWidth-1:0] LowCountWord =
      {{ExpectedCount{1'b1}}, {(ScrmblBlockWidth-ExpectedCount){1'b0}}};
  localparam logic [OtpByteAddrWidth-1:0] Secret0ZeroizeAddr =
      OtpByteAddrWidth'(PartInfo[Secret0Idx].offset + PartInfo[Secret0Idx].size -
                        (ScrmblBlockWidth / 8));

  logic clk_i;
  logic rst_ni;
  logic init_req_i;
  logic init_done_o;
  logic part_init_req_o;
  logic [NumPart-1:0] part_init_done_i;
  lc_tx_t escalate_en_i;
  otp_err_e error_o;
  logic fsm_err_o;
  part_access_t [NumPart-1:0] part_access_i;
  logic [OtpByteAddrWidth-1:0] dai_addr_i;
  dai_cmd_e dai_cmd_i;
  logic dai_req_i;
  logic [NumDaiWords-1:0][31:0] dai_wdata_i;
  logic dai_idle_o;
  logic dai_prog_idle_o;
  logic dai_cmd_done_o;
  logic [NumDaiWords-1:0][31:0] dai_rdata_o;
  logic otp_req_o;
  otp_ctrl_macro_pkg::cmd_e otp_cmd_o;
  logic [otp_ctrl_macro_pkg::OtpSizeWidth-1:0] otp_size_o;
  logic [otp_ctrl_macro_pkg::OtpIfWidth-1:0] otp_wdata_o;
  logic [otp_ctrl_macro_pkg::OtpAddrWidth-1:0] otp_addr_o;
  logic otp_gnt_i;
  logic otp_rvalid_i;
  logic [ScrmblBlockWidth-1:0] otp_rdata_i;
  otp_ctrl_macro_pkg::err_e otp_err_i;
  logic scrmbl_mtx_req_o;
  logic scrmbl_mtx_gnt_i;
  otp_scrmbl_cmd_e scrmbl_cmd_o;
  digest_mode_e scrmbl_mode_o;
  logic [ConstSelWidth-1:0] scrmbl_sel_o;
  logic [ScrmblBlockWidth-1:0] scrmbl_data_o;
  logic scrmbl_valid_o;
  logic scrmbl_ready_i;
  logic scrmbl_valid_i;
  logic [ScrmblBlockWidth-1:0] scrmbl_data_i;
  mubi8_t [NumPart-1:0] zer_trigs_o;
  mubi8_t [NumPart-1:0] zer_i;

  otp_ctrl_dai u_dut (
    .clk_i,
    .rst_ni,
    .init_req_i,
    .init_done_o,
    .part_init_req_o,
    .part_init_done_i,
    .escalate_en_i,
    .error_o,
    .fsm_err_o,
    .part_access_i,
    .dai_addr_i,
    .dai_cmd_i,
    .dai_req_i,
    .dai_wdata_i,
    .dai_idle_o,
    .dai_prog_idle_o,
    .dai_cmd_done_o,
    .dai_rdata_o,
    .otp_req_o,
    .otp_cmd_o,
    .otp_size_o,
    .otp_wdata_o,
    .otp_addr_o,
    .otp_gnt_i,
    .otp_rvalid_i,
    .otp_rdata_i,
    .otp_err_i,
    .scrmbl_mtx_req_o,
    .scrmbl_mtx_gnt_i,
    .scrmbl_cmd_o,
    .scrmbl_mode_o,
    .scrmbl_sel_o,
    .scrmbl_data_o,
    .scrmbl_valid_o,
    .scrmbl_ready_i,
    .scrmbl_valid_i,
    .scrmbl_data_i,
    .zer_trigs_o,
    .zer_i
  );

  always #5 clk_i = ~clk_i;

  task automatic pulse_init_rsp();
    begin
      init_req_i = 1'b1;
      @(posedge clk_i);
      init_req_i = 1'b0;
      otp_rvalid_i = 1'b1;
      otp_err_i = otp_ctrl_macro_pkg::NoError;
      @(posedge clk_i);
      otp_rvalid_i = 1'b0;
    end
  endtask

  task automatic issue_zeroize_rsp();
    begin
      dai_addr_i = Secret0ZeroizeAddr;
      dai_cmd_i = DaiZeroize;
      dai_req_i = 1'b1;
      @(posedge clk_i);
      dai_req_i = 1'b0;
      wait (otp_cmd_o == otp_ctrl_macro_pkg::Zeroize && otp_req_o);
      @(posedge clk_i);
      otp_rdata_i = LowCountWord;
      otp_rvalid_i = 1'b1;
      otp_err_i = otp_ctrl_macro_pkg::NoError;
      @(posedge clk_i);
      otp_rvalid_i = 1'b0;
      otp_rdata_i = '0;
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    init_req_i = 1'b0;
    part_init_done_i = '1;
    escalate_en_i = Off;
    part_access_i = '0;
    foreach (part_access_i[i]) begin
      part_access_i[i].read_lock = MuBi8False;
      part_access_i[i].write_lock = MuBi8False;
    end
    dai_addr_i = '0;
    dai_cmd_i = DaiRead;
    dai_req_i = 1'b0;
    dai_wdata_i = '0;
    otp_gnt_i = 1'b1;
    otp_rvalid_i = 1'b0;
    otp_rdata_i = '0;
    otp_err_i = otp_ctrl_macro_pkg::NoError;
    scrmbl_mtx_gnt_i = 1'b0;
    scrmbl_ready_i = 1'b0;
    scrmbl_valid_i = 1'b0;
    scrmbl_data_i = '0;
    zer_i = '{default: MuBi8False};

    repeat (3) @(posedge clk_i);
    rst_ni = 1'b1;

    pulse_init_rsp();
    wait (init_done_o && dai_idle_o);
    repeat (2) @(posedge clk_i);

    issue_zeroize_rsp();
    wait (dai_cmd_done_o);
    @(posedge clk_i);

    if (error_o != otp_ctrl_top_specific_pkg::NoError) begin
      $fatal(1, "Unexpected OTP error: %0d", error_o);
    end
    if (dai_rdata_o[0] !== ExpectedCount[31:0]) begin
      $fatal(1, "Expected countones result %0d, got %0d", ExpectedCount, dai_rdata_o[0]);
    end
    if (dai_rdata_o[1] !== 32'd0) begin
      $fatal(1, "Upper word should stay zero, got %0d", dai_rdata_o[1]);
    end
    if (zer_trigs_o[Secret0Idx] !== MuBi8True) begin
      $fatal(1, "Zeroize trigger not asserted for Secret0");
    end

    $display("TB_PASS expected=%0d observed=%0d", ExpectedCount, dai_rdata_o[0]);
    $finish;
  end
endmodule
SVEOF

cat > "${TB_DIR}/otp_ctrl_dai_zeroize.core" <<'COREEOF'
CAPI=2:
name: local:tb:otp_ctrl_dai_zeroize:0.1
description: "Minimal DAI zeroize regression for otp_ctrl"

filesets:
  files_dv:
    depend:
      - lowrisc:darjeeling_ip:otp_ctrl:1.0
    files:
      - otp_ctrl_dai_zeroize_tb.sv
    file_type: systemVerilogSource

targets:
  default:
    default_tool: vcs
    filesets:
      - files_dv
    toplevel: otp_ctrl_dai_zeroize_tb
COREEOF

set +e
(
  cd "${TB_DIR}" && \
  fusesoc --cores-root /home/opentitan --cores-root "${TB_DIR}" run --target=default --tool=vcs local:tb:otp_ctrl_dai_zeroize:0.1
) 2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ] && grep -q "TB_PASS expected=" "${RUN_LOG}"; then
  echo "TEST: ${TB_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
else
  echo "TEST: ${TB_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi
